\dist*
\begin{proof}
\textbf{$\mathbf{\textbf{ID}_m}$ and $\mathbf{\textbf{UN}_m}$:} We start by computing the distance between $\ID_m$ and $\UN_m$. Note that $\UN_m$ always remains the same matrix independent of how its columns are ordered. Thus, we can compute the distance between these two matrices using the identity permutation between the columns of the two matrices: 
    $\POS(\ID_m,\UN_m) = \sum_{i=1}^m \EMD((\ID_m)_i, (\UN_m)_i)=\textstyle\sum_{i=1}^m (\textstyle\sum_{j=1}^{i-1} \frac{j}{m} + \textstyle\sum_{j=1}^{m-i} \frac{j}{m}) 
\\ = \frac{1}{m} \textstyle\sum_{i=1}^m ( \frac{1 + (i-1)}{2}(i-1) + \frac{1 + (m-i)}{2}(m-i) ) 
\\ = \frac{1}{2m} \textstyle\sum_{i=1}^m (2i^2 - 2i - 2mi + m^2  + m) 
\\ = \frac{1}{2m} (2\frac{m(m+1)(2m+1)}{6} - m(m+1)-m^2(m+1)  + m(m^2 + m))
\\ = \frac{1}{2m} (\frac{(m^2+m)(2m+1)}{3} - (m+1)(m+m^2)  + m(m^2 + m))
\\ = \frac{m+1}{2} (\frac{(2m+1)}{3} - (m+1)  + m) = \frac{(m+1)(m-1)}{3} = \frac{1}{3}(m^2-1).$

In the following, we use $(*)$ when we omit some calculations analogous to the calculations for $\POS(\ID_m,\UN_m)$.

\medskip
\noindent \textbf{$\mathbf{\textbf{UN}_m}$ and $\mathbf{\textbf{ST}_m}$:} Similarly, we can also directly compute the distance between $\UN_m$ and $\ST_m$ using the identity permutation between the columns of the two matrices. In this case, all column vectors of the two matrices have indeed the same $\EMD$ distance to each other:

 \noindent
 $\POS(\UN_m,\ST_m) =  m\cdot (\frac{1}{2}+2\cdot\textstyle\sum_{i=1}^{\frac{m}{2}-1} \frac{i}{m})= \frac{m}{2}+\frac{m}{2}(\frac{m}{2}-1) = \frac{m^2}{4}.$

  \medskip
\noindent \textbf{$\mathbf{\textbf{UN}_m}$ and $\mathbf{\textbf{AN}_m}$:} Next, we compute the distance between $\UN_m$ and $\AN_m$ using the identity permutation between the columns of the two matrices.  Recall that $\AN_m$ can be written as:
\[
  \AN_m = 0.5\begin{bmatrix}
    \ID_{\nicefrac{m}{2}} & \rID_{\nicefrac{m}{2}} \\
    \rID_{\nicefrac{m}{2}} & \ID_{\nicefrac{m}{2}}
  \end{bmatrix}.
\] Thus, it is possible to reuse our ideas from computing the distance between identity and uniformity:

  \noindent
 $\POS(\UN_m,\AN_m) = 4 \textstyle\sum_{i=1}^{\frac{m}{2}}(\textstyle\sum_{j=1}^{i-1} \frac{j}{m} + \textstyle\sum_{j=1}^{\frac{m}{2}-i} \frac{j}{m}) = (*) = \frac{2}{3}(\frac{m^2}{4}-1).$

 \medskip
\noindent \textbf{$\mathbf{\textbf{ID}_m}$ and $\mathbf{\textbf{ST}_m}$:}
There exist only two different types of column vectors in $\ST_m$, i.e.,  $\frac{m}{2}$ columns starting with $\frac{m}{2}$ entries of value $\frac{2}{m}$ followed by $\frac{m}{2}$ zero-entries and $\frac{m}{2}$ columns starting with $\frac{m}{2}$ zero entries followed by $\frac{m}{2}$ entries of value $\frac{2}{m}$. In $\ID_m$, $\frac{m}{2}$ columns have a one entry in the first $\frac{m}{2}$ rows and $\frac{m}{2}$ columns have a one entry in the last $\frac{m}{2}$ rows. Thus, again the identity permutation between the columns of the two matrices minimizes the $\EMD$ distance:

  \noindent
 $\POS(\ID_m,\ST_m) = 2\cdot \POS(\ID_{\frac{m}{2}},\UN_{\frac{m}{2}}) = \frac{2}{3}(\frac{m^2}{4}-1)$

  \medskip
\noindent \textbf{$\mathbf{\textbf{AN}_m}$ and $\mathbf{\textbf{ST}_m}$:} We now turn to computing the distance between $\AN_m=(\an_1,\dots , \an_m)$ and $\ST_m=(\stt_1,\dots , \stt_m)$. As all column vectors of $\AN_m$ are palindromes, each column vector of $\AN_m$ has the same $\EMD$ distance to all column vectors of $\ST_m$, i.e., for $i\in [m]$ it holds that $\EMD(\an_i,\stt_j)=\EMD(\an_i,\stt_{j'})$ for all $j,j'\in [m]$. Thus, the distance between $\AN_m$ and $\ST_m$ is the same for all permutation between the columns of the two matrices. Thus, we again use the identity permutation. 
We start by computing $\EMD(\an_i,\stt_i)$ for different $i\in [m]$ separately distinguishing two cases. Let $i\in [\frac{m}{4}]$. Recall that $\an_i$ has a $0.5$ at position $i$ and position $m-i+1$ and that $\stt_i$ has a $\frac{2}{m}$ at entries $j\in [\frac{m}{2}]$. We now analyze how to transform $\an_i$ to $\stt_i$. For all $j\in [i-1]$, it is clear that it is optimal that the value $\frac{2}{m}$ moved to position $j$ comes from position $i$. The overall cost of this is $\textstyle\sum_{j=1}^{i-1} \frac{2j}{m}$. Moreover, the remaining surplus value at position $i$ (that is, $\frac{1}{2}-\frac{2i}{m}$) needs to be moved toward the end. Thus, for $j\in [i+1,\frac{m}{4}]$, we move value $\frac{2}{m}$ from position $i$ to position $j$. The overall cost of this is  $\textstyle\sum_{j=1}^{\frac{m}{4}-i} \frac{2j}{m}$. Lastly, we need to move value $\frac{2}{m}$ to positions $j\in [\frac{m}{4}+1,\frac{m}{2}]$. This needs to come from position $m-i+1$. Thus, for each $j\in [\frac{m}{4}+1,\frac{m}{2}]$, we move value $\frac{2}{m}$ from position $m-i+1$ to position $j$. The overall cost of this is $\frac{1}{2}\cdot (\frac{m}{2}-i)+\textstyle\sum_{j=1}^{\frac{m}{4}} \frac{2j}{m}=\frac{1}{2}(\frac{m}{2}-i)+\frac{m}{16}+\frac{1}{4}$ 

Now, let $i\in [\frac{m}{4}+1,\frac{m}{2}]$. For $j\in [\frac{m}{4}]$, we need to move value $\frac{2}{m}$ from position $i$ to position $j$. The overall cost of this is $\frac{1}{2}\cdot (i-\frac{m}{4}-1)+\textstyle\sum_{j=1}^{\frac{m}{4}} \frac{2j}{m}=\frac{1}{2}\cdot (i-\frac{m}{4}-1)+\frac{m}{16}+\frac{1}{4}$. For $j\in [\frac{m}{4}+1,\frac{m}{2}]$, we need to move value $\frac{2}{m}$ from position $m-i+1$ to position $j$. The overall cost of this is $\frac{1}{2}\cdot (\frac{m}{2}-i)+\textstyle\sum_{j=1}^{\frac{m}{4}} \frac{2j}{m}=\frac{1}{2}\cdot (\frac{m}{2}-i)+\frac{m}{16}+\frac{1}{4}$. 

Observing that the case $i\in [\frac{3m}{4}+1,m]$ is symmetric to $i\in [\frac{m}{4}]$ and the case $i\in [\frac{m}{2}+1,\frac{3m}{4}]$ is symmetric to $i\in [\frac{m}{4}+1,\frac{m}{2}]$ the $\EMD$ distance between $\AN_m$ and $\ST_m$ can be computed as follows:

\noindent$\POS(\AN_m,\ST_m) = 2\cdot ( A + \frac{1}{2}\cdot (\sum_{i=1}^{\frac{m}{4}} \frac{m}{2}-i)  + \frac{m}{4}\cdot (\frac{m}{16}+\frac{1}{4})+ \frac{1}{2} \cdot (\sum_{i=\frac{m}{4}+1}^{\frac{m}{2}} \cdot (i-\frac{m}{4}-1))+\frac{m}{4}\cdot (\frac{m}{16}+\frac{1}{4})+ \frac{1}{2}\cdot (\sum_{i=\frac{m}{4}+1}^{\frac{m}{2}} \frac{m}{2}-i)+\frac{m}{4}\cdot (\frac{m}{16}+\frac{1}{4}))\\
=\frac{m^2}{48} - \frac{1}{3} + \frac{3m^2-4m}{32}  + \frac{m}{2}\cdot (\frac{m}{16}+\frac{1}{4})+  \frac{m^2-4m}{32}+\frac{m}{2}\cdot (\frac{m}{16}+\frac{1}{4})+ \frac{m^2-4m}{32}+\frac{m}{2}\cdot (\frac{m}{16}+\frac{1}{4}))\\
=\frac{m^2}{48}-\frac{1}{3}+\frac{3m^2-4m}{32}+\frac{3m}{2}(\frac{m}{16}+\frac{1}{4})+\frac{m^2-4m}{16}=(\frac{1}{48}+\frac{3}{32}+\frac{3}{32}+\frac{1}{16})m^2+(-\frac{4}{32}+\frac{3}{8}-\frac{4}{16})m\frac{1}{3}=\frac{13}{48}m^2-\frac{1}{3}$

\smallskip
\noindent with 

\noindent$A =  \textstyle\sum_{i=1}^{\frac{m}{4}}(\textstyle\sum_{j=1}^{i-1} \frac{2j}{m} + \textstyle\sum_{j=1}^{\frac{m}{4}-i} \frac{2j}{m}) = (*) = \frac{1}{6}(\frac{m^2}{16}-1) = \frac{1}{2}(\frac{m^2}{48} - \frac{1}{3})$

  \medskip

\noindent \textbf{$\mathbf{\textbf{ID}_m}$ and $\mathbf{\textbf{AN}_m}$:} Lastly, we consider $\ID_m=(\id_1,\dots , \id_m)$ and $\AN_m=(\an_1,\dots , \an_m)$. Note that, for $i\in [m]$, $\id_i$ contains a $1$ at position $i$ and $\an_i$ contains a $0.5$ at position $i$ and position $m-i$. Note further that for $i\in [\frac{m}{2}]$ it holds that $\an_i=\an_{m-i+1}$.
Fix some $i\in [\frac{m}{2}]$. For all $j\in [i,m-i+1]$ it holds that $\EMD(\an_i,\id_j)=\frac{m-2i+1}{2}$ and for all $j\in [1,i-1]\cup [m-i+2,m]$ it holds that $\EMD(\an_i,\id_j)>\frac{m-2i+1}{2}$. 
That is, for every $i\in [m]$, $\an_i$ has the same distance to all column vectors of $\ID_m$ where the one entry lies in between the two $0.5$ entries of $\an_i$ but a larger distance to all column vectors of $\ID_m$ where the one entry is above the top $0.5$ entry of $\an_i$ or below the bottom $0.5$ entry of $\an_i$. Thus, it is optimal to choose a mapping of the column vectors such that for all $i\in [m]$ it holds that $\an_i$ is mapped to a vector $\id_j$ where the one entry of $\id_j$ lies between the two $0.5$ in $\an_i$. This is, among others, achieved by the identity permutation, which we use to compute:

 \noindent
 $\POS(\ID_m,\AN_m) = 2 \textstyle\sum_{i=1}^{\frac{m}{2}} (\frac{1}{2} (m-2i+1)) 
  = \frac{m}{2}m-\frac{m}{2}(\frac{m}{2}+1)+\frac{m}{2} = \frac{m^2}{4}$
\end{proof}

