\subsection{Lemmas on Permutation Matrix}
Recall that $\rho_n$ denotes an $n\times n$ permutation matrix. It can apply to a vector $\mathbf{a}\triangleq a_{1:n}\in\mathbb{R}^n$, i.e., 
\begin{align}
	\rho_n\mathbf{a}=\rho_n[a_1,a_2,\cdots,a_n]^\top=[a_{\rho_n^{-1}(1)},a_{\rho^{-1}_n(2)},\cdots,a_{\rho^{-1}_n(n)}]^\top,
\end{align}
where $\rho^{-1}_n(i)$ denotes the original position of index $i$ before applying $\rho_n$.
Also, we define $\rho_n(i)$ as the position of index $i$ after applying $\rho_n$.
Consider a matrix $\mathbf{A}\in\mathbb{R}^{n\times n}$, the permutation matrix $\rho_n$ can swap the row of $\mathbf{A}$ by multiplying it on the left, i.e., 
\begin{align}
	\rho_n \mathbf{A}=\begin{bmatrix} a_{\rho^{-1}_n(1)1} & a_{\rho^{-1}_n(1)2}  &\cdots & a_{\rho^{-1}_n(1)n} 
		\\ a_{\rho^{-1}_n(2)1} & a_{\rho^{-1}_n(2)2} & \cdots& a_{\rho^{-1}_n(2)n}
		\\
		\vdots&\vdots&\ddots&\vdots
		\\
		a_{\rho^{-1}_n(n)1} & a_{\rho^{-1}_n(n)2} & \cdots& a_{\rho^{-1}_n(n)n}
	\end{bmatrix},
\end{align}
where $a_{ij}$ denotes the element in the $i$-th row and the $j$-th column of $\mathbf{A}$.
The permutation matrix $\rho_n$ can also swap the column of $\mathbf{A}$ by multiplying it on the right, i.e., 
\begin{align}
	\label{equ:c_swap}
	\mathbf{A}\rho_n^\top=\begin{bmatrix} a_{1\rho^{-1}_n(1)} & a_{1\rho^{-1}_n(2)}  &\cdots & a_{1\rho^{-1}_n(n)} 
		\\ a_{2\rho^{-1}_n(1)} & a_{2\rho^{-1}_n(2)} & \cdots& a_{2\rho^{-1}_n(n)}
		\\
		\vdots&\vdots&\ddots&\vdots
		\\
		a_{n\rho^{-1}_n(1)} & a_{n\rho^{-1}_n(2)} & \cdots& a_{n\rho^{-1}_n(n)}
	\end{bmatrix}.
\end{align}
We give the following lemmas on the permutation matrix for later use.
\begin{lemma}
	\label{lemma:i}
	It holds that $\rho_n^\top\rho_n=\rho_n\rho_n^\top=\mathbf{I}_n$.
\end{lemma}
\begin{proof}
	There are many ways to prove this well-known lemma. A quick way to prove it is that: $\rho_n$ both belong to the orthogonal matrix whose inverse is just its transpose.
\end{proof}

\begin{lemma}
	\label{lemma:equv}
	It holds that for any matrix $\mathbf{A}\in\mathbb{R}^{n\times n}$, we have $\mathrm{diag}(\rho_n\mathbf{A}\rho_n^\top)=\rho_n\mathrm{diag}(\mathbf{A})$.
\end{lemma}
\begin{proof}
