			\\ a_{2\rho^{-1}_n(1)} & a_{2\rho^{-1}_n(2)} & \cdots& a_{2\rho^{-1}_n(n)}
			\\
			\vdots&\vdots&\ddots&\vdots
			\\
			a_{n\rho^{-1}_n(1)} & a_{n\rho^{-1}_n(2)} & \cdots& a_{n\rho^{-1}_n(n)}
		\end{bmatrix}\bigg)
		\notag\\
		&=
		\mathrm{diag}\bigg(\begin{bmatrix} a_{\rho^{-1}_n(1)\rho^{-1}_n(1)} & a_{\rho^{-1}_n(1)\rho^{-1}_n(2)}  &\cdots & a_{\rho^{-1}_n(1)\rho^{-1}_n(n)} 
			\\ a_{\rho^{-1}_n(2)\rho^{-1}_n(1)} & a_{\rho^{-1}_n(2)\rho^{-1}_n(2)} & \cdots& a_{\rho^{-1}_n(2)\rho^{-1}_n(n)}
