				$Q_i(\mathbf{s}_t,\mathbf{a}_t;\nu,\theta)$&\makecell{the expected return in the weighted \\POMDP   starting from $(\mathbf{s}_t,\mathbf{a}_t)$\\ following $\bar{\pi}_{\nu,\theta}^i$}
				&$Q_\theta(\mathbf{s}_t,\mathbf{a}_t)$&\makecell[c]{the weighted expected return of \\all agents when all agents follow $\pi_\theta$}\\
                \midrule
$\pi_{\bar{\nu}}$ & the policy with parameter $\bar{\nu}$
&$\pi_\nu$ & the policy with parameter $\nu$\\
				\bottomrule
			\end{tabular}
		\end{small}
	\end{center}
\end{table}

Before diving into the detailed derivations of policy gradients, we introduce some extra notations used in this section in \cref{table:policy_gradient_notations}.
We also give some definitions that will be used in the proof.
\begin{definition}[Arrival Probability]
	Let $\text{Pr}\big\{\mathbf{s}\big|\mathbf{s}_0, t,\bar{\pi}\big\}$  be the probability of arriving $\mathbf{s}$ at time step $t$ when starting from $\mathbf{s}_0$ and following a product policy $\bar{\pi}$, i.e., 
	\begin{align}
		\label{equ:prob_state_t}
		\text{Pr}\big\{\mathbf{s}\big|\mathbf{s}_0,t ,\bar{\pi}\big\}\triangleq \int_{\mathbf{a}_{t-1}}\int_{\mathbf{s}_{t-1}}\cdots\int_{\mathbf{s}_{1}}\int_{\mathbf{a}_{0}}\phi(\mathbf{s}_0)\Pi_{t'=0}^{t-1}\bar{\pi}(\mathbf{a}_{t'}|\mathbf{s}_{t'})P(\mathbf{s}_{t'+1}|\mathbf{s}_{t'},\mathbf{a}_{t'})\bigg\vert_{\mathbf{s}_t=\mathbf{s}}\mathrm{d}\mathbf{a}_0\mathrm{d}\mathbf{s}_1\cdots\mathrm{d}\mathbf{s}_{t-1}\mathrm{d}\mathbf{a}_{t-1}.
	\end{align}
\end{definition}

\begin{definition}[Discounted State Distribution]
	Let 
	$d_{\bar{\pi}}(\mathbf{s})$ be the discounted distribution of a global state $\mathbf{s}$ over the course of a whole trajectory when following the product policy $\bar{\pi}$, i.e., 
	\begin{align}
		d_{\bar{\pi}}(\mathbf{s})\triangleq \int_{\mathbf{s}_0}\phi(\mathbf{s}_0)\sum_{t=0}^{T-1}
		\text{Pr}\big\{\mathbf{s}\big|\mathbf{s}_0,t, \bar{\pi}\big\}\mathrm{d}\mathbf{s}_0.
	\end{align}
\end{definition}
\begin{definition}[Expectation Under Product Policy]
	Let $\mathbf{E}_{\bar{\pi}}[f(\mathbf{s},\mathbf{a})]$ be the expectation of function $f(\mathbf{s},\mathbf{a})$ under the distribution $d_{\bar{\pi}}(\mathbf{s})\bar{\pi}(\mathbf{a}|\mathbf{s})$, i.e., 
	\begin{align}
		\mathbf{E}_{\bar{\pi}}[f(\mathbf{s},\mathbf{a})]\triangleq\int_{\mathbf{s}}\int_{\mathbf{a}}d_{\bar{\pi}}(\mathbf{s})\bar{\pi}(\mathbf{a}|\mathbf{s})f(\mathbf{s},\mathbf{a})\mathrm{d}\mathbf{a}\mathrm{d}\mathbf{s}.
	\end{align}
\end{definition}

\subsection{Derivation of $L_1(\theta)$, $ L_s(\theta,\bar{\nu})$, $L_g'(\theta,\bar{\nu})$ and $L^*_w(\theta)$}
\label{app:derivation_final_gradient}
The gradients $L_1(\theta)$, $ L_s(\theta,\bar{\nu})$, $L_g'(\theta,\bar{\nu})$ and $L^*_w(\theta)$ can be derived directly based on the classical policy gradient method \cite{sutton1999policy}. In particular, they are all in the  form of: 
\begin{align}
    \mathbb{E}_\beta [\nabla_\beta \pi_{\beta}(a|s) Q(s,a)], 
\end{align}
where $\beta$ denotes the parameter of the policy and $Q$ represents the subsequent accumulative reward starting from $(s,a)$ following $\pi_\beta$.
The specific expressions of these policy gradients are given in \cref{table:policy_gradient_summary}. In the following, we take $L_1(\theta)$ as an example, and the other three gradients can be derived in the same way.

	Recall that the definition of the cooperative gradient $L_1(\theta)$ is:
	\begin{align}
		L_1(\theta)\triangleq\sum_{i\in [N]}(1+\lambda_i)\nabla_\theta G_i(\theta).
	\end{align}
The gradient of agent $i$'s expected return $G_i(\theta)$ can be expressed as:
\begin{align}
	\label{equ:1}
	\nabla_\theta G_i(\theta) =\nabla_\theta \int_{\mathbf{s}_0}\phi(\mathbf{s}_0) V_\theta^i(\mathbf{s}_0)\mathrm{d}\mathbf{s}_0=\int_{\mathbf{s}_0}\phi(\mathbf{s}_0)\nabla_\theta V_\theta^i(\mathbf{s}_0)\mathrm{d}\mathbf{s}_0,
\end{align}
where $V^i_\theta(\mathbf{s}_t)$ denotes the value function of agent $i$, referring to its expected return when starting from $\mathbf{s}_t$ under $\bar{\pi}_\theta$.
We start with the derivation of $\nabla_\theta V_\theta^i(\mathbf{s}_0)$. Specifically, we have
\begin{align}
	\label{equ:2}
	\nabla_\theta V_\theta^i(\mathbf{s}_0)&=\nabla_\theta \bigg[\int_{\mathbf{a}_0}\bar{\pi}_\theta(\mathbf{a}_0 | \mathbf{s}_0)Q_\theta^i(\mathbf{s}_0,\mathbf{a}_0)\mathrm{d}\mathbf{a}_0\bigg]\notag\\
	&=\int_{\mathbf{a}_0}\bigg[
	\nabla_\theta\bar{\pi}_\theta(\mathbf{a}_0 | \mathbf{s}_0)Q_\theta^i(\mathbf{s}_0,\mathbf{a}_0)
	+\bar{\pi}_\theta(\mathbf{a}_0 | \mathbf{s}_0)\nabla_\theta Q_\theta^i(\mathbf{s}_0,\mathbf{a}_0)\bigg]
	\mathrm{d}\mathbf{a}_0\notag\\
	&=\int_{\mathbf{a}_0}\bigg[
	\nabla_\theta\bar{\pi}_\theta(\mathbf{a}_0 | \mathbf{s}_0)Q_\theta^i(\mathbf{s}_0,\mathbf{a}_0)
	+\bar{\pi}_\theta(\mathbf{a}_0 | \mathbf{s}_0)\nabla_\theta \bigg[r(\mathbf{s}_0,\mathbf{a}_0,i)+\int_{\mathbf{s}_1}P(\mathbf{s}_1|\mathbf{s}_0,\mathbf{a}_0)V_\theta^i(\mathbf{s}_1)\mathrm{d}\mathbf{s}_1\bigg]\bigg]
	\mathrm{d}\mathbf{a}_0\notag\\
	&=\int_{\mathbf{a}_0}
	\nabla_\theta\bar{\pi}_\theta(\mathbf{a}_0 | \mathbf{s}_0)Q_\theta^i(\mathbf{s}_0,\mathbf{a}_0)\mathrm{d}\mathbf{a}_0 + \int_{\mathbf{s}_1}
	\int_{\mathbf{a}_0}\bar{\pi}_\theta(\mathbf{a}_0 | \mathbf{s}_0)P(\mathbf{s}_1|\mathbf{s}_0,\mathbf{a}_0)\mathrm{d}\mathbf{a}_0	\nabla_\theta V_\theta^i(\mathbf{s}_1)\mathrm{d}\mathbf{s}_1\notag\\
	&=\int_{\mathbf{a}}
	\nabla_\theta\bar{\pi}_\theta(\mathbf{a} | \mathbf{s}_0)Q_\theta^i(\mathbf{s}_0,\mathbf{a})\mathrm{d}\mathbf{a}\notag\\
	&\quad + \int_{\mathbf{s}}\text{Pr}\big\{\mathbf{s}\big|\mathbf{s}_0,1,\bar{\pi}_\theta\big\}\int_{\mathbf{a}}
	\nabla_\theta\bar{\pi}_\theta(\mathbf{a} | \mathbf{s})Q_\theta^i(\mathbf{s},\mathbf{a})\mathrm{d}\mathbf{a}\mathrm{d}\mathbf{s}\notag\\
	&\quad+\int_{\mathbf{s}}\text{Pr}\big\{\mathbf{s}\big|\mathbf{s}_0,2, \bar{\pi}_\theta\big\}\int_{\mathbf{a}}
	\nabla_\theta\bar{\pi}_\theta(\mathbf{a} | \mathbf{s})Q_\theta^i(\mathbf{s},\mathbf{a})\mathrm{d}\mathbf{a}\mathrm{d}\mathbf{s}\notag\\
	&\quad+\cdots\notag\\
	&=\sum_{t=0}^{T-1}\int_{\mathbf{s}}\text{Pr}\big\{\mathbf{s}\big|\mathbf{s}_0,t,\bar{\pi}_\theta\big\}\int_{\mathbf{a}}\nabla_\theta\bar{\pi}_\theta(\mathbf{a} | \mathbf{s})Q_\theta^i(\mathbf{s},\mathbf{a})\mathrm{d}\mathbf{a}\mathrm{d}\mathbf{s},
\end{align}
where $Q^i_\theta(\mathbf{s},\mathbf{a})$ is the Q function of agent $i$, referring to its expected return when starting from $\mathbf{s}$ and $\mathbf{a}$ under $\bar{\pi}_\theta$.
Then, with the log-trick, we can express the gradient of $G_i(\theta)$ as 
\begin{align}
	\label{equ:3}
	\nabla_\theta G_i(\theta)&=\sum_{t=0}^{T-1}\int_{\mathbf{s}_0}\phi(\mathbf{s}_0)\int_{\mathbf{s}}\text{Pr}\big\{\mathbf{s}\big|\mathbf{s}_0,t;\bar{\pi}_\theta\big\}\int_{\mathbf{a}}\nabla_\theta\bar{\pi}_\theta(\mathbf{a} | \mathbf{s})Q_\theta^i(\mathbf{s},\mathbf{a})\mathrm{d}\mathbf{a}\mathrm{d}\mathbf{s}\mathrm{d}\mathbf{s}_0\notag\\
	&=\int_{\mathbf{s}}\int_{\mathbf{a}}\sum_{t=0}^{T-1}\int_{\mathbf{s}_0}\phi(\mathbf{s}_0)\text{Pr}\big\{\mathbf{s}\big|\mathbf{s}_0,t;\bar{\pi}_\theta\big\}\bar{\pi}_\theta(\mathbf{a}|\mathbf{s})\nabla_\theta\ln\bar{\pi}_\theta(\mathbf{a}|\mathbf{s})Q_\theta^i(\mathbf{s},\mathbf{a})\mathrm{d}\mathbf{a}\mathrm{d}\mathbf{s}\mathrm{d}\mathbf{s}_0\notag\\
	&=\int_{\mathbf{s}}\int_{\mathbf{a}}
	d_{\bar{\pi}_\theta}(\mathbf{s})\bar{\pi}_\theta(\mathbf{a}|\mathbf{s})
	\bigg[\nabla_\theta\ln\bar{\pi}_\theta(\mathbf{a}|\mathbf{s})Q^i_\theta(\mathbf{s},\mathbf{a})\bigg]\mathrm{d}\mathbf{a}\mathrm{d}\mathbf{s}\\\notag
	&=\mathbb{E}_{\bar{\pi}_\theta}\bigg[\nabla_\theta\ln\bar{\pi}_\theta(\mathbf{a}_t|\mathbf{s}_t,i)Q^i_\theta(\mathbf{s}_t,\mathbf{a}_t)\bigg].
\end{align}
%Note that the derivation process of $\nabla_\theta G_i(\theta)$ resembles the proof in the classical policy gradient theorem \cite{sutton1999policy}.
Then
we can obtain the cooperative gradient as:
\begin{align}
	\label{equ:coop_L_1}
	L_1(\theta)&=\sum_{i\in [N]}(1+\lambda_i)\nabla_\theta G_i(\theta)\notag\\
	&=\mathbb{E}_{\bar{\pi}_\theta}\bigg[\nabla_\theta\ln\bar{\pi}_\theta(\mathbf{a}_t|\mathbf{s}_t)\sum_{i\in [N]}(1+\lambda_i)Q^i_\theta(\mathbf{s}_t,\mathbf{a}_t)\bigg]\notag\\
	&=\mathbb{E}_{ \bar{\pi}_\theta}\bigg[\sum_{i\in[N]}\nabla_\theta\ln{{\pi}}_\theta({a}_{i,t}|{s}_{i,t},i) Q_\theta(\mathbf{s}_t,\mathbf{a}_t)\bigg],
\end{align}
where
\begin{align}
	\label{equ:coop_q}
	Q_\theta(\mathbf{s}_t,\mathbf{a}_t)\triangleq\sum_{i\in[N]}(1+\lambda_i)Q_\theta^i(\mathbf{s}_t,\mathbf{a}_t)=\mathbb{E}_{\bar{\pi}_\theta}\bigg[\sum_{t'=t}^T\sum_{i\in[N]}(1+\lambda_i) r(\mathbf{s}_{t'},\mathbf{a}_{t'},i)\big\vert\mathbf{s}_t,\mathbf{a}_t\bigg]
\end{align}
 is the weighted sum of all agents' Q functions.
 %So far, \eqref{equ:coop_L_1} and \eqref{equ:coop_q} concludes the proof.



\subsection{Derivation of the policy gradient \eqref{equ:final_gradient}}
\label{app:unified_gradient}
Denote the objective of the unified optimizer based single-level optimization problem \eqref{equ:simplified_single_level} as:
	\begin{align}
		L_p(\bar{\nu},\theta) \triangleq -\sum_{i=1}^N\bigg[G_i(\theta)+\lambda_i\bigg[G_i(\theta)-G_i(\bar{\nu};\theta)+\epsilon\bigg]\bigg] + \xi\bigg({G}_w(x^*;\theta)-{G}_w(\bar{\nu};\theta)\bigg)
	\end{align}

	We take the derivative of $L_p(\bar{\nu},\theta)$ with respect to $[\bar{\nu},\theta]$ and get:
	\begin{align}
		\nabla_{[\bar{\nu},\theta]}L_p(\bar{\nu},\theta)&=\begin{bmatrix}
			\nabla_{\bar{\nu}} \bigg[-\sum_{i=1}^N\bigg[-\lambda_iG_i(\bar{\nu};\theta)\bigg]-\xi{G}_w(\bar{\nu};\theta)\bigg]
			\\
			\nabla_\theta\bigg[-\sum_{i=1}^N\bigg[(1+\lambda_i)G_i(\theta)-\lambda_i G_i(\bar{\nu};\theta)\bigg]+\xi{G}_w(x^*)-\xi{G}(\bar{\nu};\theta)\bigg]
		\end{bmatrix}\notag\\
		&=\begin{bmatrix}
			\underbrace{\nabla_{\bar{\nu}}\bigg[\sum_{i=1}^N\lambda_iG_i(\bar{\nu};\theta)\bigg]}_{=L_g'({\bar{\nu}},\theta)}
			-\xi\underbrace{\nabla_{\bar{\nu}}{G}_w({\bar{\nu}};\theta)}_{\triangleq{L}_w({\bar{\nu}})}
			\\
			\underbrace{\nabla_\theta\bigg[-\sum_{i=1}^N\bigg[(1+\lambda_i)G_i(\theta)\bigg]\bigg]}_{=-L_1(\theta)}+\underbrace{\nabla_\theta\sum_{i=1}^N\bigg[\lambda_i G_i({\bar{\nu}};\theta)\bigg]}_{=L_s({\bar{\nu}},\theta)}+\xi\underbrace{\nabla_\theta{G}_w(x^*;\theta)}_{\triangleq {L}^*_w(\theta)}-\xi\underbrace{\nabla_\theta{G}_w({\bar{\nu}};\theta)}_{\triangleq {L}_w(\theta)}\bigg]
		\end{bmatrix}\notag
		\\
		&=\begin{bmatrix}
			L_g'({\bar{\nu}},\theta) - \xi {L}_w({\bar{\nu}})
			\\
			-L_1(\theta)+L_s({\bar{\nu}},\theta)+\xi{L}_w^*(\theta)-\xi{L}_w(\theta)
		\end{bmatrix}
	\end{align}

Recall that the sample ratio of the weighted POMDP is designed as $\kappa_i=\frac{\lambda_i}{\bar{\lambda}}$. Hence, we have 
\begin{align}
	 \label{equ:G}{G}_w(\bar{\nu};\theta)=\mathbb{E}_{\frac{\lambda_i}{\bar{\lambda}} \phi_i,\bar{\pi}_{\bar{\nu},\theta}}\bigg[\sum_{t\in[T]} \bar{r}_t\bigg]
    % \notag\\
	% &
    =\mathbb{E}_{\frac{\lambda_i}{\bar{\lambda}} \phi_i,\bar{\pi}_{\bar{\nu},\theta}}\bigg[\sum_{t\in[T]} {r}_{i,t}\bigg]
 %    \notag
 %    \\
	% &
    =\sum_{i\in[N]}\frac{\lambda_i}{\bar{\lambda}}\mathbb{E}_{\phi_i,\bar{\pi}_{\bar{\nu},\theta}}\bigg[\sum_{t\in[T]}r_{i,t}\bigg]
 %    \notag\\
	% &
    =\sum_{i\in[N]}\frac{\lambda_i}{\bar{\lambda}}G_i(\bar{\nu};\theta).
\end{align}
Hence, $L_w(\theta)$ and $L_w(\bar{\nu})$ can be expressed as:
\begin{align}
	L_w(\theta)=\nabla_\theta {G}_w(\bar{\nu};\theta)=\sum_{i\in[N]}\frac{\lambda_i}{\bar{\lambda}}\nabla_\theta G_i(\nu;\theta)=\frac{L_s(\bar{\nu},\theta)}{\bar{\lambda}},\\
    L_w(\bar{\nu})=\nabla_{\bar{\nu}} {G}_w(\bar{\nu};\theta)=\sum_{i\in[N]}\frac{\lambda_i}{\bar{\lambda}}\nabla_{\bar{\nu}} G_i(\nu;\theta)=\frac{L_g'(\bar{\nu},\theta)}{\bar{\lambda}}.
\end{align}
With the above equations, the gradient of \eqref{equ:simplified_single_level} can be simplified to:
\begin{align}
      \begin{bmatrix}
	  	\Delta\theta\\
		\Delta\bar{\nu}
	\end{bmatrix}=
\begin{bmatrix}
		\xi L_w^*(\theta)+(1-\xi/\bar{\lambda})L_s(\theta, \bar{\nu})-L_1(\theta)\\
		(1-\xi/\bar{\lambda})L_g'(\theta,\bar{\nu})
	\end{bmatrix}.
\end{align}
This is the expression presented in \eqref{equ:final_gradient}.

\subsubsection{A Special Case When $\bar{\lambda}=0$}
\label{app:lambda_zero}
When $\bar{\lambda}=0$, each Lagrange factor $\lambda_i$ is zero, which indicates that the $\epsilon$-NE is fully satisfied. In this case, from the expressions of $L_s(\theta\,\bar{\nu})$ and $L_g'(\theta,\bar{\nu})$ which are proportional to $\lambda_i$, we have $L_g'(\theta,\bar{\nu})=L_s(\theta\,\bar{\nu})=0$.
In addition,
the sample ratios $\kappa_i$ of the weighted POMDP are zero, and from \eqref{equ:G}, we have $G_w(\bar{\nu},\theta)=0$. This means that we do not need to construct the weighted POMDP, and hence $L^*_w(\theta)=0$. Then we have
\begin{align}
      \begin{bmatrix}
	  	\Delta\theta\\
		\Delta\bar{\nu}
	\end{bmatrix}=
\begin{bmatrix}
		-L_1(\theta)\\
	0
	\end{bmatrix}.
\end{align}


\subsection{Derivation of the Complex Gradient $\nabla_\theta \nu_{i,\theta}$}
\label{app:second_order}

% \textbf{Temporary Notations in this subsection.} 
% Due to the numerous symbols used in this subsection, we will simplify some of the notations for ease of reading as follows. 
%  We use $r^t_i$, $\bar{\pi}_\nu^t$, $\bar{\pi}_\theta^t$, $\bar{\pi}^t_{\nu,\theta}$, $V_i^t$ and $Q_i^t$ to represent $r(\mathbf{s}_t,\mathbf{a}_t, i)$, $\bar{\pi}_\nu({a}_{i,t}|s_{i,t})$,
%  $\bar{\pi}_{\theta}(\mathbf{a}_{-i,t}|\mathbf{s}_{-i,t})$, $\bar{\pi}_{\nu,\theta}(\mathbf{a}_t|\mathbf{s}_t)$, $V_i(\mathbf{s}_t;\nu,\theta)$ and $Q_i(\mathbf{s}_t,\mathbf{a}_t;\nu,\theta)$, respectively, namely the reward, the policy in the weighted POMDP, the other joint policy in the weighted POMDP as defined in Definition \ref{def:other_joint_policy_weight_pomdp},
%  the joint policy in the weighted POMDP as defined in Definition \ref{def:joint_policy_weight_pomdp}, the value function and the action value function in the weighted POMDP, respectively. 

With the first-order optimality condition (where we suppose $\nu_{i,\theta}$ is exactly the global or local solution to the $i$-th unilateral optimization problem, otherwise it would even harder to derive the analytical expression), we have
	\begin{align}
		\nabla_\nu {G}_i(\nu;\theta)\bigg |_{\nu=\nu_{i,\theta}}=0.
	\end{align}
	The left-hand side (LHS) is a function of two variables, including $\nu_{i,\theta}$ and $\theta$. We take the derivative with respect to $\theta$ on both sides. With the multi-variable chain rule, we have
	\begin{align}
		\label{equ:nu_theta}
		\nabla_\theta\bigg(\nabla_\nu {G}_i(\nu;\theta)\bigg |_{\nu=\nu_{i,\theta}}\bigg)&=
		\nabla_\theta\nu_{i,\theta}\nabla_{\nu}\bigg(	\nabla_\nu {G}_i(\nu;\theta)\bigg |_{\nu=\nu_{i,\theta}}\bigg)_{\nu_{i,\theta}=\nu}\bigg |_{\nu=\nu_{i,\theta}}+\nabla_\theta\bigg(\nabla_\nu {G}_i(\nu;\theta)\bigg |_{\nu=\nu_{i,\theta}}\bigg)\notag\\
		&=	\nabla_\theta\nu_{i,\theta}\nabla^2_\nu {G}_i(\nu;\theta)\bigg |_{\nu=\nu_{i,\theta}}+\nabla^2_{\theta,\nu} {G}_i(\nu;\theta)\bigg |_{\nu=\nu_{i,\theta}}\notag\\
		&=0.
	\end{align}
	Note that the term $\nabla_\theta(\nabla_\nu G_i(\nu;\theta)\big|_{\nu=\nu_{i,\theta}})$ in the above equation only takes the derivative with respective to $\theta$, not $\nu_{i,\theta}$. Hence, it is equivalent to $\nabla^2_{\theta,\nu} G_i(\nu;\theta)\big|_{\nu=\nu_{i,\theta}}$. From \eqref{equ:nu_theta}, we can get
	\begin{align}
		\nabla_\theta\nu_{i,\theta}=-\bigg(\nabla^2_{\theta,\nu} {G}_i(\nu;\theta)\bigg |_{\nu=\nu_{i,\theta}}\bigg)^\top\bigg(
		\nabla^2_\nu {G}_i(\nu;\theta)\bigg |_{\nu=\nu_{i,\theta}}\bigg)^{-1}=-\mathbf{J}_i(\nu,\theta)^\top\mathbf{H}_i(\nu,\theta)^{-1}\bigg |_{\nu=\nu_{i,\theta}}.
	\end{align}
	The derivations of the expressions of $\mathbf{J}(\nu,\theta)$ and $\mathbf{H}(\nu,\theta)$ are given in the next two sections, respectively. 

    For simplicity, in the following, we use $V_i^{t}$ and $Q_i^t$ to represent the value function and the action value function of agent $i$ at time step $t$.


\subsubsection{Jacobian Matrix}
\label{app:competitive_gradient_J}

{The Jacobian matrix} can be expressed as  
\begin{align}
	\label{equ:0}
	\nabla^2_{\theta,\nu} G_i(\nu;\theta)&=\int_{\mathbf{s}_0}\phi(\mathbf{s}_0)	\nabla^2_{\theta,\nu}{V}^t_i\mathrm{d}\mathbf{s}_0\notag\\
	&=\int_{\mathbf{s}_0}\phi(\mathbf{s}_0)\int_{\mathbf{a}_0}\bigg[\nabla^2_{\theta,\nu}\bar{\pi}^t_{\nu,\theta}Q_i^0+\nabla_{\nu}\bar{\pi}_{\nu,\theta}^0(\nabla_{\theta}Q_i^0)^\top+\nabla_{\nu}Q_i^0(\nabla_{\theta}\bar{\pi}_{\nu,\theta}^0)^\top\notag\\
	&+\bar{\pi}^t_{\nu,\theta}\nabla^2_{\theta,\nu}Q_i^0\bigg]\mathrm{d}\mathbf{a}_0\mathrm{d}\mathbf{s}_0.
\end{align}
Let us derive the expressions of each of the four differentiating terms in the square bracket at any time step $t$. For the first term, with the log-trick, we have:
\begin{align}
	\label{equ:compet_1}
	\nabla^2_{\theta,\nu}\bar{{\pi}}^t_{\nu,\theta}Q_i^t&=\nabla_\theta\bigg(\bar{\pi}^t_{\nu,\theta}\frac{\nabla_{\nu}\bar{\pi}^t_{\nu,\theta}}{\bar{\pi}^t_{\nu,\theta}}\bigg)Q_i^t\notag\\
	&=\bigg[\nabla_{\nu}\ln\bar{\pi}^t_{\nu,\theta}(	\nabla_\theta\bar{\pi}^t_{\nu,\theta})^\top + \bar{\pi}^t_{\nu,\theta}\nabla^2_{\theta, \nu}\ln\bar{\pi}^t_{\nu,\theta} \bigg]
	Q_i^t\notag\\
	&=\bigg[\nabla_{\nu}\ln\bar{\pi}^t_{\nu,\theta}\bigg(\bar{\pi}^t_{\nu,\theta}\frac{\nabla_\theta\bar{\pi}^t_{\nu,\theta}}{\bar{\pi}^t_{\nu,\theta}}\bigg)^\top+0\bigg]
	Q_i^t\notag\\
	&=\bar{\pi}^t_{\nu,\theta}\nabla_{\nu}\ln\bar{\pi}^t_{\nu,\theta}(\nabla_\theta\ln\bar{\pi}^t_{\nu,\theta})^\top Q_i^t.
\end{align}
For the second term, we have $\nabla_{\nu}\bar{\pi}_{\nu,\theta}^t=\bar{\pi}_{\nu,\theta}^t\nabla_{\nu}\ln\bar{\pi}_{\nu,\theta}^t$ and 
\begin{align}
	\label{equ:compet_2}
	\nabla_{\theta}Q_i^t&=\nabla_{\theta}\bigg[r_i^t+\sum_{\mathbf{s}_{t+1}}P(\mathbf{s}_{t+1}|\mathbf{s}_t,\mathbf{a}_t)V_i^{t+1}\bigg]\notag\\
	&=\int_{\mathbf{s}_{t+1}}P(\mathbf{s}_{t+1}|\mathbf{s}_t,\mathbf{a}_t)\nabla_{\theta}V_i^{t+1}\mathrm{d}\mathbf{s}_{t+1}\notag\\
	&=\int_{\mathbf{s}}\text{Pr}\big\{\mathbf{s}|\mathbf{s}_0, t+1, \bar{\pi}_{\nu,\theta}\big\}\int_{\mathbf{a}}\bar{\pi}_{\nu,\theta}(\mathbf{a}|\mathbf{s})\nabla_{\theta}\ln \bar{\pi}_{\nu,\theta}(\mathbf{a}|\mathbf{s})Q_i(\mathbf{s},\mathbf{a};\nu,\theta)\mathrm{d}\mathbf{a}\mathrm{d}\mathbf{s}\notag\\
	&\quad+\int_{\mathbf{s}}\text{Pr}\big\{\mathbf{s}|\mathbf{s}_0, t+2, \bar{\pi}_{\nu,\theta}\big\}\int_{\mathbf{a}}\bar{\pi}_{\nu,\theta}(\mathbf{a}|\mathbf{s})\nabla_{\theta}\ln \bar{\pi}_{\nu,\theta}(\mathbf{a}|\mathbf{s})Q_i(\mathbf{s},\mathbf{a};\nu,\theta)\mathrm{d}\mathbf{a}\mathrm{d}\mathbf{s}\notag\\
	&\quad+\cdots\notag\\
	&=\sum_{t'=t+1}^{T-1}\int_{\mathbf{s}}\text{Pr}\big\{\mathbf{s}|\mathbf{s}_0, t', \bar{\pi}_{\nu,\theta}\big\}\int_{\mathbf{a}}\bar{\pi}_{\nu,\theta}(\mathbf{a}|\mathbf{s})\nabla_{\theta}\ln \bar{\pi}_{\nu,\theta}(\mathbf{a}|\mathbf{s})Q_i(\mathbf{s},\mathbf{a};\nu,\theta)\mathrm{d}\mathbf{a}\mathrm{d}\mathbf{s},
\end{align}
%where $\text{Pr}\big\{\mathbf{s}|\mathbf{s}_0, t', \bar{\pi}_{\nu,\theta}\big\}$ denotes the probability of being state $s$ at time step $t'$ starting from $\mathbf{s}_{t}$ under joint policy $\bar{\pi}_{\nu,\theta}$.
As the policy with $\nu_{i,\theta}$ maximizes the accumulative return $\bar{G}(\nu;\theta)$ of the $i$-th agent, it also maximizes its value function $V_i^t$ and its Q function $Q_i^t$. With the first order optimality condition, we have $\forall t$:
\begin{align}
	\label{equ:compet_3}
	\nabla_{\nu}V_i^t\bigg|_{\nu=\nu_{i,\theta}} = \nabla_{\nu}Q_i^t\bigg|_{\nu=\nu_{i,\theta}} =\mathbf{0}.
\end{align}
Hence, the third term will always be zero when substituting $\nu$ by $\nu_{i,\theta}$. As for the fourth term, the second derivative $\nabla^2_{\theta,\nu}Q_i^t$ can be expanded as:
\begin{align}
	\label{equ:compet_4}
	\nabla^2_{\theta,\nu}Q_i^t&=	\int_{\mathbf{s}_{t+1}}P(\mathbf{s}_{t+1}|\mathbf{s}_t,\mathbf{a}_t)\nabla^2_{\theta,\nu}V_i^{t+1}\mathrm{d}\mathbf{s}_{t+1}\notag\\
	&=\int_{\mathbf{s}_{t+1}}P(\mathbf{s}_{t+1}|\mathbf{s}_t,\mathbf{a}_t)\int_{\mathbf{a}_{t+1}}\bigg[\nabla^2_{\theta,\nu}\bar{\pi}^{t+1}_{\nu,\theta}Q_i^{t+1}+\nabla_{\nu}\bar{\pi}_{\nu,\theta}^{t+1}(\nabla_{\theta}Q_i^{t+1})^\top+\nabla_{\nu}Q_i^{t+1}(\nabla_{\theta}\bar{\pi}_{\nu,\theta}^{t+1})^\top\notag\\
	&\quad+\bar{\pi}^{t+1}_{\nu,\theta}\nabla^2_{\theta,\nu}Q_i^{t+1}\bigg]\mathrm{d}\mathbf{a}_{t+1}\mathrm{d}\mathbf{s}_{t+1},
\end{align}
which induces the four derivative terms in the next time step. Hence, iteratively substituting the term $	\nabla^2_{\theta,\nu}Q_i^t$ in \eqref{equ:0} by \eqref{equ:compet_4}, we can express $	\nabla^2_{\theta,\nu} G_i(\nu;\theta)$ by the sum of the weighted sequential sum of the first three terms in the square bracket of \eqref{equ:0}, which are denoted as \ding{172}, \ding{173} and \ding{174}, respectively, i.e., $\nabla^2_{\theta,\nu} G_i(\nu;\theta)=\text{\ding{172}+\ding{173}+\ding{174}}$.
With \eqref{equ:compet_1}, the weighted sequential sum of the first term can be expressed as 
\begin{align}
	\text{\large\ding{172}}&=\int_{\mathbf{s}}\int_{\mathbf{a}}\sum_{t=0}^{T-1}\phi(\mathbf{s}_0)\text{Pr}\big\{\mathbf{s}|\mathbf{s}_0,t,\bar{\pi}_{\nu,\theta}\big\}\bar{\pi}_{\nu,\theta}(\mathbf{a}|\mathbf{s})\nabla_{\nu}\ln\bar{\pi}_{\nu,\theta}(\mathbf{a}|\mathbf{s})(\nabla_\theta\ln\bar{\pi}_{\nu,\theta}^t)^\top Q_i(\mathbf{s},\mathbf{a};\nu,\theta)\mathrm{d}\mathbf{a}\mathrm{d}\mathbf{s}\notag\\
	&=\mathbb{E}_{\bar{\pi}_{\nu,\theta}}\bigg[\sum_{t=0}^{T-1}\nabla_{\nu}\ln\bar{\pi}_{\nu,\theta}^t(\nabla_\theta\ln\bar{\pi}_{\nu,\theta}^t)^\top Q_i^t\bigg],
\end{align}
%where $\text{Pr}\big\{\mathbf{s}|\nu,\theta,t\big\}$ denotes the probability of being state $\mathbf{s}$ at time step $t$ under joint policy $\bar{\pi}_{\nu,\theta}$ with $\phi(\mathbf{s}_0)$ as the initial state distribution.
With \eqref{equ:compet_2}, we can further compute \ding{173} as:
\begin{align}
	\text{\large\ding{173}}&=\int_{\mathbf{s}}\sum_{t=1}^{T-1}\text{Pr}\big\{\mathbf{s}|\mathbf{s}_0, t, \bar{{\pi}}_{\nu, \theta}\big\}\nabla_{\nu}\ln\bar{\pi}^t_{\nu,\theta}\int_{\mathbf{a}}\bar{\pi}_{\nu,\theta}(\mathbf{a}|\mathbf{s})(\nabla_{\theta}\ln\bar{\pi}_{\nu,\theta}(\mathbf{a}|\mathbf{s}))^\top Q_i(\mathbf{s},\mathbf{a};
	\nu,\theta)\mathrm{d}\mathbf{a}\mathrm{d}\mathbf{s}\notag\\
	&\quad+\int_{\mathbf{s}}\sum_{t=2}^{T-1}\text{Pr}\big\{\mathbf{s}|\mathbf{s}_0, t, \bar{{\pi}}_{\nu, \theta}\big\}\nabla_{\nu}\ln\bar{\pi}^1_{\nu,\theta}\int_{\mathbf{a}}\bar{\pi}_{\nu,\theta}(\mathbf{a}|\mathbf{s})(\nabla_{\theta}\ln\bar{\pi}_{\nu,\theta}(\mathbf{a}|\mathbf{s}))^\top Q_i(\mathbf{s},\mathbf{a};
	\nu,\theta)\mathrm{d}\mathbf{a}\mathrm{d}\mathbf{s}\notag\\
	&\quad+\cdots\notag\\
	&=\int_{\mathbf{s}}\int_{\mathbf{a}}\text{Pr}\big\{\mathbf{s}|\mathbf{s}_0, 1, \bar{{\pi}}_{\nu, \theta}\big\}\bar{\pi}_{\nu,\theta}(\mathbf{a}|\mathbf{s})\nabla_{\nu}\ln\bar{\pi}^t_{\nu,\theta}(\nabla_{\theta}\ln\bar{\pi}_{\nu,\theta}(\mathbf{a}|\mathbf{s}))^\top Q_i(\mathbf{s},\mathbf{a};
	\nu,\theta)\mathrm{d}\mathbf{a}\mathrm{d}\mathbf{s}\notag\\
	&\quad+\int_{\mathbf{s}}\int_{\mathbf{a}}\text{Pr}\big\{\mathbf{s}|\mathbf{s}_0, 2, \bar{{\pi}}_{\nu, \theta} \big\}\bar{\pi}_{\nu,\theta}(\mathbf{a}|\mathbf{s})\big(\nabla_{\nu}\ln\bar{\pi}^t_{\nu,\theta}+\nabla_{\nu}\ln\bar{\pi}^1_{\nu,\theta}\big)(\nabla_{\theta}\ln\bar{\pi}_{\nu,\theta}(\mathbf{a}|\mathbf{s}))^\top Q_i(\mathbf{s},\mathbf{a};
	\nu,\theta)\mathrm{d}\mathbf{a}\mathrm{d}\mathbf{s}\notag\\
	&\quad+\cdots\notag\\
	&=\mathbb{E}_{\bar{\pi}_{\nu,\theta}}\bigg[\sum_{t=1}^{T-1}\bigg(\sum_{t'=0}^{t-1}\nabla_{\nu}\ln\bar{\pi}^{t'}_{\nu,\theta}\bigg)(\nabla_{\theta}\ln\bar{\pi}_{\nu,\theta}^t)^\top Q_i^t\bigg].
\end{align}
Due to \eqref{equ:compet_3}, any term with $\nabla_{\nu}Q_i^t$ will be zero when we assign $\nu$ by $\nu_{i,\theta}$ later on. Hence, we know:
\begin{align}
	\text{\large\ding{174}}\bigg |_{\nu=\nu_{i,\theta}}=0.
\end{align}
Overall, the Jacobian matrix with $\nu=\nu_{i,\theta}$ can be expressed as:
\begin{align}
	\nabla_{\theta,\nu}^2G_i(\nu;\theta)\bigg|_{\nu=\nu_{i,\theta}}&=\text{\large\ding{172}}\bigg|_{\nu=\nu_{i,\theta}}+\text{\large\ding{173}}\bigg|_{\nu=\nu_{i,\theta}}+\text{\large\ding{174}}\bigg|_{\nu=\nu_{i,\theta}}\notag\\
	&=\mathbb{E}_{\bar{\pi}_{\nu,\theta}}\bigg[\sum_{t=1}^{T-1}\bigg(\sum_{t'=0}^{t-1}\nabla_{\nu}\ln\bar{\pi}^{t'}_{\nu,\theta}+\nabla_{\nu}\ln\bar{\pi}^{t}_{\nu,\theta}\bigg)(\nabla_{\theta}\ln\bar{\pi}_{\nu,\theta}^t)^\top Q_i^t\bigg]_{\nu=\nu_{i,\theta}}\notag\\
	&=\mathbb{E}_{\bar{\pi}_{\nu,\theta}}\bigg[\sum_{t=1}^{T-1}\bigg(\sum_{t'=0}^{t}\nabla_{\nu}\ln\bar{\pi}^{t'}_{\nu,\theta}\bigg)(\nabla_{\theta}\ln\bar{\pi}_{\nu,\theta}^t)^\top Q_i^t\bigg]_{\nu=\nu_{i,\theta}}\notag\\
	&=\mathbb{E}_{\bar{\pi}_{\nu,\theta}}\bigg[\sum_{t=1}^{T-1}\bigg(\sum_{t'=0}^{t}\nabla_{\nu}\ln\bar{\pi}_{\nu}^t\bigg)(\nabla_{\theta}\ln\bar{\pi}_{\theta}^t)^\top Q_i^t\bigg]_{\nu=\nu_{i,\theta}}.
\end{align}
\subsubsection{Hessian Matrix}
\label{app:competitive_gradient_H}
{The Hessian matrix} can be expressed as:
\begin{align}
	\nabla^2_{\nu} G_i(\nu;\theta)&=\int_{\mathbf{s}_0}\phi(\mathbf{s}_0)	\nabla^2_{\nu}V_i^t\mathrm{d}\mathbf{s}_0\notag\\
	&=\int_{\mathbf{s}_0}\phi(\mathbf{s}_0)\int_{\mathbf{a}_0}\bigg[\nabla^2_{\nu}\bar{\pi}^t_{\nu,\theta}Q_i^0+\nabla_{\nu}\bar{\pi}_{\nu,\theta}^0(\nabla_{\nu}Q_i^0)^\top+\nabla_{\nu}Q_i^0(\nabla_{\nu}\bar{\pi}_{\nu,\theta}^0)^\top+\bar{\pi}^t_{\nu,\theta}\nabla^2_{\nu}Q_i^0\bigg]\mathrm{d}\mathbf{a}_0\mathrm{d}\mathbf{s}_0.
\end{align}
Due to the first-order optimality shown in \eqref{equ:compet_3}, the second and third terms are zero when assigning $\nu_{i,\theta}$ to $\nu$ after differentiating. Hence, we can safely omit the $\nabla_{\nu}Q_i^t,\forall t$ terms. In addition, the second derivative of the joint policy $\nabla_{\nu}^2\bar{\pi}^t_{\nu,\theta}$ can be written as:
\begin{align}
	\nabla_{\nu}^2\bar{\pi}^t_{\nu,\theta}=\nabla_{\nu}\bigg(\bar{\pi}^t_{\nu,\theta}\nabla_{\nu}\ln \bar{\pi}^t_{\nu,\theta}\bigg)=\bar{\pi}^t_{\nu,\theta}\bigg[\nabla_{\nu}\ln \bar{\pi}^t_{\nu,\theta}(\nabla_{\nu}\ln \bar{\pi}^t_{\nu,\theta})^\top+\nabla_{\nu}^2\ln \bar{\pi}^t_{\nu,\theta}\bigg].
\end{align}
Then the Hessian matrix can be further computed as:
\begin{align}
	\nabla^2_{\nu} G_i(\nu;\theta)\bigg|_{\nu=\nu_{i,\theta}}
	&=\int_{\mathbf{s}_0}\phi(\mathbf{s}_0)\int_{\mathbf{a}_0}\bigg[\nabla^2_{\nu}\bar{\pi}^t_{\nu,\theta}Q_i^0+\bar{\pi}^t_{\nu,\theta}\nabla^2_{\nu}Q_i^0\bigg]\mathrm{d}\mathbf{a}_0\mathrm{d}\mathbf{s}_0\notag\\
	&=\int_{\mathbf{s}_0}\phi(\mathbf{s}_0)\int_{\mathbf{a}_0}\bar{\pi}^t_{\nu,\theta}\bigg[\nabla_{\nu}\ln \bar{\pi}^t_{\nu,\theta}(\nabla_{\nu}\ln \bar{\pi}^t_{\nu,\theta})^\top+\nabla_{\nu}^2\ln \bar{\pi}^t_{\nu,\theta}\bigg]Q_i^0\mathrm{d}\mathbf{a}_0\mathrm{d}\mathbf{s}_0\notag\\
	&\quad+\int_{\mathbf{s}_0}\phi(\mathbf{s}_0)\int_{\mathbf{a}_0}\bar{\pi}^0_{\nu,\theta}\int_{\mathbf{s}_1}P(\mathbf{s}_1|\mathbf{s}_0,\mathbf{a}_0)\int_{\mathbf{a}_1}\bar{\pi}^1_{\nu,\theta}\bigg[\nabla_{\nu}\ln \bar{\pi}^1_{\nu,\theta}(\nabla_{\nu}\ln \bar{\pi}^1_{\nu,\theta})^\top+\nabla_{\nu}^2\ln \bar{\pi}^1_{\nu,\theta}\bigg]\notag\\
	&\quad Q_i^1\mathrm{d}\mathbf{a}_1\mathrm{d}\mathbf{s}_1\mathrm{d}\mathbf{a}_0\mathrm{d}\mathbf{s}_0+\cdots\bigg|_{\nu=\nu_{i,\theta}}\notag\\
	&=\int_\mathbf{s}\int_\mathbf{a}\sum_{t=0}^{T-1}\text{Pr}\big\{\mathbf{s}|\mathbf{s}_0, t, \bar{\pi}_{\nu,\theta}\big\}\bar{\pi}^t_{\nu,\theta}\bigg[\nabla_{\nu}\ln \bar{\pi}^t_{\nu,\theta}(\nabla_{\nu}\ln \bar{\pi}^t_{\nu,\theta})^\top+\nabla_{\nu}^2\ln \bar{\pi}^t_{\nu,\theta}\bigg]_{\nu=\nu_{i,\theta}}Q_i^t\mathrm{d}\mathbf{a}\mathrm{d}\mathbf{s}\notag\\
	&=\mathbb{E}_{\bar{\pi}_{\nu,\theta}}\bigg[\sum_{t=0}^{T-1}\bigg[\nabla_{\nu}\ln \bar{\pi}^t_{\nu}(\nabla_{\nu}\ln \bar{\pi}^t_{\nu})^\top+\nabla_{\nu}^2\ln \bar{\pi}^t_{\nu}\bigg]Q_i^t\bigg]_{\nu=\nu_{i,\theta}}.
\end{align}

\section{Proof of \cref{thm:equivalence}}
\label{app:proof_equivalence}

To prove \cref{thm:equivalence}, we first introduce the $\gamma$-approximate problem of \eqref{equ:primal_domain_objective}, and then show the equivalence between the $\gamma$-approximate problem and \eqref{equ:single_level}.

\subsection{$\gamma$-Approximate Problem of \eqref{equ:primal_domain_objective}}
\label{app:gamma_approx}
Recall that the bi-level optimization problem \eqref{equ:primal_domain_objective} in the primal domain update is
\begin{align}
	\theta\leftarrow \arg\min_\theta L(\theta,\lambda,\nu_\theta)
    \quad\;\mathrm{s.t.} \;\;\nu_{i,\theta}\in \arg\max_{\pi_i} {G}_i(\pi_i;\theta),\; \forall i.
\end{align}
Let $S(\theta)\triangleq \arg\max_\nu\mathbf{{G}}(\nu;\theta)$ be the space of $\nu_\theta$, where $\mathbf{G}\triangleq [G_1,\cdots, G_N]$.
Define the distance between $\nu$ and $S(\theta)$ as:
\begin{align}
	d_{S(\theta)}(\nu)\triangleq \min_{\nu'\in S(\theta)}\|\nu-\nu'\|.
\end{align}
We claim that under  \cref{assump:single_level}, the design
\begin{align}
	\omega(\nu,\theta)\triangleq\left\|\mathbf{G}(\nu_\theta;\theta)-\mathbf{G}(\nu;\theta)\right\|
\end{align} 
is an upper bound of $\frac{\mu}{4}d_{S(\theta)}(\nu)$. Besides,  as $S(\theta)$ is typically a close set, we have:
\begin{align}
	\omega(\nu,\theta)=0\;\; \text{if and only if} \;\;\nu\in S(\theta)\quad \Rightarrow \quad
	\omega(\nu,\theta)=0\;\; \text{if and only if} \;\;
	d_{S(\theta)}(\nu)=0.
\end{align}
Importantly, from Assumption \ref{assump:single_level}, we know $\exists\mu\in\mathbb{R}_+$, such that $\forall \theta$, we have $	\|\nabla_{\nu_i}{G}_i(\nu_i;\theta)\|^2_2\ge\frac{1}{\mu}\big({G}_i(\nu_\theta;\theta)-{G}_i(\nu_i;\theta)\big)$. This suggests that ${G}_i(\nu,\theta)$ satisfies the \emph{Polyak-Lojasiewicz} (PL) condition. From Theorem 2 in \cite{PL_QG}, we know that PL condition implies the \emph{Quadratic Growth} (QG) condition with the same constant, i.e., 
\begin{align}
	\|\nabla_{\nu_i}{G}_i(\nu_i;\theta)\|^2_2\ge{\mu}\big({G}_i(\nu_{i,\theta};\theta)-{G}_i(\nu_i;\theta)\big)\ge \frac{\mu^2}{4}\left\|\nu_i-\nu_{i,\theta}\right\|_2^2.
\end{align}
As $\left\|\nu_i-\nu_{i,\theta}\right\|_2^2 \le d_{S(\theta)}(\nu_i)$, we have:
\begin{align}
	\omega(\nu_i,\theta)\ge \frac{\mu}{4}\left\|\nu_i-\nu_{i,\theta}\right\|_2^2\ge\frac{\mu}{4}d_{S(\theta)}(\nu_i).
\end{align}
Hence, $\omega(\nu_i,\theta)$ is an upper bound of $\frac{\mu}{4}d_{S(\theta)}(\nu_i)$. 
We construct a single-level optimization problem as:
\begin{align}
	\label{equ:gamma_approx}
	\gamma-\text{Approximate}:\quad
\max_{\nu,\theta} L(\theta,\lambda, \nu)\;\;\mathrm{s.t.}\; \omega(\nu,\theta)\le \gamma.
\end{align}
The constraint $\omega(\nu,\theta)\le \gamma$ indicates that $\frac{\mu}{4}d_{S(\theta)}(\nu)$ is upper bounded by $\gamma$. Hence, we can view the global or local solution to \eqref{equ:gamma_approx} as nearly the global or local solution to \eqref{equ:primal_domain_objective}.

\subsection{Equivalence between \eqref{equ:gamma_approx} and \eqref{equ:primal_domain_objective}}
\label{app:equivalence_problems}
Next, we show the equivalence between \eqref{equ:gamma_approx} and \eqref{equ:primal_domain_objective} by adapting Proposition 1 and Proposition 2 in \cite{shen2023penalty} as two lemmas. 
\begin{lemma}[Relation on Global Solutions, Proposition 1 in \cite{shen2023penalty}]
	Under  \cref{assump:single_level},
	given $\delta>0$, 
let $\xi\ge Z\sqrt{({\mu\delta})^{-1}}$, 
	If $(\nu_\xi,\theta_\xi)$ is a global solution to \eqref{equ:primal_domain_objective}, then it is a global solution to \eqref{equ:gamma_approx} with $\gamma\le \delta$.
\end{lemma}
\begin{lemma}[Relation on Local Solutions, Proposition 2 in \cite{shen2023penalty}]Under  \cref{assump:single_level},
	given $\delta>0$, 
	let $\xi\ge Z\sqrt{3({\mu\delta})^{-1}}$, 
	If $(\nu_\xi,\theta_\xi)$ is a global solution to \eqref{equ:primal_domain_objective}, then it is a global solution to \eqref{equ:gamma_approx} with $\gamma\le \delta$.
\end{lemma}
Note that we should let $\xi$ big enough, i.e., 
\begin{align}
	\xi\ge\max\{Z\sqrt{3(\mu\delta)^{-1}},Z\sqrt{(\mu\delta)^{-1}}\}=Z\sqrt{3(\mu\delta)^{-1}}\ge Z\sqrt{3/\mu\gamma},
\end{align}
to ensure the equivalence between \eqref{equ:gamma_approx} and \eqref{equ:primal_domain_objective}.

 Section \ref{app:gamma_approx} and Section \ref{app:equivalence_problems} together conclude the proof of \cref{thm:equivalence}.



\section{Proof of \cref{thm:pe}}
\label{app:proof_pe}

	Recall that the allocation mechanism is $g: \mathcal{X}^N\times\mathcal{A}^N\times\mathcal{Y}\rightarrow\{0,1\}^N$ and the pricing mechanism is $u: \mathcal{X}^N\times\mathcal{A}^N\times\mathcal{Y}\rightarrow\mathbb{R}_+^N$, as described in Section \ref{sec:pre}.
	Denote the contextual features of all advertisers as $\mathbf{x}\triangleq x_{1:N}\in\mathcal{X}^N$, where $x_i$ represents the contextual feature of advertiser $i$.
	Consider a specific impression opportunity with contextual feature $y$.
	The value of the impression opportunity with respect to advertiser $i$, denoted as $v_i\in\mathbb{R}_+$, is typically related to their contextual features \footnote{Note that strictly speaking, it should be assumed that the value of the impression opportunity with respect to advertiser $i$ is typically related to their contextual features. Nonetheless, as is often the case in practice and as this is a common setting in many other works \cite{PE_auction}, we directly use it here without additional assumptions.}, i.e., $v_i = v_i(x_i,y)$, and the values for all advertisers can be denoted as $\mathbf{v}(\mathbf{x},y)\triangleq v_{1:N}$.
	Clearly, we have for any permutation matrix $\rho_n$, it holds that:
	\begin{align}
		\label{equ:v_define}
		\mathbf{v}(\rho_n \mathbf{x},y) = \rho_n \mathbf{v}(\mathbf{x},y).
	\end{align}
Besides, recall that the bidding process of agents is divided into $T$ time steps, and the reward function and the transition rule are both related to the bidding results of all the impression opportunities between two time steps, as stated in Section \ref{sec:pre}.
Therefore, we consider the bidding results of $M\in\mathbb{R}_+$ impression opportunities with contextual features $\mathbf{y}\triangleq y_{1:M}\in\mathcal{Y}^M$ between time step $t$ and $t+1$, where $y_j$ denotes the contextual feature of impression opportunity $j\in [M]$, and recall that the joint bid of all agents is $\mathbf{a}_t\in\mathcal{A}^N$.
Then the allocation results can be represented by a matrix $\mathbf{G}(\mathbf{x},\mathbf{a}_t,\mathbf{y})\in\{0,1\}^{N\times M}$, where the $j$-th column is just $g(\mathbf{x},\mathbf{a}, y_j)$, i.e.,
\begin{align}
	\mathbf{G}(\mathbf{x},\mathbf{a}_t,\mathbf{y})=
	\begin{bmatrix}
		g(\mathbf{x},\mathbf{a}, y_1), g(\mathbf{x},\mathbf{a}, y_2), \cdots, g(\mathbf{x},\mathbf{a}, y_M)
	\end{bmatrix}.
\end{align}
Based on Assumption \ref{assump:equ_mechanism}, we have
\begin{align}
	\label{equ:G_pe}
	\mathbf{G}(	\rho_n \mathbf{x},	\rho_n \mathbf{a}_t,\mathbf{y})=	\rho_n\mathbf{G}(	 \mathbf{x}, \mathbf{a}_t,\mathbf{y})
\end{align}
Similarly, the pricing results can also be represented by a matrix $\mathbf{U}(\mathbf{x},\mathbf{a}_t,\mathbf{y})\in\mathbb{R}_+^{N\times M}$, where the $j$-th column is just $u(\mathbf{x},\mathbf{a}_t, y_j)$, i.e., 
\begin{align}
	\mathbf{U}(\mathbf{x},\mathbf{a}_t,\mathbf{y}) = [u(\mathbf{x},\mathbf{a}_t, y_1), u(\mathbf{x},\mathbf{a}_t, y_2), \cdots, u(\mathbf{x},\mathbf{a}_t, y_M)].
\end{align} 
Based on Assumption \ref{assump:equ_mechanism}, we can also have:
\begin{align}
		\label{equ:u_pe}
		\mathbf{U}(\rho_n\mathbf{x},\rho_n\mathbf{a}_t,\mathbf{y}) =\rho_n	\mathbf{U}(\mathbf{x},\mathbf{a}_t,\mathbf{y}).
\end{align}
Besides, we stack the value of all impression opportunities into a matrix, i.e., 
\begin{align}
	\mathbf{V}(\mathbf{x},\mathbf{y})=[\mathbf{v}(\mathbf{x}, y_1), \mathbf{v}(\mathbf{x}, y_2), \cdots, \mathbf{v}(\mathbf{x}, y_M) ],
\end{align}
and based on \eqref{equ:v_define}, we can have:
\begin{align}
		\label{equ:v_pe}
		\mathbf{V}(\rho_n\mathbf{x},\mathbf{y})=\rho_n	\mathbf{V}(\mathbf{x},\mathbf{y}).
\end{align}
As the reward of agent $i$ is the sum of values of impression opportunities it wins, we have
\begin{align}
	\mathbf{r}_t(\mathbf{s}_t,\mathbf{a}_t)=\mathrm{diag}(\mathbf{G}(\mathbf{x},\mathbf{a}_t,\mathbf{y})\mathbf{V}(\mathbf{x},\mathbf{y})^\top).
\end{align} 
Therefore, based on \eqref{equ:G_pe} and \eqref{equ:v_pe} and Lemma \eqref{lemma:equv},  we have:
\begin{align}
	\label{equ:r_pe}
		\mathbf{r}_t(\rho_n\mathbf{s}_t,\rho_n\mathbf{a}_t)&=\mathrm{diag}\bigg(\mathbf{G}(\rho_n\mathbf{x},\rho_n\mathbf{a}_t,\mathbf{y})\mathbf{V}(\rho_n\mathbf{x},\mathbf{y})^\top\bigg)\notag\\
	&=\mathrm{diag}\bigg((\rho_n\mathbf{G}(\mathbf{x},\mathbf{a}_t,\mathbf{y}))(\rho_n\mathbf{V}(\mathbf{x},\mathbf{y}))^\top\bigg)\notag\\
	&=\mathrm{diag}\bigg(\rho_n\mathbf{G}(\mathbf{x},\mathbf{a}_t,\mathbf{y})\mathbf{V}(\mathbf{x},\mathbf{y})^\top\rho_n^\top\bigg)\notag\\
	&=\rho_n\mathrm{diag}\bigg(\mathbf{G}(\mathbf{x},\mathbf{a}_t,\mathbf{y})\mathbf{V}(\mathbf{x},\mathbf{y})^\top\bigg)\notag\\
	&=\rho _n	\mathbf{r}_t(\mathbf{s}_t,\mathbf{a}_t).
\end{align}
In the auto-bidding problems, the transition of each agent's local state basically depends on the cost between two time steps \cite{USCB, SAB_1}. Hence, we consider:
\begin{align}
	P(\mathbf{s}_{t+1}|\mathbf{s}_t,\mathbf{a}_t)=P(\mathbf{c}_t(\mathbf{s}_t,\mathbf{a}_t)),
\end{align}
where 
\begin{align}
	\mathbf{c}_t(\mathbf{s}_t,\mathbf{a}_t)=\mathrm{diag}\bigg(\mathbf{U}(\mathbf{x},\mathbf{a}_t,\mathbf{y})\mathbf{J}\bigg),
\end{align}
and $\mathbf{J}$ is an $M\times N$ matrix with all elements as $1$. Hence, based on \eqref{equ:u_pe} and Lemma \ref{lemma:equv}, 
we have:
\begin{align}
	\label{equ:P_pe}
		P\bigg(\rho_n\mathbf{s}_{t+1}|\rho_n\mathbf{s}_t,\rho_n\mathbf{a}_t\bigg)&=P\bigg(\mathbf{c}_t(\rho_n\mathbf{s}_t,\rho_n\mathbf{a}_t)\bigg)\notag\\
	&=P\bigg(\mathrm{diag}\bigg(\mathbf{U}(\rho_n\mathbf{x},\rho_n\mathbf{a}_t,\mathbf{y})\mathbf{J}\bigg)\bigg)\notag\\
	&=P\bigg(\mathrm{diag}\bigg(\rho_n\mathbf{U}(\mathbf{x},\mathbf{a}_t,\mathbf{y})\mathbf{J}\rho_n^\top\bigg)\bigg)\notag\\
	&=P\bigg(\rho_n\mathrm{diag}\bigg(\mathbf{C}(\mathbf{x},\mathbf{a}_t,\mathbf{y})^\top\mathbf{J}\bigg)\bigg)\notag\\
	&=P\bigg(\rho_n\mathbf{c}_t(\mathbf{s}_t,\mathbf{a}_t) \bigg)\notag\\
	&=P\bigg(\mathbf{c}_t(\mathbf{s}_t,\mathbf{a}_t) \bigg)\notag\\
	&=P\bigg(\mathbf{s}_{t+1}|\mathbf{s}_t,\mathbf{a}_t\bigg).
\end{align}
Note that $P (\rho_n\mathbf{c}_t(\mathbf{s}_t,\mathbf{a}_t) )$ and $P (\mathbf{c}_t(\mathbf{s}_t,\mathbf{a}_t) )$ both represent the probability of paying $\mathbf{c}_t(\mathbf{s}_t,\mathbf{a}_t)$ of all agents and hence are equal. So far, \eqref{equ:r_pe} \eqref{equ:P_pe} have concluded the proof. 

\section{Explanations on the Identical POMDPs}
\label{app:pomdps}

We note that
	each POMDP$_i$ is a tuple $<\widetilde{\mathcal{S}}_i, \widetilde{O}_i,
	\widetilde{\mathcal{A}}_i,  \widetilde{r}_i,\widetilde{P}_i, >$, where $\widetilde{\mathcal{S}}_i=\mathcal{S}^N$ is the state space, $\widetilde{O}_i=\mathcal{S}$ is the observation space,
	$\widetilde{\mathcal{A}}_i=\mathcal{A}$ is the action space,  $\widetilde{r}_i:\mathcal{S}^N\times\mathcal{A}\rightarrow\mathbb{R}_+$ is the reward function, and $\widetilde{P}_i:\mathcal{S}^N\times\mathcal{A}\rightarrow\Delta(\mathcal{S}^N)$ is the transition rule.
	Clearly, it holds that $\forall i$:
		\begin{align}
		\label{equ:equal_others}
		\widetilde{\mathcal{S}}_i=\widetilde{\mathcal{S}}_{i'},
		\quad
		\widetilde{O}_i=\widetilde{O}_{i'}.
		\quad \widetilde{\mathcal{A}}_i=\widetilde{\mathcal{A}}_{i'}.
	\end{align}
Before moving on to further proof, we want to clarify what the definition of two POMDPs being in the same state is.
Specifically, denote the states of POMDP$_i$ and POMDP$_{i'}$ as $\widetilde{\mathbf{s}}_{i,t}\in\mathcal{S}^N$ and $\widetilde{\mathbf{s}}_{i',t}\in\mathcal{S}^N$, respectively.
We claim that POMDP$_i$ and POMDP$_{i'}$ are in the same state if 
\begin{align}
	\label{equ:equal_state}
	\widetilde{{s}}_{i,i,t}=\widetilde{{s}}_{i',i',t}\quad\text{and}\quad\exists \rho_{n-1},\; \mathrm{s.t.}\;\; \rho_{n-1}\widetilde{\mathbf{s}}_{i,-i,t}=\widetilde{\mathbf{s}}_{i',-i',t},
\end{align}
where $\widetilde{{s}}_{i,i,t}$ denotes the local state $i$ in $\widetilde{\mathbf{s}}_{i,t}$ and $\widetilde{\mathbf{s}}_{i,-i,t}$ denotes the joint state except for $\widetilde{{s}}_{i,i,t}$.
Specifically, \eqref{equ:equal_state} means that the local states are identical while the distribution of other states is the same. Based on this, we examine the reward function and the transition rule. 
Specifically, for POMDP$_i$ and POMDP$_{i'}$, $i\neq i'$, we construct a permutation matrix $\bar{\rho}_n$ that satisfies:
\begin{align}
	\bar{\rho}_n(i) = i', \quad \bar{\rho}_n(i')=i,\quad \bar{\rho}_n(k)=k,\forall k\neq i, i'.
\end{align}
Note that from  \cref{thm:pe}, we have:
\begin{align}
	r(\mathbf{s}_t,\mathbf{a}_t, i) = r(\bar{\rho}_n\mathbf{s}_t,\bar{\rho}_n\mathbf{a}_t, \bar{\rho}_n(i)).
\end{align}
Hence, for any $a\in\mathcal{A}$, we have
\begin{align}
	\label{equ:equal_reward}
\widetilde{r}_i(\widetilde{\mathbf{s}}_{i,t}, a)&=\sum_{ {\mathbf{a}}_{-i,t}}r(\widetilde{\mathbf{s}}_{i,t},
(a,\mathbf{a}_{-i,t}), i
)\Pi_{j\neq i}\pi_\theta\big({a}_{j,t}|{{s}}_{j,t}\big)\notag\\
		&=\sum_{ {\mathbf{a}}_{-i,t}}r(\bar{\rho}_n\widetilde{\mathbf{s}}_{i,t},\bar{\rho}_n(a,\mathbf{a}_{-i,t}), \bar{\rho}_n(i))\Pi_{\bar{\rho}_n(j)\neq \bar{\rho}_n(i)}\pi_\theta\big({a}_{\bar{\rho}_n(j),t}|s_{\bar{\rho}_n(j), t})\big)\notag\\
		&=\sum_{ {\mathbf{a}}_{-i',t}}r(\bar{\rho}_n\widetilde{\mathbf{s}}_{i,t}, (a, \mathbf{a}_{-i, t}), i')\Pi_{j\neq i'}\pi_\theta\big({a}_{j,t}|s_{j,t}\big)\notag\\
		&=	\widetilde{r}_{i'}(\bar{\rho}_n\widetilde{\mathbf{s}}_{i,t}, a).
	\end{align}
Note that as $\widetilde{\mathbf{s}}_{i,t}$ and $\bar{\rho}_n \widetilde{\mathbf{s}}_{i,t}$ are the same state in the sense of \eqref{equ:equal_state}, we can conclude from \eqref{equ:equal_reward} that the reward of POMDP$_i$ and the reward of POMDP$_{i'}$ are the same when standing at the same state (in the sense of \eqref{equ:equal_state}) and taking the same action. Therefore, we have:
\begin{align}
	\widetilde{r}_i=\widetilde{r}_{i'}.
\end{align}
Similarly, for the transition rule, we have:
	\begin{align}
	\widetilde{P}_i(\widetilde{\mathbf{s}}_{i,t+1}|\widetilde{\mathbf{s}}_{i,t},a)&=\sum_{ {\mathbf{a}}_{-i,t}}P(\widetilde{\mathbf{s}}_{i,t+1}|\widetilde{\mathbf{s}}_{i,t}, (a, \mathbf{a}_{-i,t}))\Pi_{j\neq i}\pi_\theta\big({a}_{j,t}|s_{j,t}\big)\notag\\
	&=\sum_{ {\mathbf{a}}_{-i,t}}P(\bar{\rho}_n\widetilde{\mathbf{s}}_{i,t+1}|\bar{\rho}_n\widetilde{\mathbf{s}}_{i,t}, \bar{\rho}_n (a, \mathbf{a}_{-i,t}))\Pi_{\bar{\rho}_n(j)\neq \bar{\rho}_n(i)}\pi_\theta\big({a}_{\bar{\rho}_n(j),t}|s_{\bar{\rho}_n(j),t}\big)\notag\\
	&=\sum_{ {\mathbf{a}}_{-i',t}}P(\bar{\rho}_n\widetilde{\mathbf{s}}_{i,t+1}|\bar{\rho}_n\widetilde{\mathbf{s}}_{i,t}, (a, \mathbf{a}_{-i',t}))\Pi_{j\neq i}\pi_\theta\big({a}_{j,t}|s_{j,t}\big)\notag\\
	&=\widetilde{P}_{i'}(\bar{\rho}_n\widetilde{\mathbf{s}}_{i,t+1}|\bar{\rho}_n\widetilde{\mathbf{s}}_{i,t},a).
\end{align}
This means that the probabilities of transiting to the same next state (in the sense of \eqref{equ:equal_state}) in POMDP$_i$ and POMDP$_{i'}$ are the same when starting from the same state and taking the same action. Hence, we have:
\begin{align}
	\label{equ:equal_transition_rule}
	\widetilde{P}_i=	\widetilde{P}_{i'}.
\end{align}
Together with \eqref{equ:equal_others}, \eqref{equ:equal_reward} and \eqref{equ:equal_transition_rule}, we prove that the all the POMDPs share the same structures. 



