    \end{align}
    % \end{subequations}
    \item When $\xi_{n,m}^t=0$, $x_{n}^t$ is not updated at slot $t$, i.e.,
    \begin{equation}
        \label{notupdateError}
\begin{aligned}
e_{n,m}^{t} &=x_{n}^{t}-\hat{x}_{n,m}^{t}=x_{ n}^{t}-\hat{x}_{n,m}^{t-1} \\
&=\left(x_{n}^{t}-x_{n}^{t-1}\right)+\left(x_{n}^{t-1}-\hat{x}_{n,m}^{t-1}\right)  \\
&=\varepsilon_{n}(1)+e_{n,m}^{t-1}  \,.
\end{aligned}
    \end{equation}
According to (\ref{gaussianVariable}), $e_{n,m}^{t}$ is a Gaussian random variable:
    \begin{equation}
    \label{errorgaussian}
