\end{equation}
where $\tau_{n,m}^t$ is the number of slots since the last time $x_{n}^{t_0}, \forall t_0 \leq t$, was received by robot $m$. At slot $t$, $\tau_{n,m}^t=\tau_{n,m}^{t-1}+1$ if $x_{n}^t$ is not received; otherwise, $\tau_{n,m}^t=0$. The belief distribution of $e_{n,m}^t$ in (\ref{notupdateError}) is 
\end{itemize}
\begin{equation}
       b\left(e_{n,m}^{t} \!\mid \!\xi_{n,m}^{t}\!=\!0\right)\!=\!\frac{1}{\sqrt{2 \pi \tau_{n,m}^{t} \sigma_{n}^{2}}} \exp \left[-\frac{\left(e_{n,m}^{t}\right)^{2}}{2 \tau_{n,m}^{t} \sigma_{n}^{2}}\right] \label{emjkBelief}. 
\end{equation}
