 \subsection{  {Convergence Analysis}}
We analyze the convergence of the proposed MADDPG framework by proving the existence of the Nash Equilibrium (NE) in the framework. This starts by interpreting the framework as a distributed resource scheduling game $\Gamma=({\cal M}, {\cal A}, {\cal U})$ among the robots. The game consists of:
\begin{itemize}
\item The set of players ${\cal M} = \{1,2,\cdots,M\} $;
\item The {action} spaces of all robots ${\cal A}=\left\{{\cal A}_m\right\}_{m\in {\cal M}}$; and
\item The set of the joint costs of all robots ${\cal U}=\left\{{\cal U}_m\right\}_{m\in {\cal M}}$, 
\end{itemize}
where ${\cal U}_m$ is the immediate reward of robot $m$, i.e.,
\begin{equation}
\label{joint cost m}
      {\cal U}_m=r_m  \,. \\
\end{equation}


According to (\ref{optimizationP}) and (\ref{joint cost m}), {robot $m$ wishes to maximize its reward during the game:}
\begin{equation}
\label{purpose}
    {\max}_{a_m \in {\cal A}_m}  {r}_m\left(a_m,{\bf a}_{-m}\right)    \,, \\
\end{equation}
where ${\bf a}_{-m}=\{a_1,\cdots,a_{m-1},a_{m+1},\cdots,a_M\}$ collects the {action}s of the robots other than robot $m$.

%In the following, we first introduce the definition of NE \cite{fudenberg1991game} and the potential game\cite{monderer1996potential}, then analyze the existence of NE of the proposed distributed resource scheduling game $\Gamma$.

\textit{Definition 1 (Nash Equilibrium): For game $\Gamma$, we call ${\bf a}^\ast=(a_1^\ast,a_2^\ast,\cdots,a_M^\ast)$ a Nash Equilibrium if and only if no robot can further improve its {reward} by unilaterally changing its {action} at the equilibrium ${\bf a}^\ast$, i.e.,}
\begin{equation}
\label{NE}
      {r}_m\left(a_m^\ast,{\bf a}_{-m}^\ast\right){>}{r}_m\left(a_m,{\bf a}_{-m}^\ast\right)  \,. \\
\end{equation}

\textit{Definition 2 (Potential Game): A game is a potential game if there exists a potential function $\Phi$: ${\bf a}=(a_1,a_2,\cdots,a_M) \to \Bbb{R}$ such that ${\forall m} \in {\cal M}$ :}
\begin{equation}
% \begin{aligned}
\label{PG}
      {r}_m\!\left(a_m,\!{\bf a}_{-\!m}\right)\!-\!{r}_m\!\left(a'_m,\!{\bf a}_{-\!m}\right)\!\!=\!\! 
      \Phi\!\left(a_m,\!{\bf a}_{-\!m}\right)\!-\!\Phi\!\left(a'_m,\!{\bf a}_{-\!m}\right). 
      % \end{aligned}
\end{equation}

\textit{Theorem 1: $\Gamma$ is a potential game and has an NE with a finite number of unilateral overhead updates.}

\textit{Proof:} By Definition 2, we define a function $\Phi$ : ${\bf a}=(a_1,a_2,\cdots,a_M) \to \Bbb{R}$ as
\begin{equation}
\label{PoF}
      {\Phi}\left(a_m,{\bf a}_{-m}\right)= \frac{1}{M} \sum_{m'=1}^{M} {r}_{m'}(a_{m'},{\bf a}_{-m'}) \,. \\
\end{equation}
Consider the semi-decentralized training process illustrated in Fig.~\ref{fig:maddpg}. Each robot takes the global reward as its reward. The reward is evaluated centrally by the critic network at the BS. According to (\ref{globalreward}) and (\ref{joint cost m}), the reward ${r}_{m}(a_{m},{\bf a}_{-m})$ is 
\begin{equation}
\begin{aligned}
\label{pro1}
      {r}_{m}(a_{m},{\bf a}_{-m})= & \frac{1}{M} \sum_{m'=1}^{M} r_{m'}^{\mathrm{l}} \,, \\
      %= & \frac{1}{M} (r_{m}^{\mathrm{L}}+\sum_{m'=1,m' \ne m}^{M} r_{m'}^{\mathrm{l}}) \,, \\
\end{aligned}
\end{equation}
which is also the global reward and does not change over $m$.

Then, the potential function ${\Phi}\left(a_m,{\bf a}_{-m}\right)$ is given by 
\begin{equation}
\begin{aligned}
\label{PoF2}
      {\Phi}\left(a_m,{\bf a}_{-m}\right)= & \frac{1}{M} \sum_{m'=1}^{M} \left( \frac{1}{M} \sum_{m'=1}^{M} r_{m'}^{\mathrm{l}} \right) \\
      = & \frac{1}{M} \cdot M {r}_{m}(a_{m},{\bf a}_{-m}) 
      = {r}_{m}(a_{m},{\bf a}_{-m}). 
\end{aligned}
\end{equation}
Consequently, (\ref{PG}) is obtained. As a potential game, $\Gamma$ surely has an NE. 


{
Consider the game is a one-step {decision} process; i.e., $Q^{\bf \pi}\!({\bf S}(t+1),{\bf a}(t+1))$ is independent with $Q^{\bf \pi}\!({\bf S}(t),{\bf a}(t)\!)$. Thus, the second term on the right-hand side of \eqref{q_value_update} is $0$ and, subsequently, $Q^{\bf \pi}\!\left({\bf S}(t),{\bf a}(t)\!\right)\!\!=\! \!\mathbb{E}\{r_m(t)\}$~\cite{geng2024balancing}. From \eqref{PoF2}, it follows that $\nabla_{a_{m}} Q^{\theta^Q}({\boldsymbol{o}}, {\boldsymbol{a}})=\nabla_{a_{m}} {\Phi}(a_m,{\bf a}_{-m})$, i.e., each agent’s local gradient step aligns with $\nabla_{a_{m}} {\Phi}(a_m,{\bf a}_{-m})$, which implies $\Phi(\mathbf{a})$ is non-decreasing. 

Assume that the actor and critic networks have bounded parameters and Lipschitz gradients. By designing the learning rates satisfying standard stochastic approximation conditions~\cite{robbins1951stochastic} and exploration noise diminishing over time, the actor-critic updates converge almost surely to a stationary point of the expected update dynamics~\cite{konda2000actor}, i.e.,
\begin{equation}
  \lim_{t \to \infty} \theta_m^{\mu} \;\to\; (\theta_m^{\mu})^*,
  \quad
  \text{where } \nabla_{\theta_m^{\mu}} J_m((\theta_m^{\mu})^*) = 0.
\end{equation}

Based on \eqref{actorUpdate}, any stationary point of the global updates must satisfy $\nabla_{\mathbf{a}} \Phi(\mathbf{a}^*) = \mathbf{0}$, with $\mathbf{a}_{m}^*=\mu_{(\theta_m^{\mu})^*}$.
% we have ${\Phi}({\boldsymbol{a}}(t+1))\geq {\Phi}({\boldsymbol{a}}(t))$, and the direction of the updates align with $\nabla_{a_{m}} {\Phi}(a_m,{\bf a}_{-m})$, which implies convergence to a local maximum of $\Phi$ (i.e., local NE). 
According to \textit{Definitions 1} and \textit{2}, the policy converges to a local maximum of $\Phi(\mathbf{a})$, which is a local NE of the potential game.
In this way, the convergence of the MADDPG framework is guaranteed.
In a more general or complex setting, the convergence properties can be empirically validated, as in Section~V-C.
