%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\vspace{-3.0mm}
\subsection{Not Contains Predicate}\label{sec:notcontains}
\vspace{-0.0mm}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% In this section, we show first steps towards solving constraints involving the
% $\notcontains$ predicate, whose general decidability is, to the best of our
% knowledge, currently unknown.

% \ol{bla bla flat restriction, talk about the general case}

\figNotContainsSemantics  %%%%%%%%%%%%%%%

In this section, we extend the reasoning about the disequality tag
automaton~$\aut^{\singlediseq}$ introduced in \cref{sec:single-gen-diseq} to
handling $\notcontains$ with flat languages.
The constraint $\notcontains(u,v)$ for $u,v\in\vars^*$ is satisfiable 
if there is a string assignment of variables from $u$ and $v$ yielding words $w_u$ and $w_v$ respectively such that 
for \emph{every} alignment of $w_u$ and $w_v$
%
\begin{inparaenum}[(i)]
  \item there is a mismatch symbol of $w_u$ and~$w_v$ or
  \item $w_u$~overflows $w_v$.
\end{inparaenum}
%
For example, considering the constraint $\notcontainsof{u}{v}$, the assignment
$\sigma = \{u \mapsto aba, v\mapsto aabba\}$ is a~model---for every 
alignment of $aba$ and $aabba$, there is either a~mismatching symbol or a~part
of~$aba$ is outside~$aabba$ (cf.\ \cref{fig:notcontainsSemantics}).
The alignment of $w_u$ and $w_v$ can be characterized by the offset $\offset
\in \nat$ of $w_u$ counted from the beginning of $w_v$.
Therefore, the semantics of $\notcontains$ implicitly involves a~universal
quantifier ranging over all possible offsets.

Since we need to consider mismatches for all offsets of~$w_u$ and~$w_v$, 
one might consider the formula~$\varphi^{\singlediseq}$ from
\cref{sec:single-gen-diseq}, but changed such that the position constraints
$\formdiseqposij$ take into account a~universally quantified offset
variable~$\offset$.
Such a~solution, however, does not work, since we need that
%
\begin{inparaenum}[(i)]
  \item for each value of~$\offset$, the string assignment remains the same (we
    want to shift the same assignment to different positions given by the
    offset and not obtain a different assignment for each offset), and 
  \item for each offset the particular mismatch position and symbol (if any)
    may be different.
\end{inparaenum}
%
The second property is problematic as the different offsets might involve
different runs in the tag automaton that are, however, over the same string
assignment.
For this reason, we need to impose a~\emph{flat language restriction}, since
for flat automata, the number of taken transitions (and so a~model
of~$\parikhformof \aut$) uniquely determines the accepted word.
On the other hand, for non-flat automata, this property does not hold.
E.g,. consider an NFA with a~single state~$q$ (which is both initial and
accepting) and two transitions: $q \ltr a q$ and $q \ltr b q$.
The two words $aabb$ and $bbaa$ accepted by the NFA are different, but they
have the same Parikh images.
Our restriction to flat languages gives us the guarantee that a~model of the
Parikh formula uniquely determines the string assignment.

%*******************************************************************************
\vspace{-0.0mm}
\subsubsection{Formula Construction}\label{sec:label}
\vspace{-0.0mm}
%*******************************************************************************

Let $\varphi = \notcontains(u, v)$ where $u = u_1\dots u_n$ and $v = v_1\dots v_m$ are sequences of variables from~$\vars$ such that
$\langof {\autass(x)}$ is flat for every $x \in \vars$, and let $\aut^{\singlediseq}$ be
a tag automaton constructed as described in \cref{sec:single-gen-diseq}.
Since we now need to speak about different runs of $\aut^{\singlediseq}$, we 
lift the definition of the Parikh tag image to 
explicitly speak about the Parikh variables, i.e., $\parikhformtag(T, \num)$
where $\num$ denotes the set of all $\num$-prefixed variables
in~$\parikhformtag$.
Since we need to speak about alignments of assignments, we also refine the
formulae $\formdiseqposij$ from \cref{sec:single-gen-diseq} to
$\formdiseqposij(\offset, \num)$, explicitly relating the used Parikh variables
and the particular offset~$\offset$.
The offset~$\offset$ is added to the left-hand side of every equation occurring
inside~$\formdiseqposij$, in order to express that the assignments of the
left-hand side are shifted to the right by~$\offset$.
The formula $\formdiseqmis^{\singlediseq}$ from \cref{sec:single-gen-diseq} is
then also changed into~$\formdiseqmis(\offset, \num)$, which
uses~$\formdiseqposij(\offset, \num)$ instead of~$\formdiseqposij$.

Let us start by defining some auxiliary predicates used later in the resulting formula:
%
\begin{align}
  \pi (\move {q} {\tagsymof a, \taglenof x} {p}) &\quad\defequal\quad \left\{ \move {(q,i)} {U} {(p,j)} \mid \move {(q,i)} {U} {(p,j)} \in \Delta(\aut^{\singlediseq}), \tagsymof a \in U \right\}~\text{and} \\
  % \pi (\move {q} {S} {p}) &\defequal \left\{ \move {(q,i)} {S} {(p,j)} \mid \move {(q,i)} {S} {(p,j)} \in \Delta(\aut^{\singlediseq}) \right\}  \\
  \equalword{\num_1} {\num_2} &\quad\defequiv\quad
    \bigwedge_{t \in \Delta (\autcon)} \left( \sum_{r \in \pi(t)} \num_1 r =
    \sum_{r \in \pi(t)} \num_2 r  \right).
\end{align}
%
Let $\num_1$ and $\num_2$ be two sets of Parikh variables encoding accepting runs of $
\aut^{\singlediseq}$, i.e., 
$\parikhformtagof{\aut^{\singlediseq}, \num_1}$ and $\parikhformtagof{\aut^{\singlediseq}, \num_2}$ hold. 
%
Intuitively, $\equalword{\num_1} {\num_2}$ is satisfied iff $\num_1$ and $\num_2$ correspond to the
same sets of runs in the $\epsilon$-concatenation~$\autcon$ serving as a basis for $\aut^{\singlediseq}$, and, therefore, 
since we assume flat automata, 
$\num_1$~and~$\num_2$ correspond to the same string assignments. 
% Since we assume that the variable languages are
% flat, $\pisAgree {\aut^{\singlediseq}} {\piModelA} {\piModelB}$ holds iff $\piModelA$ and $
% \piModelB$ correspond to the same string assignment. Finally, we can construct $
% \notcontainsLIA_\varphi$ as follows:
%
Further, we define $\lenDiff {\num}$ expressing the difference $|w_v| - |w_u|$ 
where $w_u$ and $w_v$ are concatenated assignments of $\notcontains$'s arguments 
given by the Parikh image:
%
\vspace{-2mm}
\begin{equation}
  \lenDiff {\num} \quad\defequal\quad
      \left( \sum_{1 \le j \le m} \numof{\taglenof{v_j}} \right)
      - \left(\sum_{1 \le i \le n} \numof{\taglenof{u_i}} \right).
%\vspace{-1mm}
\end{equation}
%
The resulting formula equisatisfiable to the $\notcontains$ is then given as
%
\begin{equation}
  \begin{aligned}
    \notcontainsLIA\quad \defequiv \quad
    \parikhformtagof{\aut^{\singlediseq}, \num_1} \land &
      \forall \offset \exists \num_2
      \Big(
        \big(
          \parikhformtagof{\aut^{\singlediseq}, \num_2} \land {}  \equalword{\num_1} {\num_2} \land \formdiseqmis(\offset, \num_2) 
        \big)
    \lor {} &\\[-2mm]
        &
        \hspace*{12mm}
        \offset < 0
        \lor
        \offset > \lenDiff{\num_1}
      \Big).
  \end{aligned}
\end{equation} 
%
Note that in the formula, we use $\exists \num$ to denote the existential quantification over all variables in $\num$.
Intuitively, $\notcontainsLIA$ is satisfied iff there is a string assignment corresponding to $\num_1$ such that
for every offset $\offset$, we can find some other model $\num_2$ satisfying
$\parikhformtagof{\aut^{\singlediseq}, \num_2}$ that encodes the same string
model (but potentially a~different run through~$\aut^{\singlediseq}$.
Moreover, $\notcontainsLIA$ says that the
run corresponding to~$\num_2$ contains a mismatch for the offset~$\kappa$.
Alternatively, the offset $\kappa$ might be larger than the difference between lengths of $\notcontains$ arguments or negative, 
in which case the corresponding alignment
is trivially satisfied.

\cbstart
\begin{theorem}\label{thm:}
The formula $\regconstr' \land \intconstr \land \notcontains(u_1\dots u_n,
v_1\dots v_m)$ where the language of each~$u_i$ and~$v_j$ is flat is
equisatisfiable to the formula $\intconstr \land \notcontainsLIA$.
Moreover, the size of $\notcontainsLIA$ is polynomial to~$mn\cdot|\regconstr'|$.
\end{theorem}
\cbend


%*******************************************************************************
\vspace{-0.0mm}
\subsection{Arbitrary Combination of Position Predicates}\label{sec:combination}
\vspace{-0.0mm}
%*******************************************************************************

The construction of the tag automaton for multiple disequalities and the
subsequent LIA reduction can be easily extended to a system $\psi \equiv \bigwedge_{1 \le k
\le K} P_{k}(x_{k, 1} \cdots x_{k, n_k}, y_{k, 1} \cdots y_{k, m_k})$ where
$P_{k} \in \{\neq$, $\notprefix$, $\notsuffix$, $\strat$, $\notstrat$, $\notcontains \}$.
From a high-level perspective, a single $\epsilon$-concatenation~$\autcon$ of
all automata of variables occurring in $\psi$ is created. The tag automaton
is formed in the same way as described in \cref{sec:diseqSystem},
containing $2K+1$ copies of $\autcon$ to track up to $2K$ possible
mismatch symbols (one for each side of every predicate).
The resulting LIA formula is then
%
\begin{equation}
    \varphi^\combination \defiff \fParikh \land \fConsist{} \land \fCopies{} \land
    \bigwedge_{1 \le i \le K} \fPredSat {i}
\end{equation}
%
where $\fPredSat {i}$ is a LIA formula specific to the type of $i$-th constraint
described in previous sections expressing that the predicate is satisfied. Note
that $\fPredSat {i}$ needs to be modified in the same way as in the case of a
system of multiple disequalities (cf. \cref{sec:diseqSystem}) to make use of
the $p_{D, s}$ and $m_{D, s}$ variables.
Furthermore, all variables present in any
$\notcontains$ predicate must have a flat language to maintain soundness, similar
as in the case of a~single $\notcontains$ predicate.

\cbstart
\begin{theorem}\label{thm:}
The formula $\regconstr' \land \intconstr \land \psi$
  is equisatisfiable to the formula
$\intconstr \land \varphi^{\combination}$, provided all variables occurring
  in~$\notcontains$ constraints within~$\psi$ are assigned flat languages
  by~$\regconstr'$.
  In addition, the size of~$\varphi^{\combination}$ is polynomial
  to~$mn\cdot|\regconstr'|$ where~$n$ is the number of constraints in~$\psi$
  and~$m$ is the maximum size of any side of the constraints in~$\psi$.
\end{theorem}
\cbend

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\vspace{-0.0mm}
\section{Decidability and Complexity}\label{sec:dec_complexity}
\vspace{-0.0mm}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%\begin{center}
This section covers theoretical results that follow from tag-automaton
constructions based on position predicates and subsequent reductions into LIA
described in previous sections. We will formulate our results as instances of
the following parametrized decision problem.

\begin{center}
\begin{tabular}{ll}
  \toprule
$\posregsat(\eqconstr, \regconstr, \intconstr, \diseqconstr)$
\\ \midrule
  \textbf{INPUT:}
  &
  $\bullet$ a~set of string variables~$\vars = \{x_1, x_2, \dots, x_k\}$,
  \\
  &
  $\bullet$ a conjunction of word equations $\eqconstr$,
  \\
  &
  $\bullet$ a conjunction of regular constraints $\regconstr = \big\{ x \in \langof{\aut_x} \mid x \in \vars \big\}$,
  \\
  &
  $\bullet$ a conjunction of length constraints $\intconstr$, and
  \\
  &
  $\bullet$ a conjunction of position constraints $\diseqconstr$.
  \\
  \textbf{QUESTION:}
  &
  \parbox[t]{9.8cm}{Is there an assignment $\sigma\colon \vars \to
\alphabet^*$ satisfying $\eqconstr \land \regconstr \land \intconstr \land \diseqconstr$?}\\
\bottomrule
\end{tabular}
\end{center}

In the following, we write $\regconstr$ to denote an~arbitrary conjunction of
regular constraints of the form $\regconstr = \bigwedge_{x \in \vars}  x \in
\langof{\aut_x}$ where $\aut_x$ is an NFA associated with the variable $x$
if not specified otherwise.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\cbstart
\begin{theorem}\label{thm:ptime}
    The time complexity of $\posregsat(\emptyset, \regconstr, \emptyset, \diseqconstr)$ with
    $\diseqconstr = P(x_1 \cdots x_n, $ $ y_1 \cdots y_m)$ for $P \in \{\neq, \notsuffix, \notprefix \}$ is
    in $\clP$, more concretely in $\bigOOf{nm \cdot |\alphabet|^3\cdot |\regconstr|^6}$.
\end{theorem}
\cbend


