\begin{lemma}\label{lemma:nphard}
    $\posregsat(\emptyset, \regconstr, \emptyset, \diseqconstr)$ with
    $\diseqconstr = \bigwedge_{1 \le i \le K} (x_{i, 1} \cdots x_{i, n_i} \neq y_{i, 1} \cdots y_{i, m_i})$
    is $\clNP$-hard.
\end{lemma}
\begin{proof}
    By reduction from 3-SAT.
    Let $\varphi$ be an input 3-SAT formula.
    For each Boolean variable~$x_i$ in~$\varphi$, we create a~string
    variable~$y_i$ with $\autass(y_i)$ being a~DFA with 2 states accepting the
    language $\{0,1\}$.
    For each clause in~$\varphi$, we create a~new disequality such that, e.g.,
    for a~clause $(x_1 \lor \neg x_2 \lor x_3)$, we create the disequality $y_1
    y_2 y_3 \neq 010$.
    Then the system of disequalities is equisatisfiable to~$\varphi$.
\end{proof}

\begin{theorem}\label{thm:npcomplete}
    $\posregsat(\emptyset, \regconstr, \emptyset, \diseqconstr)$ with
    $\diseqconstr = \bigwedge_{1 \le i \le K} P_i(x_{i, 1} \cdots x_{i, n_i}, y_{i, 1} \cdots y_{i, m_i})$
    for $P_i \in \{\neq$, $\notsuffix, \notprefix, \strat, \notstrat \}$
    is $\clNP$-complete. 
\end{theorem}
\begin{proof}
    From \cref{lemma:nphard} we have that the problem is $\clNP$-hard.
    $\clNP$-membership follows from constructing an equisatisfiable quantifier-free
    LIA formula $\psi$ as described in~\cref{sec:combination} and
    observing that $\psi$ is of polynomial size.
    Satisfiability of quantifier-free LIA is in $\clNP$~\cite{qfLiaNP}.
\end{proof}

The following theorem states that position constraints with structurally
limited languages of variables occurring in $\notcontains$ predicates
can be decided in $\clNEXPTIME$.

\begin{theorem}\label{thm:notContainsComplexity}
    $\posregsat(\emptyset, \regconstr, \emptyset, \diseqconstr)$ with
    $\diseqconstr = \bigwedge_{1 \le i \le K} P_i(x_{i, 1} \cdots x_{i, n_i}, y_{i, 1} \cdots y_{i, m_i})$
    for $P_i \in \{\neq$, $\notsuffix, \notprefix, \notcontains, \strat, \notstrat \}$
    such that $\langof{\aut_x}$ of any variable $x$ that occurs in a~$\notcontains$
    predicate is flat can be decided in $\clNEXPTIME$.
\end{theorem}
\begin{proof}
    We can observe that, in the presence of $\notcontains$ predicates,
    the resulting formula $\psi$ constructed as described in \cref{sec:combination}
    falls into the $\exists \forall \exists$-fragment of LIA (after transforming into the prenex normal form).
    As the number of quantifier alternations is $2$, we obtain that
    $\psi$ is decidable in $\Sigma^{\clEXP}_1 = \clNEXPTIME$~\cite{Haase14},
    where $\Sigma^{\clEXP}_1$ is the first level of the weak exponential hierarchy.
\end{proof}

Contrary to deciding a~single disequality (which is in \clP), deciding
a~single $\notcontains$ is already \clNP{}-hard, as stated by the following theorem
(proven in \cref{app:npHardess}).

\begin{theorem}\label{thm:notContainsHardness}
    $\posregsat(\emptyset, \regconstr, \emptyset, \diseqconstr)$ with
    $\diseqconstr = \notcontains(x_1 \ldots x_n, y_1 \ldots y_m)$
    is $\clNP$-hard.
\end{theorem}

Finally, we obtain the decidability of the whole fragment considered in the
paper for chain-free word equations.

\begin{theorem}\label{thm:decidability}
    $\posregsat(\eqconstr, \regconstr, \intconstr, \diseqconstr)$ with
    $\eqconstr$ being chain-free~\cite{ChainFree},
    $\diseqconstr = \bigwedge_{1 \le i \le K} P_i(x_{i, 1} \cdots x_{i, n_i}, $ $ y_{i, 1} \cdots y_{i, m_i})$
    for $P_i \in \{\neq, \notsuffix, \notprefix, \notcontains, \strat, \notstrat \}$
    and
    $\regconstr = \bigwedge_{x \in \vars} x \in \langof{\aut_x}$
    such that $\langof{\aut_x}$ of any variable~$x$ that occurs in a~$\notcontains$
    predicate is flat
    is decidable. 
\end{theorem}

\begin{proof}
    As $\eqconstr$ is chain-free, we start by solving only $\eqconstr \land
    \regconstr \land \intconstr$ using the approach described
    in~\cite{ChenCHHLS23}, obtaining a new set of variables $\vars'$ along with
    a length constraint $\intconstr'$ (extension of $\intconstr$ with equalities 
    relating lengths of the original variables and the variables from $\vars'$), 
    a~monadic decomposition $\regconstr' = \bigwedge_{x' \in \vars'} x' \in
    \langof{\aut_{x'}}$ and a~length constraint (we note that the \emph{noodlification} procedure
    in~\cite{ChenCHHLS23} preserves flatness of languages), and a substitution
    map $\sigma\colon \vars \rightarrow (\vars')^*$ mapping original variables
    to (potentially concatenations of) new variables.
    Applying $\sigma$ to $\diseqconstr$, we obtain a~conjunction $\diseqconstr'$
    of new position predicates. We are left to solve a new system
    $\regconstr' \land \intconstr' \land \diseqconstr'$, for which we can construct an
    equisatisfiable LIA formula using the techiniques presented in this work.
    Therefore, we obtain an equisatisfiable formula in a decidable theory, concluding the proof.
\end{proof}

