Finally, we use additional notion to improve the readability of the proofs.
When \( \ll \) is a linear order on \( \ksMathcal{E} \), then \( \minOf{S}{\ll} \) will either be a singleton set or empty.
For such linear orders, we use \( \mins(\ll) \) as shorthand for \( \minsOf{A}{\ll} \), whereby we define \( \minsOf{S}{\ll} \) as the single element in \( \minOf{S}{\ll} \) if is a singleton set; otherwise, we say that \( \minsOf{S}{\ll} \) is undefined, i.e.:
\begin{equation*}
    \minsOf{S}{\ll} = \begin{cases}
	        E & \ksIF \minOf{S}{\ll} = \{ E \}\\
	        \text{undefined} & \ksOtherwise
	    \end{cases}
\end{equation*}
By doing so, we can easily address with \( \minsOf{S}{\ll} = E \) the one and only single element in \( \minOf{S}{\ll}=\{ E \} \), i.e., we avoid the explicit unboxing of \( E \) from \( \{ E \} \).
Note that \( \minsOf{S}{\ll} \) is also undefined if \( \minOf{S}{\ll} \) contains more than one element, which can appear when \( \ll \) is not a linear order.


\subsection{\( K \)-Minimal Linear Choice Functions to Postulates}\label{sec:appproof}


We start with the left-to-right direction of Theorem~\ref{thm:reptheorem_linearchoiceNonUnion}.

%
 \begin{proposition}\label{prop:rightdirection}
	Let \( \ksChoiceStructure = \tuple{\ksChoiceAlternatives,\ksChoiceDomain,\ksChoiceCoDomain} \) be a restricted choice structure. 
	Every \( K \)-minimal linear choice function \( \triangledown : \ksChoiceDomain \to \ksChoiceCoDomain \) for \( \ksChoiceStructure \) satisfies \eqref{pstl:SS0a}--\eqref{pstl:SS4}, \eqref{pstl:SS5E} and \eqref{pstl:SS6E}.
%
 \end{proposition}
%
\begin{proof}
	Let  \( \triangledown : \ksChoiceDomain \to \ksChoiceCoDomain \) be a linear choice function for \( \ksChoiceStructure \).
	This means that there is a linear order \( {\ll} \)  on \( \ksChoiceCoDomain \) that is \( \ksChoiceStructure \)-smooth such that \( {\triangledown} = {\triangledown_{\ll}} \).
	We show satisfaction of the postulates:
	\begin{description}
		%
		%
		%
		\item[\normalfont{[}\eqref{pstl:SS0a} is satisfied{]}] 
		We have to show that if \( \ksChoiceCoDomain \cap \ksPowerset{S} \neq \emptyset \), then \( \triangledown(S) \subseteq S \) holds. 
		Clearly, \( \ksChoiceCoDomain \cap \ksPowerset{S} \neq \emptyset \) implies that there is some \( E \in \ksChoiceCoDomain \) with \( E \subseteq S \). Thus, we also have that \( \minsOf{S}{\ll} \) is non-empty. Inspecting Definition~\ref{def:linear_choice_function} reveals that this means that \( \triangledown(S) \subseteq S \).


		%
		%
		%
		\item[\normalfont{[}\eqref{pstl:SS1} is satisfied{]}] 
		We have to show that \( \triangledown(S) \subseteq S \) or \( \triangledown(S) = K \) holds. There are two cases.
		The first case is \( K \subseteq S \). 
		In this case we have that \( K \) is the globally minimal element of \( \ll \).
		Hence, we obtain that \( \triangledown(S) = K = \triangledown_{\ll}(S) = \minsOf{S}{\ll} \).
		If \( K \not\subseteq S \) holds, then there are two subcases. 
		The first subcase is that there no \( E \in \ksChoiceCoDomain \) such that \( E \subseteq S \).
		In this case we have \( \minOf{S}{\ll} = \emptyset \), and thus, by definition of \( \triangledown_{\ll} \), we obtain \( \triangledown_{\ll}(S)=\triangledown(S)= K  \).
		The second subcase is that there an \( E \in \ksChoiceCoDomain \) such that \( E \subseteq S \).
		In this case we have \( \minsOf{S}{\ll} \subseteq S \), because \( \ll \) is \( N \)-smooth.
		Consequently, we obtain \( \triangledown(S) \subseteq S \) because of  \( {\triangledown} = {\triangledown_{\ll}} \).
		%
		%
		%


		%
		%
		%
		\item[\normalfont{[}\eqref{pstl:SS2} is satisfied{]}] 
		We have to show that \( K\subseteq S \) implies \( \triangledown(S)=K \).
		Note that \( \mins(\ll)=K \) holds, because \( \triangledown \) is a linear choice function for \( N \).
		Consequently, for each \( K\subseteq S \) we obtain \( \triangledown(S)=\minsOf{S}{\ll}=K  \).


		%
		%
		%
		\item[\normalfont{[}\eqref{pstl:SS3} is satisfied{]}] 
		We have to show that \(  \triangledown(S_{1}) \subseteq S_{2} \ksAND  \triangledown(S_{2})\subseteq S_{1} \) together imply \( \triangledown(S_{1}) = \triangledown(S_{2}) \).
		Assume that \(  \triangledown(S_{1}) \subseteq S_{2} \ksAND  \triangledown(S_{2})\subseteq S_{1} \) hold.
		Because \( \triangledown \) satisfies \eqref{pstl:SS1}, we have  \( \triangledown(S) \subseteq S \) or \( \triangledown(S) = K \) for each \( S\in\ksChoiceCoDomain \).

		The case of \( \triangledown(S_{1}) = K \) or \( \triangledown(S_{2}) = K \). We will consider only the case of \( \triangledown(S_{1}) = K \), the proof for the case of \( \triangledown(S_{2}) = K \) is analogue.
		From \( \triangledown(S_{1}) \subseteq S_{2} \), we obtain that \( K \subseteq S_{2} \) holds. 
		Because \( \triangledown \) satisfies \eqref{pstl:SS2}, we obtain \( \triangledown(S_{2}) = K  \) from \( K \subseteq S_{2} \).
		Hence, we have \( \triangledown(S_{1}) = \triangledown(S_{2}) \).

		The case of \( \triangledown(S_{1}) \subseteq S_{1} \) and  \( \triangledown(S_{2}) \subseteq S_{2} \).  
		Let \( M = {\minsOf{S_{1}}{\ll}} \) and let \( N = {\minsOf{S_{2}}{\ll}} \). 
		Clearly, we have that \( M = \triangledown(S_{1}) \) and \( N = \triangledown(S_{2}) \) hold. 
		If \( M = N \), then we are done. We continue for the case of \( M \neq N \).
		From  our assumptions, we obtain that \( M \subseteq S_{2}  \) and that \( N \subseteq S_{1}  \) holds. 
		Now, recall that every linear order is total and antisymmetric, and thus, also \( \ll \).
		Hence, we have that exactly one of \( M \ll N \) or \( N \ll M \) holds.
		This yields a contradiction, because \( M \ll N \) contradicts \( N = \minsOf{S_{2}}{\ll} \), and \( N \ll M \) contradicts \( M = \minsOf{S_{1}}{\ll} \).


		%
		%
		%
		\item[\normalfont{[}\eqref{pstl:SS4} is satisfied{]}] 
		We have to show that \( \triangledown(S_{1}) \subseteq S_{1} \) and \( S_{1} \subseteq S_{2} \) implies \( \triangledown(S_{2}) \subseteq S_{2} \).
		Assume that \( \triangledown(S_{1}) \subseteq S_{1} \) and \( S_{1} \subseteq S_{2} \) hold.
		First, we show that \( \minsOf{S_{1}}{\ll} \) is defined.
		%
		We consider the two cases of \( \triangledown(S_{1}) \neq K \) and \( \triangledown(S_{1}) = K \).
		From Equation~\eqref{eq:triangledownLLdefinition} we obtain that \( \triangledown(S_{1}) \subseteq S_{1} \) is only possible in the case of \( \triangledown(S_{1}) \neq K \), if \( \minsOf{S_{1}}{\ll} \) is defined. For the case of \( \triangledown(S_{1}) = K \), recall that \( \min({\ll})=K \) holds because \( \ll \) is \( \ksChoiceStructure \)-smooth. Consequently, we obtain that  \( \minsOf{S_{1}}{\ll} \) is defined from \( \triangledown(S_{1}) = K \subseteq S_{1} \).        
		Now, because \( \minsOf{S_{1}}{\ll} \) is defined, we obtain that \( \minsOf{S_{2}}{\ll} \) is defined from \( S_{1}\subseteq S_{2} \) and Equation~\eqref{eq:triangledownLLdefinition}. 
		Consequently, 
		%
		we obtain that \( \triangledown(S_{2}) \subseteq S_{2} \) holds.


		%
		%
		%
%
        \item[\normalfont{[}\eqref{pstl:SS5E} is satisfied{]}] 
		We have to show that for
		\begin{align*}
			S_{0} \cup S_{1} & \subseteq S_{0,1}\\
			 & \vdots \\
			S_{n-1} \cup S_{n} & \subseteq S_{n-1,n}\\
			S_{n} \cup S_{0} & \subseteq S_{n,0}
		\end{align*}
		with		
		 \( \triangledown(S_{0,1}) = S_{0}, \ldots, \triangledown(S_{n-1,n}) = S_{n-1} \) and \( S_0 \neq S_{n} \) together imply \( \triangledown(S_{n,0})  \neq S_{n} \).
		The proof is by contradiction. Henceforth, towards a contradiction, assume that \( \triangledown(S_{n,0}) = S_{n} \) holds, as well as 
		\begin{equation*}
			\triangledown(S_{0,1}) = S_{0},\ \ldots,\ \triangledown(S_{n-1,n}) = S_{n-1}
		\end{equation*}		
		and \( S_0 \neq S_{n} \).

		First, we show that \( \minsOf{S_{i,i+1 \,\mathrel{\mathrm{mod}}\, (n+1)}}{\ll} \) is defined for all \( i \in \{ 0, \ldots, n \} \). Towards a contradiction, assume that \( \minsOf{S_{i,i+1 \,\mathrel{\mathrm{mod}}\, (n+1)}}{\ll} \) is undefined.
		Clearly, by considering Equation~\eqref{eq:triangledownLLdefinition} we obtain that \( {\triangledown(S_{i,i+1 \,\mathrel{\mathrm{mod}}\, (n+1)}) = K} \).
		The last observation together with \( \triangledown(S_{i,i+1 \,\mathrel{\mathrm{mod}}\, (n+1)})= S_{i} \) implies that \( {S_{i} = K} \) holds.
		And consequently, because \( \ll \) is a \( K \)-minimal \( \ksChoiceStructure \)-smooth linear order, we have \( {\min(\ll)} = \{ K \} \).
		We obtain that \( {\minsOf{S_{i,i+1 \,\mathrel{\mathrm{mod}}\, (n+1)}}{\ll} = K} \) is defined.

		For what remains of proving that \eqref{pstl:SS5E} is satisfied, we assume that \( S_{i} \neq S_{j} \) holds for all \( i,j\in\{0,\ldots, n\} \). 
		This is valid, because we have \( S_{0} \neq S_{n} \) and whenever \( S_{i} = S_{j} \) holds with \( i < j \), we can just consider this proof just for the sets \(  S_{1}, \ldots, S_{i}, S_{j+1},\ldots S_{n}\).

		Because, \( \minsOf{S_{i,i+1 \,\mathrel{\mathrm{mod}}\, (n+1)}}{\ll}  \) is defined, we have \[ \triangledown(S_{i,i+1 \,\mathrel{\mathrm{mod}}\, (n+1)}) = \minsOf{ S_{i,i+1 \,\mathrel{\mathrm{mod}}\, (n+1)} }{\ll} \ . \] 
		Consequently, because we have \( S_{i} \neq S_{i+1 \,\mathrel{\mathrm{mod}}\, (n+1)} \), we obtain \( S_{j} \ll S_{j+1} \) for all \( j\in\{0,\ldots,n-1\} \) from \( \triangledown(S_{j,j+1}) = S_{j} \).
		Moreover, \( \triangledown(S_{n,0}) = S_{n}  \) yields \( S_{n} \ll S_{0} \).
		Which shows that we have \( S_{0} \ll S_{1} \ll \ldots \ll S_{n} \ll S_{0} \) and thus, that \( \ll \) violates the \hyperref[pstl:Suzumura_consistency]{consistency} condition. We obtain a contradiction, because \( \ll \) is a \hyperref[pstl:transitive]{transitive} relation, yet not \hyperref[pstl:Suzumura_consistency]{consistent}, which is impossible.
		%

		%
		%
		%
%
        %
        %
        %
        %
        %
        %
        %
        %
        %
        %
        %
        %
        %
        %
        %
        %
        %
        %
        %
        %
        \item[\normalfont{[}\eqref{pstl:SS6E} is satisfied{]}] 
        First, note that \( S_{1,2}=S_{1} \cup S_{2} \) and \( S_{1,3}=S_{1} \cup S_{3} \) ensure existence of the corresponding unions.
        We have to show that \( \ksChoiceFunction(S_{1} \cup S_{2}) = S_{3} \) implies \(
        \ksChoiceFunction(S_{1} \cup S_{3}) = S_{3} \).
        Assume that \( \ksChoiceFunction(S_{1} \cup S_{2}) = S_{3} \) holds.
        Because \( \ksChoiceFunction \) satisfies \eqref{pstl:SS1}, we have \( \ksChoiceFunction(S_{1} \cup S_{2}) = K \) or \( \ksChoiceFunction(S_{1} \cup S_{2}) \subseteq S_{1} \cup S_{2} \).

        We start with the case that \( \triangledown(S_{1} \cup S_{2}) = K \) holds.
        Observe that in this case, we have \( K = S_{3} \), and thus we have \( K \subseteq S_{1} \cup S_{3} \).
        Consequently, we obtain \(   \triangledown(S_{1} \cup S_{3}) = K = S_{3} \) from \eqref{pstl:SS2}.

        We continue with the case of \( \ksChoiceFunction(S_{1} \cup S_{2}) \subseteq S_{1} \cup S_{2} \) and \( \ksChoiceFunction(S_{1} \cup S_{2}) \neq K \).
        This case is only possible if \( \minsOf{S_{1} \cup S_{2}}{\ll}  \) is defined.
        Consequently, from Equation~\ref{eq:triangledownLLdefinition} and \( \ksChoiceFunction(S_{1} \cup S_{2}) = S_{3} \), we obtain \( \minsOf{S_{1} \cup S_{2}}{\ll} = S_{3} \). Because of the latter, also \( \minsOf{S_{1} \cup S_{3}}{\ll}  \) is defined and thus,  \( \ksChoiceFunction(S_{1} \cup S_{3}) = \minsOf{S_{1} \cup S_{3}}{\ll} \).
        Now, towards a contradiction to \( \ksChoiceFunction(S_{1} \cup S_{3}) =  S_{3} \) assume \( \ksChoiceFunction(S_{1} \cup S_{3}) \neq  S_{3} \).
        Clearly, this means there is some \( S \) with \( S_{3} \neq S \) and  \( {S} = \ksChoiceFunction(S_{1} \cup S_{3}) = {\minsOf{S_{1} \cup S_{3}}{\ll} \neq  S_{3}}  \).
        Because of this, we obtain \( {\minsOf{S_{1} \cup S_{3}}{\ll}} = S \subseteq S_{3} \) from Equation~\eqref{eq:triangledownLLdefinition}.
        Observe also that we have \( S \ll S_{3} \), as otherwise, we wouldn't have \( S = {\minsOf{S_{1} \cup S_{3}}{\ll}} \).
        Because we have \( \minsOf{S_{1} \cup S_{2}}{\ll} = S_{3} \) and \( \ksChoiceFunction(S_{1} \cup S_{2}) \neq K \), we obtain \( S_{3} \subseteq S_{1} \cup S_{2} \) from \eqref{pstl:SS1}.
        Furthermore, observe that \( S_{1} \cup S_{3} \subseteq S_{1} \cup S_{2} \) holds, because \( S_{3} \subseteq S_{1} \cup S_{2} \) holds. 
        Consequently, we also have that \( S \subseteq S_{1} \cup S_{2} \).
        From the chain of though above obtain that \( S \in \minOf{S_{1} \cup S_{2}}{\ll} \) and  \( S_{3} \in \minOf{S_{1} \cup S_{2}}{\ll} \) holds a that the same time, which is impossible, because \( \ll \) is a linear order. \qedhere
	\end{description}
\end{proof}

From Proposition~\ref{prop:rightdirection}, we obtain the following corollary for union-closed choice structures.
\begin{corollary}\label{prop:rightdirection_unionclosed}
	Let \( \ksChoiceStructure = \tuple{\ksChoiceAlternatives,\ksChoiceDomain,\ksChoiceCoDomain} \) be a union-closed restricted choice structure. 
	Every \( K \)-minimal linear choice function \( \triangledown : \ksChoiceDomain \to \ksChoiceCoDomain \) for \( \ksChoiceStructure \) with fallback \( K \) satisfies \eqref{pstl:SS0a}--\eqref{pstl:SS6}.
\end{corollary}


\subsection{Postulates to \( K \)-Minimal Linear Choice Functions}\label{sec:appproof2}
In the following, we provide an approach to obtain a linear order \( \ll \) that encodes a choice function \( \ksChoiceFunction \) that satisfies \eqref{pstl:SS1}--\eqref{pstl:SS4}, \eqref{pstl:SS5E} and \eqref{pstl:SS6E}.
This order \( \ll \) will be obtained by a multistep process, consisting of a constructive part and a non-constructive part.
In the constructive part we construct a smooth relation that encodes the behaviour of the choice function and is \enquote{nearly} a linear order.
We call such relations \( \ksChoiceStructure \)-compatible.

\newpage
\begin{definition}\label{def:BUCcompatible}
	Let \( \ksChoiceStructure = \tuple{\ksChoiceAlternatives,\ksChoiceDomain,\ksChoiceCoDomain} \) be a restricted choice structure and let be a function \( \ksChoiceFunction : \ksChoiceDomain \to \ksChoiceCoDomain \).
	%
	A relation \( \unlhd \) is called \emph{\( \ksChoiceStructure \)-compatible with \( \ksChoiceFunction \)}, if \( {\unlhd} \subseteq \ksMathcal{E} \times \ksMathcal{E} \) is a \ref{pstl:reflexive}, \ref{pstl:antisymmetric}, \ref{pstl:Suzumura_consistency}, \( \ksChoiceStructure \)-smooth relation on some set \( \ksMathcal{E} \subseteq \ksChoiceCoDomain \), such that the following is satisfied for every \( S \in \ksChoiceDomain \):
	\begin{equation*}\tag{\ref{eq:triangledownLLdefinition}}
		\ksChoiceFunction(S) = \begin{cases}
			E & \ksIF \minOf{S}{{\unlhd}}=\{E\} \\
			K & \ksOtherwise
		\end{cases}
	\end{equation*}
\end{definition}
As one may notice, \( \ksChoiceOrderEF \) in from Definition~\ref{def:BUCcompatible}  is an order some subset \( \ksMathcal{E} \subseteq \ksChoiceDomain \).
The specific set \( \ksMathcal{E} \) we will use will be called the \emph{image of \( \ksChoiceFunction \)}, which is the following:
\begin{equation*}
	\ksChoiceImage{\ksChoiceFunction} = \{\, \ksChoiceFunction(S) \mid S \in \mathbb{S}  \,\}
\end{equation*}
This set satisfied the following property which will be very helpful.
\begin{lemma}\label{lem:BUCimage}
	Let \( \ksChoiceStructure = \tuple{\ksChoiceAlternatives,\ksChoiceDomain,\ksChoiceCoDomain} \) be a restricted choice structure.
If  \( \ksChoiceFunction : \ksChoiceDomain \to \ksChoiceCoDomain \) satisfies \eqref{pstl:SS6E}, then \(  \ksChoiceImage{\ksChoiceFunction} = \{ E \in \ksChoiceCoDomain \mid \ksChoiceFunction(E) = E  \} \).	
\end{lemma}
\begin{proof}
	Observe that for every \( E \in \ksChoiceCoDomain \) there is some \( S \in \mathbb{S} \) with \( \ksChoiceFunction(S)=E \) and \( S \subseteq E \). By setting \( S_1=S_3=E \) and \( S_2=S \) in \eqref{pstl:SS6E},  one obtains that \(  \ksChoiceFunction(S)=\ksChoiceFunction(S_1\cup S_2)=E \) implies that \( \ksChoiceFunction(S_1\cup S_3)=\ksChoiceFunction(E)=E \).
\end{proof}

The encoding of \( \ksChoiceFunction \) works intuitively by saying \( E_1 \) is preferred over \( E_2 \) if there is a set that  witnesses that \( E_1 \) is preferred over \( E_2 \).
A similar encoding scheme has been described by Sen~\cite[Def. 2]{KS_Sen1971}.
\begin{definition}\label{def:encoding_scheme}
	Let \( \ksChoiceStructure = \tuple{\ksChoiceAlternatives,\ksChoiceDomain,\ksChoiceCoDomain} \) be a restricted choice structure and let be a function \( \ksChoiceFunction : \ksChoiceDomain \to \ksChoiceCoDomain \).
	The binary relation \( {\unlhd} \subseteq  \ksChoiceImage{\ksChoiceFunction} \times  \ksChoiceImage{\ksChoiceFunction} \) on \( \ksChoiceImage{\ksChoiceFunction} \) which is given by:
	%
		%
		%
		%
		%
	%
	\begin{align*}        
			E_1 \unlhd E_2 \text{ if }E_1 = K \text{ or there} & \text{ exist some } E\in\ksChoiceDomain \\
		& \text{ such that } E_1\cup E_2 \subseteq E \ksAND \ksChoiceFunction(E) = E_1
%
		%
		%
	\end{align*}
\end{definition}
