    We proof several properties of \( {\unlhd} \):
    \begin{description}    	
    	%
    	%
    	%
    	\item[\normalfont{[}\emph{{\( \min({\unlhd}) = \{K\} \)}.}{]}]
    	Clearly, \( K \unlhd E \) holds for all \( E \in  \textsf{Image}(\triangledown) \).
    	We have to show that \( E \centernot{\unlhd} K \) holds for all \( E \in  \textsf{Image}(\triangledown) \) with \( E\neq K \).
    	Towards a contradiction, suppose there is some \( E \) with \( E \unlhd K \) and \( E\neq K \).
    	Then there must be an \( E' \) with \( E \cup K \subseteq E' \) with \( \ksChoiceFunction(E') = E \).
    	But this is impossible, as we have \( K \subseteq E' \), and thus we have \( \ksChoiceFunction(E')=K \) due to \eqref{pstl:SS2}.

    	%
    	%
    	%
    	\item[\normalfont{[}\emph{{\( {\unlhd} \) is \ref{pstl:reflexive}}.}{]}]
    	We have to show that for every \( E \in \ksChoiceImage{\ksChoiceFunction} \) holds \( E \unlhd E \).
    	By Lemma~\ref{lem:BUCimage} we have \( \ksChoiceFunction(E) = E \), which yields \( \ksChoiceFunction(E \cup E) = E \). Consequently, we also have \( E \unlhd E \).

    	%
    	%
    	%
    	\item[\normalfont{[}\emph{{\( {\unlhd} \) is \ref{pstl:antisymmetric}}.}{]}]
    	We have to show that for all \( E_1,E_2 \in \ksChoiceImage{\ksChoiceFunction} \) with \( E_1 \preceq E_2 \) and \( E_2 \preceq E_1 \) it holds that \( E_1 = E_2 \).
    	Towards a contradiction we assume \( E_1 \neq E_2 \), and let \( E_1 \unlhd E_2 \) and \( E_2 \unlhd E_1 \). 
    	From the last two assumptions we obtain that there are \(  E_{1,2},E_{2,1} \in \ksChoiceDomain \) with \( E_1\cup E_2 \subseteq E_{1,2} \) and \( E_1\cup E_2 \subseteq E_{2,1} \) such that \( \ksChoiceFunction(E_{1,2}) = E_1 \) and \( \ksChoiceFunction(E_{2,1}) = E_2 \).
    	Clearly, we have \( \ksChoiceFunction(E_{1,2}) \subseteq E_{2,1} \) and \( \ksChoiceFunction(E_{2,1}) \subseteq E_{1,2} \), and thus \( \ksChoiceFunction(E_{1,2}) = \ksChoiceFunction(E_{2,1}) \) due to \eqref{pstl:SS3}.
    	We obtain the contradiction of \( E_1 = E_2 \) and \( E_1 \neq E_2 \).
    	Hence, the relation is antisymmetric.


    	%
    	%
    	%
    	\item[\normalfont{[}\emph{{\( {\unlhd} \) is \ref{pstl:Suzumura_consistency}}.}{]}]
    	We have to show that for all \( n\in\mathbb{N}^{+} \) and \( x_0,\ldots,x_n\in X \) holds \( E_0 \unlhd E_1 \), ..., \( E_{n-1} \unlhd E_{n} \) implies that not \( E_{n} \lhd_{\Psi} E_{0} \).
    	Recall that \( E_{n} \lhd_{\Psi} E_{0} \) means that \( E_{n} \unlhd E_{0} \) holds and that \( E_{0} \centernot{\unlhd} E_{n} \) holds.

    	Towards a contradiction, assume that \hyperref[pstl:Suzumura_consistency]{consistency} is violated by \( \unlhd \).
    	This means there exist \( E_0,\ldots,E_n \), for some \(  n\in\mathbb{N}^+ \), such that \( E_{0} \unlhd E_{1} \), ..., \( E_{n-1} \unlhd E_{n} \) and \( E_{n} \lhd E_{0} \). 
    	Because \( \unlhd \) is \ref{pstl:reflexive} and \hyperref[pstl:antisymmetric]{antisymmetric}, \( E_{n} \lhd E_{0} \) implies that \( E_{n} \neq E_{0} \).
    	From the definition of \( {\unlhd} \), we obtain that
    	there are \( E_{0,1},E_{1,2},\ldots,E_{n-1,n} \) and \( E_{n,0} \) with 
    	\begin{align*}
    	E_0 \cup E_1 & \subseteq E_{0,1}\\
    		& \vdots \\
    	E_{n-1} \cup E_n &  \subseteq E_{n-1,n}\\
    	E_n \cup E_0 & \subseteq E_{n,0}
    	\end{align*}
    	 such that the following holds:
    	\begin{align*}
    		\ksChoiceFunction(E_{0,1}) & = E_0 \\
    		& \ \,\vdots \\
    		\ksChoiceFunction(E_{n-1,n}) & = E_{n-1} \\
    		\ksChoiceFunction(E_{n,0}) & = E_n 
    	\end{align*}
    	In summary, we obtain a violation of \eqref{pstl:SS5E}, which is satisfied by \( {\ksChoiceFunction} \) and consequently, we have shown that \( {\unlhd} \) is \ref{pstl:Suzumura_consistency}.


        %
        %
        %
        %
		\item[\normalfont{[}\emph{{If \( \ksChoiceFunction(S) \neq K \), then \( \ksChoiceFunction(S) \in \minOf{S}{\unlhd} \)}.}{]}]
		Towards a contradiction, we assume that \( \ksChoiceFunction(S) \neq K \) and  \( \ksChoiceFunction(S) \notin \minOf{S}{\unlhd} \) hold.
		Let \(  M \in \ksChoiceImage{\ksChoiceFunction} \) with \( M = \ksChoiceFunction(S) \).
		Furthermore, because we have \( \ksChoiceFunction(S) \neq K  \) and because \( \ksChoiceFunction \) satisfied \eqref{pstl:SS1}, we have \( M \subseteq S \).
		From \( \ksChoiceFunction(S) \notin \minOf{S}{\unlhd} \) we obtain that there is some 
		%
		\( N \in \ksChoiceImage{\ksChoiceFunction}  \)
		such that \( N \subseteq S \) and   \( N \unlhd M \).
		From \( N \unlhd M \) we obtain some \( E\in\ksChoiceDomain \) with \( N \cup M \subseteq E \) and \( \ksChoiceFunction(E) = N \).
		We obtain \( \ksChoiceFunction(S) \subseteq E\) and \( \ksChoiceFunction(E) \subseteq S \), and thus, we obtain \( \ksChoiceFunction(S)  = \ksChoiceFunction(E) = M \) from \eqref{pstl:SS3} and \( \ksChoiceFunction(S) = M \). 
		We obtain the  contradiction of having \( M \neq N \) and \( M = N \) at the same time.

		\item[\normalfont{[\emph{If \( \ksChoiceFunction(S) \neq K \), then \( \minOf{S}{\unlhd} \) is a singleton set}.]}]
		Towards a contradiction, assume there are sets \( M,N \) with \( M,N \in \min(S,{\unlhd}) \) and \( M \neq N \).
		As shown before, we can safely assume that \( M = \ksChoiceFunction(S) \) holds.
		Because we have \( M,N \in \min(S,{\unlhd}) \), we obtain that \( M \cup N \subseteq S \).
		Thus, from \( \ksChoiceFunction(S) = M \) we obtain \( M \unlhd N \).
		Because \( \unlhd \) is antisymmetric, we obtain \( N \centernot\unlhd M  \) from \( M \neq N \).
		The latter observation is a contradiction to the minimality of \( N \), i.e., \( N \in \min(S,{\unlhd}) \).


        \item[\normalfont{[}\emph{{If \( \triangledown(S) = K \), then \( \minOf{S}{\unlhd}=\{K\} \) or \( \minOf{S}{\unlhd} = \emptyset \)}.}{]}]
        We consider two cases.
        The first case is \( {K \subseteq S} \).
        Recall that we have shown above that \( \min(\unlhd)= \{ K \} \) holds in this case. Hence, we also have \( \minOf{S}{\unlhd}=\{K\} \) whenever \( K \subseteq S \).
        The second case is \( {K \not\subseteq S} \).
        We will show that \( {\minOf{S}{\unlhd} = \emptyset} \).
        Towards a contradiction, we assume that \( \minOf{S}{\unlhd} \) is non-empty, i.e., there is some \( M \in \minOf{S}{\unlhd} \).
        Clearly, by definition, we have that \( M \) satisfies \( M \subseteq S \).
        Moreover, from \( M \in \minOf{S}{\unlhd} \) we obtain \( \triangledown(M) = M  \) and hence, by employing \eqref{pstl:SS4}, we obtain \( \triangledown(S) \subseteq S \) from \( M \subseteq S \). 
        This is a contradiction to \( {K \not\subseteq S} \), because we have \( \triangledown(S) = K \).


