{\medskip\noindent\textbf{Theorem~\ref{thm:reptheorem_linearchoiceNonUnion} {(Representation Theorem)}.}~\textit{%
        %
        Assume the Axiom of Choice.
        Let \( \ksChoiceStructure = \tuple{\ksChoiceAlternatives,\ksChoiceDomain,\ksChoiceCoDomain} \) be a restricted choice structure and let \( K \in \ksChoiceCoDomain \). 
        A function \( \triangledown : \ksChoiceDomain \to \ksChoiceCoDomain \) is a \( K \)-minimal linear choice function for \( \ksChoiceStructure \) if and only if the axioms \eqref{pstl:SS0a}--\eqref{pstl:SS4}, \eqref{pstl:SS5E} and \eqref{pstl:SS6E} are satisfied.
        %
        %
}}
\begin{proof}
%
%
We show each direction independently.
{[}\emph{\enquote{\( \Rightarrow\)}}{]} 
Corollary~\ref{prop:rightdirection_unionclosed} yields the left-to-right direction.
{[}\emph{\enquote{\( \Leftarrow  \)}}{]}
%
By employ Proposition~\ref{prop:BUCleftdirection}, we obtain from the satisfaction of \eqref{pstl:SS1}--\eqref{pstl:SS6} by \( \triangledown \) that there is a linear order \( {\lll} \subseteq \ksMathcal{E} \times \ksMathcal{E} \) on some set \( \ksMathcal{E} \subseteq \ksChoiceCoDomain \) that is \( \ksChoiceStructure \)-compatible with \( \triangledown \), and \( K \)-minimal and \( R \)-smooth.
Because \( \triangledown \) satisfies \eqref{pstl:SS0a}, we have for all \( S \in \ksChoiceDomain \) that \( \triangledown(S) \subseteq S \) holds if and only if there is some \( E \in \ksChoiceCoDomain \) such that \( E \subseteq S \).
This implies we have for all \( S \in \ksChoiceDomain \) that \( \minsOf{S}{\lll}  \subseteq S \) if and only if there is some \( E \in \ksChoiceCoDomain \) such that \( E \subseteq S \).
We extend \( \lll \) to a linear order \( {\ll} \subseteq \ksChoiceCoDomain \times \ksChoiceCoDomain  \) on \( \ksChoiceCoDomain \) as follows:
\begin{equation*}
	S_1 \ll S_2 \text{ if }  \left(\ S_1  \lll S_2 \ \right) \ksOR \left(\ S_1 \in \ksMathcal{E} \ksAND s_2 \in \ksChoiceCoDomain\setminus\ksMathcal{E} \ \right) \ksOR \left(\ S_1  \Subset S_2 \ \right)
\end{equation*}
whereby \( {\Subset} \subseteq (\ksChoiceCoDomain\setminus\ksMathcal{E}) \times (\ksChoiceCoDomain\setminus\ksMathcal{E})  \) is some arbitrary linear order on \( \ksChoiceCoDomain\setminus\ksMathcal{E} \), whose existence is guaranteed by the Axiom of Choice.
Note that \( \ll \) is \( \ksChoiceStructure \)-smooth, \( K \)-minimal and we have \( \minsOf{S}{\ll} = \minsOf{S}{\lll} \) for all \( S \in \ksChoiceDomain \).
Inspecting Definition~\ref{def:linear_choice_function} reveals that we have \( {\triangledown} = {\triangledown_{\ll}^{K}} \) for \( \ll \) because \( \lll \) is \( \ksChoiceStructure \)-compatible with \( \triangledown \).
Thus, we have that \( \triangledown \) is a \( K \)-minimal linear choice function.
\end{proof}

We show that for union-closed restricted choice structure, satisfaction of \eqref{pstl:SS5E} and \eqref{pstl:SS6E} coincides with satisfaction of \eqref{pstl:SS5} and \eqref{pstl:SS6}. 
\begin{proposition}\label{prop:EandNonE}
    Assume the Axiom of Choice.
    Let \( \ksChoiceStructure = \tuple{\ksChoiceAlternatives,\ksChoiceDomain,\ksChoiceCoDomain} \) be a union-closed restricted choice structure and let \( K \in \ksChoiceCoDomain \) . 
    For every function \( \triangledown : \ksChoiceDomain \to \ksChoiceCoDomain \), the following statements are equivalent:
    \begin{enumerate}[(a)]
        \item \( \triangledown \) satisfies \eqref{pstl:SS5} and \eqref{pstl:SS6} 
        \item \( \triangledown \) satisfies \eqref{pstl:SS5E} and \eqref{pstl:SS6E} 
    \end{enumerate}
\end{proposition}
\begin{proof}
Because \( \ksChoiceStructure \) is union-closed, we have \( S_1 \cup S_2 \in \ksChoiceDomain \) and \( S_1 \cup S_3 \in \ksChoiceDomain \) for all \( S_1,S_2,S_3 \in \ksChoiceDomain \).
Consequently, \eqref{pstl:SS6E} and \eqref{pstl:SS6} are the same postulate for union-closed restricted choice structures.


Next, we observe that  \eqref{pstl:SS5E} implies \eqref{pstl:SS5}.
Because \( \ksChoiceStructure \) is union-closed, we have \( S_n \cup S_0 \in \ksChoiceDomain \) and \( S_0 \cup S_{1} \in \ksChoiceDomain \), ..., \( S_{n-1} \cup S_{n} \in \ksChoiceDomain \) for all \( S_0,\ldots,S_n \in \ksChoiceDomain \). 
Consequently, \eqref{pstl:SS5} is a special case of \eqref{pstl:SS5E} and thus, \eqref{pstl:SS5E} implies \eqref{pstl:SS5}.

We show that satisfaction of \eqref{pstl:SS5} and \eqref{pstl:SS6} imply satisfaction of \eqref{pstl:SS5E}.
Let \(  S_{i}\cup S_{i+1} \subseteq S_{i,i+1} \) and \( \triangledown(S_{i,i+1})  = S_{i} \) for \( 0\leq i\leq n \) and let \( S_n \cup S_0 \subseteq S_{n,0} \) and \( S_{n} \neq S_{0} \).
We show that \( \triangledown(S_{n,0})  \neq S_{n} \) holds.
The proof is by contradiction, i.e., we assume that \( \triangledown(S_{n,0})  = S_{n} \) holds.
By employing \eqref{pstl:SS6},  we obtain \( \triangledown(S_{i+1}  \cup S_{i} ) = S_{i} \) from  \( \triangledown(S_{i,i+1}) = \triangledown(S_{i+1}  \cup S_{i,i+1} ) = S_{i} \) for \( 0\leq i\leq n \). 
Clearly, we also obtain \( \triangledown(S_{n}  \cup S_{0} ) = S_{n} \) analogously.
This is a contradiction, because from \eqref{pstl:SS5} we obtain that \( \triangledown(S_n \cup S_0)  \neq S_{n} \) holds.
For that we employ that \( S_{n} \neq S_{0} \) and \( \triangledown(S_{i+1}  \cup S_{i} ) = S_{i} \) for \( 0\leq i\leq n \) holds.
\end{proof}
\noindent Conjoin Theorem~\ref{thm:reptheorem_linearchoiceNonUnion} and Proposition~\ref{prop:EandNonE} yields Theorem~\ref{thm:reptheorem_linearchoice} immediately.

{\medskip\noindent\textbf{Theorem~\ref{thm:reptheorem_linearchoice}.}~\textit{%
		%
		Assume the Axiom of Choice.
		Let \( \ksChoiceStructure = \tuple{\ksChoiceAlternatives,\ksChoiceDomain,\ksChoiceCoDomain} \) be a union-closed restricted choice structure and let \( K \in \ksChoiceCoDomain \). 
		A function \( \triangledown : \ksChoiceDomain \to \ksChoiceCoDomain \) is a \( K \)-minimal linear choice function for \( \ksChoiceStructure \) if and only if the axioms \eqref{pstl:SS0a}--\eqref{pstl:SS6} are satisfied.
		%
		%
}}

\medskip
One can show that in the case of union-closed restricted choice structure, an easier encoding scheme that is different from Definition~\ref{def:encoding_scheme} is also sufficient. The encoding schemes, which is known from, e.g.,  theory change \cite{KS_KatsunoMendelzon1991,KS_FalakhRudolphSauerwald2022}, is the following:
\begin{equation*}
	E_1 \unlhd E_2 \text{ if } \ksChoiceFunction(E_1\cup E_2) = E_1 \tag{\( \Box \)}\label{eq:Box}
\end{equation*}
For the proof of Theorem~\ref{thm:reptheorem_linearchoiceNonUnion}, respectively Proposition~\ref{prop:compatible}, we cannot use such an encoding scheme.
This is because \( \ksChoiceDomain \) is in general not union-closed and thus one cannot safely assume that \( E_1 \cup E_2 \in \ksChoiceDomain \) holds.
More precisely, when one would only consider cases where \( E_1 \cup E_2 \) from \eqref{eq:Box} exist, the order \( \unlhd \) via \eqref{eq:Box} would not fully encode \( \ksChoiceFunction \), i.e., \( \minOf{S}{\unlhd} \) would differ from \( \ksChoiceFunction(S) \) for some \( S \). \end{document}

