\section{Boundary value problem of the Cosserat rod} \label{app:bvp}
%
The boundary value problem of the Cosserat rod can be derived for both formulations of the internal virtual work~\cref{eq:internal_virtual_work2} and~\cref{eq:internal_virtual_work_HR_3}. Starting with the first one, we perform an integration by parts on~\cref{eq:internal_virtual_work2} and write ${}_I \vn = \vA_{IB} \, {}_B \vn$, which yields
%
\begin{equation} \label{eq:bvp:int1}
\begin{multlined}
    \delta W^\mathrm{int}
        = - \left[{}_I \delta \vr_{C}\T \, {}_I\vn + {}_B \delta \vph_{IB}\T \, {}_B \vm\right]_\mathcal{J} \\
            + \int_{\mathcal{J}} \Big\{ 
                {}_I \delta \vr_C\T \, {}_I \vn_{, \xi} 
                + {}_B \delta \vph_{IB}\T \big[
                    ({}_B \vm)_{, \xi}
                    + {}_B \stretchedStrain{\vga} \times {}_B \vn 
                    + {}_B \stretchedStrain{\vka}_{IB} \times {}_B \vm
                \big] 
            \Big\} \diff[\xi]
    %
    \, .
\end{multlined}
\end{equation}
%
Further, using
%
\begin{equation} \label{eq:bvp:int2}
\begin{multlined}
    ({}_B \vm)_{, \xi}
        = (\vA_{IB}\T \, {}_I \vm)_{, \xi}
        = \vA_{IB, \xi}\T \, {}_I \vm + \vA_{IB}\T \, {}_I \vm_{, \xi} \\ 
        = - {}_B \tilde{\stretchedStrain{\vka}}_{IB} \vA_{IB}\T \, {}_I \vm + \vA_{IB}\T \, {}_I (\vm_{, \xi})
        = - {}_B \stretchedStrain{\vka}_{IB} \times {}_B \vm + {}_B (\vm_{, \xi})
\end{multlined}
\end{equation}
%
simplifies the internal virtual work to
%
\begin{equation} \label{eq:bvp:int3}
    \delta W^\mathrm{int}
        = - \left[{}_I \delta \vr_{C}\T \, {}_I\vn + {}_B \delta \vph_{IB}\T \, {}_B \vm\right]_\mathcal{J}
            + \int_{\mathcal{J}} \Big\{ 
                {}_I \delta \vr_C\T \, {}_I \vn_{, \xi} 
                + {}_B \delta \vph_{IB}\T \big[
                    {}_B (\vm_{, \xi})
                    + {}_B \stretchedStrain{\vga} \times {}_B \vn 
                \big] 
            \Big\} \diff[\xi]
    %
    \, .
\end{equation}
%
Using this internal virtual work and the external virtual work from~\cref{eq:external_virtual_work} and applying the principle of virtual work, which states that the totality of virtual work has to vanish for all virtual displacements and virtual rotations, leads to the strong variational formulation of the rod 
%
\begin{equation}
    \delta W^\mathrm{tot} 
        = \delta W^\mathrm{int} + \delta W^\mathrm{ext}
        \stackrel{!}{=} 0
    %
    \quad
    %
    \forall {}_I \delta \vr_C
    %
    \, , \;
    %
    \forall {}_B \delta \vph_{IB}
    %
    \, ,
\end{equation}
%
from which the boundary value problem can be easily extracted as
%
\begin{equation} \label{eq:BVP_DB}
\begin{aligned}
    &{}_I \vn 
        = - {}_I \vb_0 
    %
    \, , \quad &
    %
    &{}_B \vm
        = - {}_B \vc_0
    %
    & \quad & \mathrm{at} \ \xi = \xi_0 
    %
    \, , \\
    %
    &{}_I \vn 
        = {}_I \vb_1
    %
    \, , \quad &
    %
    &{}_B \vm
        = {}_B \vc_1
    %
    & \quad & \mathrm{at} \ \xi = \xi_1
    %
    \, , \\
    %
    &\begin{aligned}
        &{}_I \vn_{, \xi} + J {}_I \vb 
            = \vzero
        %
        \, , \quad \\
        %
        &{}_B \vn 
            = \vC_{\vga} \, \vvep_\vga 
        %
        \, , \quad
    \end{aligned}&
    %
    &\begin{aligned}
        &{}_B (\vm_{, \xi}) + {}_B \stretchedStrain{\vga} \times {}_B \vn + J {}_B \vc
            = \vzero
        %
        \, , \quad \\
        %
        &{}_B \vm 
            = \vC_{\vka} \, \vvep_\vka 
    \end{aligned}
    %
    & \quad & \Bigg\} \ \mathrm{in} \ \operatorname{int}(\mathcal{J}) 
    %
    \, .
\end{aligned} 
\end{equation}
%
Note that since ${}_B \stretchedStrain{\vga} = \vA_{IB}\T \, {}_I \vr_{OC, \xi} = {}_B (\vr_{OC, \xi})$, this boundary value problem is equivalent to the boundary value problem derived in \textcite{Eugster2014}. Further note, that the last line states the constitutive law in primal form.

In the second case, we perform integration by parts on the second line of the internal virtual work from~\cref{eq:internal_virtual_work_HR_3} and use the same abbreviations as above, which leads to
%
\begin{equation}\label{eq:bvp:int_HR1}
\begin{multlined}
    \delta W^\mathrm{int, HR} 
        = - \int_{\mathcal{J}} \Big\{
        \delta ({}_B \vn)^T \left[
            \stretchedStrain{\vvep}_\vga 
            - J \, \vC_{\vga}^{-1} {}_B \vn
        \right]
        +
        \delta ({}_B \vm)^T \left[
            \stretchedStrain{\vvep}_\vka 
            - J \, \vC_{\vka}^{-1} {}_B \vm
        \right]
    \Big\} \diff[\xi] 
    \\
    - \left[{}_I \delta \vr_{C}\T \, {}_I\vn + {}_B \delta \vph_{IB}\T \, {}_B \vm\right]_\mathcal{J}
        + \int_{\mathcal{J}} \Big\{ 
            {}_I \delta \vr_C\T \, {}_I \vn_{, \xi} 
            + {}_B \delta \vph_{IB}\T \big[
                {}_B (\vm_{, \xi})
                + {}_B \stretchedStrain{\vga} \times {}_B \vn 
            \big] 
        \Big\} \diff[\xi]
    %
    \, .
\end{multlined}
\end{equation}
%
Adding the external virtual work from~\cref{eq:external_virtual_work} leads to the totality of virtual work, which has now not only to vanish for all ${}_I \delta \vr_C$ and ${}_B \delta \vph_{IB}$, but also for all $\delta ({}_B \vn)$ and $\delta ({}_B \vm)$, i.e.,
%
\begin{equation}
    \delta W^\mathrm{tot} 
        = \delta W^\mathrm{int, HR} + \delta W^\mathrm{ext}
        \stackrel{!}{=} 0
    %
    \quad
    %
    \forall {}_I \delta \vr_C
    %
    \, , \;
    %
    \forall {}_B \delta \vph_{IB}
    \, , \;
    %
    \forall \delta ({}_B \vn)
    \, , \;
    %
    \forall \delta ({}_B \vm)
    %
    \, .
\end{equation}
%
In this case we can also easily extract the boundary value problem as
%
\begin{equation} \label{eq:BVP_MX}
\begin{aligned}
    &{}_I \vn 
        = - {}_I \vb_0 
    %
    \, , \quad &
    %
    &{}_B \vm
        = - {}_B \vc_0
    %
    & \quad & \mathrm{at} \ \xi = \xi_0 
    %
    \, , \\
    %
    &{}_I \vn 
        = {}_I \vb_1
    %
    \, , \quad &
    %
    &{}_B \vm
        = {}_B \vc_1
    %
    & \quad & \mathrm{at} \ \xi = \xi_1
    %
    \, , \\
    %
    &\begin{aligned}
        &{}_I \vn_{, \xi} + J {}_I \vb 
            = \vzero
        %
        \, , \quad \\
        %
        &\stretchedStrain{\vvep}_\vga 
            = J \, \vC_{\vga}^{-1} {}_B \vn
        %
        \, , \quad
    \end{aligned}&
    %
    &\begin{aligned}
        &{}_B (\vm_{, \xi}) + {}_B \stretchedStrain{\vga} \times {}_B \vn + J {}_B \vc
            = \vzero
        %
        \, , \quad \\
        %
        &\stretchedStrain{\vvep}_\vka 
            = J \, \vC_{\vka}^{-1} {}_B \vm
    \end{aligned}
    %
    & \quad & \Bigg\} \ \mathrm{in} \ \operatorname{int}(\mathcal{J}) 
    %
    \, .
\end{aligned}
\end{equation}
%
Note that this boundary value problem equivalent to the boundary value problem from~\cref{eq:BVP_DB}, where the constitutive law in the last line is given in dual form with the strain measures from~\cref{eq:continuous_strain_measures}. 
%
\section{Details of the finite element formulation} \label{app:fem}
\subsection{Lagrangian basis functions} \label{app:Lagrangian}
%
For element $e$ with the interval $\mathcal{J}^e = [\xi^{e}, \xi^{e+1})$, the Lagrangian basis function of polynomial degree $q$ and its derivative are given by
%
\begin{equation}\label{eq:Lagrangian_polynomials}
    N^{q, e}_i(\xi) 
        = \underset{\substack{0 \leq j \leq q \\ j \neq i}}{\prod} \frac{\xi - \xi_j}{ \xi_i - \xi_j} 
    %
    \, , \qquad 
    %
    N^{q, e}_{i,\xi}(\xi) 
        = N^{q, e}_i(\xi) \underset{\substack{k=0 \\ k \neq i}}{\sum^{q}} \frac{1}{\xi - \xi_k}
    %
    \, ,
\end{equation}
%
where $\xi_i = \xi^e + i / q \, (\xi^{e+1} - \xi^e)$ with $i \in \{0, \ldots q\}$. Divisions of the form $0/0$ in the case of $q=0$ are treated as $0$, such that $\xi_0 = \xi^e$. One obtains then only one constant basis function $N^{0, e}_0(\xi) = 1$ with $N^{0, e}_{0, \xi}(\xi) = 0$, resulting from the empty product being $1$ and the empty sum being $0$. This case occurs for the interpolation of the resultant contact forces and moments for a linear element ($p=1$). \Cref{fig:lag_functions} shows the Lagrangian basis functions for $q \in \{0, 1, 2\}$.
%
\begin{figure}[h]
	\centering
    \includegraphics[scale=1]{figs/Lagrange_shape_functions.pdf}
	\caption{Lagrange basis functions $N^{q, e}_i$ for $q=0$ (left), $q=1$ (middle) and $q=2$ (right). The functions are indicated by $N^{q, e}_0$ (\protect\refnx), $N^{q, e}_1$ (\protect\refny) and $N^{q, e}_2$ (\protect\refnz).}
	\label{fig:lag_functions}
\end{figure}
