We start by giving the pseudo-algorithm for checking for a given point $\bar{x}$ and a candidate solution $v^*$, if the candidate solution is in $N_C(\bar{x})$.

\begin{algorithm}
\caption{Checking if a given $v^* \in \hat{N}_C(\bar{x})$}\label{alg:cap}
\begin{algorithmic}
\Require $C$ semi-algebraic\\\vspace{-3mm}
\State $S \leftarrow \forall \epsilon>0\,\exists\delta>0\,\forall x\in \{y\in C\setminus \{\bar{x}\}\, :\, ||y-\bar{x}||^2\le \delta^2\}\ \ \langle v^*,x-\bar{x}\rangle^2\le \epsilon^2||x-\bar{x}||^2\lor\langle v^*,x-\bar{x}\rangle\le 0$ 
\State $TF \leftarrow$ Apply QE to $S$.\\
\Return $TF$ \Comment $TF$ is True/False since $S$ is a sentence.
\end{algorithmic}
\end{algorithm}


