\section{Generational Adversarial MAP-Elites}

GAME is a QD algorithm that aims to illuminate both sides (Blue and Red) of an adversarial problem using coevolution to nurture an open-ended discovery of solutions (Fig.~\ref{fig:main_method}). It is divided into two levels: (1) Intergenerational illumination of solutions, switching from one side to the other at each generation, Alg.~\ref{alg:main_alg} (\textbf{a}, \textbf{f}, and \textbf{g}); and (2) Intragenerational execution of MTMB-ME at each generation, using one side as tasks and the other as solutions, Alg.~\ref{alg:MTMB-ME} (\textbf{b}, \textbf{c}, \textbf{d}, and~\textbf{e}). 

It proceeds as follows (the paper's values in parentheses):
\begin{itemize}[leftmargin=*,align=left,widest={(c)}]
    \item[\textbf{(a)}] randomly sample $N_{task}$ (\num{100}) Blue solutions as tasks;

\noindent \textbf{For $N_{gen}$ (\num{20}) generations:}

    \begin{itemize}[leftmargin=*]
        \item[\textbf{(b)}] initialize a multi-task multi-behavior growing archive with $N_{cells}$ (\num{25}) for each task;

        \textbf{For $N_{budget}$ (\num{100000}) evaluations:}
        \begin{itemize}[leftmargin=*]
            \item[\textbf{(c)}] pick a $task$ at random and use a variation operator on randomly picked elites from the whole archive to generate a candidate solution $s$;
            \item[\textbf{(d)}] evaluate $s$ against the $task$, collect the video and fitness $f$, subsample the video (five uniformly spaced frames) to get $frames$, get the embedding (\num{512}D) from each using a VEM (CLIP), and concatenate to get the behavior descriptor $b$ (\num{2560}D);
            \item[\textbf{(e)}] update $task$'s archive (Alg.~\ref{alg:growing_archive}): (1) if the new behavior $b$ is farther from all the current cell's centroids than the closest pair of centroids, it is added to the archive and one of the two centroids from the pair is removed; (2) else if the new fitness $f$ is greater than the corresponding cell's fitness then the new solution becomes the elite of its cell;
        \end{itemize}
        \item[\textbf{(f)}] aggregate all the elites, cluster them into $N_{tasks}$ clusters using K-Means, and select the elite of each cluster to form the next generation of tasks;
        \item[\textbf{(g)}] bootstrap the next generation with a tournament between the new and previous tasks.
    \end{itemize}
\end{itemize}

\vspace{-2pt}
\begin{algorithm} %GAME algorithm\\ 
    \small
    \caption{GAME\\
    \textbf{Inputs}: \textcolor{red}{Red} search space \textcolor{red}{$S_{Red}$}, \textcolor{blue}{Blue} search space \textcolor{blue}{$S_{Blue}$} \\
    \textbf{Parameters}: $N_{gen}$, $N_{task}$ 
    }\label{alg:main_alg}
\begin{algorithmic}[1]
\State{} $Tasks \leftarrow$ Sample $N_{task}$ random \textcolor{blue}{Blue} solutions \Comment{\textbf{(a)}}
\State{} $Generations = \{0: Tasks\}$
\State{} $\mathcal{B} = \emptyset$ \Comment{For storing bootstrapping evaluations}
\For{$gen\_id=1$ \texttt{in} $N_{gen}$}
    \State{} S $\leftarrow$ \textcolor{red}{$S_{Red}$} if $gen\_id$ is odd else \textcolor{blue}{$S_{Blue}$}
    \State{} $\mathcal{A} \leftarrow \operatorname{MTMB-ME}(Tasks, S, \mathcal{B})$ \Comment{\textbf{(b-e) - Alg.~\ref{alg:MTMB-ME}}}
    \State{} $Behaviors$ $\leftarrow$ Aggregate the archive's elites \Comment{\textbf{(f)}}
    \State{} Clusters $\leftarrow \operatorname{K-means}(Behaviors, k=N_{task})$ 
    \State{} $Tasks \leftarrow \{\operatorname{Elite}(cluster)\}_{cluster \in Clusters}$ 
    %\State{} Tasks $\leftarrow = \{\underset{c\in C}{argmax}f(c) | C \in Clusters\}$  \Comment{\textbf{(f)}}
    \State{} $Generations[gen\_id] = Tasks$
    \State{} $\mathcal{B} \leftarrow$ $Tasks$ versus $Generations[gen\_id-1]$ \Comment{\textbf{(g)}}
\EndFor{}
\State{} \Return{} $Generations$
\end{algorithmic}
\end{algorithm}
\vspace{-15pt}

\begin{algorithm} %MTMB-ME algorithm\\ 
    \small
    \caption{MTMB-ME with growing archive and a VEM\\ 
    \textbf{Inputs}: $Tasks$, search space $S$, bootstrap set $\mathcal{B}$\\
    \textbf{Parameters}: Number of evaluations $N_{budget}$, Number of initial random search $N_{init}$, evaluation function $\operatorname{Evaluate}$, variation operator $\operatorname{Variation}$, VEM 
    }\label{alg:MTMB-ME}
\begin{algorithmic}[1]
\State{} $\mathcal{A} \leftarrow$ Initialize $N_{task}$ growing archives \Comment{\textbf{(b)}}
\For{$(task, s, f, b)$ \texttt{in} $\mathcal{B}$} \Comment{\textbf{(g)} - Bootstrapping}
   \State{}  $\mathcal{A} \leftarrow \operatorname{Update}(\mathcal{A}[task], s, f, b)$ \Comment{\textbf{Alg.~\ref{alg:growing_archive}}}
\EndFor{}
\For{$i=1$ \texttt{to} $N_{budget}$} \Comment{Main loop}
    \State{} $task \leftarrow$  Select a task at random from $Tasks$ \Comment{\textbf{(c)}}
    \If{ $\mathcal{A}$ has less than $N_{init}$ elites} 
        \State{} $s \leftarrow$ Sample a random solution from $S$ 
    \Else{}
        \State{} $s \leftarrow \operatorname{Variation}(\mathcal{A})$ 
    \EndIf{}
    \State{} $f$, $video \leftarrow \operatorname{Evaluate}(s, task)$ \Comment{\textbf{(d)}}
    \State{} $frames \leftarrow$ Subsample the $video$ 
    \State{} $b$ $\leftarrow$ Apply the VEM on each frame 
       \State{}  $\mathcal{A} \leftarrow \operatorname{Update}(\mathcal{A}[task], s, f, b)$ \Comment{\textbf{(e) - Alg.~\ref{alg:growing_archive}}}
\EndFor{}
\State{} \Return{} Archives
\end{algorithmic}
\end{algorithm}


