%\subsection{Implementation details}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsubsection{Using a VEM for behavior space}
When using a VEM, GAME follows ASAL by using cosine similarity to compute the distance between two behaviors (which are \num{2560}D): $$\operatorname{dist}(b,b')=1-\dfrac{b \cdot b'}{\|b\|_2 \|b'\|_2}.$$ The reason is that Euclidean distance loses meaning as the number of dimensions increases. This doesn't impact the growing archive, as it uses the relative comparison of distances between behaviors and not their actual positions.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsubsection{Growing an unstructured archive}

One point to consider when growing an archive is that when a new behavior takes over a cell, it can ``steal'' the elites of neighboring cells as it changes the whole CVT, which creates ``holes''. A simple solution to fill those ``holes'' is to reinstate the centroid as the elite of its cell, as it can never be ``stolen.'' It only requires storing an additional solution per cell. More elaborate heuristics can be used, e.g., storing all the past elites and checking with the current CVT. However, we found that this doesn't significantly improve performance for most problems while increasing computation and memory space.

\begin{algorithm} %Growing archive\\ 
    \small
    \caption{Growing unstructured archive update\\ 
    \textbf{Inputs}: archive $A$, solution $s$, fitness $f$, behavior $b$\\
    \textbf{Parameters}: max archive size $N_{cells}$, distance function $\operatorname{dist}$
    }\label{alg:growing_archive}
\begin{algorithmic}[1] 
\State{} $(C, E, E_{backup}) = A$  \Comment{Centroids, Elites and Backup Elites}
\If{$\operatorname{size}(C) < N_{cells}$} \Comment{Add a new cell}
    \State{} $i = \operatorname{size}(E)$
    \State{} $C_i = b$ 
    \State{} $E[i] \leftarrow (s, f, b)$
    \State{} $E_{backup}[i] \leftarrow (s, f, b)$  
\Else{} \Comment{Check behavior and fitness}
    \State{} $distances = \{\operatorname{dist}(C_i, C_j)\}_{0 \le i < j < N_{cells}}$
    \State{} $d_{min} = \min(distances)$
    \State{} $d = \min\{dist(b, C_i)\}_{0 \le i < N_{cells}}$
    \State{} $c_{id} = \operatorname{find\_cell}(C, b)$ \Comment{Closest centroid's index}
    \If{ $d > d_{min}$} \Comment{New enough behavior = growth}
        \State{} $j, k \leftarrow \operatorname{argmin}(distances)$  
        \State{} $d_j \leftarrow \min\{dist(C_j, C_i)\}_{0 \le i \ne b < N_{cells} }$
        \State{} $d_k \leftarrow \min\{dist(C_k, C_i)\}_{0 \le i \ne a < N_{cells} }$
        \State{} $k \leftarrow j $ if $d_j < d_k$ else $k$ 
        \State{} $C_k \leftarrow b$
        \State{} $E[k] \leftarrow (s, f, b)$
        \State{} $E_{backup}[k] \leftarrow (s, f, b)$
        \For{$i=0$ to $N_{cells}$} \Comment{Check and repair holes}
            \If{$\operatorname{find\_cell}(C, E[i].b) \ne i$}
                \State{} $E[i] \leftarrow E_{backup}[i]$
            \EndIf{}
        \EndFor{}
    \ElsIf{f $>$ E[$c_{id}$].f} \Comment{Better fitness}
        \State{} $E[c_{id}] \leftarrow (s, f, b)$
    \EndIf{}
\EndIf{}
\State{} \Return{} $(C, E, E_{backup})$
\end{algorithmic}
\end{algorithm}

