\subsection{The maps $\pi$ and $\Psi$}\label{sec:calc pi Psi RS}
Straightforward calculations show that
$$
\Psi(v)=\left\{v,2v,2v+1,4v+1\right\} \text{ and } \pi(q)=\left\{\begin{array}{rl}
q/2 & \text{if }-1 \leq q<0,
\\ q & \text{if }q\geq 0. \end{array}
\right.
$$
We do not need to specify $\pi(q)$ when $q < -1$. 




\subsection{The sets $\V_i$}\label{the Vi for RS example}
One can compte as many $\V_{i}$ as necessary using their recursive definition. For instance, 
\begin{eqnarray*}
 \mathcal V_0&=&-\S(L)=\left\{-\frac{1}{2},0\right\},\\ 
\V_1&=&\pi\left(\Psi\left(-\frac{1}{2}\right)\cup\Psi(0)\right)
= \pi\left(\left\{-1,-\frac{1}{2},0,1\right\}\right)
=\left\{-\frac{1}{2},-\frac{1}{4},0,1\right\}, \\
\V_2&=& \pi\left(\Psi\left(-\frac{1}{2}\right) \cup\Psi\left(-\frac{1}{4}\right) \cup \Psi\left(0\right) \cup \Psi(1)\right)
\\ &=&\left\{-\frac{1}{2},-\frac{1}{4},-\frac{1}{8},0,\frac{1}{2},1,2,3,5\right\} \\
\cdots & \cdots & \cdots
\end{eqnarray*}

\begin{rem}
 In this very peculiar example, we could prove that
\begin{equation*}
\label{eq:V_rudin_shapiro}
\V=\left\{ k-\frac{1}{2^n} \ \vert \  k,n\in \Z_{\geq 0},\, (k,n)\neq (0,0)\right\}.
\end{equation*}
As this property will not be used, we only briefly indicate how to prove the most useful inclusion, namely the inclusion of $\V$ in the right-hand side of the latter equality, and leave the details and proof of the other inclusion to the reader.   Let us denote this right-hand side by $\mathcal W$. One can easily check that $-\S(L)\subset \mathcal W$ and that, for any $w \in \mathcal W$, $\pi(\Psi(w))\subset \mathcal W$. Given the definition of $\V$, this clearly implies that $\V \subset \mathcal W$.  
\end{rem}

When running Algorithm \ref{algo: rep main question}, we will first need to call Algorithm \ref{algo:minepsilon} in order to calculate a positive lower bound $\minepsilonlb$ on $\minepsilon$, which is defined by \eqref{eq:epsilon}.

\subsection{Computation of a positive lower bound on $\minepsilon$}\label{comput vareps example RS}




We will now explain how  Lower\textunderscore Bound\textunderscore $\minepsilon$($L$) described in Algorithm \ref{algo:minepsilon} runs to compute a lower bound $\minepsilonlb$ on $\minepsilon$. It takes the following steps: 
\begin{enumerate}
 \item it computes a lower bound 
 $$\theta_{2}=\text{LB\textunderscore $\epsilon$\textunderscore p$(L,2,(),-\mu_{2})$=LB\textunderscore $\epsilon$\textunderscore p$(L,2,(),-\frac{1}{2})$}
 $$ on $\epsilon(-\mu_{2})=\epsilon(-\frac{1}{2})$; 
 \item it computes a lower bound 
 $$\theta_{1}=\text{LB\textunderscore $\epsilon$\textunderscore p$(L,1,(\theta_{2}),-\mu_{1})$=LB\textunderscore $\epsilon$\textunderscore p$(L,1,(\theta_{2}),0)$}
 $$ on $\epsilon(-\mu_{1})=\epsilon(0)$;
 \item it returns 
 $$
 \minepsilonlb=\min\{\theta_1,\theta_2,\frac{1}{2\cdot 2^2}\};
 $$
\end{enumerate}
where we have written LB\textunderscore $\epsilon$\textunderscore p for Lower\textunderscore Bound\textunderscore $\epsilon$\textunderscore param defined in Algorithm \ref{algo:lower bound eps avec param}, in order to avoid heavy notations. These three steps are detailed in the following three sections. 

\subsubsection{Execution of LB\textunderscore $\epsilon$\textunderscore p$(L,2,(),-\mu_{2})=$LB\textunderscore $\epsilon$\textunderscore p$(L,2,(),-\frac{1}{2})$}
\label{item:theta_2} 
We are in the situation starting in row 4 of Algorithm \ref{algo:lower bound eps avec param} since $-\frac{1}{2}=-\mu_{2}$. 
Thus, LB\textunderscore $\epsilon$\textunderscore p($L,2,(),-\frac{1}{2})$ returns
	$$
\min\left( \V_1 \setminus\left\{-\frac{1}{2}\right\}\right)+ \frac{1}{2} = -\frac{1}{4}+\frac{1}{2} = \frac{1}{4}\,.
	$$
This latter value $\frac{1}{4}$ is stored in $\theta_{2}$. 
\subsubsection{Execution of LB\textunderscore $\epsilon$\textunderscore p$(L,1,(\theta_{2}),-\mu_{1})=$LB\textunderscore $\epsilon$\textunderscore p$(L,1,(\frac{1}{4}),0)$} 
It takes the following steps. 
	\begin{enumerate}
		\item Since $0 = -\mu_1$, we are in the situation starting in row \ref{debutStep3} of Algorithm \ref{algo:lower bound eps avec param} with $k=2$.
		\item For any $w' \in \Delta(-\mu_{1})=\Delta(0)=\{-\frac{1}{2},-\frac{1}{4}\}$, it computes
		$$m_{w'}=\text{LB\textunderscore $\epsilon$\textunderscore p$(L,1,(\frac{1}{4}),w')$}.
		$$
		\item LB\textunderscore $\epsilon$\textunderscore p$(L,1,(\frac{1}{4}),-\frac{1}{2})$ returns $\frac{1}{4}$ after calculations similar  to those described in \ref{item:theta_2}.
		\item LB\textunderscore $\epsilon$\textunderscore p($L,1,(\frac{1}{4}),-\frac{1}{4}$) runs as follows.
\begin{enumerate}
 \item Since $-\frac{1}{4} \in ]-\frac{1}{2},0[=]-\mu_{2},-\mu_{1}[$, we are in the situation starting in row \ref{debutStep2} of Algorithm \ref{algo:lower bound eps avec param} with $k=2$. So, LB\textunderscore $\epsilon$\textunderscore p($L,1,(\frac{1}{4}),-\frac{1}{4}$) calls LB\textunderscore $\epsilon$\textunderscore i $(L,1,(\frac{1}{4}), -\frac{1}{4})$, where we have written LB\textunderscore $\epsilon$\textunderscore i for Lower\textunderscore Bound\textunderscore $\epsilon$\textunderscore interval defined in Algorithm \ref{algo:lower bound eps avec param interval}, in order to avoid heavy notations.
 \item LB\textunderscore $\epsilon$\textunderscore i $(L,1,(\frac{1}{4}), -\frac{1}{4})$ runs as follows.
 \begin{enumerate}
 \item Since $-\frac{1}{4} \geq -\mu_{2}+\theta_{2}=-\frac{1}{2}+\frac{1}{4}=-\frac{1}{4}$, we are in the situation starting in row \ref{finStep2d} of Algorithm \ref{algo:lower bound eps avec param interval}. Therefore, for each $v \in \Delta(-\frac{1}{4})=\{-\frac{1}{2},-\frac{3}{4},-\frac{3}{8}\}$, it computes $\boldsymbol b_{v}=\text{LB\textunderscore $\epsilon$\textunderscore i$(L,1,(\frac{1}{4}),v)$}$.
\begin{enumerate}
 \item LB\textunderscore $\epsilon$\textunderscore i$(L,1,(\frac{1}{4}),-\frac{3}{4})$ returns $(-\frac{3}{4},\frac{1}{4})$  because $-\frac{3}{4}<-\frac{1}{2}=-\mu_{2}$ so we are in the situation starting with row \ref{finStep2b} of Algorithm \ref{algo:lower bound eps avec param interval} so it calls LB\textunderscore $\epsilon$\textunderscore p$(L,2,(),-\frac{3}{4})$ which returns $-\mu_{2}-(-\frac{3}{4})=-\frac{1}{2}+\frac{3}{4}=\frac{1}{4}$ because we are in the situation starting in  row \ref{debutStep1} of Algorithm \ref{algo:lower bound eps avec param}.
  \item LB\textunderscore $\epsilon$\textunderscore i$(L,1,(\frac{1}{4}),-\frac{1}{2})$ returns $(-\frac{1}{2},\frac{1}{4})$ because $-\frac{1}{2} < -\mu_{2}+\theta_{2}=-\frac{1}{2}+\frac{1}{4}=-\frac{1}{4}$ and $-\frac{1}{2} \geq -\mu_{2}=-\frac{1}{2}$ so we are in the situation starting with row \ref{finStep2c} of Algorithm \ref{algo:lower bound eps avec param interval}  and  $-\mu_{2}+\theta_{2}-(-\frac{1}{2})=-\frac{1}{2}+\frac{1}{4}+\frac{1}{2}=\frac{1}{4}$.
 \item LB\textunderscore $\epsilon$\textunderscore i$(L,1,(\frac{1}{4}),-\frac{3}{8})$ returns $(-\frac{3}{8},\frac{1}{8})$ because $-\frac{3}{8} < -\mu_{2}+\theta_{2}=-\frac{1}{2}+\frac{1}{4}=-\frac{1}{4}$ and $-\frac{3}{8} \geq -\mu_{2}=-\frac{1}{2}$ so we are in the situation starting with row \ref{finStep2c} of Algorithm \ref{algo:lower bound eps avec param interval} and $-\mu_{2}+\theta_{2}-(-\frac{3}{8})=-\frac{1}{2}+\frac{1}{4}+\frac{3}{8}=\frac{1}{8}$.
\end{enumerate}
\item It computes the minimum $m$ of the set \eqref{eq:setpourminvertexnotleaf}, which is, as explained in details in Example~\ref{ex:rec step case 1}, the minimum of  
				\begin{itemize}[label=$\bullet$]
					\item  $\frac{1}{4}\times2^{0-1}=\frac{1}{8}$, 
					\item $\frac{1}{4}\times2^{1-1}=\frac{1}{4}$, 
					\item $\frac{1}{8}\times2^{2-1}=\frac{1}{4}$, 
					\item $0 - \left(- \frac{1}{4}\right)=\frac{1}{4}$,
					\item $\min\{\pi(\Psi(-\frac{1}{4}))\setminus \{-\frac{1}{4}\}\} + \frac{1}{4}=-\frac{1}{8}+\frac{1}{4} = \frac{1}{8}$.
				\end{itemize}
We thus have $m=\frac{1}{8}$.
\item LB\textunderscore $\epsilon$\textunderscore i($L,1,(\frac{1}{4}),-\frac{1}{4}$) returns $(-\frac{1}{4},\frac{1}{8})$.
\end{enumerate}
		\item LB\textunderscore $\epsilon$\textunderscore p$(L,1,(\frac{1}{4}),-\frac{1}{4})$ returns $\frac{1}{8}$.  
					\end{enumerate}
		\item Last, it runs row \ref{finalstepalgo} of Algorithm \ref{algo:lower bound eps avec param} and, after calculations already presented in details in Example \ref{ex:step 3 pour RS}, we find that LB\textunderscore $\epsilon$\textunderscore p$(L,1,(\frac{1}{4}),0)$ returns $\frac{1}{2}$.  	
\end{enumerate}
The latter value $\frac{1}{2}$ is stored in $\theta_1$.



\subsubsection{Last step of Lower\textunderscore Bound\textunderscore $\minepsilon$($L$) } Finally,  Lower\textunderscore Bound\textunderscore $\minepsilon$($L$) returns 
$$
\minepsilonlb=\min\left\{\theta_1,\theta_2,\frac{1}{8}\right\} =\frac{1}{8}\,.
$$


\subsection{Algorithm \ref{algo: rep main question}}\label{main algo on RS example}

 We already computed the positive lower bound $\minepsilonlb=\frac{1}{8}$ on $\minepsilon$. We check that $H=2$ and $N=8$ by definition of $\mathcal E$. Then we have
	$$
	M=(n+1)\left(\left\lfloor (n+1)\frac{\hgt+\mu_{\kappa}}{\minepsilonlb} \right\rfloor + H\right)=618\,.
	$$
	We could compute the set $\V_M$ but, in practice, we can save a few calculations by exploiting the fact that, according to Lemma \ref{lem:infT}, any element of $\Rr$ (and, hence, of any $\Rr_{i}$) is lower than or equal to $\max \E \cup -\S(L) = 8$. Indeed, this remark entails that the intersections with $\V_{M}$ involved in Algorithm \ref{algo: rep main question} for calulating the $\Rr_{i}$ can be replaced  by intersections with $\V_M\cap \Q_{\leq 8}$ without changing the result of the calculations, {\it i.e.}, we have 
	$$\Rr_0 = (\E\cup -\S(L)) \cap \V_{M}=(\E\cup -\S(L)) \cap \V_{M} \cap \Q_{\leq 8}$$
			and  $$\Rr_{i+1}=\bigcup_{(\ellmahl^{\alpha},\beta) \in \P(L)}  \ellmahl^{-\alpha} (\minP (\Rr_i)-\beta)  \cap \V_{M}= \bigcup_{(\ellmahl^{\alpha},\beta) \in \P(L)}  \ellmahl^{-\alpha} (\minP (\Rr_i)-\beta)  \cap \V_{M} \cap \Q_{\leq 8}.$$
Thus, we  only need to compute the set $\V_M\cap \Q_{\leq 8}$, not the whole $\V_{M}$. Let us now explain how one can compute the sets $\Vmaj{i}=\V_i\cap \Q_{\leq 8}$.  We recall that, by definition, the $(\V_{i})_{i \geq 0}$ can be computed recursively as follows: $$
\V_{0}=-\S(L)$$ 
and, for all $i \in \Z_{\geq 0}$,  
$$
\V_{i+1}=\bigcup_{v \in \V_i} \pi(\Psi(v)). 
$$ 
Intersecting with $\Q_{\leq 8}$, we obtain: 
\begin{equation}\label{eq:init Vmaj}
 \Vmaj{0}=-\S(L) \cap \Q_{\leq 8} =-\S(L)
\end{equation}
and, for all $i \in \Z_{\geq 0}$,  
\begin{equation}\label{eq rec inters with Q leq 8}
\Vmaj{i+1}=\bigcup_{v \in \V_i} \pi(\Psi(v)) \cap \Q_{\leq 8}.  
\end{equation}
But, according to \eqref{eq:min Psi(s)=s}, we have, for all $v \in \Q$,  $v=\min \pi(\Psi(v))$. So, for any $v \in \V_{i} \setminus \Vmaj{i}$, we have $\pi(\Psi(v)) \cap \Q_{\leq 8}=\emptyset$ and, hence, \eqref{eq rec inters with Q leq 8} can be rewritten as follows:  
\begin{equation}\label{eq rec Vmaj}
\Vmaj{i+1}=\bigcup_{v \in \Vmaj{i}} \pi(\Psi(v)) \cap \Q_{\leq 8}.  
\end{equation}
Now, \eqref{eq:init Vmaj} and \eqref{eq rec Vmaj} allow us to recursively calculate as many $\Vmaj{i}$ as we like. Note also that, for computing the right-hand side of \eqref{eq rec Vmaj}, we only need to compute $\pi(\Psi(v))$ for $v \in \Vmaj{i} \setminus \Vmaj{i-1}$ because 
$$
\Vmaj{i+1} = \Vmaj{i} \cup \bigcup_{v \in \Vmaj{i}\setminus \Vmaj{i-1}} \pi(\Psi(v)) \cap \Q_{\leq 8}.
	$$
Using this, we may compute $\Vmaj{M}$, which has $5512$ elements, in a fair time\footnote{With a basic desktop computer and the computer algebra software Giac/Xcas it took us less than a minute.}. 	We then compute
\begin{multline*}
\mathcal R_0= (\E\cup -\S(L)) \cap \V_{M}=\E \cap \V_{M} \cap \Q_{\leq 8}=\E \cap \Vmaj{M}\\ 
=	\left\{-\frac{1}{2},-\frac{1}{4},-\frac{1}{8},0,\frac{1}{2},\frac{3}{4},\frac{7}{8},1,\frac{3}{2},\frac{7}{4},2,\frac{5}{2},3,\frac{7}{2},4,5,6,7,8\right\}. 
\end{multline*}
Then, in order to compute $\Rr_{1}$, we first compute (the finite set) $$\bigcup_{(\ellmahl^{\alpha},\beta) \in \P(L)}  \ellmahl^{-\alpha} (\minP (\Rr_0)-\beta)$$
and, then, we compute its intersection with $\Vmaj{M}$. We obtain
$$
\Rr_1 = \Rr_0 \cup \left\{-\frac{1}{16},-\frac{1}{32}\right\}.
$$
 Iterating this process, we find $\Rr_2=\Rr_1$. Thus, $\Rr=\Rr_1$ is a set with $21$ elements.


The next step of Algorithm \ref{algo: rep main question} consists in computing a basis of $\mathcal C_{\Rr}$. 
As explained in the proof of Theorem \ref{theo algo}, this amounts to solve the linear system 
$$F_{\delta}((f_{\gamma})_{\gamma \in \Rr})=0,\quad \delta \in \minP(\Rr)
$$
with $\card \minP(\Rr)=\card \Rr=21$ equations given by \eqref{eq:Fdelta}.  
 We may gather these equations in a matrix whose columns are indexed by the elements of $\Rr$ and whose rows are indexed by the elements of $\minP(\Rr)$. The coefficient of the entry $(\lambda,\gamma)$ of this matrix is the coefficient of $z^\lambda$ in 
$$
L(z^\gamma)=z^{1+4\gamma}+(z-1)z^{2\gamma}-2z^\gamma.
$$
To save space, we shall not reproduce here the square matrix of this system.
After calculations, we find that the kernel of this matrix has dimension $1$, generated by some explicit $(f_{\gamma})_{\gamma \in \Rr}$. This means that $\mathcal C_{\Rr}$ has dimension $1$ and is generated 
by $\sum_{\gamma \in \Rr} f_{\gamma} z^{\gamma}$. 

Last, Algorithm \ref{algo: rep main question} returns $\sum_{\gamma \in \E} f_{\gamma} z^{\gamma}$. Replacing the $f_{\gamma}$ by their explicit values, we find \eqref{output algo ex RS}. 


