The action of $\widehat{\Delta}$ in \eqref{Delhat} on a vector $\mathbf{u}$ with entries $u_{i,j}$ is given by
\begin{equation}\label{delhat}
\widehat{\Delta}\mathbf{u}=(\mathcal{M}-\mathcal{N}_1-\mathcal{N}_2)\mathbf{u},
\end{equation}
where matrix $\mathcal{M}$ is the Kronecker sum in \eqref{kronsum} forcing the boundary conditions \eqref{extbcD} or \eqref{extbcN}, and matrices $\mathcal{N}_1$ and $\mathcal{N}_2$ are sparse matrices with nonzero entries introducing the correction terms $-\Delta (\chi_{\widehat{\Omega}}(x_i,y_j)u_{i,j})$ and $-\Delta (\chi_{\Theta}(x_i,y_j)u_{i,j})$, respectively, according to \eqref{Delhat}. We stress that while the contributions given by $\mathcal{N}_1\mathbf{u}$ may be large and fundamental to have \eqref{phic0}, the correction $\mathcal{N}_2\mathbf{u}$ is small or even zero if the variables exactly vanish on $\Theta$.

Thus, the system of ODEs \eqref{L1} for vectors $\boldsymbol{\phi}$ and $\mathbf{c}$ amounts to
\begin{align}\label{ACodecirc}
\frac{\mathrm{d}\boldsymbol{\phi}}{\mathrm{d}t}=&\,D_\phi (\mathcal{M}-\mathcal{N}_1-\mathcal{N}_2)\boldsymbol{\phi}+F_1(\mathbf{x},\boldsymbol{\phi},\mathbf{c}),\\\label{CHodecirc}
\frac{\mathrm{d}\mathbf{c}}{\mathrm{d}t}=&\, D_c(\mathcal{M}-\mathcal{N}_1-\mathcal{N}_2)(\mathbf{c}+F_2(\boldsymbol{\phi})),
\end{align}
with initial conditions \eqref{initsysom}--\eqref{initsysthet}. In \eqref{ACodecirc}, $\mathbf{x}$ is a vector with the node coordinates lexicographically ordered. $F_1(\mathbf{x},\boldsymbol{\phi},\mathbf{c})$ and $F_2(\boldsymbol{\phi})$ are vectors with entries $\chi_{\widehat{\Omega}}(x_i,y_j)F_1(\phi_{i,j},c_{i,j})$ and $F_2(\phi_{i,j})$, respectively, sorted analogously.

\begin{remark}
As a consequence of Remark \ref{remcons}, the solutions of  \eqref{ACodecirc}--\eqref{CHodecirc} with \eqref{initsysom}--\eqref{initsysthet} satisfy \eqref{phic0}. In particular, the homogeneous Dirichlet boundary conditions \eqref{BCholesDir} of the original problem are naturally satisfied by the solutions of the initial value problem. 
\end{remark}

%\begin{remark}\label{dec}
%Subtracting $\mathcal{N}_1+\mathcal{N}_2$ from $\mathcal{M}$ has the effect of decoupling the equations in each of the systems \eqref{ACodecirc} and \eqref{CHodecirc} in two groups: one involving approximations in $\widehat{\Omega}$ only, the other involves only approximations in $\Theta$. Indeed, solving the first set of equations, is equivalent as solving the original system \eqref{AC}-\eqref{CH} with \eqref{BCholesDir} on the non rectangular domain $\widehat{\Omega}$ by \eqref{centdiff}. However, the diffusion matrix corresponding to these equations only is not a Kronecker sum, and the problem can not be formulated as a Sylvester system for the efficient implementation in [Simoncini]. Indeed, neither matrix $\mathcal{M}-\mathcal{N}_1-\mathcal{N}_2$ is a Kronecker sum, but in the next section we describe efficient time integrators that exploit the Kronecker structure of $\mathcal{M}$, by isolating the contributions of $\mathcal{N}_1$ and $\mathcal{N}_2$. For this reason, we do not actually decouple the two groups of equations. 
%\end{remark}
\subsection{Time integration}\label{sec:TIholes}
Let $\phi_{i,j}^n$ and $c_{i,j}^n$ be the approximation to $\phi(x_i,y_j,t_n)$ and $c(x_i,y_j,t_n)$, respectively.
In order to preserve property \eqref{vanish} we require that
\begin{equation}\label{tdzero}
\phi_{i,j}^n=c_{i,j}^n=0,\qquad (x_i,y_j)\in\Theta,\quad n\geq 0.
\end{equation}
This is achieved if the time discretization of operators $\widehat{\mathcal{L}}_1$ and $\widehat{\mathcal{L}}_2$ preserve their properties \eqref{L11}--\eqref{L1L2}, i.e., denoting them as $\widetilde{\mathcal{L}}_1$ and $\widetilde{\mathcal{L}}_2$, respectively,
\begin{align*}
\widetilde{\mathcal{L}}_1(x_i,y_j,t_n)\approx &\,D_\phi {\Delta}\phi(x_i,y_j,t_n)+F_1(\phi(x_i,y_j,t_n),c(x_i,y_j,t_n)),\quad \text{if}\,\,(x_i,y_j)\in\widehat{\Omega},\\
\widetilde{\mathcal{L}}_2(x_i,y_j,t_n)\approx&\, D_c \Delta[c(x_i,y_j,t_n)+F_2(\phi(x_i,y_j,t_n))],\quad \text{if}\,\,(x_i,y_j)\in\widehat{\Omega},\\
\widetilde{\mathcal{L}}_1(x_i,y_j,t_n)=&\,\widetilde{\mathcal{L}}_2(x_i,y_j,t_n)=0,\quad \text{if}\,\,(x_i,y_j)\in{\Theta},
\end{align*}
for all $n\geq 0$. Hence, we define
\begin{align*}
\widetilde{\mathcal{L}}_1(x_i,y_j,t_n)=&\,D_\phi \widetilde{\Delta}\phi_{i,j}^n+\chi_{\widehat{\Omega}}(x_i,y_j)F_1(\phi_{i,j}^n,c_{i,j}^n),\\
\widetilde{\mathcal{L}}_2(x_i,y_j,t_n)=&\,D_c \widetilde{\Delta}[c_{i,j}^n+F_2(\phi_{i,j}^n)],
\end{align*}
where the operator $\widetilde{\Delta}$ applied to a totally discrete variable $u_{i,j}^n$ is such that
$$\widetilde{\Delta}u_{i,j}^n\approx \widehat{\Delta}u_{i,j}(t_n).$$
Depending on the definition of $\widetilde{\Delta}$ we obtain and compare different IMEX methods. 
\subsubsection{First-order accuracy}
As for the case of a rectangular domain, we relax the stiff equation \eqref{ACodecirc} before the time discretization. A straightforward application of the IMEX Euler method in Section \ref{sec:FirstOrder} to problem \eqref{ACodecirc}--\eqref{CHodecirc} leads to the scheme:
\begin{align}\label{EulerHolesAC}
&(I_{m_xm_y}-\Delta t(D_\phi\mathcal{M}-wI_{m_xm_y}))\boldsymbol{\phi}^{n+1}=\boldsymbol{\phi}^n+\Delta t[ F_1(\mathbf{x},\boldsymbol{\phi}^n,\mathbf{c}^n)- D_\phi(\mathcal{N}_1+\mathcal{N}_2)\boldsymbol{\phi}^n+w\boldsymbol{\phi}^n],\\\label{EulerHolesCH}
&(I_{m_xm_y}-\Delta tD_c\mathcal{M})\mathbf{c}^{n+1}=\mathbf{c}^n+\Delta tD_c (\mathcal{M}-\mathcal{N}_1-\mathcal{N}_2)F_2(\boldsymbol{\phi}^{n+1})-\Delta t D_c\,(\mathcal{N}_1+\mathcal{N}_2)\mathbf{c}^n,
\end{align}
and the corresponding operator $\widetilde{\Delta}$ is defined as
\begin{equation}\label{DeltaEuler}
\widetilde{\Delta} \mathbf{u}^n:=\,\mathcal{M}\mathbf{u}^n-(\mathcal{N}_1+\mathcal{N}_2)\mathbf{u}^{n-1}.
\end{equation}
We observe that, since the coefficient matrices in \eqref{EulerHolesAC}--\eqref{EulerHolesCH} are Kronecker sums, this scheme can be reformulated as a system of Sylvester equations that can be efficiently solved by the strategy in Section \ref{sec:MatOriApp}. However, this method is not really effective in practice. In fact, in order to exactly impose the boundary conditions \eqref{BCholesDir} and have \eqref{phic0}, it is crucial that the time discretization preserves \eqref{Dhat2}, i.e.,
\begin{equation}\label{tildel0}
\widetilde{\Delta}u_{i,j}^n=0,\qquad (x_i,y_j)\in\Theta, \quad n\geq 0.
\end{equation}
Unfortunately, operator $\widetilde{\Delta}$ in \eqref{DeltaEuler} does not satisfy this property. We show this fact referring to the point $(x_i,y_j)$ in Figure \ref{stenc}(b), for simplicity. Even assuming that $u_{i,j}^n=0$ for all $(x_i,y_j)\in\Theta$ and all $n$, we have
\begin{align*}\nonumber
\widetilde{\Delta}u_{i,j}^n=&\,\frac{{u}_{i-1,j}^n-2{u}_{i,j}^n+{u}_{i+1,j}^n}{\Delta x^2}+\frac{{u}_{i,j-1}^n-2{u}_{i,j}^n+{u}_{i,j+1}^n}{\Delta y^2}-\frac{{u}_{i-1,j}^{n-1}}{\Delta x^2}-\frac{{u}_{i,j+1}^{n-1}}{\Delta y^2}\\%\label{resDEE}
=&\,\frac{{u}_{i-1,j}^n-{u}_{i-1,j}^{n-1}}{\Delta x^2}-\frac{{u}_{i,j+1}^n-{u}_{i,j+1}^{n-1}}{\Delta y^2},
\end{align*}
that is nonzero, in general. This quantity is indeed $\mathcal{O}(\Delta t/\Delta x^2)+\mathcal{O}(\Delta t/\Delta y^2)$. A similar result holds for any point of $\Theta$ with neighbors in $\widehat{\Omega}$. We can expect that \eqref{tdzero} is satisfied, at least approximately, when these quantities are negligible. In principle, this happens if $D\Delta t\ll  h^2=\min\{\Delta x^2,\Delta y^2\}$, where $D$ is the diffusion coefficient, that is a too demanding restriction to satisfy.

Thus, we propose here two different versions of the IMEX Euler method by providing two different definitions of the operator $\widetilde{\Delta}$. These are defined by their action on vectors as
\begin{align*}
\widetilde{\Delta}^{I} \mathbf{u}^n:=&\,(\mathcal{M}-\mathcal{N}_1-\mathcal{N}_2)\mathbf{u}^n,\\
\widetilde{\Delta}^{E} \mathbf{u}^n:=&\,(\mathcal{M}-\mathcal{N}_1)\mathbf{u}^n-\mathcal{N}_2\mathbf{u}^{n-1}.
\end{align*}
Superscripts $I$ and $E$ denote that the terms multiplying matrix $\mathcal{N}_2$ are treated implicitly or explicitly, respectively.


In vector form, the schemes obtained by these two operators are, respectively:\\\\
\textbf{IMEX-I Euler}
\begin{align*}
&[I_{m_xm_y}-\Delta t(D_\phi(\mathcal{M}-\mathcal{N}_1-\mathcal{N}_2)-wI_{m_xm_y})]\boldsymbol{\phi}^{n+1}= \boldsymbol{\phi}^n+\Delta t [w\boldsymbol{\phi}^n+F_1(\mathbf{x},\boldsymbol{\phi}^n,\mathbf{c}^n)],\\
&[I_{m_xm_y}-\Delta tD_c(\mathcal{M}-\mathcal{N}_1-\mathcal{N}_2)]\mathbf{c}^{n+1}=\,\mathbf{c}^n+\Delta tD_c (\mathcal{M}-\mathcal{N}_1-\mathcal{N}_2)F_2(\boldsymbol{\phi}^{n+1}),
\end{align*}
\textbf{IMEX-E Euler}
\begin{align*}
&[I_{m_xm_y}-\Delta t(D_\phi(\mathcal{M}-\mathcal{N}_1)-wI_{m_xm_y})]\boldsymbol{\phi}^{n+1}=\boldsymbol{\phi}^n+\Delta t [w\boldsymbol{\phi}^n+F_1(\mathbf{x},\boldsymbol{\phi}^n,\mathbf{c}^n)- D_\phi\mathcal{N}_2\boldsymbol{\phi}^n],\\
&[I_{m_xm_y}-\Delta tD_c(\mathcal{M}-\mathcal{N}_1)]\mathbf{c}^{n+1}=\mathbf{c}^n+\Delta tD_c (\mathcal{M}-\mathcal{N}_1-\mathcal{N}_2)F_2(\boldsymbol{\phi}^{n+1})-\Delta t D_c\mathcal{N}_2\mathbf{c}^n,
\end{align*}
with $w$ such that \eqref{fov} holds true at each time step with $\mathcal{D}$ as in \eqref{Dord1}, and
\begin{equation}\label{ABII}
\mathcal{A}_w=D_\phi(\mathcal{M}-\mathcal{N}_1-\mathcal{N}_2)-wI_{m_xm_y},\quad \mathcal{B}_w=\mathcal{J}_{F_1}+wI_{m_xm_y},
\end{equation}
for IMEX-I Euler,
\begin{equation}\label{ABIE}
\mathcal{A}_w=D_\phi(\mathcal{M}-\mathcal{N}_1)-wI_{m_xm_y},\quad\mathcal{B}_w=\mathcal{J}_{F_1}+wI_{m_xm_y}-D_\phi\mathcal{N}_2,
\end{equation}
for IMEX-E Euler.

We observe that since both matrices $\mathcal{N}_1+\mathcal{N}_2$ and $\mathcal{N}_1$ do not have the structure in \eqref{kronsum}, the coefficient matrices in IMEX-I and IMEX-E are not Kronecker sums. Hence, the efficient implementation in Section \ref{sec:MatOriApp} can not be applied to these methods.

Solving their vector form requires the solution of two linear systems of dimension $m_xm_y$ at each time step. This can be computationally burdensome even if the space grid is not too fine and the domain not too large.

We then look for a technique to speed up the solution of methods in this form. Before presenting such technique, we extend the arguments to second-order accurate schemes.



