\subsubsection{Second-order accuracy}
Following similar arguments as in the previous section, we  define the operators
\begin{align*}
\widetilde{\Delta}^{I} \mathbf{u}^n:=&\,(\mathcal{M}-\mathcal{N}_1-\mathcal{N}_2)\mathbf{u}^n,\\
\widetilde{\Delta}^{E} \mathbf{u}^n:=&\,(\mathcal{M}-\mathcal{N}_1)\mathbf{u}^n-2\mathcal{N}_2\mathbf{u}^{n-1}+\mathcal{N}_2\mathbf{u}^{n-2},
\end{align*}
where the same notation as above is used.

By relaxing the stiff equation \eqref{ACodecirc} as before, the schemes for system \eqref{ACodecirc}--\eqref{CHodecirc} obtained in this way are, respectively:\\\\
\textbf{IMEX-I 2SBDF}
\begin{align*}
[3I_{m_xm_y}-2\Delta t[D_\phi(\mathcal{M}-&\mathcal{N}_1-\mathcal{N}_2)-wI_{m_xm_y}]]\boldsymbol{\phi}^{n+2}=4 \boldsymbol{\phi}^{n+1}-\boldsymbol{\phi}^{n}\\
&+2\Delta t [2F_1(\mathbf{x},\boldsymbol{\phi}^{n+1},\mathbf{c}^n)+2w\boldsymbol{\phi}^{n+1}-F_1(\mathbf{x},\boldsymbol{\phi}^{n},\mathbf{c}^n)-w\boldsymbol{\phi}^{n}],\\
[3I_{m_xm_y}-2\Delta tD_c(\mathcal{M}-\mathcal{N}_1&-\mathcal{N}_2)]\mathbf{c}^{n+2}=4\mathbf{c}^{n+1}-\mathbf{c}^n+2\Delta tD_c (\mathcal{M}-\mathcal{N}_1-\mathcal{N}_2)F_2(\boldsymbol{\phi}^{n+2}),
\end{align*}
\textbf{IMEX-E 2SBDF}
\begin{align*}
[3I_{m_xm_y}-2\Delta t[D_\phi(\mathcal{M}&-\mathcal{N}_1)-wI_{m_xm_y}]]\boldsymbol{\phi}^{n+2}=4\boldsymbol{\phi}^{n+1}-\boldsymbol{\phi}^n+2\Delta t [2F_1(\mathbf{x},\boldsymbol{\phi}^{n+1},\mathbf{c}^n)\\
&+2w\boldsymbol{\phi}^{n+1}- 2D_\phi\mathcal{N}_2\boldsymbol{\phi}^{n+1}-F_1(\mathbf{x},\boldsymbol{\phi}^{n},\mathbf{c}^n)-w\boldsymbol{\phi}^{n}+ D_\phi\mathcal{N}_2\boldsymbol{\phi}^n],\\
(3I_{m_xm_y}-2\Delta tD_c(\mathcal{M}&-\mathcal{N}_1))\mathbf{c}^{n+2}=4\mathbf{c}^{n+1}-\mathbf{c}^n+2\Delta tD_c (\mathcal{M}-\mathcal{N}_1-\mathcal{N}_2)F_2(\boldsymbol{\phi}^{n+2})\\
&-2\Delta tD_c\,\mathcal{N}_2 (2\mathbf{c}^{n+1}-\mathbf{c}^{n}).
\end{align*}
In the two methods above, parameter $w$ satisfies at each time step condition \eqref{fov} with $\mathcal{D}$ in \eqref{Dord2}, and matrices $\mathcal{A}_w$ and $\mathcal{B}_w$ as in \eqref{ABII}--\eqref{ABIE}, respectively.

As before, the efficient implementation in Section \ref{sec:MatOriApp} can not be applied to these methods, as they can not be reformulated in Sylvester form.
\begin{remark}
We do not consider the alternative operators
$$\widetilde{\Delta} \mathbf{u}^n:=(\mathcal{M}-\mathcal{N}_2)\mathbf{u}^n-\mathcal{N}_1\mathbf{u}^{n-1}\,\,\, \text{and} \,\,\,\, \widetilde{\Delta} \mathbf{u}^n:=(\mathcal{M}-\mathcal{N}_2)\mathbf{u}^n-2\mathcal{N}_1\mathbf{u}^{n-1}+\mathcal{N}_1\mathbf{u}^{n-2},$$
to define IMEX methods of order one and two, respectively. In fact, not only the resulting schemes can not be implemented efficiently by the strategy in Section \ref{sec:MatOriApp}, but also these operators do not satisfy \eqref{tildel0} and so they suffer from severe restrictions on the time step to fulfill (approximately) \eqref{tdzero} and the boundary conditions on $\partial\Theta$.

It is easy to show that instead all operators $\widetilde{\Delta}^{I}$ and $\widetilde{\Delta}^{E}$ defined above satisfy property \eqref{tildel0}.
