\section{Iterative matrix-oriented approach on domains with holes}\label{sec:iterative}
For the efficient time integration of system \eqref{ACodecirc}--\eqref{CHodecirc}, we embed an iterative procedure in methods IMEX-I and IMEX-E defined in the previous sections. For the first-order Euler methods we define it as follows:\\\\
\textbf{Iter. IMEX-I Euler and Iter. IMEX-E Euler}
\begin{align}\label{ACiter}
&\!\![(1+w\Delta t)I_{m_xm_y}\!\!-\!\Delta tD_\phi\mathcal{M}]\boldsymbol{\phi}^{n+1,k+1}\!=\boldsymbol{\phi}^n\!+\!\Delta t [w\boldsymbol{\phi}^n\!\!+\!F_1(\mathbf{x},\boldsymbol{\phi}^n,\mathbf{c}^n)\!-\!D_\phi(\mathcal{N}\boldsymbol{\phi}^{n+1,k}\!\!+\!\mathcal{G}\boldsymbol{\phi}^{n})],\\\label{CHiter}
&(I_{m_xm_y}\!-\!\Delta tD_c\mathcal{M})\mathbf{c}^{n+1,k+1}\!=\mathbf{c}^n\!+\!\Delta tD_c [(\mathcal{M}-\mathcal{N}_1-\mathcal{N}_2)F_2(\boldsymbol{\phi}^{n+1})\!-(\mathcal{N}\mathbf{c}^{n+1,k}+\mathcal{G}\mathbf{c}^{n})],
\end{align}
where $\mathcal{N}=\mathcal{N}_1+\mathcal{N}_2$ or $\mathcal{N}=\mathcal{N}_1$, respectively, $\mathcal{G}=\mathcal{N}_1+\mathcal{N}_2-\mathcal{N}$ and $k$ is the iteration number.

The iterative versions of the second-order accurate methods are defined as:\\\\
\textbf{Iter. IMEX-I 2SBDF and Iter. IMEX-E 2SBDF}
\begin{align}\nonumber
&[(3+2w\Delta t) I_{m_xm_y}-2\Delta tD_\phi\mathcal{M}]\boldsymbol{\phi}^{n+2,k+1}=-2\Delta tD_\phi(\mathcal{N}\boldsymbol{\phi}^{n+2,k}+\mathcal{G}(2\boldsymbol{\phi}^{n+1}-\boldsymbol{\phi}^{n}))\\\label{ACiter2}
&\quad+4 \boldsymbol{\phi}^{n+1}-\boldsymbol{\phi}^{n}+2\Delta t [2F_1(\mathbf{x},\boldsymbol{\phi}^{n+1},\mathbf{c}^n)+2w\boldsymbol{\phi}^{n+1}-F_1(\mathbf{x},\boldsymbol{\phi}^{n},\mathbf{c}^n)-w\boldsymbol{\phi}^{n}],\\\nonumber
&[3I_{m_xm_y}-2\Delta tD_c\mathcal{M}]\mathbf{c}^{n+2,k+1}=4\mathbf{c}^{n+1}-\mathbf{c}^n-2\Delta tD_c(\mathcal{N}\mathbf{c}^{n+2,k}+\mathcal{G}(2\mathbf{c}^{n+1}-\mathbf{c}^{n}))\\\label{CHiter2}
&\quad+2\Delta tD_c (\mathcal{M}-\mathcal{N}_1-\mathcal{N}_2)F_2(\boldsymbol{\phi}^{n+1}),
\end{align}
with, again, $\mathcal{N}=\mathcal{N}_1+\mathcal{N}_2$ or $\mathcal{N}=\mathcal{N}_1$, respectively, $\mathcal{G}=\mathcal{N}_1+\mathcal{N}_2-\mathcal{N}$ and $k$ is the iteration number.

The iterative procedures above solve two sequences of linear systems at each time step, in contrast to the IMEX-I and IMEX-E methods in Section \ref{sec:TIholes}, which solve only two linear systems per time step.
%In principle, the advantage of these procedures relies on the Kronecker sum structure of the coefficient matrices in \eqref{ACiter} and \eqref{CHiter} that allows for the efficient implementation in \citep{Simoncini} as discussed in the previous sections. 
However, the coefficient matrices in \eqref{ACiter}--\eqref{CHiter} and in \eqref{ACiter2}--\eqref{CHiter2} are all Kronecker sums. Thus, these systems can all be written in Sylvester form and solved efficiently as in Section~\ref{sec:MatOriApp}.

Next, we will analyze under which circumstances the linear systems in \eqref{ACiter}--\eqref{CHiter} and \eqref{ACiter2}--\eqref{CHiter2} are solvable, and the resulting iterative methods converge and how fast.

The linear systems defining the iterative methods in \eqref{ACiter}--\eqref{CHiter2} have a unique solution if their coefficient matrices are non singular. All these matrices are in the form
\begin{equation}\label{matP}
\mathcal{P}= \beta I-\alpha\mathcal{M},\qquad \alpha, \beta>0,
\end{equation}
%In particular, $(\alpha,\beta)=(\Delta tD_\phi,\zeta)$ in \eqref{ACiter}, $(\alpha,\beta)=(\Delta tD_c,1)$ in \eqref{CHiter}, $(\alpha,\beta)=(2\Delta tD_\phi,3+2w\Delta t)$ in \eqref{ACiter2}, and $(\alpha,\beta)=(2\Delta tD_c,3)$ in \eqref{CHiter2}. 
with $\mathcal{M}$ in \eqref{kronsum}. The following theorem establishes that the proposed methods are well-defined for any choice of the grid steps.
\begin{theorem}
Any matrix $\mathcal{P}$ in the form \eqref{matP} is invertible.
\end{theorem}
\begin{proof}
Matrix $\mathcal{M}$ is diagonalizable with all negative eigenvalues. Thus, there exists a matrix $Q$ such that $\mathcal{M}=QDQ^{-1}$ with $D$ the diagonal matrix of the eigenvalues. Hence,
$$\det(\mathcal{P})=\det(\beta I-\alpha QDQ^{-1})=\det(\beta I-\alpha D),$$
that is nonzero because matrix $\beta I -\alpha D$ is diagonal with positive entries.
\end{proof}

To establish when and how fast the proposed iterations converge, we start by providing upper bounds for the spectral radius of the iteration matrices in the iterative IMEX-I methods.
Henceforth, the spectral radius of a matrix $A$ is denoted by $\rho(A)$.

In principle, we limit the following discussion to the case of Dirichlet boundary conditions \eqref{extbcD}. In this case matrix $\mathcal{P}$ in \eqref{matP} is symmetric.

\begin{theorem}\label{theorhosig}
The spectral radius of matrix 
\begin{equation}\label{Sig}
\Sigma=-\alpha\mathcal{P}^{-1}\mathcal{N},\qquad \mathcal{N}=\mathcal{N}_1+\mathcal{N}_2
\end{equation}
with $\mathcal{P}$ as in \eqref{matP}, is such that 
\begin{equation}\label{th2th1}
\rho(\Sigma)\leq \frac{4\alpha}{\beta}\left(\frac{1}{\Delta x^2}+\frac{1}{\Delta y^2}\right).
\end{equation}
\end{theorem}
\begin{proof}
The spectral radius of matrix $\Sigma$ can be bounded as follows,
$$\rho(\Sigma) = \alpha\rho(\mathcal{P}^{-1}\mathcal{N})\leq \alpha\|\mathcal{P}^{-1}\mathcal{N}\|_2\leq \alpha\|\mathcal{P}^{-1}\|_2\|\mathcal{N}\|_2.$$
Since $\mathcal{P}$ is symmetric, and using well-known norm inequalities, then
$$\rho(\Sigma)\leq \alpha\|\mathcal{P}^{-1}\|_2\|\mathcal{N}\|_2= \alpha \rho(\mathcal{P}^{-1}) \|\mathcal{N}\|_2\leq \alpha\rho(\mathcal{P}^{-1}) \sqrt{\|\mathcal{N}\|_1\|\mathcal{N}\|_{\infty}}.$$
The eigenvalues of matrix $\mathcal{M}$ are known and negative, thus if $\lambda$ is the largest eigenvalue of $\mathcal{M},$ then the smallest eigenvalue of $\mathcal{P}$ is 
$$\beta-\alpha \lambda >0,$$
and the spectral radius of $\mathcal{P}^{-1}$ is then
$$\rho(\mathcal{P}^{-1})=\frac{1}{\beta-\alpha\lambda}<\frac{1}{\beta}.$$
In order to bound the two norms of $\mathcal{N}$ we observe that 
%\begin{itemize}
%\item[•] For IMEX-E Euler $\mathcal{N}=\mathcal{N}_1$ and the $i$-th row has nonzero entries if node $\mathbf{x}_i\in\Theta$ and has neighbors in $\widehat{\Omega}$. The number of nonzero entries in this row is given by the number of such neighbors and can not be more than four.
%Their sum, $S_{\mathrm{row}}(\mathcal{N})$, is such that
%$$-2\left(\frac{1}{\Delta x^2}+\frac{1}{\Delta y^2}\right)\leq S_{\mathrm{row}}(\mathcal{N})\leq 0.$$
%Therefore,
%$$\|\mathcal{N}\|_1\leq 2\left(\frac{1}{\Delta x^2}+\frac{1}{\Delta y^2}\right).$$
%
%Similarly, the $j$-th column has nonzero entries if node $\mathbf{x}_j\in\widehat{\Omega}$ with neighbors in $\Theta$. The number of nonzero entries is equal to the number of such neighbors and is no more than four. Thus,
%$$\|\mathcal{N}\|_\infty\leq 2\left(\frac{1}{\Delta x^2}+\frac{1}{\Delta y^2}\right).$$
%Thus, we conclude that for IMEX-E,
%$$\rho(\Sigma)\leq \alpha\rho(\mathcal{P}^{-1}) \sqrt{\|\mathcal{N}\|_1\|\mathcal{N}\|_{\infty}}\leq \frac{2\alpha}{\beta}\left(\frac{1}{\Delta x^2}+\frac{1}{\Delta y^2}\right).$$
%\item[•] 
%\end{itemize}
the $i$-th row has nonzero entries only if some nodes in the stencil centered on $\mathbf{x}_i$ are in $\Theta$. Thus, the number of nonzero entries in a row and the sum of their moduli is maximized when the whole stencil is in $\Theta$, and thus,
$$\|\mathcal{N}\|_\infty\leq 4\left(\frac{1}{\Delta x^2}+\frac{1}{\Delta y^2}\right).$$
We can reason in a similar way on the columns, and so,
$$\|\mathcal{N}\|_1\leq 4\left(\frac{1}{\Delta x^2}+\frac{1}{\Delta y^2}\right).$$
We conclude then that
$$\rho(\Sigma)\leq \alpha\rho(\mathcal{P}^{-1}) \sqrt{\|\mathcal{N}\|_1\|\mathcal{N}\|_{\infty}}\leq \frac{4\alpha}{\beta}\left(\frac{1}{\Delta x^2}+\frac{1}{\Delta y^2}\right).$$
\end{proof}
The following corollary establishes an upper bound for the spectral radii of the iteration matrices in \eqref{ACiter}--\eqref{CHiter2} with $\mathcal{N}=\mathcal{N}_1+\mathcal{N}_2$.
\begin{corollary}\label{cor1}
