\begin{remark}\label{rem:notsharp}
With similar steps as in the proofs of Theorem \ref{theorhosig} and Corollary \ref{cor1}, one can obtain similar bounds on the spectral radius of the iteration matrices in \eqref{ACiter}--\eqref{CHiter2} of the iterative IMEX-E method. In fact, by reasoning in a similar way on the norms of matrix $\mathcal{N}=\mathcal{N}_1$, it is easy to prove that
$$\rho_\phi \leq \frac{2D_\phi\Delta t}{1+w \Delta t}\left(\frac{1}{\Delta x^2}+\frac{1}{\Delta y^2}\right),\qquad \rho_c \leq 2D_c\Delta t \left(\frac{1}{\Delta x^2}+\frac{1}{\Delta y^2}\right),$$
for the iteration matrices of IMEX-E Euler in \eqref{ACiter}--\eqref{CHiter}, and
$$\rho_\phi \leq \frac{4D_\phi\Delta t}{3+2w \Delta t}\left(\frac{1}{\Delta x^2}+\frac{1}{\Delta y^2}\right),\qquad \rho_c \leq \frac{4}3D_c\Delta t \left(\frac{1}{\Delta x^2}+\frac{1}{\Delta y^2}\right),$$
for the iteration matrices of IMEX-E 2SBDF in \eqref{ACiter2}--\eqref{CHiter2}.
However, bounds sharper than these are provided below.
\end{remark}
We now aim at establishing bounds on the spectral radius of the iteration matrices defined by the iterative {IMEX-E} method in \eqref{ACiter}--\eqref{CHiter}, which are sharper than those in Remark \ref{rem:notsharp}. These bounds are derived from the fact that matrix $\mathcal{N}=\mathcal{N}_1$ is nilpotent of order two (see Lemma \ref{lemnil}).

\begin{Lemma}[see \cite{Shemesh}]\label{Shemesh}
If two matrices $A$ and $B$ satisfy
$$A[A,B]=[A,B]B=0,\qquad [A,B]=AB-BA,$$
then they are simultaneously triangularizable, i.e. there exists an invertible matrix $Q$ such that $Q^{-1}AQ$ and $Q^{-1}BQ$ are upper triangular.
\end{Lemma}

\begin{theorem}\label{theosig}
%Let be $\|\cdot\|$ a matrix norm, and matrix $\Sigma$ as in \eqref{Sig} with $\mathcal{N}$ nilpotent such that $\mathcal{N}^2=0$. If $\alpha$ and $\beta$ are such that $\alpha\|\mathcal{M}\|<\beta$, then 
%\begin{equation}\label{thth2}
%\rho(\Sigma)< \frac{\alpha^2\rho(\mathcal{M})\sqrt{\|\mathcal{N}\|_1\|\mathcal{N}\|_\infty}}{\beta^2+\alpha\beta\rho(\mathcal{M})}.
%\end{equation}
Let $\Sigma$ be a matrix as in \eqref{Sig} with $\mathcal{N}$ nilpotent such that $\mathcal{N}^2=0$. Then 
\begin{equation}\label{thth2}
\rho(\Sigma)< \frac{\alpha^2\rho(\mathcal{M})\sqrt{\|\mathcal{N}\|_1\|\mathcal{N}\|_\infty}}{\beta^2+\alpha\beta\rho(\mathcal{M})}.
\end{equation}
\end{theorem}
\begin{proof}
%The inverse of matrix $\mathcal{P}$ is
%$$\mathcal{P}^{-1}=\frac{1}{\beta}\left(I-\frac{\alpha}{\beta}\mathcal{M}\right)^{-1}.$$
%If $\alpha\|\mathcal{M}\|<\beta,$ then $\mathcal{P}^{-1}$ can be expanded as a convergent power series,
%$$\mathcal{P}^{-1}=\frac{1}{\beta}\left[I+\sum_{k=1}^\infty \left(\frac{\alpha}{\beta}\mathcal{M}\right)^k\right],$$
%and so
%$$\Sigma=\frac{-\alpha}{\beta^2}\left[\beta\mathcal{N}+{\alpha}\mathcal{SN}\right],$$
%where 
%$$\mathcal{S}=\mathcal{M}\left[\sum_{k=0}^\infty \left(\frac{\alpha}{\beta}\right)^{k}\mathcal{M}^k\right]=\frac{\beta}{\alpha}(\beta\mathcal{P}^{-1}-I).$$
Matrix $\Sigma$ can be written as 
$$\Sigma=\frac{-\alpha}{\beta^2}\left[\beta\mathcal{N}+{\alpha}\mathcal{SN}\right],\qquad \mathcal{S}=\frac{\beta}{\alpha}(\beta\mathcal{P}^{-1}-I).$$
We show that the sets of the eigenvalues of matrices $\beta\mathcal{N}+{\alpha}\mathcal{SN}$ and ${\alpha}\mathcal{SN}$ coincide. According to Lemma \ref{Shemesh} matrices ${\alpha}\mathcal{SN}$ and $\beta\mathcal{N}$ are simultaneously triangularizable. In fact, taking into account that $\mathcal{N}^2=0$,
\begin{align*}
&{\alpha}\mathcal{SN}[{\alpha}\mathcal{SN},\beta\mathcal{N}]={\alpha}\mathcal{SN}({\alpha}\beta\mathcal{SN}\mathcal{N}-{\alpha}\beta\mathcal{N}\mathcal{SN})=0,\\
&[{\alpha}\mathcal{SN},\beta\mathcal{N}]\beta\mathcal{N}=\beta({\alpha}\beta\mathcal{SN}\mathcal{N}-{\alpha}\beta\mathcal{N}\mathcal{SN})\mathcal{N}=0.
\end{align*}
Therefore, there exists an invertible matrix $Q$ such that $\alpha Q^{-1}\mathcal{SN}Q$ and $\beta Q^{-1}\mathcal{N}Q$ are both triangular with diagonal entries equal to the eigenvalues of $\mathcal{SN}$ and of $\mathcal{N}$, respectively. The triangularization of matrix $\beta\mathcal{N}+{\alpha}\mathcal{SN}$ is then
$$Q^{-1}\beta\mathcal{N}Q+Q^{-1}{\alpha}\mathcal{SN}Q,$$
whose diagonal entries are sums of an eigenvalue of $\mathcal{SN}$ and an eigenvalue of $\mathcal{N}$. Since $\mathcal{N}$ is nilpotent, its eigenvalues are all zero, and thus the eigenvalues of $\beta\mathcal{N}+{\alpha}\mathcal{SN}$ are those of ${\alpha}\mathcal{SN}$.
We can conclude that 
\begin{equation}\label{eqrhosi}
\rho(\Sigma)=\frac{\alpha^2}{\beta^2}\rho(\mathcal{SN})\leq \frac{\alpha^2}{\beta^2}\|\mathcal{S}\|_2\|\mathcal{N}\|_2\leq \frac{\alpha^2}{\beta^2}\rho(\mathcal{S})\sqrt{\|\mathcal{N}\|_1\|\mathcal{N}\|_\infty},
\end{equation}
since matrix $\mathcal{S}$ is symmetric. Moreover,
$$\rho(\mathcal{S})=\frac{\beta}{\alpha}\rho(\beta\mathcal{P}^{-1}-I),$$
and the eigenvalues of $\beta\mathcal{P}^{-1}$ are in the form
$$0<\frac{\beta}{\beta - \alpha \lambda}<1,$$
with $\lambda<0$ eigenvalue of $\mathcal{M}$. Then,
$$\rho(\beta\mathcal{P}^{-1}-I)=\max_\lambda \left|\frac{\beta}{\beta-\alpha \lambda}-1\right|=1-\frac{\beta}{\beta+\alpha \rho(\mathcal{M})}=\frac{\alpha\rho(\mathcal{M})}{\beta+\alpha \rho(\mathcal{M})}.$$
So, 
$$\rho(\mathcal{S})=\frac{\beta\rho(\mathcal{M})}{\beta+\alpha \rho(\mathcal{M})},$$
and the theorem is proved after substitution in \eqref{eqrhosi}.
\end{proof}
\begin{Lemma}\label{lemnil}
Matrix $\mathcal{N}=\mathcal{N}_1$ in \eqref{delhat} is nilpotent and such that $\mathcal{N}^2=0$ 
\end{Lemma}
\begin{proof}
Let us denote by $\mathbf{x}_k$ the $k$-th grid node following the lexicographic order. 
The statement is proved by showing that for any $i,j$ and $k$
$$\mathcal{N}_{i,k}\,\mathcal{N}_{k,j}=0,$$
where $\mathcal{N}_{m,n}$ denotes the entry $(m,n)$ of matrix $\mathcal{N}$. In fact, for sake of contradiction, we assume that there exist $i,j$ and $k$ such that
\begin{equation}\label{nil}
\mathcal{N}_{i,k}\neq 0,\qquad \mathcal{N}_{k,j}\neq 0.
\end{equation}
By construction of matrix $\mathcal{N}$, entry $\mathcal{N}_{m,n}\neq 0$ if node $\mathbf{x}_m\in\Theta$ and node $\mathbf{x}_n\in\widehat{\Omega}$ is a neighbor of $\mathbf{x}_m$. Assuming \eqref{nil} implies that $\mathbf{x}_k\in \widehat{\Omega}\cap\Theta$, which leads to a contradiction as these sets are disjoint.
\end{proof}
The following corollary provides sharper bounds than Remark \ref{rem:notsharp} on the spectral radius of the iteration matrices of the iterative IMEX-E Euler method in \eqref{ACiter}--\eqref{CHiter} and of IMEX-E 2SBDF method in \eqref{ACiter2}--\eqref{CHiter2}.
\begin{corollary}\label{cor4}
%Let be $\|\cdot\|$ a matrix norm, and $\mathcal{N}=\mathcal{N}_1$ as defined in \eqref{delhat}. If $\omega$ and $\Delta t$ are such that
%\begin{equation}\label{h1}
%(D_\phi\|\mathcal{M}\|-\omega)\Delta t<1,
%\end{equation} then 
%\begin{equation}\label{t1}
%\rho_\phi \leq \frac{D_\phi^2\Delta t^2\rho(\mathcal{M})\sqrt{\|\mathcal{N}\|_1\|\mathcal{N}\|_\infty}}{(1+\omega \Delta t)(1+\omega \Delta t+\Delta t D_\phi\rho(\mathcal{M}))}.
%\end{equation}
%If 
%\begin{equation}\label{h2}
%\Delta t<(D_c\|\mathcal{M}\|)^{-1}
%\end{equation}
%then 
%\begin{equation}\label{t2}
%\rho_c \leq \frac{D_c^2{\Delta t^2}\rho(\mathcal{M})\sqrt{\|\mathcal{N}\|_1\|\mathcal{N}\|_\infty}}{1+\Delta t D_c\rho(\mathcal{M})}.
%\end{equation}
Let $\mathcal{N}=\mathcal{N}_1$ as defined in \eqref{delhat}. Then, the spectral radii of the iteration matrices of IMEX-E Euler method in \eqref{ACiter} and \eqref{CHiter} are such that 
\begin{equation}\label{t1}
\rho_\phi \leq \frac{D_\phi^2\Delta t^2\rho(\mathcal{M})\sqrt{\|\mathcal{N}\|_1\|\mathcal{N}\|_\infty}}{(1+w \Delta t)(1+w \Delta t+\Delta t D_\phi\rho(\mathcal{M}))},
\end{equation}
and
\begin{equation}\label{t2}
\rho_c \leq \frac{D_c^2{\Delta t^2}\rho(\mathcal{M})\sqrt{\|\mathcal{N}\|_1\|\mathcal{N}\|_\infty}}{1+\Delta t D_c\rho(\mathcal{M})},
\end{equation}
respectively. The spectral radii of the iteration matrices of IMEX-E 2SBDF method in \eqref{ACiter2} and \eqref{CHiter2} satisfy the bounds 
\begin{equation}\label{t12}
\rho_\phi \leq \frac{4D_\phi^2\Delta t^2\rho(\mathcal{M})\sqrt{\|\mathcal{N}\|_1\|\mathcal{N}\|_\infty}}{(3+2w \Delta t)(3+2w \Delta t+2\Delta t D_\phi\rho(\mathcal{M}))},
\end{equation}
and
\begin{equation}\label{t22}
\rho_c \leq \frac{4D_c^2{\Delta t^2}\rho(\mathcal{M})\sqrt{\|\mathcal{N}\|_1\|\mathcal{N}\|_\infty}}{9+6\Delta t D_c\rho(\mathcal{M})},
\end{equation}
respectively.
\end{corollary}
\begin{proof}
The iteration matrices of equations \eqref{ACiter} and \eqref{CHiter} are in the form \eqref{Sig}. As a consequence of Lemma \ref{lemnil}, the assumptions of Theorem \ref{theosig} are satisfied. 
The bounds in the statement are proved by replacing in \eqref{thth2} the corresponding values of $\alpha$ and $\beta$.
\end{proof}

\begin{remark}\label{rem3}
More explicit bounds on $\rho_\phi$ and $\rho_c$ can be obtained by considering that the eigenvalues of $\mathcal{M}$ are known, and that
\begin{equation}\label{rhoMb}
\rho(\mathcal{M})<\frac{4}{\Delta x^2}+\frac{4}{\Delta y^2}.
\end{equation}
\end{remark}
The next corollary provides explicit bounds in terms of the discretization steps, when $\Theta$ is a circle. This particular geometry is relevant for one of the experiments in Section \ref{sec:tests}. The arguments can be straightforwardly adapted to sets of different shape or union of disjoint sets.
\begin{corollary}\label{cor2}
Let $\Theta$ be a circle with radius $r>h=\Delta x=\Delta y$. Then the spectral radii of the iteration matrices of IMEX-E Euler method in \eqref{ACiter} and \eqref{CHiter} with $\mathcal{N}=\mathcal{N}_1$ in \eqref{delhat} are such that
\begin{align*}%\label{boundphic}
\rho_\phi<\,\frac{8\sqrt{6}D_\phi^2\Delta t^2 }{h^4(1+w \Delta t)(1+w \Delta t+8\Delta t D_\phi/h^2)},\quad
\rho_c <\, \frac{8\sqrt{6}D_c^2{\Delta t^2}}{h^4(1+8\Delta t D_c/h^2)}
\end{align*}
respectively. The spectral radii of the iteration matrices of IMEX-E 2SBDF method in \eqref{ACiter2} and \eqref{CHiter2} with $\mathcal{N}=\mathcal{N}_1$ in \eqref{delhat} satisfy the bounds
\begin{align*}%\label{boundphic2}
\rho_\phi<\,\frac{32\sqrt{6}D_\phi^2\Delta t^2 }{h^4(3+2w \Delta t)(3+2w \Delta t+16\Delta t D_\phi/h^2)},\quad
\rho_c <\, \frac{32\sqrt{6}D_c^2{\Delta t^2}}{h^4(9+48\Delta t D_c/h^2)}
\end{align*}
respectively.
\begin{proof}
The proof follows from Corollary \ref{cor4}, considering that with this geometry of $\Theta$ each node $(x_i,y_j)\in\widehat{\Omega}$ can not have more than two neighbors in $\Theta$ and if two, they are in perpendicular directions from $(x_i,y_j)$. Thus,
$$\|\mathcal{N}\|_1\leq \frac{1}{\Delta x^2}+\frac{1}{\Delta y^2}=\frac{2}{h^2}.$$
Similarly, each node in $\Theta$ can only have no more than three neighbors in $\widehat{\Omega}$. Hence,
$$\|\mathcal{N}\|_\infty\leq \frac{1}{\Delta x^2}+\frac{1}{\Delta y^2}+\frac{1}{\min\{\Delta x,\Delta y\}}=\frac{3}{h^2}.$$
The statement then follows from Corollary \ref{cor4}, considering also \eqref{rhoMb}.
\end{proof}
\end{corollary}
\begin{remark}
In the previous corollary the assumption $\Delta x=\Delta y$ is introduced only for sake of simplicity. As clear from its proof, the results can be generalized to the more general case $\Delta x \neq \Delta y$.
\end{remark}
\begin{remark} Let $\mathcal{N}=\mathcal{N}_1$ as defined in \eqref{delhat}, and let $C$ denote generic real quantities independent of the steps. From Corollary \ref{cor4}, it follows straightforwardly that there exist $C$ such that
\begin{align*}
&\rho_\phi <C{\Delta t^2}({D_\phi^2\rho(\mathcal{M})\sqrt{\|\mathcal{N}\|_1\|\mathcal{N}\|_\infty}})\\
&\rho_c <C{\Delta t^2}(D_c^2\rho(\mathcal{M})\sqrt{\|\mathcal{N}\|_1\|\mathcal{N}\|_\infty}),
\end{align*}
where $\rho_\phi$ and $\rho_c$ are the spectral radii of the iteration matrices of IMEX-E Euler in \eqref{ACiter} and \eqref{CHiter}, respectively, or of IMEX-E 2SBDF in \eqref{ACiter2} and \eqref{CHiter2}, respectively. 
Since (see Remark \ref{rem3} and, e.g., the proof of Corollary \ref{cor2})
$$\rho(\mathcal{M})\sqrt{\|\mathcal{N}\|_1\|\mathcal{N}\|_\infty}\sim \frac{1}{h^4},\qquad h=\min\{\Delta x,\Delta y\},$$
then, there exists $C$ such that
$$\rho_\phi<C\frac{\Delta t^2}{h^4},\qquad \rho_c<C\frac{\Delta t^2}{h^4}.$$
The methods are convergent if both $\rho_\phi<1$ and $\rho_c<1$.  This leads to restrictions on the steps of the type $C\Delta t<h^2$, that are unpractical when solving general PDEs. However, in this case, it is clear from \eqref{t1}--\eqref{t22} that
$$C\leq\max\left\{\frac{D_\phi}{1+w\Delta t},D_c\right\}\qquad \text{and}\qquad C\leq\max\left\{\frac{2D_\phi}{3+2w\Delta t},\frac{2D_c}3\right\}$$
for first- and second-order methods, respectively.

Thus, in all cases constant $C$ is small, being the diffusion coefficients very tiny, and $w$ very large, as it reflects the order of magnitude of the eigenvalues of $\mathcal{J}_{F_1}\sim 10^8$. Therefore, these restrictions do not severely prevent the use of relatively large time steps.  

We observe that restrictions of the type $C\Delta t<h^2$ are typical in the time integration of diffusion-reaction equations by explicit methods. However, for these methods, constant $C$ is large because of the large eigenvalues of $\mathcal{J}_{F_1}$.
\end{remark}

\begin{remark}[Neumann Boundary Conditions]\label{remsym}
Theorems \ref{theorhosig} and \ref{theosig} and their corollaries are proved assuming that matrix $\mathcal{P}$ in \eqref{matP} is symmetric. This is the case if Dirichlet boundary conditions \eqref{extbcD} are applied on $\partial \Omega$ or if Neumann boundary conditions \eqref{extbcN} are approximated by first-order finite differences. However, when using the second-order discretization \eqref{kronsum} with \eqref{MN}, this assumption is not satisfied. Nevertheless, methods \eqref{ACiter} and \eqref{CHiter} can be adapted to this case. Let
$$\overline{\mathcal{M}}=I_{m_y}\otimes\frac{1}{\Delta x^2}\left[\begin{array}{ccccc}
0 & -1 & & &\\
0 & 0 & 0 & &\\
& \ddots & \ddots & \ddots &\\
& & 0 & 0 & 0\\
& & & -1 & 0
\end{array}\right]+\frac{1}{\Delta y^2}\left[\begin{array}{ccccc}
0 & -1 & & &\\
0 & 0 & 0 & &\\
& \ddots & \ddots & \ddots &\\
& & 0 & 0 & 0\\
& & & -1 & 0
\end{array}\right]\otimes I_{m_x}$$ 
be the difference between the Laplacian matrix with Dirichlet and Neumann boundary conditions, i.e. between \eqref{kronsum} with \eqref{MD} and \eqref{kronsum} with \eqref{MN}.

The iterative IMEX-I methods are adjusted by redefining $\mathcal{N}=\mathcal{N}_1+\mathcal{N}_2+\overline{\mathcal{M}}$ in \eqref{ACiter}--\eqref{CHiter2}. Note that although matrix $\mathcal{N}$ is changed, the result in Corollary~\ref{cor1} still holds true as the bounds on the norms of $\mathcal{N}$ do not change.

The rationale in IMEX-E methods is that small correction terms can be treated explicitly. We distinguish here two circumstances.

\begin{itemize}
\item[a)] The corrosion interface does not reach $\partial \Omega$ for all $t\in[0,T]$. In this case we do not expect a great difference in the values of the dependent variables close to the boundary when stepping from time $t_n$ to $t_{n+1}$. Thus, we can modify the iterative IMEX-E methods by setting $\mathcal{G}=\mathcal{N}_2+\overline{\mathcal{M}}$.
\item[b)] 
The corrosion interface will reach $\partial \Omega$ at some time $t_c\in[0,T]$. After $t_c$ the value of the dependent variables close to the boundary may change sensibly from one time step to the next one. Thus, it would be recommendable to redefine $\mathcal{N}=\mathcal{N}_1+\overline{\mathcal{M}}$ and $\mathcal{G}=\mathcal{N}_2$ for accuracy. However, in this case the new matrix $\mathcal{N}$ is not nilpotent of order two and thus Theorem \ref{theosig} can not be applied. Nevertheless, the bounds in Remark \ref{rem:notsharp} are valid. 
\end{itemize}
In case a) matrix $\mathcal{N}$ is unchanged and all the convergence results in this section still apply. In case b), although one could introduce control techniques to detect the critical time $t_c$ and redefine the matrices only for $t>t_c$, the bounds in Remark \ref{rem:notsharp} are larger than the ones in Corollary \ref{cor4}. So the speed of convergence may be drastically reduced.

Based on heuristics, we observe that Corollary \ref{cor4} seems valid also in other circumstances when matrix $\mathcal{M}$ is given by \eqref{kronsum} with \eqref{MN}, although $\mathcal{P}$ is not symmetric.
So, despite the modifications above give solid theoretical information on the convergence of the iterative method, it is recommendable, at least in the circumstances described in b), to apply the original iterative IMEX-E methods \eqref{ACiter}--\eqref{CHiter2}, where $\mathcal{M}$ is the Kronecker sum \eqref{kronsum} with \eqref{MN}.
\end{remark}
