\subsection{DEF allocation}
\begin{Theorem} \label{thm:efable--iff-cost-cycles}
    For $O$ the allocation of the original apartments and $A$ the new apartments allocation, the following statements are equivalent:
    \begin{enumerate} [label=(\alph*)]
    \item $A$ is DEF-able
    \item $
\sum_{i\in N} v_i(A_i) - v_i(o_i) \geq \sum_{i\in N} v_i(A_{\pi(i)}) - v_i(o_{\pi(i)})$, 
for all permutations $\pi$ of $N$. 
%\erel{In the LHS $i$ is a summation index, but in the RHS $i$ appears without a sum. Is it a typo?}
    \item $G_{A,O}$ has no positive-cost cycles; that is, for every cycle $C$, $cost_A(C) \leq cost_O(C)$. \label{condition b of theorem thm:efable--iff-cost-cycles}
\end{enumerate}
\end{Theorem} 
\begin{proof}
$(a) \Rightarrow (b)$: Suppose $A$ is DEF-able. Then, there exists a payment vector \textbf{p} such that$(A,\mathbf{p})$ are DEF. that is, for all agents $i,j$, $v_i(A_i) - v_i(o_i) + p_i \geq v_i(A_j) - v_i(o_j) + p_j$. Equivalently, $\left( v_i(A_j) - v_i(o_j) \right) - \left( v_i(A_i) - v_i(o_i) \right) \leq p_i - p_j$.

Consider any permutation $\pi$ of $N$. Then,
\[
\sum_{i\in N} \left(\left( v_i(A_{\pi(i)}) - v_i(o_{\pi(i)}) \right) - \left( v_i(A_i) - v_i(o_i) \right) \right) \leq \sum_{i\in N} \left( p_i - p_{\pi(i)}\right) = 0.
\]
The last entry is zero as all the payments are considered twice, and they cancel out each other. Hence, 
\[
\sum_{i\in N} v_i(A_{i}) - v_i(o_{i}) \geq \sum_{i\in N} v_i(A_{\pi(i)}) - v_i(o_{\pi(i)})
\]
for each permutation $\pi$ of $N$.

$(b) \Rightarrow (c)$: Suppose that $
\sum_{i\in N} v_i(A_i) - v_i(o_i) \geq \sum_{i\in N} v_i(A_{\pi(i)}) - v_i(o_{\pi(i)})$, 
%\erel{In the LHS $i$ is a summation index, but in the RHS $i$ appears without a sum. Is it a typo?}
for some allocation $A$, and all permutations $\pi$ of $N$. 
Consider a cycle $C = (i_{1} , ... , i_{r})$ in $G_{A,O}$, and a permutation $\pi$, defined for each agent $i_k \in N$ as follows: \[\pi(i_k) = \begin{cases}
    i_k, &i_k\notin C \\
    i_{k+1}, & k \in \{1, \ldots, r-1 \} \\
    i_1 & k = r 
\end{cases}. \]
Examining the cost of $C$ in the difference graph $G_{A,O}$:
\begin{equation*} 
\begin{split}
    &cost_A(C) - cost_O(C) = cost_{A,O}(C) = \\
    &\sum_{i\in C} \left(\left(v_{i}(A_{\pi(i)}) - v_i(o_{\pi(i)}) \right) - \left(v_{i}(A_{i}) - v_{i}(o_i) \right)\right) \leq 0.
\end{split}
\end{equation*}
The validity of the equality arises from the assumption.

$(c) \Rightarrow (a)$: Suppose $G_{A,O}$ has no positive-cost cycles. Then, we can define for each agent $i$, the maximum-cost of any path in the difference graph that starts at $i$. We denote the cost of this path by $\ell_i$. For each $i \in N $, let $p_i = \ell_i - \frac{\sum_{i\in N} \ell_i}{n}$. 
It is noteworthy that $\sum_{i\in N}p_{i} = 0$, establishing the suitability of \textbf{p} as a balanced payment vector.
Furthermore, in accordance with the definition of highest-cost paths, it follows that for all $i \neq j \in N$:
\begin{align*}
     &p_i =  \ell_i - \frac{\sum_{i\in N} \ell_i}{n}  \geq \\
     &cost_{A,O}(i,j) + \ell_j -\frac{\sum_{i\in N} \ell_i}{n} = \\ &
     \left( v_i(A_j) - v_i(o_j) \right) - \left( v_i(A_i) - v_i(o_i) \right) + \ell_j - \frac{\sum_{i\in N} \ell_i}{n} =  \\ &
     v_i(A_j) - v_i(o_j) + p_j - \left(v_i(A_i) - v_i(o_i) \right) \Longleftrightarrow \\ & v_i(A_i) - v_i(o_i) + p_i \geq v_i(A_j) - v_i(o_j) + p_j
\end{align*}


Hence, $(A,\mathbf{p})$ are DEF, and thus, $A$ is DEF-able.
\end{proof}

\begin{Theorem} \label{theorem:equivalent statements for difference model}
    For $O$, the original apartments allocation, let $A$ be the new apartments allocation and $\mathbf{p}$ the payment vector, such that $(A,\mathbf{p})$ are DEF. 
    Then, it holds that:
    \begin{enumerate}


 \item $\sum_{i\in N} \left(\frac{\sum_{j\in N}\left(v_i(A_j) - v_i(o_j)\right)}{n}\right) \leq \sum_{i\in N}\left(v_i(A_i) - v_i(o_i)\right)$.

        \item For each cycle $C={i_1, ..., i_{r}}$, 
        the cost of the cycle $C$ in the envy-graph $G_A$, corresponding to the new (DEF) allocation, is at most the cost of the same cycle $C$ in the envy graph $G_O$, corresponding the original allocation:
        \begin{align*}
            & cost_O(C)= \sum_{j=1}^{r} \left(v_{i_{j}}(o_{i_{j+1}}) - v_{i_j}(o_{i_{j}})\right) \geq \sum_{j=1}^{r} \left(v_{i_j}(A_{i_{j+1}}) - v_{i_{j}}(A_{i_j})\right) = cost_A(C),
        \end{align*}
        where for brevity we denote $r+1\equiv 1$.
    \end{enumerate}
\end{Theorem}
\begin{proof}
    \begin{enumerate}
    \item \begin{align}
    \nonumber
        &\sum_{i\in N} \left(\sum_{j\in N}\left(v_i(A_j) - v_i(o_j) + p_j - (v_i(A_i) - v_i(o_i) + p_i)\right)\right) \leq 0
\Longleftrightarrow \\
\nonumber
 &\sum_{i\in N} \left(\sum_{j\in N}\left(v_i(A_j) - v_i(o_j) - (v_i(A_i) - v_i(o_i))\right)\right) \leq 0
\Longleftrightarrow \\
\nonumber
 &\sum_{i\in N} \left(\sum_{j\in N}\left(v_i(A_j) - v_i(o_j)\right)\right) \leq \sum_{i\in N} \left(\sum_{j\in N}\left(v_i(A_i) - v_i(o_i)\right)\right)
\Longleftrightarrow \\
\nonumber
 &\sum_{i\in N} \left(\sum_{j\in N}\left(v_i(A_j) - v_i(o_j)\right)\right) \leq n\cdot \sum_{i\in N}\left(v_i(A_i) - v_i(o_i)\right)
\Longleftrightarrow \\
 &\sum_{i\in N} \left(\frac{\sum_{j\in N}\left(v_i(A_j) - v_i(o_j)\right)}{n}\right) \leq \sum_{i\in N}\left(v_i(A_i) - v_i(o_i)\right).
 \label{eq:5}
    \end{align}
    \item For each cycle $C={i_1, ..., i_{r}}$:
    \begin{align*}
        & 0 \geq \sum_{j=1}^{r} \left(v_{i_j}(A_{i_{j+1}}) - v_{i_{j}}(o_{i_{j+1}}
        )+ p_{i_{j+1}} - (v_{i_j}(A_{i_j}) - v_{i_j}(o_{i_j}) + p_{i_j}\right) \Leftrightarrow\\
        & 0 \geq \sum_{j=1}^{r} \left(v_{i_j}(A_{i_{j+1}}) - v_{i_{j}}(o_{i_{j+1}}
        )- (v_{i_j}(A_{i_j}) - v_{i_j}(o_{i_j})\right) \Leftrightarrow \\
        & \sum_{j=1}^{r} \left(v_{i_{j}}(o_{i_{j+1}}
        )- v_{i_j}(o_{i_j})\right)  \geq \sum_{j=1}^{r} \left(v_{i_j}(A_{i_{j+1}}) - v_{i_j}(A_{i_j})\right) \Leftrightarrow \\
        & cost_O(C) \geq cost_A(C).
    \end{align*}
\end{enumerate}
\end{proof}


\begin{Lemma} \label{lemm: cycle cost unchanged}
    The total cost of any cycle in $G_{A,O}$ is the same for any payment vector.
\end{Lemma}
\begin{proof}
    Suppose we give some agent $i$ a payment of $p_i$. As a result, the cost of every edge from $i$ decreases by $p_i$ (as $i$ experiences less envy), and the cost of every edge into $i$ increases by $p_i$ (as other agents experience more envy in $i$).
Every cycle through $i$ contains exactly one edge from $i$ and one edge into $i$, and every other cycle contains no such edges. Therefore, the total cost of any cycle remains unchanged.
\end{proof}

First, we present simple scenarios in which a DEF-able allocation exists (\Cref{prop: def1}, \Cref{prop: def2}). Then, we demonstrate that in the general case, DEF is not always achievable (\Cref{prop:no-defable}).
