\[
\sum_{j\in N} \left(v_i(A_j) - v_i(A_i)\right)\leq \sum_{j\in N}\left(v_i(o_j) - v_i(o_i)\right)
\]
\end{Definition}
\fi
\begin{Definition}
For an allocation $A$, the \emph{envy-sum} of an agent $i\in N$ is defined by
\[
    ES(A)_i = \sum_{j\in N} \left(v_i(A_j) -v_i(o_j)\right) -\left(v_i(A_i) - v_i(o_i)\right),
\]

and the \emph{total envy-sum} is given by 
\[
    ES(A) = \sum_{i\in N} ES(A)_i.
\]
\end{Definition}

\begin{Definition}
For an allocation $A$ and a payment vector $\mathbf{p}$, the \emph{envy-sum} of an agent $i\in N$ is defined by
\[
    ES(A,\mathbf{p})_i = \sum_{j\in N} \left(v_i(A_j) -v_i(o_j) + p_j\right) -\left(v_i(A_i) - v_i(o_i) + p_i\right),
\]

and the \emph{total envy-sum} is given by 
\[
    ES(A,\mathbf{p}) = \sum_{i\in N} ES_i(A,\mathbf{p}).
\]
    Allocation $A$ and payment vector $\mathbf{p}$ are \emph{Sum-Envy-Free (SEF)} if the envy-sum of each agent $i\in N$ is at most 0.
\end{Definition}

In this model, the concept of the envy graph does not have significance because each agent does not directly compare the specific apartments received by other agents with their own. Instead, each agent is primarily concerned with bounding the total amount of envy they experience overall.


\begin{Observation}
    If an allocation is DEF, then it is SEF; but the opposite is not true.
\end{Observation}
To understand why this is true, recall the definition of DEF. An allocation $A$ and a payment vector $\mathbf{p}$ are DEF if for each agents $i,j\in N$, the following condition holds: $v_i(A_i) - v_i(o_i) + p_i \geq v_i(A_j) - v_i(o_j) + p_j$. Summing this inequality over all $j\in N$, we obtain for each $i\in N$: 
\begin{align*}
    & \sum_{j\in N}\left(v_i(A_i) - v_i(o_i) + p_i\right) \geq \sum_{j\in N}\left(v_i(A_j) - v_i(o_j) + p_j\right) \Leftrightarrow  \\
 & \sum_{j\in N}\left((v_i(A_j) - v_i(o_j) + p_j) - (v_i(A_i) - v_i(o_i) + p_i) \right) = ES_i(A,\mathbf{p}) \leq 0,
\end{align*}
which is exactly the definition of SEF.


\begin{Proposition} \label{prop: not SEF-able}
    There are original apartments $O$ and a set of new apartments $M$ such that, for every allocation of one apartment per agent, the resulting allocation is not SEF-able.
\end{Proposition}
\begin{proof}
   Consider the following example with 2 agents.
The values of the original apartments are
\[
\begin{bmatrix}
   & o_1 & o_2 \\
  i_1 & z + \epsilon & z \\
  i_2 & y & y + \epsilon\\
\end{bmatrix}
\]
The values for the new apartments are
\[
\begin{bmatrix}
   & a_1 & a_2 \\
  i_1 & V & V\\
  i_2 & V & V \\
\end{bmatrix}
\]
when $x,y,\epsilon,V \in \mathbb{N}$.

For any allocation $A$ such that each agent receives exactly one item: assuming there is a balanced payment vector $\mathbf{p}$, we have:
\begin{align*}
& \begin{cases}
    ES_1(A,\mathbf{p}) \leq 0\\
    ES_2(A,\mathbf{p}) \leq 0
\end{cases} 
\Leftrightarrow\\
& \begin{cases}
    v_1(A_2)+p_2 - v_1(A_1) - p_1 \leq  v_1(o_2) - v_1(o_1)\\
    v_2(A_1) + p_1 - v_2(A_1) - p_2\leq v_2(o_1) - v_2(o_2)
\end{cases}
\Leftrightarrow^{p_1 = -p_2} \\
&\begin{cases}
    v_1(A_2)+p_2 - v_1(A_1) + p_2 \leq  v_1(o_2) - v_1(o_1)\\
    v_2(A_1) -p_2 - v_2(A_1) - p_2\leq v_2(o_1) - v_2(o_2)
\end{cases}
\Leftrightarrow \\
&\begin{cases}
    V +p_2 - V + p_2 \leq  z - z - \epsilon\\
    V -p_2 - V - p_2\leq y - y - \epsilon
\end{cases}
\Leftrightarrow 
\\
&\begin{cases}
    p_2 \leq -\epsilon/2 \\
    \epsilon/2 \leq p_2
\end{cases}
\end{align*}
Obviously, there is no solution.
\end{proof}
\subsection{SEF allocation}
\begin{Theorem} \label{theorem:equivalent statements for Sum model}
    For $O$, the original apartments, and $A$, new apartments allocation, the following statements are equivalent:
    \begin{enumerate} [label=(\alph*)]
        \item There exists a balanced payment vector $\mathbf{p}$ such that $(A, \mathbf{p})$ are SEF,
        \item  $\sum_{i\in N}\left(\frac{\sum_{j\in N} v_i(A_j) - v_i(o_j) }{n}\right) \leq \sum_{i\in N}v_i(A_i) - v_i(o_i)$
    \end{enumerate}
\end{Theorem}
\begin{proof}
