    & ES_i(A,\mathbf{p}) \leq 0 \Longleftrightarrow\\
    &\sum_{j\in N} \left(v_i(A_j) +p_j - \left(v_i(A_i) + p_i\right)\right)\leq \sum_{j\in N}\left(v_i(o_j) - v_i(o_i)\right)
