\]
Given $\sum_{i \in N} \frac{ES(A)_i}{n} \leq 0$, we have $c \geq 0$. Thus, there always exists a solution for the given constraints\footnote{We could also minimize the payments $\sum_{i \in N, p_i \geq 0} p_i$ by solving  a linear program.}.
\end{proof}

Note that in the definition of $$ES(A)_i = \sum_{j\in N} \left(v_i(A_j) - v_i(o_j)\right) - \left( v_i(A_i) - v_i(o_i) \right),$$ the expression $$\sum_{j\in N} \left(v_i(A_j) - v_i(o_j)\right) + v_i(o_i)$$ remains independent of the allocation $A$. Thus, we can conclude the following:

\begin{Proposition}\label{prop: minimum total envy for maximum uw allocation}
     Let $A$ be the allocation that maximizes utilitarian welfare among all allocations in which each agent receives exactly one item. That is, for every allocation $B$, where each agent receives exactly one item $\sum_{i\in N} v_i(B_i) \leq \sum_{i\in N} v_i(A_i)$. Then, $A$ minimizes the total envy attainable, $ES(A)$, across all such allocations.
     If the allocation is SEF-able, than $A$ also minimizes the total envy attainable with payments, $ES(A,\mathbf{p})$, across all such allocations.
\end{Proposition}
\begin{proof}
We first prove the claim in the absence of payments, meaning that the result holds even for allocations that are not necessarily SEF-able.
    Let $A$ and $B$ be allocations in which each agent receives exactly one item. Since $A$ maximizes the utilitarian welfare, we have $\sum_{i\in N} v_i(A_i) \geq \sum_{i\in N} v_i(B_i)$.

Now, consider the difference in total envy between $A$ and $B$:
\begin{align*}
    & ES(A) - ES(B) = 
    \sum_{i\in N} ES(A)_i - ES(B)_i = \\
    & \sum_{i\in N} \left( \sum_{j\in N} v_i(A_j) - v_i(o_j) - v_i(A_i) + v_i(o_i) \right) - \sum_{i\in N} \left( \sum_{j\in N} v_i(B_j) - v_i(o_j) - v_i(B_i) + v_i(o_i) \right) = \\
    & \sum_{i\in N} \left( v_i(M) -  \sum_{j\in N} v_i(o_j) + v_i(A_i) - v_i(o_i) \right) - \sum_{i\in N} \left( v_i(M) - \sum_{j\in N} v_i(o_j) + v_i(B_i) - v_i(o_i) \right) = \\
    & n \left(\sum_{i\in N} v_i(B_i) - \sum_{i\in N} v_i(A_i) \right) \leq 0.
\end{align*}
Since $A$ maximizes utilitarian welfare, we conclude that the total envy $ES(A)$ is minimized among all such allocations.

