\begin{Lemma} \label{lemm: payment vector minimizes envy}
    For every allocation $A$ there exists a balanced payment vector $\mathbf{p}$ such that
    \begin{align*}
        ES(A, \mathbf{p})_i = \frac{ES(A)}{n}.
    \end{align*}
    Furthermore, this $\mathbf{p}$ minimizes (among all payment vectors) the maximum (over all agents) envy sum, making $\mathbf{p}$ the optimal payment vector for allocation $A$.
\end{Lemma}
\begin{proof}
    We define the payment vector for an allocation $A$ by:
    \[
    p_i = \frac{ES(A)_i - \frac{ES(A)}{n}}{n}.
    \]
    First, let us prove that the payments are balanced:
    \[
    \sum_{i\in N} p_i= \sum_{i\in N} \frac{ES(A)_i - \frac{ES(A)}{n}}{n} = \frac{ES(A) - \frac{n}{n}ES(A)}{n} = 0.
    \]
    Now, let us prove that the envy-sum of agent $i$ equals $\frac{ES(A)}{n}$:
    \begin{align*}
        & ES(A,\mathbf{p})_i = \sum_{j\in N} \left(v_i(A_j) -v_i(o_j) + p_j\right) -\left(v_i(A_i) - v_i(o_i) + p_i\right) = \\
        & ES(A)_i + \sum_{j\in N} p_j - n  p_i = ES(A)_i + \sum_{j \neq i \in N} p_j - (n-1) p_i.
    \end{align*}
        Since $\mathbf{p}$ is balanced, $\sum_{j\neq i\in N} p_j = -p_i$. Thus:
        \begin{align*}
        & ES(A,\mathbf{p})_i =  ES(A)_i - np_i = ES(A)_i - n\frac{ES(A)_i - \frac{ES(A)}{n}}{n} = \frac{ES(A)}{n}.
    \end{align*}

    Note that $$ES(A,\mathbf{p})_i = \frac{ES(A)}{n} =  \frac{\sum_{j\in N}ES(A)_j}{n},$$ which means that the envy sum with the payment vector $\mathbf{p}$ is the average envy sum for the agents without any payments. Therefore, for any other payment vector $\mathbf{p}'$, there must be at least one agent with an envy sum of at least $\frac{ES(A)}{n} $. Hence, $\mathbf{p}$ is the optimal payment vector for the allocation $A$.
\end{proof}

\begin{Theorem} 
	\label{thm: envy sum mechanism}
    %For $O$, the original apartments, and the new apartments $M$, when no allocation and payment vector satisfy SEF, an allocation $A$ and a payment vector $\mathbf{p}$ that minimize the maximum envy sum per agent can be found in polynomial time.
