\begin{Definition}
The \textit{ratio-envy} of agent $i$ towards agent $j$ under an allocation $A$
and payments $\mathbf{p}$ is defined as 
\[\frac{u_i(A_j)}{w_{i,j}} - \frac{u_i(A_i)}{w_{i,i}}
= \frac{v_i(A_j)+p_j}{w_{i,j}} - \frac{v_i(A_i)+p_i}{w_{i,i}}.\]
Allocation $A$ and payment vector $\mathbf{p}$ are \emph{Ratio-envy-free (REF)} if 
for each $i,j \in N$:
\[
\frac{v_i(A_j)+p_j}{w_{i,j}} - \frac{v_i(A_i)+p_i}{w_{i,i}} \leq 0
\]
\end{Definition}
\begin{Definition}
An allocation $A$ is \emph{ratio envy-freeable (REF-able)} if there exists a vector of payments $\mathbf{p}$ such that $(A,\mathbf{p})$ are REF.
\end{Definition}

\begin{Definition}
    The \emph{ratio envy graph} of allocation $A$, denoted $G_{A,w}$, is a complete directed graph consisting of a set of vertices representing agents $N$.

For any pair of agents $i$ and $j$ in $N$, the cost assigned to the arc $(i,j)$ in $G_{A,w}$ is defined as the ratio envy that agent $i$ holds toward agent $j$ under allocation $A$: 
$cost_A(i,j) := \frac{v_i(A_j)}{w_{i,j}} - \frac{v_i(A_i)}{w_{i,i}}$.
We denote the cost of a path $(i_1,...,i_k)$ as $cost_A(i_1,...,i_k) = \sum_{j = 1}^{k-1} cost_A(i_j, i_{j+1})$.
\end{Definition}


