        #include <iostream>
        #include <cmath>
        #include <algorithm>
        #include <vector>
        #include <cstdlib>

        using namespace std;

        //A "NavigateLevel" function prototype. Full declaration to be done later in the code.
        void NavigateLevel(vector<long long>&, unsigned long long, long long, signed long long, long long&, unsigned long long&);

        unsigned long long numOddElements; // A variable to help us recognize the trivial Subset Sum case where you are given an odd target sum and only even number elements. There is no solution in this instance.
        //********************************************************************/
        //A function that processes the elements in the set before they are passed for searching the target sum.
        //Sections to read: 3.4, 3.5 and 3.13.
        signed long long Preprocessor(vector<long long>& Elements, long long negElementsTotal) {

            //Searches for negative elements in the set and adds them all up. This sum is to be passed back to the caller of this function.
            //We always process the elements of a set as positive in this program, but it would not be incorrect to process it as negative or dynamically between negative and positive as desired. Simply adapt this code accordingly.
            for (long long& element : Elements) {
                if (element < 0)
                    negElementsTotal += element; //Linear time complex process (O(n)).
                if ((abs(element) % 2) == 1)
                    numOddElements++;
            }

            //Sort the elements in the set by their absolute value without modifying the sign of negative elements in the set.
            sort(Elements.begin(), Elements.end(), [](long long a, long long b) {
                return abs(a) < abs(b); //Linearithmic/Log-Linear time complex (O(nlogn)).
            });

            //Sorting is has the dominant complexity and therefore, the overall complexity of this function is Linearithmic/Log-Linear (O(nlogn)).
            return negElementsTotal;
        }
        //********************************************************************/

        //********************************************************************/
        //A function to map back to the elements in the set the positions of where the target sums are found.
        //The positions of the solutions are passed as parameter "numPreceding" into this function.
        //Section to read: 3.6.
        string elementCombinations(vector<long long>& Elements, unsigned long long numPreceding) {

            string contributingElements = ""; //Variable used to store the elements contributing to the solution in position "numPreceding".
            unsigned long long numElements = Elements.size() - 1;

            if (numPreceding > 0) {
                //Loop through the elements in the set and determine if the element contributes to sum to the solution in position "numPreceding".
                //When the element in the set is negative, the bit ("rem") corresponding to the element is negated.
                //This is a linear time complex process (O(n)).
                for (unsigned long long n = 0; n <= numElements; n++) {
                    if (numPreceding == 1 && Elements[n] > 0) {
                        //During the conversion of the position "numPreceding", when the position is "1", it should be taken as is and not divided further.
                        //If the element in the set corresponding to it is positive, we add the element to "contributingElements". Otherwise, we would have to negate it and would not add it to "contributingElements".
                        contributingElements == "" ? contributingElements += to_string(Elements[n]) : contributingElements += " + " + to_string(Elements[n]);
                        numPreceding = 0; //When "numPreceding" is equal to "1", it would mean the conversion has reached its highest bit to initially be set to "1" and all higher bits would trivially be set to "0".
                    } else if (numPreceding == 0 && Elements[n] < 0) {
                        //Negates the higher bits that were trivially set to "0" if the element corresponding to it is negative. The bit then turns to "1" and means the corresponding element should be added to "contributingElements".
                        contributingElements == "" ? contributingElements += to_string(Elements[n]) : contributingElements += " + " + to_string(Elements[n]);
                    } else {
                        int rem = numPreceding % 2;

                        //Negating bits that correspond to negative elements in the set.
                        //Helps us correctly identify if the element contributes to sum to the solution even for set with negative elements or a mix of negative and positive elements.
                        if (Elements[n] < 0 && rem == 1)
                            rem = 0;
                        else if (Elements[n] < 0 && rem == 0)
                            rem = 1;

                        if (rem == 1 && (n == 0 || contributingElements == ""))
                            contributingElements += to_string(Elements[n]);
                        else if (rem == 1)
                            contributingElements += " + " + to_string(Elements[n]);

                        numPreceding /= 2;
                    }
                }

                if (contributingElements == "")
                    contributingElements += "Empty Set Zero";

            } else
                contributingElements += "Empty Set Zero";

            //The time complexity of this function is linear (O(n)).
            return contributingElements;
        }
        //********************************************************************/

        unsigned long long depth = 0, ActualCountSolutions = 0, PrecedingPossibilities = 0, TrivialCountSolutions = 0;
        //********************************************************************/
        //A function to determine whether the desired solution can or cannot be found within a S/E point.
        //Sections to read: 3.4, 3.6, 3.10 and 3.13.
        bool ZoomInCriteria(vector<long long>& Elements, long long& Target, long long num1, long long num2, unsigned long long num3, bool isFirstSEP, unsigned long long& AllSEPSC) {

            //"isFirstSEP" means "is First S/E point".
            unsigned long long currentPreceding = PrecedingPossibilities; //Stores the number of preceding possibilities for events where we zoom-in into a S/E point.

            if (num1 <= Target && num2 >= Target) {
                for (unsigned long long d = 0; d <= depth; d++) {cout << "\t";}
                cout << PrecedingPossibilities << "(" << num1 << ", " << num2 << ")" << exp2(num3 + 1) - 1 << endl;

                if ((num1 == Target || num2 == Target)) {
                    //If the starting or ending point of a S/E point are equal to the target sum, there is no need to zoom into it as all inner possibilities would be less than (if ending point = target) or greater than (if starting point = target) the target sum.
                    //The program outputs this as a solution and does not further zoom-in (with proper indentation of levels where the solution is found).
                    //This can also be a point where the program realizes the latest when it has run into a false positive if the execution flow does not reach this scope.
                    for (unsigned long long d = 0; d <= depth; d++) {cout << "\t";}
                    if (num1 == Target)
                        cout << "Target Sum found! = " << PrecedingPossibilities << "(" << num1 << ")0 = " << elementCombinations(Elements, PrecedingPossibilities) << endl;
                    else if (num2 == Target)
                        cout << "Target Sum found! = " << PrecedingPossibilities + exp2(num3 + 1) - 1 << "(" << num2 << ")0 = " << elementCombinations(Elements, PrecedingPossibilities + exp2(num3 + 1) - 1) << endl;

                    ActualCountSolutions++, AllSEPSC++;
                } else {
                    if (num3 > 0) {
                        //We zoom-in deeper into a S/E point that satisfies the criteria and properly increase and decrease "depth".
                        //To zoom-in, we again call the "NavigateLevel" function, passing in specific values.
                        //NOTE! The number of elements ("num3"/second parameter of "NavigateLevel") we pass here are less than number of elements in the "NavigateLevel" that called this "ZoomInCriteria" function.
                        //Therefore, as "NavigateLevel" is linear time complex, passing a lesser number of elements to work with, makes the complexity of the "NavigateLevel" called here to be sub-linear.
                        //We pass in "0" as the "negElementsTotal" because there would be no need to again shift the inner possibilities.
                        depth++;
                        NavigateLevel(Elements, num3, num1, 0, Target, AllSEPSC);
                        depth--;
                        PrecedingPossibilities = currentPreceding; //Recalls the number of preceding possibilities before we zoomed in.
                    } else {
                        for (unsigned long long d = 0; d <= depth; d++) {cout << "\t";}
                        cout << "False Positive!" << endl; //Program realizes the latest that it has ran into a false positive otherwise, if it zooms back or skips exploration without reaching the deepest depth, it detected the false positive early and avoided zooming.
                        return true;
                    }
                }

                //In the pair of S/E points found using the current element in "NavigateLevel", if the S/E point processed in this "ZoomInCriteria" is the first S/E point of the pair and its starting point is equal to the target, there is no need to further explore any other possibilities to come after in this level.
                //Possibilities to come after will all be greater than the target sum.
                if (num1 > Target && isFirstSEP == true) {return false;}
                else {return true;}
            } else {
                //In the pair of S/E points found using the current element in "NavigateLevel", if the S/E point processed in this "ZoomInCriteria" is the first S/E point of the pair and its starting point is greater than the target, there is no need to further explore any other possibilities to come after in this level.
                //Possibilities to come after will all be greater than the target sum.
                if (num1 > Target && isFirstSEP == true) {return false;}
                else {return true;}
            }

            //Overall Complexity of this function is constant time complex (O(1)). The number of steps taken to verify if we should zoom-in or not, or continue exploring S/E points of this level or not are the same for any S/E point.
        }
        //********************************************************************/

        //********************************************************************/
        //A function to help us perform  the trivial count of redundant subsets as a product of repeating elements in the set.
        //Section to read: 3.10.
        void Trivial(vector<unsigned long long>& TrivialCountArr, unsigned long long TrivialArrSize, unsigned long long& TrivialTotal, bool skipTrivial) {

            bool AltAddSubtract = false; //Variable to alternate the addition and substraction of trivial terms.
            unsigned long long Coeffient = TrivialArrSize - 1;
            bool skipTrivialCount = skipTrivial;
            //Check if any of the subsets that were actually explored had solutions. If the have no solutions, there no trivial solutions to be calculated.
            //This check is only done for the highest level repeating element. For lower levels during which the function is cumulatively adding the "TrivialTotal", we take "skipTrivialCount" from the highest level repeating element.
            if (TrivialArrSize == TrivialCountArr.size()) {
                for (int i = 0; i < (TrivialArrSize - 1); i++) {
                    if (TrivialCountArr[i] != 0) {
                        skipTrivialCount = false;
                        break; //breakout of the loop if we find even one actual explored subsets count greater than 0.
                    }
                }
            }
            //Accordingly adds and subtracts the terms of each repeating element level all up to the highest level.
            if (skipTrivialCount == true) {
                for (unsigned long long d = 0; d <= depth; d++) {cout << "\t";}
                cout << "End Of Repetition! No Trivial Solutions Within, Trivial Count Up To Date." << endl;
            } else {
                for (int i = 1; i <= TrivialArrSize - 1; i++) {
                    if (TrivialArrSize == 2) {
                        AltAddSubtract = true;
                    }
                    if (Coeffient == 1) {
                        if (AltAddSubtract == false) {
                            TrivialTotal -= TrivialCountArr[0];
                            TrivialCountArr[i] -= TrivialCountArr[0];
                            AltAddSubtract = true;
                        } else {
                            TrivialTotal += TrivialCountArr[0];
                            TrivialCountArr[i] += TrivialCountArr[0];
                            AltAddSubtract = false;
                        }
                    } else if (i == 1) {
                        Trivial(TrivialCountArr, TrivialArrSize - 1, TrivialTotal, skipTrivialCount);
                        TrivialTotal += (Coeffient * TrivialCountArr[(TrivialArrSize - (i + 1))]);
                        TrivialCountArr[(TrivialArrSize - 1)] += (Coeffient * TrivialCountArr[(TrivialArrSize - (i + 1))]);
                        Coeffient *= ((TrivialArrSize - (i + 1)));
                        Coeffient /= (i + 1);
                    } else {
                        if (AltAddSubtract == false) {
                            TrivialTotal -= (Coeffient * TrivialCountArr[(TrivialArrSize - (i + 1))]);
                            TrivialCountArr[(TrivialArrSize - 1)] -= (Coeffient * TrivialCountArr[(TrivialArrSize - (i + 1))]);
                            AltAddSubtract = true;
                        } else {
                            TrivialTotal += (Coeffient * TrivialCountArr[(TrivialArrSize - (i + 1))]);
                            TrivialCountArr[(TrivialArrSize - 1)] += (Coeffient * TrivialCountArr[(TrivialArrSize - (i + 1))]);
                            AltAddSubtract = false;
                        }
                        Coeffient *= ((TrivialArrSize - (i + 1)));
                        Coeffient /= (i + 1);
                    }
                }
                if (TrivialArrSize == TrivialCountArr.size()) {
                    for (unsigned long long d = 0; d <= depth; d++) {cout << "\t";}
                    cout << "End Of Repetition! Trivial Count Updated." << endl;
                }
            }

            //Complexity of this function is O(n^2) if it had to calculate the trivial solutions within. Otherwise, it would be skipping over the n^2 possibilities.
        }
        //********************************************************************/

        //********************************************************************/
        //A function that successively moves through S/E points of each level.
        //Sections to read: 3.3, 3.5, 3.7, 3.10 and 3.13.
        void NavigateLevel(vector<long long>& Elements, unsigned long long numElements, long long StartingPoint, signed long long negElementsTotal, long long& Target, unsigned long long& AllSEPSC) {

            //"AllSEPSC" means All S/E point Solutions Count. It is incremented for all trivial and actual solutions count.
            unsigned long long FirstSEPSC = 0, SecondSEPSC = 0; //Suffix "SEPSC" means "S/E Point Solutions Count".
            long long num1 = 0, num2 = 0, num3 = 0, num4 = 0, num5 = 0;
            unsigned long long num6 = 0;
            unsigned long long lastPartSEPdistance = 0, lastPartSEPSC = 0; //Variables to store the distance of subsets we would have to explore in case of repeating elements and the number of solutions found within those subsets.
            long long RepetitionCount = 0;
            bool Continue = true; //A variable to check if we should continue exploring S/E points of this level.
            bool isRepeating = false, ReportRepetitionDetectionOnce = false; //"ReportRepetitionDetectionOnce" is a variable to make the program output the "Repetition Detected" message only once from the start of repetition and its end on each level.
            vector<unsigned long long> TrivialCountArr;
            //From each element in the set we get a pair of S/E points, except for the first 2 elements in the set. So, :
            /*
                num1 = starting point of the first S/E point.
                num2 = ending point of the first S/E point.
                num3 = starting point of the second S/E point.
                num4 = ending point of the second S/E point.
                num5 = utility variable to help us move across S/E points.
                num6 = tells us the distance/number of possibilities represented by a S/E point. It only stores the number of elements enough to explore the S/E point so, calculations can be performed using it to achieve other needs in the program.
            */
            //Looping through the elements of the set bounded by the parameter "numElements" is linear time complex and sub-linear if "numElements" is less than the number of elements in the set.
            for (unsigned long long element = 0; element <= numElements && Continue == true; element++) {
                //Shifts and translations to variable num1 to num4 are applied accordingly using the sum of "StartingPoint" and "negElementsTotal".
                //As the negative elements in the set were not changed sign but ordered by their absolute value, when accessing them, we read them in their absolute values as we need the S/E points we get to be of a single-sign set that we later shift.
                if (element == 0) {
                    //S/E point using the first element in the set.
                    num1 += StartingPoint + negElementsTotal;
                    num2 = abs(Elements[element]) + StartingPoint + negElementsTotal;
                    Continue = ZoomInCriteria(Elements, Target, num1, num2, num6, true, FirstSEPSC);
                    AllSEPSC += FirstSEPSC;
                } else if (element == 1) {
                    //S/E point using the second element in the set.
                    num3 = abs(Elements[element]) + StartingPoint + negElementsTotal;
                    num4 = abs(Elements[element]) + abs(Elements[element - 1]) + StartingPoint + negElementsTotal;
                    PrecedingPossibilities += 2;
                    Continue = ZoomInCriteria(Elements, Target, num3, num4, num6, false, SecondSEPSC);
                    AllSEPSC += SecondSEPSC;
                } else if (element == 2) {
                    FirstSEPSC = 0, SecondSEPSC = 0;
                    //Variables num1 to num4 are translated accordingly.
                    //The third element is used and it is the first element that gives us a pair of S/E points.
                    num1 = abs(Elements[element]) + StartingPoint + negElementsTotal;
                    num2 = abs(Elements[element]) + abs(Elements[element - 2]) + StartingPoint + negElementsTotal;
                    num3 = abs(Elements[element]) + abs(Elements[element - 1]) + StartingPoint + negElementsTotal;
                    num4 = abs(Elements[element]) + abs(Elements[element - 1]) + abs(Elements[element - 2]) + StartingPoint + negElementsTotal;
                } else {
                    //We successively move across S/E points performing arithmetic operations only on variables num1 to num5.
                    //Here, each element always produces a pair of S/E points.
                    num5 = abs(Elements[element]) + StartingPoint + negElementsTotal;

                    if (num5 == num1) 
                        isRepeating = true;

                    num2 = (num4 - num1) + num5;
                    num3 = num1 + num5 - (StartingPoint + negElementsTotal);
                    num4 += num5 - (StartingPoint + negElementsTotal);
                    num1 = num5;
                    num6++;

                    if (isRepeating == true) {
                        //Increments the "RepetitionCount" accordingly as it detects repetition in the next S/E point pair and begins passing the count of solutions we found in the previous S/E point pair into "TrivialCountArr".
                        RepetitionCount == 0 ? RepetitionCount = 2 : RepetitionCount++;
                        if (TrivialCountArr.size() == 0) {
                            TrivialCountArr.push_back(FirstSEPSC + SecondSEPSC);
                            FirstSEPSC = 0, SecondSEPSC = 0;
                            lastPartSEPdistance = num6 + 1;
                        }
                    } else {
                        //Detects end of repetition then calls "Trivial" to perform the trivial count of solutions in subsets skipped over.
                        if (TrivialCountArr.size() != 0){
                            unsigned long long intermediateTrivialTotal = 0;
                            Trivial(TrivialCountArr, TrivialCountArr.size(), intermediateTrivialTotal, true);
                            TrivialCountArr = vector<unsigned long long>();
                            TrivialCountSolutions += intermediateTrivialTotal;
                            AllSEPSC += intermediateTrivialTotal;
                            ReportRepetitionDetectionOnce = false;
                        } else 
                            FirstSEPSC = 0, SecondSEPSC = 0;

                        lastPartSEPdistance = 0, RepetitionCount = 0;
                    }
                }

                //Prevents checking of S/E points got from the first 2 elements, and delegated that task to the if statement above.
                if (element > 1 && isRepeating == false) {
                    //Passes the first S/E point in the pair to the 'ZoomInCriteria' function.
                    //Increments Preceding Possibilities accordingly using "num6".
                    num6 == 0 ? PrecedingPossibilities += 2 : PrecedingPossibilities += exp2(num6);
                    Continue = ZoomInCriteria(Elements, Target, num1, num2, num6, true, FirstSEPSC);

                    //If "ZoomInCriteria" has flagged that the program should not continue exploring S/E point of this level in the first S/E point, the check of the second S/E point can be skipped.
                    if (Continue == true) {
                        num6 == 0 ? PrecedingPossibilities += 2 : PrecedingPossibilities += exp2(num6 + 1);
                        Continue = ZoomInCriteria(Elements, Target, num3, num4, num6, false, SecondSEPSC);
                    }
                    AllSEPSC += (FirstSEPSC + SecondSEPSC);
                } else if (isRepeating == true) {
                    //Calls the "ZoomInCriteria" function passing in the appropriate paramters to explore the non-redundant subsets in case of repeating elements.
                    //Passes the count of solutions found in the non-redundant subsets exploration into "TrivialCountArr"
                    if (ReportRepetitionDetectionOnce == false) {
                        for (unsigned long long d = 0; d <= depth; d++) {cout << "\t";}
                        cout << "Repetition Detected! Trivial Count To Be Updated When Repetition Ends." << endl;
                        ReportRepetitionDetectionOnce = true;
                    }
                    PrecedingPossibilities += (exp2(num6) + (2 * exp2(num6 + 1)) - exp2(lastPartSEPdistance));
                    Continue = ZoomInCriteria(Elements, Target, (abs(Elements[num6 + 1]) * RepetitionCount) + (StartingPoint + negElementsTotal), num4, lastPartSEPdistance - 1, false, lastPartSEPSC);
                    PrecedingPossibilities -= (exp2(num6 + 1) - exp2(lastPartSEPdistance));
                    TrivialCountArr.push_back(lastPartSEPSC);
                    AllSEPSC += lastPartSEPSC;
                    lastPartSEPSC = 0;
                }
                isRepeating = false;
            }
            //Detects the end of repetition at the end of a level
            if (TrivialCountArr.size() != 0) {
                unsigned long long intermediateTrivialTotal = 0;
                Trivial(TrivialCountArr, TrivialCountArr.size(), intermediateTrivialTotal, true);
                TrivialCountArr = vector<unsigned long long>();
                TrivialCountSolutions += intermediateTrivialTotal;
                AllSEPSC += intermediateTrivialTotal;
                ReportRepetitionDetectionOnce = false;
            }

            //The overall complexity of this function is independantly linear time complex for each level in the LIFO stack.
        }
        //********************************************************************/

        //********************************************************************/
        //Program execution begins here in the "main" function.
        // Sections to read: 3.3, 3.4, 3.5, 3.6, 3.7, 3.8, 3.9, 3.10 and 3.13.
        int main() {

            vector<long long> Elements;
            long long enteredElement, NumZeros = 0, TargetSum;
            unsigned long long numElements = 0;
            signed long long negElementsTotal = 0;
            bool isPureZeroInstance = false; //Pure Zero Instance is when the Subset Sum instance has a target sum equal to zero and containing of only zeros in its set. This variable helps the program keep count of the solutions equal to zero for a pure zero Subset Sum instance.

            cout << "What is the target Sum?: ";
            cin >> TargetSum;

            while (true) {
                for (long long element : Elements)
                    cout << element << "; ";

                if (Elements.size() == 0)
                    cout << "Enter element: ";
                else
                    cout << endl << "Enter element: ";

                cin >> enteredElement;

                if (enteredElement == 0)
                    NumZeros++;
                else {
                    Elements.push_back(enteredElement);
                    numElements++;
                }

                char choice;
                cout << endl << "End of Input?(y/n): ";
                cin >> choice;
                if (choice == 'y' || choice == 'Y') {
                    #ifdef _WIN32
                        system("cls");
                    #else
                        system("clear");
                    #endif
                    break;
                } else {
                    #ifdef _WIN32
                        system("cls");
                    #else
                        system("clear");
                    #endif
                }
            }

            negElementsTotal = Preprocessor(Elements, negElementsTotal);
            cout << "Elements: ";
            for (long long element : Elements)
                cout << element << "; ";

            cout << endl << "Target Sum: " << TargetSum << endl;

            unsigned long long TotalNumSolutions = 0; //This is a variable that is incremented for every solution that is found, i.e. both trivial and actual count. This variable is/should be equal to "TrivialCountSolutions" plus "ActualCountSolutions" at the end of the program.
            if (TargetSum == 0 && Elements.size() == 0) {
                cout << "Pure Zero Subset Sum Instance! Subset Sum Instance Has Target Sum Zero And A Set Containing Only Zeros." << endl;
                isPureZeroInstance = true;
            } else if (numOddElements == 0 && (TargetSum % 2) == 1)
                cout << "All Even Number Elements Cannot Result To An Odd Target Sum." << endl;
            else
                NavigateLevel(Elements, numElements - 1, 0, negElementsTotal, TargetSum, TotalNumSolutions);

            //Number of solutions found has to be multiplied with the number of zero elements entered into the program as zeros cause "z-axis exponentiation" and increases number of solutions.
            //"isPureZeroInstance" variable is used in an addition expression in the following line of code even though it is a boolean data type. If "true", it is added in the expression as "1" and if "false", as "0". It helps the program be able to keep count of the number of solutions even in a pure zero Subset Sum instance.
            cout << endl << "Zeros Count: " << NumZeros << endl << "Trivially Counted Solutions: " << TrivialCountSolutions << endl << "Actual Count Of Solutions Before Processing: " << ActualCountSolutions << endl << "Number Of Possible Solutions Found: " << (TotalNumSolutions + isPureZeroInstance) * exp2(NumZeros) << " = ((" << ActualCountSolutions << " + " << TrivialCountSolutions << ") * 2^(" << NumZeros << "))";

            cout << endl << "End of Program" << endl;
            return 0;
        }
