    %
    \lrb{\Gamma, \Delta \vdash \elimplus(m,\abstr{x}n,\abstr{y}o) \colon C } &\defeq [\lrb{n}, \lrb{o}] \circ d
      \circ \sigma \circ (\lrb{m} \otimes id) \\
    %
    \lrb{\Gamma, \Delta \vdash M \otimes N : S_1 \otimes S_2} &\defeq \lrb{M} \otimes \lrb{N} \\
    %
    \lrb{\Gamma, \Delta \vdash \elimtens(M , \abstr{xy}N) : T} &\defeq \lrb{N} \circ (id \otimes \lrb{M})\\
    %
    \lrb{\vdash \mathcal B(t) : \mathcal B (\p P)} &\defeq \mathcal B (\lrb{t})\\
    %
    \lrb{\Gamma,\Delta\vdash m~n : \mathcal B(\p Q)} &\defeq \mathcal B(\eval) \circ \tau \circ (\lrb{m} \otimes \lrb{n}) \\
    %
    \lrb{ \Gamma \vdash \tau(m) : \mathcal B(\p P \p \otimes \p Q)} &\defeq \tau \circ \lrb{m}\\
    %
    \lrb{\Delta, x : {S_2}, y : {S_1}, \Gamma \vdash M : {T}} &\defeq \lrb{M}  \circ (id \otimes \sigma \otimes id)
  \end{align*}
  \caption{Interpretation of judgements.}
  \label{fig:t_d}
\end{figure}

Our interpretation is sound with respect to the cut-elimination process (Theorem~\ref{thm:soundnesshook}), and complete (Theorem~\ref{thm:adequacy}) with respect to a notion of contextual equivalence (Definition~\ref{def:contextual_equivalence}).  
Since this completeness is established with respect to a different relation than the one used for soundness, the result is usually referred to as \emph{adequacy}.
The omitted proofs can be found in Appendix~\ref{app:denotational}.

\begin{restatable}[Soundness]{theorem}{soundnesscor}
  \label{thm:soundnesshook}
If $M \hookrightarrow^* N$ then $\lrb{M} = \lrb{N}$.  
\end{restatable}
\vspace{-1.8\baselineskip}\qed

\begin{definition}[Elimination context]
  An elimination context $E$ is a term with exactly one free variable, denoted by $[.]$, defined by the following grammar:
  \begin{align*}
    E & \defeq [.] 
    \mid \elimzero(E) 
    \mid \elimone(E, M) 
    \mid E~M \\
    & \mid \p{\elimwith^1(}E\p{, \abstr{x}m)} 
    \mid \p{\elimwith^2(}E\p{, \abstr{x}m)} 
    \mid \elimplus(E, \abstr{x}m, \abstr{y}n) 
    \mid \elimtens(E, \abstr{xy}M)
  \end{align*}
  The substitution of $[.]$ by a term $M$ in $E$ is denoted by $E[M]$.
\end{definition}

\begin{definition}[Contextual equivalence]
  \label{def:contextual_equivalence}
  Two terms $M$ and $N$ are contextually equivalent ($M \sim N$) if, for every
  elimination context $[.] \vdash E : T$, with $T \in \{\one, 1, \mathcal B(\one)\}$, there
  exists a value $V$ such that $E[M] \hookrightarrow^* V$ iff 
  $E[N] \hookrightarrow^* V$.
\end{definition}


\begin{restatable}[Adequacy]{theorem}{adequacy}
  \label{thm:adequacy}
  If $\lrb{\vdash M:T} = \lrb{\vdash N:T}$ then $M \sim N$.
\end{restatable}
\vspace{-1.8\baselineskip}\qed

\section{Encoding Quantum Computing}
\label{sssec:encoding}
The fact that our calculus is linear in a linear algebraic sense follows as a straightforward corollary of adequacy (Theorem~\ref{thm:adequacy}).  
\begin{corollary}[Linearity]
  \label{cor:linearity}
  Let $x : S \vdash M : T$,
  $\Delta \vdash N_1 : S$,
  $\Delta \vdash N_2 : S$,
  and $\Delta \vdash N : S$ (all in the same fragment), then
  $(\lambda x.M)~(\alpha\sdot N_1\Plus\beta\sdot N_2) \sim
  \alpha\sdot(\lambda x.M)~N_1 \Plus \beta\sdot (\lambda x.M)~N_2$.
\end{corollary}

Remark that Corollary~\ref{cor:linearity} excludes $\mathcal B$, sice those terms are always closed. 



Let $Q$ be the set of closed proof terms $\p m$ of $\one \pwith \one$, modulo
the equivalence relation $\equiv$. From now on, we write $\pqbit$ for $\one\pwith\one$.

\begin{theorem}[One-to-one correspondence~{\cite[Lemmas 3.7 and 3.8]{DiazcaroDowekMSCS24}}]
  \label{thm:v_space_type}
  The set $Q$ forms a finite-dimensional vector space, with vector addition and
  scalar multiplication given by $\Plus$ and $\sdot$, respectively.

  For every element $[\p m] \in Q$, there is a vector $\ul{[\p
  m]} \in \mathbb{C}^2$.  Conversely, for any vector $\vec{v} \in
  \mathbb{C}^2$, there is a closed term $\vdash \ov{\vec{v}} : \pqbit$.
  Moreover, this correspondence preserves the structure:
  $\ul{[\p{m_1 \Plus m_2}]} = \ul{[\p{m_1}]} + \ul{[\p{m_2}]}$
    and
  $\ul{[\p a \sdot \p m]} = \p a \cdot \ul{[\p m]}$.
    \qed
\end{theorem}

\begin{example}[Qubit encoding]
  A single qubit $a \ket{0} + b \ket{1} \in \mathbb{C}^2$ is encoded by the term  
  $\p{\langle a} \sdot \p{\ast , b} \sdot \p{\ast \rangle}$.
  In particular, we define the basis vectors as:
    $\ket{0} \defeq \p{\langle} \p{\ast , 0} \sdot \p{\ast \rangle}$
    and
    $\ket{1} \defeq \p{\langle 0} \sdot \p{\ast , } \p{\ast \rangle}$.
  An $n$-qubit is a vector in $\mathbb{C}^{2^n}$, and it is encoded as a linear
  combination of $n$-fold tensor products of 1-qubit encodings.
  As usual, we write $\ket{b_1\cdots b_n}$ for the $n$-qubit $\ket{b_1} \otimes \cdots \otimes \ket{b_n}$.
  For example, the
  $2$-qubit entangled state $\frac{\ket{00} + \ket{11}}{\sqrt{2}}$ is
  encoded as: $\vdash\tfrac{\p 1}{\p{\sqrt{2}}} \sdot \ket{00}
  \Plus \tfrac{\p 1}{\p{\sqrt{2}}} \sdot \ket{11}:\pqbit\p{\otimes}\pqbit$,
  that is,
  \(
    \vdash\tfrac{\p 1}{\sqrt{\p 2}} \sdot (\p{\langle} \p{\ast , 0} \sdot \p{\ast \rangle} \otimes \p{\langle} \p{\ast , 0} \sdot \p{\ast \rangle})
    \Plus
    \tfrac{\p 1}{\sqrt{\p 2}} \sdot (\p{\langle 0} \sdot \p{\ast , } \p{\ast \rangle} \otimes \p{\langle 0} \sdot \p{\ast , } \p{\ast \rangle}) : (\one\pwith\one) \p{\otimes} (\one\pwith\one)
  \).
\end{example}

\begin{remark}
In~\cite{DiazcaroDowekMSCS24}, $2^n$-dimensional vectors are encoded as proof terms of $\one^{\pwith{2^n}}$.  
Here we prefer to use the tensor notation, which provides finer control over term structure---in particular, allowing for  
a more direct encoding of constructs such as the Quantum Switch (see Example~\ref{ex:qs}).
\end{remark}


We first show how to encode $2 \times 2$ matrices (Theorem~\ref{lem:matrix_app}), and then generalise the construction to $n \times n$ matrices (Corollary~\ref{cor:tens_encoding}).

\begin{theorem}[$2 \times 2$ matrices~{\cite[Theorem 3.10]{DiazcaroDowekMSCS24}}]
\label{lem:matrix_app}
Let $M$ be a $2 \times 2$ complex matrix.  
Then there exists a closed proof term $\p f$ of $\pqbit \pmultimap \pqbit$ such that for any vector $\vec{v} \in \mathbb{C}^2$, we have:
  $M\vec{v} = \ul{\p f(\ov{\vec{v}})}$.
\end{theorem}
\begin{proof}  
  Let $M \defeq a \ketbra 00 + b \ketbra 01 + c \ketbra 10 + d \ketbra 11$ be a $2\times 2$ matrix, and let
  $\p f \defeq \p{\lambda \abstr{x} \elimwith^1(x, \abstr{x_1}{f_1 x_1}) \Plus \elimwith^2(x, \abstr{x_2}{f_2 x_2})}$,
  where
  $\p{f_1} \defeq \p{\lambda \abstr{x}\elimone(x, } \p{\langle a} \sdot \p{\ast , c} \sdot \p{\ast \rangle})$
  and
  $\p{f_2} \defeq \p{\lambda \abstr{x}\elimone(x, } \p{\langle b} \sdot \p{\ast , d} \sdot \p{\ast \rangle})$.  
  Let $\vec{v} \defeq a_1\ket 0+b_1\ket 1 \in \mathbb{C}^2$.  
  Notice that
  $\p f(\ov{\vec{v}}) \hookrightarrow^* \p{f_1}(\p a_1 \sdot \p \ast) \Plus \p{f_2}(\p b_1 \sdot \p \ast)
  \hookrightarrow^* 
  \p{\langle} (\p a_1\p a+\p b_1\p b) \sdot \p{\ast ,} (\p a_1\p c +\p b_1\p d) \sdot \p{\ast \rangle}$.
  Thus, $M\vec{v} = \ul{\p f(\ov{\vec{v}})}$.
  \qed
\end{proof}

\begin{corollary}
\label{cor:tens_encoding}
Let $M$ be a linear transformation on $\mathbb C^{2^n}$.  Then there exists a
closed term $\p f$ such that: $\underline{\p f(\ov{\vec{v}})} = M\vec{v}$ for
all $\vec{v} \in \mathbb{C}^{2^n}$.
\end{corollary}
\begin{proof}
  Let $\p f_1$ and $\p g_1$ encode two matrices $M_1$ and $N_1$ respectively.
Thethe tensor product $M_1 \otimes N_1$ can be encoded by:
  $\p{\lambda z.\, \elimtens(z, \abstr{xy}{f_1 x \otimes g_1 y})}$.
Thus, the result follows from Theorem~\ref{lem:matrix_app} and the fact that any linear transformation  
on a finite-dimensional space $V \otimes W$ can be written as a linear combination of operators of the form $f \otimes g$,  
with $f : V \rightarrow V$ and $g : W \rightarrow W$.
\qed
\end{proof}

\begin{example}[CNOT gate]
  \label{ex:CNOT}
  The $CNOT$ gate can be written as a linear combination of tensor products of Pauli matrices $X$, $Z$, and the identity $I$:  
  \(
    \tfrac{1}{2}(I \otimes I + Z \otimes I + I \otimes X - Z \otimes X)
  \).
  Let $\p f_x$, $\p f_z$ be the proof terms representing $X$ and $Z$, respectively.  
  Then, by Corollary~\ref{cor:tens_encoding}, a proof term representing the $CNOT$ gate for  
  proposition $\pqbit \p\otimes \pqbit \p\multimap \pqbit \p\otimes \pqbit$ is:
  \\
 $\p{\lambda \abstr{z} \elimtens\Big(z, \abstr{xy}}
    \tfrac{\p 1}{\p 2} \sdot \p{(x \otimes y)} \Plus
    \tfrac{\p 1}{\p 2} \sdot \p{(f_z~x \otimes y)}
    \Plus 
    \tfrac{\p 1}{\p 2} \sdot \p{(x \otimes f_x~y)} \Plus
  \tfrac{\p{-1}}{\p 2} \sdot \p{(f_z~x \otimes f_x~y)\Big)}$.
\end{example}

\begin{example}[Quantum switch]
\label{ex:qs}
The quantum switch is a higher-order construction that applies two proofs $\p f,\p g : \p P\pmultimap\p P$ in opposite order depending on the value of a control qubit.  
It can be represented in \ocalc as the proof term:\\
$\p{\lambda \abstr{h} \lambda \abstr{z}
  \elimtens\Big(\!h, \abstr{fg}{
    \elimtens(z, \abstr{xy}{
      \elimwith^1(x,\abstr{x_1}{x_1 \otimes f(g\,y)})\! \Plus
      \elimwith^2(x,\abstr{x_2}{x_2 \otimes g(f\,y)})
    })
  }\!\Big)}$\\
proving the proposition 
$((\p{P \multimap P}) \p\otimes (\p{P \multimap P})) \p\multimap (\pqbit \p\otimes \p P) \p\multimap (\pqbit \p\otimes \p P)$.
\end{example}

The mixed-state fragment allows us to represent quantum measurements.
Let $m \colon M_2 \to M_2$ be the measurement map
\[
  \textit{m}(\rho) \defeq \textstyle\sum_{i=1}^n P_i \rho P_i^\dagger,
\]
determined by a choice of positive elements $P_i \in M_2$ that sum to the identity, i.e. a POVM.
Let $\p m_i$ denote the encoding in \ocalc\ of the linear map $P_i$. Then $\mathcal B(\p m_i)$ encodes
the map $P_i(\cdot)P_i^\dagger$ in a way that allows us to recover its action on positive elements
(which is sufficient considering our choice of morphisms).
Therefore the encoding of $m$ in $\ocalc$ is
\[
  \vdash\mathcal B(\p{m_1}) \Plus \mathcal B(\p{m_2}) \Plus \cdots \Plus \mathcal B(\p{m_n}):\mathcal B(\pqbit\pmultimap\pqbit) .
\]

This construction naturally generalises to measurements on finitely many
qubits by applying Corollary~\ref{cor:tens_encoding}.

\begin{example}[Measurement in the computational basis]
  \label{ex:meas}
  Consider the $2 \times 2$ projection matrices
  $\ketbra{0}{0}$ and $\ketbra{1}{1}$.  
  Let $\p{m_1}, \p{m_2}$ denote the encoding of these matrices in \ocalc.
  Then, the measurement of a single qubit in the computational basis is given by the
  term $\vdash \mathcal B(\p{m_1}) \Plus \mathcal B(\p{m_2}) : \mathcal B(\pqbit\pmultimap\pqbit)$.
  Consider, for example, the term $\p{\ket+} \defeq \p{\langle \frac{1}{\sqrt{2}}} \sdot \p{\ast, \frac{1}{\sqrt{2}}} \sdot \p{\ast \rangle}$.
  Then:
  \begin{align*}
    (\mathcal B(\p{m_1}) \Plus \mathcal B(\p{m_2}))\,\mathcal B(\p{\ket +})
    & \hookrightarrow \mathcal B(\p{m_1~\ket +}) \Plus \mathcal B(\p{m_2~\ket +})\\
  & \hookrightarrow^* \mathcal B\big(\p{\langle} \tfrac{\p 1}{\p{\sqrt{2}}} \sdot \p{\ast , 0} \sdot \p{\ast \rangle}\big)
\Plus \mathcal B\big(\p{\langle 0} \sdot \p{\ast , }\tfrac{\p 1}{\p{\sqrt{2}}} \sdot \p{\ast \rangle}\big).
  \end{align*}
  This is, as expected, the representation of the density matrix
  $\tfrac{1}{2} \cdot \ketbra{0}{0} + \tfrac{1}{2} \cdot \ketbra{1}{1}$.
\end{example}

\begin{example}[Bell measurement]
\label{ex:bell_m}
The Bell basis is given by $\{\beta_{00},\beta_{01},\beta_{10},\beta_{11}\}$, with $\beta_{ij} \defeq CNOT((H\ket i)\otimes\ket j)$.
Let $\p m_{ij}$ be the encoding of the projector $\ketbra{\beta_{ij}}{\beta_{ij}}$. Then, Bell measurement is represented by:
\[
  \vdash\mathcal B(\p m_{00}) \Plus \mathcal B(\p m_{01}) \Plus \mathcal B(\p m_{10}) \Plus \mathcal B(\p m_{11})
  : \mathcal B(\pqbit \p\otimes \pqbit \pmultimap \pqbit \p\otimes \pqbit)
\]
\end{example}

\begin{example}[Teleportation]
\label{ex:tele}
Quantum teleportation transfers the state of a qubit $\ket{\psi}$ using shared entanglement and classical communication. Let $\p{f_i}$ be the proof terms representing the unitary corrections $U_i$, and $\p{h_i}$ the proof terms for the projectors $P_i$ used in a Bell measurement. Then, consider the proof term:
\begin{align*}
  \p{U} \defeq
  &\mathcal B(\p{\lambda \abstr{z} \elimtens(z, \abstr{xy} f_1~x \otimes h_1~y)}) \Plus
  \mathcal B(\p{\lambda \abstr{z} \elimtens(z, \abstr{xy} f_2~x \otimes h_2~y)}) \Plus\\
  &\mathcal B(\p{\lambda \abstr{z} \elimtens(z, \abstr{xy} f_3~x \otimes h_3~y)}) \Plus
  \mathcal B(\p{\lambda \abstr{z} \elimtens(z, \abstr{xy} f_4~x \otimes h_4~y)})
\end{align*}
of the proposition
$\mathcal B(\pqbit \p\otimes (\pqbit \p\otimes \pqbit)) \pmultimap \mathcal B(\pqbit \p\otimes (\pqbit \p\otimes \pqbit))$.
%
Teleportation is then encoded as the proof term for the proposition
$\mathcal B(\pqbit) \multimap \mathcal B(\pqbit \p\otimes \pqbit \p\otimes \pqbit)$ given by
\[
  \text{Telep} \defeq \lambda z.\, \p{U}~(\tau(\mathcal B(\beta_{00}) \otimes z)).
\]
Here, $\tau$ is used to encode the Bell state and the state to be teleported into a single density matrix.
\end{example}



\section{Conclusion}
\label{sec:conclusion}

We have introduced a proof language for Intuitionistic Multiplicative Additive Linear Logic (IMALL), extended with a modality $\mathcal B$ to integrate both pure and mixed-state quantum computation in a unified setting. Our calculus departs from programming-centric paradigms by treating quantum computation as a proof-theoretic discipline: terms are logical proofs, and the interplay between algebraic structure and proof-theoretic structure enforces quantum constraints naturally.

The system enjoys strong meta-theoretic properties, is supported by a denotational model validating its semantics, and allows the representation of interesting quantum phenomena---as exemplified by the quantum switch and quantum teleportation---entirely within the logic. Future work includes extending the model to the full Intuitionistic Linear Logic (ILL) and clarifying the connection with Lambda-S, whose semantics is based on the same adjunction used to interpret the exponential modality of linear logic~\cite{DiazcaroMalherbeACS2020,DiazcaroMalherbeLMCS22}.

