\section{Omitted Proofs in \secref{sec:language}}
\label{app:proofs}
\Uniqueness*
\begin{proof}
  Proof is by induction on $M$:
  \begin{itemize}
    \item $M$ is $\p x$ or $x$: In these cases $\aform{M} = 1 \sdot M$.
    \item $M$ is $\p \topintro$: Again in this case $\aform{M} = 1 \sdot M$.
    \item $M$ is $\p\ast$ or $\ast$: In these cases, $\aform{M} = 1 \sdot M$. 
    \item $M$ is $\p{\elimone(m,n)}$: By induction hypothesis $\p m, \p n$ have unique algebraic forms $\aform{\p m}, \aform{\p n}$.
      We have, $\aform{M} = 1\sdot \p{\elimone(}\aform{\p m}\p ,\aform{\p n}\p)$.
    \item $M$ is $\p{\lambda \abstr{x}m}$: By induction hypothesis, $\p m$ has a algebraic form $\aform{\p m}$. We define,
      $\aform{M} = 1 \sdot \p{\lambda \abstr{x}}\aform{m}$. Since $\aform{\p m}$ is unique, so is $\aform{M}$.
    \item $M$ is $\p{m~n}$: We have, $\aform{\p{m~n}} = \p 1 \sdot \aform{\p m}~\aform{\p n}$.
    \item $M$ is $\p{m \otimes n}$: By the induction hypothesis, we have $\aform{\p m} = \textstyle\sum_{i=1}^m \p{a_i} \sdot \mathfrak{b}^i$,
      $\aform{\p n} = \textstyle\sum_{j=1}^n \p{a_i} \sdot \mathfrak{b}^j$. Hence from transitivity and contextual rules
      it follows that $M = (\textstyle\sum_{i=1}^m \p{a_i} \sdot \mathfrak{b}^i) \p \otimes (\textstyle\sum_{j=1}^n \p{a_i} \sdot \mathfrak{b}^j)$.
      Following the rules for rewriting under $=$ in Figure~\ref{fig:bidir_rules}, we have,
      $M = \textstyle\sum_{i=1}^m \textstyle\sum_{j=1}^n \p{a_ia_j} \sdot \p{\mathfrak{b}^i \otimes \mathfrak{b}^j}$. Now, renaming indices
      and rewriting if needed using the rule $\alpha \sdot M \Plus \beta \sdot M = (\alpha + \beta)\sdot M$, gives us the desired 
      result.
    \item $M$ is $\p{\elimtens(m, \abstr{xy}n)}$: In this case we have $\aform{M} = \p{1} \sdot \p{\elimtens(} \aform{\p m} \p{, \abstr{xy}} \aform{\p n}\p{)}$.
    \item $M$ is $\p{\pair{m}{n}}$: We have, $\aform{M} = \p 1 \sdot \p{\langle} \aform{\p m}\p , \aform{\p n}\p \rangle$.
    \item $M$ is $\p{\elimwith^i(m, \abstr{x}n)}$: Follows using the same argument as the cases above.
    \item $M$ is $\p{m \Plus n}$: By induction hypothesis we have $\aform{\p m} = \textstyle\sum_{i=1}^n \p{a_i}\sdot \mathfrak{b}^i$ and
      $\aform{\p n} = \textstyle\sum_{j=1}^k \p{a_j}\sdot \mathfrak{b}^j$. Hence, 
      $M = \textstyle\sum_{i=1}^n \p{a_i}\sdot \mathfrak{b}^i \Plus \textstyle\sum_{j=1}^k \p{a_j}\sdot \mathfrak{b}^j$. Now, rewriting using commutativity
      and the rule $\alpha \sdot M \Plus \beta \sdot M = (\alpha + \beta)\sdot M$ gives us the result.
    \item $M$ is $\p{a}\sdot \p m$: 
      We have $\aform{\p m} = \textstyle\sum_{i=1}^n \p{a_i}\sdot \mathfrak{b}^i$ by the induction hypothesis. Hence, 
      $M = \p a \sdot \textstyle\sum_{i=1}^n \p{a_i}\sdot \mathfrak{b}^i$. Now rewriting using distributivity, commutativity and the 
      rule $\alpha \sdot (\beta \sdot M) = \alpha \beta \sdot M$, gives us the result.
    \item $M$ is $\mathcal B(\p m)$: In this case we have, $\aform{M} = 1 \sdot \mathcal B(\aform{\p m})$.
    \item $M$ is $\tau(m)$: In this case we have, $\aform{M} = 1 \sdot \tau(\aform{m})$.
  \end{itemize}
  The remining cases for the mixed fragment follow using similar arguments as those above.
  \qed
\end{proof}

\progress*
\begin{proof} 
  The $\leftrightarrows$ is only used to rewrite terms when $\rightarrow$ gets
  stuck, if the reduct is not in its algebraic form. We prove progress by
  induction on $M$.  $M$ cannot be a variable since it is closed, and if If $M$
  is a value, we are done.
  Otherwise, we have the following cases:
  \begin{itemize}
    \item $M$ is $\p{m_1 \Plus m_2}$:  By induction hypothesis, either $\p{m_1}, \p{m_2}$ reduce further or they are values. If they reduce further then 
      so does $M$ by the contextual reduction rules. If they are values we do a case analysis based on the proposition $\p P$ of $M$. If 
      $\p P = \p{P_1 \with P_2}, \p{P_1 \multimap P_2}$, then $\p{m_1}, \p{m_2}$ are $ 
      \p{\pair{u_1}{u_2}}, \p{\pair{v_1}{v_2}}$ or $\p{\lambda \abstr{x}n_1}, \p{\lambda \abstr{x}n_2}$ respectively. In these cases $M$ reduces further under $\rightarrow$ 
      after a rewrite of $M$ to $\aform{M}$. Now, if
      $\p P = \one, \p{P_1 \otimes P_2}$, then they are of the form $\p \ast, \p a \sdot \p \ast$ or 
      $\textstyle\sum_{i=1}^n\p{a_i} \sdot \p{v_b}^i$ as in the syntax. In all these cases, $M$ does not reduce under 
      $\rightarrow$ and hence a rewrite of $M$ under $\leftrightarrows$ gives us the desired result. Hence, in all possible cases $M$ reduces under $\hookrightarrow$.

    \item $M$ is $\p a \sdot \p n$: Again by induction hypothesis, $\p n$ reduces further until it is a value, in which case so does $M$. Now we assume $\p n$ 
      is a value. We do a case analysis based on the proposition $\p P$ of $M$. 
      If $\p P = \p{P_1 \with P_2}, \p{P_1 \multimap P_2}$, then $\p n$ is $ 
      \p{\pair{v_1}{v_2}}$ or $\p{\lambda \abstr{x}n'}$ respectively. In these cases $M$ reduces further under $\rightarrow$ to take the form $\p v$ 
      defined in the syntax. Now, if
      $\p P = \one, \p{P_1 \otimes P_2}$, then it is of the form $\p \ast, \p a \sdot \p \ast$ or 
      $\textstyle\sum_{i=1}^n\p{a_i} \sdot \p{v_b}^i$ as in the syntax. In both these cases, $M$ does not reduce under
      $\rightarrow$ and hence a rewrite of $M$ under $\leftrightarrows$ gives us the desired result. Hence, in all possible cases $M$ reduces under $\hookrightarrow$.

    \item $M$ is $\p{\elimone(m_1,m_2)}$: By induction hypothesis, $\p{m_1}$ reduces until it is a value, in which case so does $M$. Now, we assume that $\p{m_1}$ is a value. It 
      follows that $\p{m_1}$ is $\p{\ast}$ or $\p a \sdot \p \ast$. 
      Hence, it follows that $\p m$ reduces further either through a potential rewrite of $\p{m_1}$ under $\leftrightarrows$ or by reduction under $\rightarrow$.

    \item $M$ is $\p{m_1~m_2}$: Again by induction hypothesis both $\p{m_1}, \p{m_2}$ reduce until they are values, in which case so does $M$. Now, we assume both 
      $\p{m_1}, \p{m_2}$ are values. Hence, by the  rules given in Figure~\ref{fig:derivation_rules} it follows that $\p{m_1}$ is $\p{\lambda \abstr{x}n}$. Therefore, 
      $M$ reduces under $\rightarrow$.

    \item $M$ is $\p{\pair{m_1}{m_2}}$: By induction hypothesis and contextual reduction rules it follows that either $M$ is of the form $\p{\pair{v_1}{v_2}}$ for values $\p{v_1}, \p{v_2}$ or it reduces further under $\rightarrow$. 

    \item $M$ is $\p{\elimwith^1(m_1, \abstr{x} m_2)}$ or $\p{\elimwith^2(m_1, \abstr{x} m_2)}$: By induction hypothesis, either $\p{m_1}$ reduces or it is a value. If 
      it reduces then so does $M$ by the contextual reduction rules. If it is a value, then by the  rules given in Figure~\ref{fig:derivation_rules} it 
      follows that $\p{m_1}$ is $\p{\pair{v_1}{v_2}}$. Hence, $M$ reduces further in both the cases.

    \item $M$ is $\p{m_1 \otimes m_2}$:  By induction hypothesis and contextual reduction rules it follows that either $M$ is of the form $\p{v_1 \otimes v_2}$ for values
      $\p{v_1}, \p{v_2}$ or it reduces further under $\rightarrow$. In the first case a rewrite using Lemma~\ref{lem:unique_alg} gives us a value of the form $\p v$ from the syntax.
    \item $M$ is $\p{\elimtens(m_1, \abstr{xy} m_2)}$: By induction hypothesis, $\p{m_1}$ reduces further until it is a value, in which case so does $M$. Now we assume 
      $\p{m_1}$ is a value. From the  rules in Figure~\ref{fig:derivation_rules} it follows
      that $\p{m_1}$ is of the form $\p{v_n^1 \otimes v_n^2}$ or a linear combination of such values. Hence, following a potential rewrite under $\leftrightarrows$, $M$
      reduces in both the cases under $\rightarrow$.

    \item $M$ is $m_1 \Plus m_2$: Again by induction hypothesis, $m_1, m_2$ reduce further until they are values, in which case so does $M$. Hence we assume that 
      both $m_1, m_2$ are values. Now this case follows using an argument similar to the above case and rewriting
      using the rules for $\leftrightarrows$ defined in Figure~\ref{fig:bidir_rules}.

    \item $M$ is $p \sdot n$: By induction hypothesis, $n$ reduces further until it is a value, in which case so does $M$. Now we assume $n$ is a value, then 
      $n$ takes one of the forms of $v$ from the syntax. In all
      the cases, depending on the form the value takes, $M$ reduces further under $\rightarrow$ through a rewrite under $\leftrightarrows$ (when $M$ is of proposition $A \multimap B$) 
      or it is itself equal a value.

    \item $M$ is $\elimzero(n)$: By induction hypothesis, $n$ reduces until it is a value. Hence, so does $M$ by the contextual rules. Now, we assume $n$ is a value. 
      But by induction hypothesis, $n$ can never be a value.

    \item $M$ is $\elimone(m_1,m_2)$: By induction hypothesis, either $m_1$ reduces or it is a value. If it reduces then so does $M$ by the contextual reduction rules.
      If it is a value, then by the  rules given in Figure~\ref{fig:derivation_rules} it follows that $m_1$ is either $\ast$, or $p \sdot \ast$. In all cases after a 
      potential rewrite to $\aform{m_1}$, $M$ reduces further.

    \item $M$ is $m_1~m_2$: Again by induction hypothesis $m_1, m_2$ reduce further until they are values, in which case so does $M$. Now, we assume both $m_1,m_2$ are values. 
      We do a case analysis on the proposition of $m_1$. 
      First we consider the case when $m_1$ is of the proposition $A \multimap B$. Then it follows that $m_1$ is $\lambda \abstr{x}n$, 
      In this $M$ reduces further.
      Now we consider the case when $m_1$ is of proposition $\mathcal B(\p P_1 \p \multimap \p P_2)$. Then it follows that $m_1$ is $\mathcal B(\p{m_1})$ or 
      $\textstyle\sum_{i=1}^np_i \sdot \mathcal B(\p{v_i})$. Similarly, $m_2$ is also of the form
      $\mathcal B(\p v)$, or $\textstyle\sum_{i=1}^np_i \sdot \mathcal B(\p{u_i})$. This gives us 4 possible cases
      for $M$. All cases reduce using the rules in Figure~\ref{fig:red_rightarrow} after potential rewrites under $\leftrightarrows$.

    \item $M$ is $\inl(n)$ or $\inr(n)$: By induction hypothesis, $n$ reduces further until it is a value, in which case so does $M$. Now we assume $n$ is a value. 
      If $n$ is of the form $v_b$, then in both the cases $M$ is a value.
      Otherwise, $n$ can be rewritten to its algebraic form as a linear combination of $v_b^i$s, so that $M$ reduces further.

    \item $M$ is $\elimplus(m, \abstr{x} n, \abstr{y} o)$: By induction hypothesis $m$ reduces further until it is a value, in which case so does $M$. Now we assume 
      $m$ is a value. Then by Lemma~\ref{lem:unique_alg} it
      follows that $m$ can be rewritten to the form $\textstyle\sum_{i=1}^n p_i\sdot v_b^i$. Hence, $M$ reduces further.

    \item $M$ is $m_1 \otimes m_2$:  Again by induction hypothesis, $m_1, m_2$ reduce further until they are values, in which case so does $M$. Now, we assume
      $m_1, m_2$ are values, in which case $M$ is of the form $v_1 \otimes v_2$ for values
      $v_1, v_2$. A potential rewrite under $\leftrightarrows$ gives us a value of the form $v$ from
      the syntax.
    \item $M$ is $\elimtens(m_1, \abstr{x} m_2)$: By induction hypothesis $m_1$ reduces further until it is value, in which case so does $M$. Now we assume 
      $m_1$ is a value. Then by Lemma~\ref{lem:unique_alg} it
      follows that $m_1$ can be rewritten to the form $\textstyle\sum_{i=1}^n p_i\sdot v_b^i$. Hence, $M$ reduces further.
    \item $M$ is $\mathcal B(\p m)$: Again by induction hypothesis, $\p m$ reduces further until it is a value, in which case so does $M$.
    \item $M$ is $\tau(n)$: By induction hypothesis, $n$ reduces further until it is a value, in which case so does $M$. Now, we assume that $n$ is a value. Then by 
      Lemma~\ref{lem:unique_alg} it
      follows that $n$ can be rewritten to the form $\textstyle\sum_{i=1}^n p_i\sdot v_b^i$. Hence, $M$ reduces further.
     \qed
  \end{itemize}
\end{proof}

\begin{lemma}[Substitution lemma]
  \label{lem:subst}
  If $\Gamma,x: T \vdash M : S$ and $\Delta \vdash N : T$, then $\Gamma , \Delta \vdash (N/x)M : S$.
  \qed
\end{lemma}
\begin{proof}
  By induction on the derivation of $M$.
  \begin{itemize}
    \item $\p{\Delta , x : P, y : Q, \Gamma \vdash m : R}$: This case follows directly from the induction hypothesis.
    \item $\p{\Gamma \vdash \topintro : \top}$: 
      This case follows vacuously.
    \item $\p{\Gamma , \Delta \vdash \elimzero(m') : P}$:
      We consider two cases. First case is when the variable being substituted is in $\p{\Gamma}$. Then the claim follows by using the induction
      hypothesis on the term $\p m'$ and the observation that $\p{(n/x)\elimzero(m')} = \p{\elimzero((n/x)m')}$. In the other case, the claim follows
      since $\p{(n/x)\elimzero(m')} = \p{\elimzero(m')}$.
    \item $\p{x : P \vdash x : P}$: In this case, $\p \Gamma = \emptyset$, $\p P = \p Q$ and $ \p{(n/x) m} = \p n$ and the claim follows.
    \item $\p{\vdash \ast : \one}$: This case follows vacuously.
    \item $\p{\Gamma, \Delta \vdash \elimone( m_1, m_2) : P}$: We consider two cases, one when the variable appears in $\p{m_1}$ and the 
      other when it appears in $\p{m_2}$. Both follow by application of induction hypothesis on $\p{m_1}, \p{m_2}$ respectively
      and the observation that in one case $\p{(n/x)\elimone(m_1, m_2)} = \p{\elimone((n/x)m_1, m_2)}$ and in the other
      case $\p{(n/x)\elimone(m_1, m_2)} = \p{\elimone(m_1, (n/x)m_2)}$.
    \item $\p{\Gamma \vdash \lambda \abstr{x}m' : P \multimap Q}$:  This case follows using the induction hypothesis
      on $\p m'$ and the observation that $\p{(n/x)\lambda \abstr{y} m'} = \p{\lambda \abstr{y}(n/x)m'}$. 
    \item $\p{\Gamma, \Delta \vdash m_1~m_2 : Q}$: Again we consider two cases, one when the variable appears in $\p{m_1}$ and the other when
      the variable appears in $\p{m_2}$. Now the claim follows by applying induction hypothesis on $\p{m_1}, \p{m_2}$ in both
      the cases respectively and the observation that in one case $\p{(n/x)(m_1~m_2)} = \p{((n/x)m_1)~m_2}$ and in the other
      $\p{(n/x)(m_1~m_2)} = \p{m_1~((n/x)m_2)}$.
    \item $\p{\Gamma \vdash \pair{m_1}{m_2} : P \with Q}$: Follows by application of induction hypothesis on $\p{m_1}, \p{m_2}$ respectively
      and the observation that $\p{(n/x)\pair{m_1}{m_2}} = \p{\pair{(n/x)m_1}{(n/x)m_2}}$.
    \item $\p{\Gamma, \Delta \vdash \elimwith^1(m_1,\abstr{x}m_2) : R}$ or $\p{\Gamma, \Delta \vdash \elimwith^2(m_1,\abstr{x}m_2) : R}$: Again we consider two cases, 
      one when the variable appears in $\p{m_1}$ and the other when it appears in $\p{m_2}$. The proof follows by 
      applying the induction hypothesis on $\p{m_1}, \p{m_2}$ respectively and the observation that 
      $\p{(n/x)\elimwith^i(m_1, \abstr{x}m_2)}$ is equal to $\p{\elimwith^i((n/x)m_1, \abstr{x}m_2)}$ in one case and
      $\p{(n/x)\elimwith^i(m_1, \abstr{x}m_2)}$ is equal to $\p{\elimwith^i(m_1, (n/x)\abstr{x}m_2)}$ in the other.
    \item $\p{\Delta, \Gamma \vdash m_1 \otimes m_2 : P \otimes Q}$: We consider two cases, one when the variable $\p x$ appears in $\p{m_1}$ and the other when $\p x$ appears
      in $\p{m_2}$ respectively. We apply induction hypothesis on the terms $\p{m_1}, \p{m_2}$ in both the cases. The claim follows using the
      observation that $\p{(n/x)(m_1 \otimes m_2)} = \p{(n/x) m_1 \otimes m_2}$ in one case and $\p{(n/x)(m_1 \otimes m_2)} = \p{m_1 \otimes (n/x)m_2}$
      in the other.
    \item $\p{\Delta, \Gamma \vdash \elimtens(m_1,\abstr{x y}m_2) : R}$: We consider two cases, one when the variable appears in $\p{m_1}$ and the other when it
      appears in $\p{m_2}$. In both the cases we apply the induction hypothesis on the terms $\p{m_1}, \p{m_2}$ respectively. Then again, the claim
      follows from the observation that $\p{(n/x)\elimtens(m_1, \abstr{yz}m_2)}$ is equal to $\p{\elimtens((n/x)m_1, \abstr{yz}m_2)}$ in one case and
      $\p{(n/x)\elimtens(m_1, \abstr{yz}m_2)}$ is equal to $\p{\elimtens(m_1, (n/x)\abstr{yz}m_2)}$ in the other.
    \item $\p{\Gamma \vdash a} \sdot \p{m' : P}$: This case follows from the induction hypothesis applied to $\p{m'}$ and the observation
      that $\p{(n/x)(a} \sdot \p{m')} = \p{a} \sdot \p{(n/x)m'}$.
    \item $\p{\Gamma \vdash m \Plus n : P}$: This case follows from the induction hypothesis applied to $\p{m_1}, \p{m_2}$ and the 
      observation that $\p{(n/x)(m_1 \Plus m_2)} = \p{(n/x)m_1 \Plus (n/x)m_2}$.
    \item $\Delta , x : B, y : A, \Gamma \vdash m : C$: This case follows directly from the induction hypothesis.
    \item $\vdash \ast : 1$: This case follows vacuously.
    \item $\Gamma, \Delta \vdash \elimone(m_1,m_2) : A$: We consider two cases, one when the variable appears in $m_1$ and the
      other when it appears in $m_2$. Both follow by application of induction hypothesis on $m_1, m_2$ respectively
      and the observation that in one case $(n/x)\elimone(m_1, m_2) = \elimone((n/x)m_1, m_2)$ and in the other
      case $(n/x)\elimone(m_1, m_2) = \elimone(m_1, (n/x)m_2)$.
    \item $\Delta \vdash \lambda \abstr{x}m' : A \multimap B$: We consider two cases. One when the variable being substituted is $x$ which
      is different from the one being abstracted as a lambda abstraction, and the other case when
      the variable being substituted is the one that is a part of the lambda abstraction. The latter case
      follows by the induction hypothesis applied on $m'$. The former case follows using the induction hypothesis
      on $m'$ and the observation that $(n/x)\lambda \abstr{y} m' = \lambda \abstr{y}(n/x)m'$.
    \item $\Gamma, \Delta \vdash m_1~m_2 : B$ or $\Gamma, \Delta \vdash m_1~m_2 : \mathcal B(\p Q)$: Again we consider two cases, 
      one when the variable appears in $m_1$ and the other when
      the variable appears in $m_2$. Now the claim follows by applying induction hypothesis on $m_1, m_2$ in both
      the cases respectively and the observation that in one case $(n/x)(m_1~m_2) = ((n/x)m_1)~m_2$ and in the other
      $(n/x)(m_1~m_2) = m_1~((n/x)m_2)$. The other case follows vacuously since in this case both $m_1, m_2$ are closed. 
    \item $\Delta, \Gamma \vdash m_1 \otimes m_2 : A \otimes B$: We consider two cases, one when the variable $\p x$ appears in $m_1$ and the other when $x$ appears
      in $m_2$ respectively. We apply induction hypothesis on the terms $m_1, m_2$ in both the cases. The claim follows using the
      observation that $(n/x)(m_1 \otimes m_2) = (n/x) m_1 \otimes m_2$ in one case and $(n/x)(m_1 \otimes m_2) = m_1 \otimes (n/x)m_2$
      in the other.
    \item $\Delta, \Gamma \vdash \elimtens(m_1,\abstr{x y}m_2) : C$: We consider two cases, one when the variable appears in $m_1$ and the other when it
      appears in $m_2$. In both the cases we apply the induction hypothesis on the terms $m_1, m_2$ respectively. Then again, the claim
      follows from the observation that $(n/x)\elimtens(m_1, \abstr{yz}m_2)$ is equal to $\elimtens((n/x)m_1, \abstr{yz}m_2)$ in one case and
      $(n/x)\elimtens(m_1, \abstr{yz}m_2)$ is equal to $\elimtens(m_1, (n/x)\abstr{yz}m_2)$ in the other.
    \item $\Delta \vdash \inl(m') : A \oplus B$ or $\Delta \vdash \inr(m') : A \oplus B$: This case follows by applying the induction hypothesis 
      on $m'$ and the observation that $(n/x)\inl(m') = \inl((n/x)m')$.
      The case for $\inr(m')$ follows similarly.
    \item $\Delta , \Gamma \vdash \elimplus(m_1,\abstr{x}m_2,\abstr{y}m_3) : C$: We consider two cases, one when the variable appears in $m_1$ and the other when it
      appears in the terms $m_2, m_3$. Both the cases follow by applying the induction hypothesis on the terms $m_1, m_2,m_3$ respectively and the
      observation that $(n/x)\elimplus(m_1, \abstr{y} m_2, \abstr{z} m_3)$ is equal to $\elimplus((n/x)m_1, \abstr{y} m_2, \abstr{z} m_3)$ in one case and
      $(n/x)\elimplus(m_1 , \abstr{y} m_2, \abstr{z} m_3)$ is equal to $\elimplus(m_1 , (n/x) \abstr{y} m_2, (N/x) \abstr{z} m_3)$ in the other.
    \item $\vdash \mathcal B(\p{m'}): \mathcal B(\p P)$: This case follows vacuously since $\p{m'}$ is a closed term.
    \item $\Gamma \vdash \tau(m'): \mathcal B(\p P \p \otimes \p Q)$: This case follows from the induction hypothesis and the observation that $(n/x)\tau(m') = \tau((n/x)m')$.
    \item $\Gamma \vdash p \sdot m' : A$: This case follows from the induction hypothesis applied to $m'$ and the observation
      that $(n/x)(p \sdot m') = p \sdot (n/x)m'$.
    \item $\Gamma \vdash m_1 \Plus m_2 : A$: This case follows from the induction hypothesis applied to $m_1, m_2$ and the
      observation that $(n/x)(m_1 \Plus m_2) = (n/x)m_1 \Plus (n/x)m_2$.
      \qed
  \end{itemize}
\end{proof}

\subred*
\begin{proof}
  Note that from the rules for $\leftrightarrows$ in Figure~\ref{fig:bidir_rules} and the rules sum and prod$(\alpha)$ from Figure~\ref{fig:derivation_rules} it follows that propositions are preserved by $\leftrightarrows$.
  Hence, it suffices to prove that $\rightarrow$ preserves propositions. We prove this using induction
  on the relation $\rightarrow$. We focus on the basic reduction rules in Figure~\ref{fig:red_rightarrow} and omit the proof for
  contextual rules since they follow easily from the induction hypothesis.
  \begin{itemize}
    \item $M=\p{\elimone( a} \sdot \p{\ast , n)}$ and $N=\p a \sdot \p n$.
      Since we have that $\p{\vdash \ast : \one}$, if we have $\p{\Gamma \vdash n : P}$,
      it follows from the derivation rules that $\p{\Gamma \vdash a} \sdot \p{n : P}$.
    \item $M=\elimone(p \sdot \ast, n)$ and $N=a \sdot n$.
      Since we have that $\vdash a \sdot \ast : 1$, if we have $\cdot \vdash n : A$,
      it follows from the derivation rules that $\cdot \vdash a\sdot n : A$.
    \item $M=\p{(\lambda \abstr{x}m) v}$ and $N=\p{(m_2/x)m_1}$, and the result
      holds by Lemma~\ref{lem:subst}.
    \item $M=(\lambda \abstr{x}m)~v$ and $N=(v/x)m$. The result
      holds by Lemma~\ref{lem:subst}.
    \item $M=\p{\elimwith^1(\pair{v_1}{v_2} , \abstr{x}n)}$ and
      $N=\p{(v_1/x)n}$. The result holds by
      Lemma~\ref{lem:subst}.
      The case for $\p{\elimwith^2(\pair{v_1}{v_2} , \abstr{x}n)}$ is similar.
    \item $M=\elimplus(\inl(v), \abstr{x}m, \abstr{y}n)$ or $M=\elimplus(\inr(v), \abstr{x}m, \abstr{y}n)$ and $N=(v/x)/m$
      or $N=(v/y)n$ respectively. The result holds in both the cases by an application of Lemma~\ref{lem:subst}.
    \item $M=\p{\elimtens(v_n^1 \otimes v_n^2, \abstr{x y}m')}$ and $N=\p{(v_n^1/x , v_n^2/y)m'}$. The result follows by a double application of Lemma~\ref{lem:subst}.
    \item $M=\elimtens(v_n^1 \otimes v_n^2, \abstr{xy}n)$ and $N=(v_n^1/x , v_n^2/y)n$. The result
      holds by a double application of Lemma~\ref{lem:subst}.
    \item $M=\p{a}\sdot \p{\topintro}$ and $N=\p{\topintro}$. The claim follows from the rules $\top_i^p$, sum$^p$,
      and prod$(a)^p$.
    \item $M=\textstyle\sum_{i=1}^n\p{a_i} \sdot \p{\lambda \abstr{x}m_i}$ and $N=\p{\lambda \abstr{x}}\textstyle\sum_{i=1}^n\p{a_i}\sdot \p{m_i}$. 
      The claim follows from the rules $\pmultimap_i^p$, sum$^p$, prod$(a)^p$.
    \item $M=\textstyle\sum_{i=1}^n{p_i} \sdot \lambda\abstr{x}m_i$ and $N=\lambda\abstr{x}\textstyle\sum_{i=1}^n{p_i} \sdot{m_i}$.
      The claim follows from the rules $\multimap_i^m$, sum$^m$, prod$(p)^m$.
    \item $M=\textstyle\sum_{i=1}^n \p{a_i}\sdot \p{\pair{u_{i1}}{u_{i2}}}$ and $N=\p{\langle} \textstyle\sum_{i=1}^n \p{a_i} \sdot \p{u_{i1},} \textstyle\sum_{i=1}^n \p{a_i} \sdot \p{u_{i2} \rangle}$.
      The claim follows from the rules $\pwith_i^p$, sum$^p$ and prod$(a)^p$.
    \item $M=\elimplus(\textstyle\sum_{i=1}^n p_i\sdot v_{bi},x.o,y.s)$ and $N=\textstyle\sum_{i=1}^n p_i\sdot \elimplus(v_{bi},x.o,y.s)$. The claim follows from the rules $\oplus_e^m$, sum$^m$, prod$(p)^m$.
    \item $M=\p{\elimtens(} \textstyle\sum_{i=1}^n \p{a_i} \sdot \p{v_b^i, \abstr{xy}n)}$ and $N=\textstyle\sum_{i=1}^n\p{a_i} \sdot \p{\elimtens(v_b^i, \abstr{xy}n)}$.
      The claim follows from the rules $\p \otimes_e^p$, sum$^p$, prod$(a)^p$.
    \item $M=\inl(\textstyle\sum_{i=1}^n p_i \sdot v_{bi})$ and $N=\textstyle\sum_{i=1}^n p_i \sdot \inl(v_{bi})$. The claim follows from the rules $\oplus_e^{i1}$, sum$^p$ and prod$(p)^p$. The case for $\inr(\textstyle\sum_{i=1}^n p_i \sdot v_{bi})$ is similar.
    \item $M=\tau(\mathcal B(\p v_1) \otimes \mathcal B(\p v_2))$ and $N=\mathcal B(\p{v_1 \otimes v_2})$. The claim follows from
      the rules $\mathcal B(\otimes)^m$, $\p \otimes_i^p$ and $\mathcal B_i^m$.
    \item $M=\tau(\textstyle\sum_{i=1}^n p_i \sdot v_{bi})$ and $N=\textstyle\sum_{i=1}^n p_i \sdot \tau(v_{bi})$. The claim follows from the rules $\mathcal B(\otimes)^m$, sum$^m$ and prod$(p)^m$.
    \item $M=\mathcal B(\p a \sdot \p \ast)$ and $N=|\p a|^2 \sdot \mathcal B(\p{\ast})$. The claim follows by applying the rules
      $\p \one_i^p$, $\mathcal B_i^m$, prod$(a)^p$ and prod$(|a|^2)^m$.
    \item $M=(\textstyle\sum_{i=1}^n p_i \sdot \mathcal B(\p{v_i}))~(\textstyle\sum_{j=1}^k q_j \sdot \mathcal B(\p{w_j}))$ and $N=\textstyle\sum_{i,j} p_i q_j \sdot \mathcal B(\p{v_i~w_j})$. The claim follows from the rules $\mathcal B(\pmultimap)_e^m$, sum$^m$ and prod$(p)^m$.
  \qed
  \end{itemize}
\end{proof}

\subsection{Proof of Strong Normalisation (Theorem~\ref{cor:strong-norm})}
\label{app:SN}
In this section, we prove that the reduction relation $\hookrightarrow$ is strongly normalising.  
To this end, we first extend the relation with additional rules, and show that strong normalisation holds for this extended relation.  
Since the original relation is included in the extended one, this immediately implies that $\hookrightarrow$ is also strongly normalising.

The following rules are added to form the extended relation:
\begin{align*}
  M \Plus N &\hookrightarrow M\\
  M \Plus N &\hookrightarrow N\\
  \alpha \sdot M &\hookrightarrow M
\end{align*}

The \emph{length} of a strongly terminating term $M$, denoted $\ell(M)$, is the maximal length of any reduction sequence starting from $M$.

\begin{lemma}
  \label{lem:plus_sn}
  If $M$ and $N$ are strongly normalising, then so is $M \Plus N$.
\end{lemma}

\begin{proof}
  We show that all one-step reducts of $M \Plus N$ are strongly normalising,  
  by induction on $\ell(M) + \ell(N)$, and then by structural induction on the size of the term.

  If the reduction applies to either $M$ or $N$, the claim follows directly from the induction hypothesis.  
  Otherwise, the reduction applies to the outermost $\Plus$. In that case, the possible reductions are:
  \begin{align*}
    \lambda \abstr{x}m \Plus \lambda \abstr{x}n &\hookrightarrow \lambda \abstr{x}(1 \sdot m \Plus 1 \sdot n)\\
    \p{\lambda \abstr{x}m \Plus \lambda \abstr{x}n} &\hookrightarrow \p{\lambda \abstr{x}(1} \sdot \p{m \Plus 1} \sdot \p{n)}\\
    \p{a} \sdot \p{\pair{m_1}{m_2}} \Plus \p{b} \sdot \p{\pair{m_1'}{m_2'}} &\hookrightarrow \p{\langle a} \sdot \p{m_1 \Plus b} \sdot \p{m_1', a} \sdot \p{m_2 \Plus b} \sdot \p{m_2' \rangle}\\
    M \Plus N &\hookrightarrow M\\
    M \Plus N &\hookrightarrow N
  \end{align*}
  In all cases, the reduct either decreases the size of the term or is built from strongly normalising subterms.  
  Hence, each reduct is strongly normalising by the induction hypothesis or by assumption.  
  \qed
\end{proof}

\begin{lemma}
  \label{lem:dot_sn}
  If $M$ is strongly normalising, then so is $\alpha \sdot M$.
\end{lemma}

\begin{proof}
  As in the previous lemma, we prove that all one-step reducts of $\alpha \sdot M$ are strongly normalising,  
  by induction on $\ell(M)$, and then on the size of the term.

  If the reduction applies to $M$, the claim follows from the induction hypothesis.  
  Otherwise, the reduction applies to the outermost scalar multiplication. The possible reductions are:
  \begin{align*}
    p \sdot \lambda \abstr{x}m &\hookrightarrow \lambda \abstr{x}(p \sdot m)\\
    \p{a} \sdot \p{\lambda \abstr{x}m} &\hookrightarrow \p{\lambda \abstr{x}(a} \sdot \p{m)}\\
    \p{a} \sdot \p{\topintro} &\hookrightarrow \p{\topintro}\\
    \p{a} \sdot \p{\pair{m_1}{m_2}} &\hookrightarrow \p{\langle a} \sdot \p{m_1, a} \sdot \p{m_2 \rangle}
  \end{align*}
  In all cases, either the term decreases in size, or it is constructed from strongly normalising subterms.  
  Thus, the result follows by induction or by the assumption that $M$ is strongly normalising.  
  \qed
\end{proof}

We let $\mathbf{SN}$ denote the set of proof terms that terminate in finitely many steps.

\begin{definition}
We inductively define the interpretation $\sn{T}$ of each proposition $T$ as the set of strongly normalising proof terms of $T$, as follows:
\begin{align*}
  \sn{\p\top} &\defeq \{ \p m \in \mathbf{SN} \} \\
  \sn{\one} &\defeq \{ \p m \in \mathbf{SN} \} \\
  \sn{\p P \pmultimap \p Q} &\defeq \left\{ \p m \in \mathbf{SN} \mid \p m \hookrightarrow^* \lambda \abstr{x}{n} \Rightarrow \forall \p v \in \sn{\p P},\ (\p v / x)n \in \sn{\p Q} \right\} \\
  \sn{\p P \pwith \p Q} &\defeq \left\{ \p m \in \mathbf{SN} \mid \p m \hookrightarrow^* \pair{\p{v_1}}{\p{v_2}} \Rightarrow \p{v_1} \in \sn{\p P} \ \text{and}\ \p{v_2} \in \sn{\p Q} \right\} \\
  \sn{\p{P \otimes Q}} &\defeq \left\{ \p m \in \mathbf{SN} \mid \p m \hookrightarrow^* \p{v_1} \otimes \p{v_2} \Rightarrow \p{v_1} \in \sn{\p P} \ \text{and}\ \p{v_2} \in \sn{\p Q} \right\} \\
  \sn{\zero} &\defeq \{ m \in \mathbf{SN} \} \\
  \sn{1} &\defeq \{ m \in \mathbf{SN} \} \\
  \sn{A \multimap B} &\defeq \left\{ m \in \mathbf{SN} \mid m \hookrightarrow^* \lambda \abstr{x}{m'} \Rightarrow \forall v \in \sn{A},\ (v / x)m' \in \sn{B} \right\} \\
  \sn{A \oplus B} &\defeq \left\{ m \in \mathbf{SN} \mid \begin{array}{l}
      m \hookrightarrow^* \inl(v) \Rightarrow v \in \sn{A},\\
      m \hookrightarrow^* \inr(v) \Rightarrow v \in \sn{B}
    \end{array}
  \right\} \\
  \sn{A \otimes B} &\defeq \left\{ m \in \mathbf{SN} \mid m \hookrightarrow^* v \otimes w \Rightarrow v \in \sn{A} \ \text{and}\ w \in \sn{B} \right\} \\
  \sn{\mathcal B(\p P)} &\defeq \left\{ m \in \mathbf{SN} \mid m \hookrightarrow^* \mathcal B(\p v) \Rightarrow \p v \in \sn{\p P} \right\}
\end{align*}
\end{definition}

\begin{definition}[Definitions and notations]
~
\begin{itemize}
  \item A \emph{substitution function} is a map $\theta : \s{0.85}{\versalita{Vars}} \rightarrow \s{0.85}{\versalita{Pure Values}} \cup \s{0.85}{\versalita{Mixed Values}}$.
  Given a term $M$, we write $\theta(M)$ for the result of replacing all free variables in $M$ by their image under $\theta$.

  \item Given a context $\Gamma$ and a substitution function $\theta$, we say that $\theta$ is \emph{valid for} $\Gamma$, written $\theta \vDash \Gamma$,  
  if for all $x : T \in \Gamma$, we have $\theta(x) \in \sn{T}$.

  \item For a term $M$, we define the set of one-step reducts of $M$ as:
  \[
    \mathit{Red}(M) \defeq \{\, N \mid M \hookrightarrow N \,\}
  \]

  \item A term is said to be \emph{neutral} if the last rule used in its derivation is an elimination rule, or the rule $\mathcal B(\otimes)^m$.
\end{itemize}
\end{definition}

\begin{lemma}[CR3]
  \label{lem:forward}
  Let $M$ be a neutral proof term of $T$.  
  If $N \in \sn{T}$ for all $N \in \mathit{Red}(M)$, then $M \in \sn{T}$.
\end{lemma}
\begin{proof}
Since all one-step reducts of $M$ are strongly normalising, all reduction sequences originating from $M$ are finite.  
Thus, $M \in \mathbf{SN}$. Moreover, since $M$ is neutral, it is not a value.

We proceed by case analysis on the proposition $T$:

\begin{itemize}
  \item $T \in \{\one, 1, \p\top, \p\zero\}$: Immediate, as $M$ strongly terminates by assumption and no further structure is required.

  \item $T = \p{P \multimap Q}$ (or $T = A \multimap B$):  
    We show the pure case; the mixed case is analogous.  
    Let $M \hookrightarrow N \hookrightarrow^* \lambda \abstr{x}{m}$.  
    Since $N \in \sn{T}$, we know that for all $\p v \in \sn{\p P}$, we have $(\p v / x)m \in \sn{\p Q}$.  
    Thus, by definition of $\sn{\p{P \multimap Q}}$, we conclude $M \in \sn{T}$.

  \item $T = \p{P \with Q}$:  
    In this case, $M \hookrightarrow N \hookrightarrow^* \pair{\p{v_1}}{\p{v_2}}$.  
    Since $N \in \sn{T}$, we know that $\p{v_1} \in \sn{\p P}$ and $\p{v_2} \in \sn{\p Q}$.  
    Therefore, $M \in \sn{\p{P \with Q}}$.

  \item $T = A \oplus B$:  
    In this case, $M \hookrightarrow N \hookrightarrow^* \inl(v)$ or $\inr(v)$.  
    Since $N \in \sn{T}$, we have either $v \in \sn{A}$ or $v \in \sn{B}$, respectively.  
    Hence, $M \in \sn{A \oplus B}$.

  \item $T = \p{P \otimes Q}$ (or $T = A \otimes B$):  
    Again, we show the pure case.  
    Let $M \hookrightarrow N \hookrightarrow^* \p{v_1} \otimes \p{v_2}$.  
    Since $N \in \sn{T}$, we know $\p{v_1} \in \sn{\p P}$ and $\p{v_2} \in \sn{\p Q}$.  
    Thus, $M \in \sn{\p{P \otimes Q}}$.

  \item $T = \mathcal B(\p P)$:  
    In this case, $M \hookrightarrow N \hookrightarrow^* \mathcal B(\p v)$.  
    Since $N \in \sn{T}$, we have $\p v \in \sn{\p P}$.  
    Hence, $M \in \sn{\mathcal B(\p P)}$.
    \qed
\end{itemize}
\end{proof}

\begin{lemma}[Adequacy of sum]
  \label{lem:sn_plus}
  If $M, N \in \textbf{SN}(T)$, then $M \Plus N \in \textbf{SN}(T)$.
\end{lemma}
\begin{proof}
  Proof is again by induction on the proposition $T$. Again by Lemma~\ref{lem:plus_sn} we have that $M \Plus N$ always terminates.
  \begin{itemize}
    \item $T$ is $\one$ or $1$:
      Follows directly from Lemma~\ref{lem:plus_sn}.
    \item $T$ is $\p P \pwith \p Q$:
      Since $M \Plus N$ terminates and $T$ is $\p{P \with Q}$, we have $M \Plus N \hookrightarrow^{\ast} \p{\pair{v_1}{v_2}}$.
      Hence, either $M \hookrightarrow^{\ast} \p{\pair{u_1}{u_2}}$, $N \hookrightarrow^{\ast} \p{\pair{u_1'}{u_2'}}$ with
      $\p{u_1 \Plus u_1'} \hookrightarrow^{\ast} \p{v_1}$ and $\p{u_2 \Plus u_2'} \hookrightarrow^{\ast} \p{v_2}$ or $M \hookrightarrow^{\ast} \p{\pair{v_1}{v_2}}$
      or $N \hookrightarrow^{\ast} \p{\pair{v_1}{v_2}}$. The first case follows by the induction hypothesis and the assumption that $M, N \in \sn{T}$.
      The other two cases follow from the assumption $M, N \in \sn{T}$.
    \item $T$ is $\p P_1 \pmultimap \p P_2$ or $A \multimap B$:
      Since both the cases are similar, we present only one case here. Since $M\Plus N$ terminates and $T$ is $\p{P \multimap Q}$, we have
      $M \plus N \hookrightarrow^{\ast} \p{\lambda \abstr{x}m}$. Now, either $M \hookrightarrow \p{\lambda \abstr{x}m_1}$, $M \hookrightarrow \p{\lambda \abstr{x}m_2}$
      and $\p m$ is of the form $\p{m_1 \Plus m_2}$ or $M \hookrightarrow^{\ast} \p{\lambda \abstr{x}m}$ or $N \hookrightarrow^{\ast} \p{\lambda \abstr{x}m}$.
      The first case follows by an application of the induction hypothesis to $\p{(v/x)m_1 \Plus m_2}$ and the assimption that $M,N \in \sn{T}$. The other two 
      cases follow from the assumption $M,N \in \sn{T}$.
    \item $T$ is $\p{P \otimes Q}$ or $A \otimes B$:
      We present only one case here, the other case follows using a similar argument. Since, $M \Plus N$ terminates and $T$ is $\p{P \otimes Q}$ we have
      $M \Plus N \hookrightarrow^{\ast} \p{v_1 \otimes v_2}$. Then either $M \hookrightarrow^{\ast} \p{v_1 \otimes v_2}$ or $N \hookrightarrow^{\ast} \p{v_1 \otimes v_2}$.
      Both cases follow from the assumption that $M,N \in \sn{T}$.
    \item $T$ is $A \oplus B$:
      Since, $M \Plus N$ terminates and $T$ is $A \oplus B$ we have
      $M \Plus N \hookrightarrow^{\ast} \inl(v)$(or $\inr(v)$). Then either $M \hookrightarrow^{\ast} \inl(v)$(or $\inr(v)$) or $N \hookrightarrow^{\ast} \inl(v)$(or $\inr(v)$).
      Both cases follow from the assumption that $M,N \in \sn{T}$.
    \item $T$ is $\mathcal B(\p P)$:
      Since, $M \Plus N$ terminates and $T$ is $\mathcal B(\p P)$ we have
      $M \Plus N \hookrightarrow^{\ast} \mathcal B(\p v)$. Then either $M \hookrightarrow^{\ast} \mathcal B(\p v)$ or $N \hookrightarrow^{\ast} \mathcal B(\p v)$.
      Both cases follow from the assumption that $M,N \in \sn{T}$.
      \qed
  \end{itemize}
\end{proof}


\begin{lemma}[Adequacy of prod($\alpha$)]
  \label{lem:sn_bullet}
  If $M \in \sn{T}$, then $\alpha \sdot M \in \sn{T}$.
\end{lemma}
\begin{proof}
  Proof is by induction on the proposition $T$. Note that by Lemma~\ref{lem:dot_sn} we have that $\alpha \sdot M$ always terminates.
  \begin{itemize}
    \item $T$ is $\one$ or $1$:
      Directly follows from Lemma~\ref{lem:dot_sn}.
    \item $T$ is $\p P \pwith \p Q$:
      Since, $\alpha \sdot M$ terminates and $T$ is $\p{P \with Q}$ it follows that $\alpha \sdot M \hookrightarrow^{\ast} \p{\pair{v_1}{v_2}}$.
      Then either $M \hookrightarrow^{\ast} \p{\pair{u_1}{u_2}}$ with $\alpha \sdot \p{u_1} \hookrightarrow^{\ast} \p{v_1}$ and 
      $\alpha \sdot \p{u_2} \hookrightarrow^{\ast} \p{v_2}$ or $M \hookrightarrow^{\ast} \p{\pair{v_1}{v_2}}$. In the first case, the conclusion
      follows by an application of induction hypothesis to $\p{u_1}, \p{u_2}$ and $M \in\sn{T}$. In the second case, the conclusion follows
      from the fact that $M \in \sn{T}$.
    \item $T$ is $\p P \pmultimap \p Q$ or $A \multimap B$:
      We present only one case here, the other case follows similarly.
      Since $\alpha \sdot M$ terminates and $T$ is $\p{P \multimap Q}$, it follows that $\alpha \sdot M \hookrightarrow^{\ast} \p{\lambda \abstr{x}m}$.
      Now either $M \hookrightarrow^{\ast} \p{\lambda \abstr{x}n}$ and $m$ is $\alpha \sdot \p n$
      or $M \hookrightarrow^{\ast} \p{\lambda \abstr{x}m}$. The first case follows from the induction hypothesis applied to $\p{(v/x)n}$ for 
      $\p v \in \sn{\p P}$ and $M \in \sn{T}$. The latter case follows
      from $M \in \sn{T}$.
    \item $T$ is $\p{P \otimes Q}$ or $A \otimes B$:
      Again we present only one case here, the argument for the other case is similar. Since $\alpha \sdot M$ terminates and $T$ is $\p{P \otimes Q}$,
      we have $\alpha \sdot M \hookrightarrow^{\ast} \p{v_1 \otimes v_2}$ and $M \hookrightarrow^{\ast} \p{v_1 \otimes v_2}$. Now the claim follows
      since $M \in \sn{T}$.
    \item $T$ is $A \oplus B$:
      Since $\alpha \sdot M$ terminates and $T$ is $A \oplus B$,
      we have $\alpha \sdot M \hookrightarrow^{\ast} \inl(v)$(or $\inr(v)$) and $M \hookrightarrow^{\ast} \inl(v)$(or $\inr(v)$). Now the claim follows
      since $M \in \sn{T}$.
    \item $T$ is $\mathcal B(\p P)$:
      Since $\alpha \sdot M$ terminates and $T$ is $\mathcal B(\p P)$,
      we have $\alpha \sdot M \hookrightarrow^{\ast} \mathcal B(\p v)$ and $M \hookrightarrow^{\ast} \mathcal B(\p v)$. Now the claim follows
      since $M \in \sn{T}$.
  \end{itemize}
	\qed
\end{proof}

\begin{lemma}[Adequacy of $\zero_e^m$]
\label{lem:sn_elimzero}
        If $m \in \sn{\zero}$ then ${\elimzero(m)} \in \sn{A}$.
\end{lemma}
\begin{proof}
 $m$ always terminates. Any reduction acting on ${\elimzero(m)}$ can only reduce $m$, hence it always terminates. Since, ${\elimzero(m)}$
can never reduce to a closed value, it follows that ${\elimzero(m)} \in \sn{A}$.
\qed
\end{proof}


\begin{lemma}[Adequacy of $\one_e^p$]
  \label{lem:sn_elimone_p}
  If $\p{m_1} \in \sn{\one}$ and $\p{m_2} \in \sn{\p P}$, then $\p{\elimone(m_1,m_2)} \in \sn{\p P}$.
\end{lemma}
\begin{proof}
  We use induction on $\ell(\p{m_1})$ and Lemma~\ref{lem:forward} to prove that $\p{\elimone(m_1,m_2)} \in \sn{\p P}$.
  From Lemma~\ref{lem:forward} it suffices to show that all one-step reducts of the term $\p{\elimone(m_1,m_2)}$
  are in $\sn{\p P}$. Now if a reduction applies to $\p{m_1}$, then by induction hypothesis the resulting
  term is in $\sn{\p P}$. Otherwise, $\p{m_1}$ is of the form $\p a \sdot \p \ast$, in which case,
  $\p{\elimone(m_1,m_2)} \hookrightarrow \p a \sdot \p{m_2}$. Now again from Lemma~\ref{lem:sn_bullet}
  it follows that $\p a \sdot \p{m_2} \in \sn{\p P}$. Hence, from Lemma~\ref{lem:forward} it follows
  that $\p{\elimone(m_1,m_2)} \in \sn{\p P}$.
  \qed
\end{proof}

\begin{lemma}[Adequacy of $1_e^m$]
  \label{lem:sn_elimone_m}
  If $m_1 \in \sn{1}$ and $m_2 \in \sn{A}$, then $\elimone(m_1,m_2) \in \sn{A}$.
\end{lemma}
\begin{proof}
  Proof for this lemma follows by the same argument as for Lemma~\ref{lem:sn_elimone_p}.
  \qed
\end{proof}

\begin{lemma}[Adequacy of $\pmultimap_i^p$]
  \label{lem:sn_arrow_p}
  If $\p v \in \sn{\p P}$ and $\p{(v/x)m} \in \sn{\p Q}$ then $\p{\lambda \abstr{x}m} \in \sn{\p P  \p \multimap \p Q}$.
\end{lemma}
\begin{proof}
  Straightforward from the definition of $\sn{\p{P \multimap Q}}$.
  \qed
\end{proof}

\begin{lemma}[Adequacy of $\multimap_i^m$]
  \label{lem:sn_arrow_m}
  If $v \in \sn{A}$ and $(v/x)m \in \sn{B}$ then $\lambda \abstr{x}m \in \sn{A \multimap B}$.
\end{lemma}
\begin{proof}
  Straightforward from the definition of $\sn{A \multimap B}$.
  \qed
\end{proof}


\begin{lemma}[Adequacy of $\pmultimap_e^p$]
  \label{lem:sn_arrow_ep}
  If $\p n \in \sn{\p P}$ and $\p m \in \sn{\p P \p \multimap \p Q}$ then $\p{m~n} \in \sn{\p Q}$.
\end{lemma}
\begin{proof}
  Proof is by induction on $\ell(m) + \ell(n)$ and Lemma~\ref{lem:forward}. If a reduction applies to either
  $\p m$ or $\p n$, then the resulting term is in $\sn{\p Q}$ by the induction hypothesis. Otherwise, both
  $\p m$ and $\p n$ are values and $\p{m~n}$ reduces to $\p{(n/x)m'}$ for some term $\p{m'}$. Since $\p m \in \sn{\p{P \multimap Q}}$,
  we have that $\p{(n/x)m'} \in \sn{\p Q}$. Hence, all one step reducts of $\p{m~n} \in \sn{\p Q}$. Therefore, by Lemma~\ref{lem:forward}
  it follows that $\p{m~n} \in \sn{\p Q}$.
  \qed
\end{proof}

\begin{lemma}[Adequacy of $\multimap_e^m$]
  \label{lem:sn_arrow_em}
  If $n \in \sn{A}$ and $m \in \sn{A \multimap B}$ then $m~n \in \sn{B}$.
\end{lemma}
\begin{proof}
  Analogous to the proof of Lemma~\ref{lem:sn_arrow_ep}.
  \qed
\end{proof}

\begin{lemma}[Adequacy of $\p\with_i^p$]
  \label{lem:sn_with}
  If $\p{m_1} \in \sn{\p P}$ and $\p{m_2} \in \sn{\p Q}$ then $\p{\pair{m_1}{m_2}} \in \sn{\p P \pwith \p Q}$.
\end{lemma}
\begin{proof}
  Note that since a reduction can only apply to $\p{\pair{m_1}{m_2}}$ if it applies to either $\p{m_1}$ or $\p{m_2}$,
  it follows that since $\p{m_1}$ and $\p{m_2}$ strongly terminate, so does $\p{\pair{m_1}{m_2}}$. Moreover, we also have
  that $\p{\pair{m_1}{m_2}} \hookrightarrow^{\ast} \p{\pair{v_1}{v_2}}$ for $\p{v_1} \in \sn{\p P_1}$ and $\p{v_2} \in \sn{\p P_2}$,
  since $\p{\pair{m_1}{m_2}} \hookrightarrow \p{\pair{m_1'}{m_2'}} \implies \p{m_1} \hookrightarrow \p{m_1'}$ and $\p{m_2} \hookrightarrow \p{m_2'}$.
  \qed
\end{proof}

\begin{lemma}[Adequacy of $\p\with_{e1}^p$]
\label{lem:sn_with_e1}
	If $\p{m_1} \in \sn{\p P \pwith \p Q}$ and for all $\p v \in \sn{\p P}$, $\p{(v/x)m_2} \in \sn{\p R}$,
	then $\p{\elimwith^1(m_1 , \abstr{x}m_2)} \in \sn{\p R}$.
\end{lemma}
\begin{proof}
  Proof is by induction on $\ell(\p{m_1})$ and Lemma~\ref{lem:forward}. If a reduction applies
  to $\p{m_1}$, then we have that the resulting term is in $\sn{\p P \pwith \p Q}$. If 
  $\p{m_1}$ is a value, then we have $\p{(m_1/x)m_2} \in \sn{\p R}$. Hence all one step reducts of 
  $\p{\elimwith^1(m_1 , \abstr{x}m_2)}$ are in $\sn{\p R}$. Therefore, the result follows
  from Lemma~\ref{lem:forward}.
  \qed
\end{proof}

\begin{lemma}[Adequacy of $\p\with_{e1}^p$]
  \label{lem:sn_with_e2}
  If $\p{m_1} \in \sn{\p P \pwith \p Q}$ and for all $\p v \in \sn{\p Q}$, $\p{(v/x)m_2} \in \sn{\p R}$,
  then $\p{\elimwith^2(m_1 , \abstr{x}m_2)} \in \sn{\p R}$.
\end{lemma}
\begin{proof}
  Proof follows by the same argument as that for the proof of Lemma~\ref{lem:sn_with_e1}.
  \qed
\end{proof}

\begin{lemma}[Adequacy of $\oplus_{i1}^m$]
  \label{lem:sn_oplus_l}
  If $m \in \sn{A}$, then $\inl(m) \in \sn{A \oplus B}$.
\end{lemma}
\begin{proof}
  Note that a reduction can only apply to $\inl(m)$ through $m$. Hence, $\inl(m)$ strongly terminates.
  Moreover, since $\inl(m) \hookrightarrow \inl(m') \implies m \hookrightarrow m'$, we have $\inl(m) \in \sn{A \oplus B}$.
  \qed
\end{proof}

\begin{lemma}[Adequacy of $\oplus_{i2}^m$]
  \label{lem:sn_oplus_r}
  If $m \in \sn{B}$, then $\inr(m) \in \sn{A \oplus B}$.
\end{lemma}
\begin{proof}
  This result follows using the same argument as the one for the proof of Lemma~\ref{lem:sn_oplus_l}.
  \qed
\end{proof}

\begin{lemma}[Adequacy of $\oplus_{e}^m$]
  \label{lem:sn_oplus_elim}
  If $m \in \sn{A \oplus B}$ and for all $m_1 \in \sn{A}, m_2 \in \sn{B}$, we have $(m_1/x)n \in \sn{C}$ and $(m_2/y)o \in \sn{C}$,
  then $\elimplus(m, \abstr{x}n, \abstr{y}o) \in \sn{C}$.
\end{lemma}
\begin{proof}
  Proof is by induction on $\ell(m)$ and an application of Lemma~\ref{lem:forward}. If a reduction applies
  to $m$ then the resulting term is in $\sn{A \oplus B}$ as a result of the induction hypothesis. If,
  $m$ is a value, and the resulting term is of the form $(m_1/x)n$ or $(m_2/y)o$. Otherwise, $m$ is of the form
  $\textstyle\sum_{i=1}^n v_i$, where $v_i$ is of the form $\inl(v)$ or $\inr(v)$. Then $\elimplus(m, \abstr{x}n, \abstr{y}o)$
  reduces to $\textstyle\sum_{i=1}^n p_i \sdot \elimplus(v_i, \abstr{x}n, \abstr{y}o)$. This term is in $\sn{A \oplus B}$ by the
  induction hypothesis, Lemma~\ref{lem:sn_bullet} and Lemma~\ref{lem:sn_plus}. Hence, all one-step reducts of
  $\elimplus(m, \abstr{x}n, \abstr{y}o)$ are in $\sn{C}$. Therefore, the claim follows by Lemma~\ref{lem:forward}.
  \qed
\end{proof}

\begin{lemma}[Adequacy of $\p\otimes_i^p$]
  \label{lem:sn_tens_p}
  If $\p{m_1} \in \sn{\p P}$ and $\p{m_2} \in \sn{\p Q}$ then $\p{m_1 \otimes m_2} \in \sn{\p P \p \otimes \p Q}$.
\end{lemma}
\begin{proof}
  Note that since a reduction can only apply to $\p{m_1 \otimes m_2}$ if it applies to either $\p{m_1}$ or $\p{m_2}$,
  it follows that since $\p{m_1}$ and $\p{m_2}$ strongly terminate, so does $\p{m_1 \otimes m_2}$. Moreover, we also have
  that $\p{m_1 \otimes m_2} \hookrightarrow^{\ast} \p{v_1 \otimes v_2}$ for $\p{v_1} \in \sn{\p P_1}$ and $\p{v_2} \in \sn{\p P_2}$,
  since $\p{m_1 \otimes m_2} \hookrightarrow \p{m_1' \otimes m_2'} \implies \p{m_1} \hookrightarrow \p{m_1'}$ and $\p{m_2} \hookrightarrow \p{m_2'}$.
  \qed
\end{proof}

\begin{lemma}[Adequacy of $\otimes_i^m$]
  \label{lem:sn_tens_m}
  If $m \in \sn{A}$ and $n \in \sn{B}$ then $m \otimes n \in \sn{A \otimes B}$.
\end{lemma}
\begin{proof}
  The result follows using the same argument as the one for Lemma~\ref{lem:sn_tens_m}.
  \qed
\end{proof}

\begin{lemma}[Adequacy of $\p\otimes_{e}^p$]
  \label{lem:sn_tenselim_p}
  If $\p{m_1} \in \sn{\p P \p \otimes \p Q}$ and for all $\p{v_1} \in \sn{\p P}, \p{v_2} \in \sn{\p Q}$
  we have $\p{(v_1/x,v_2/y)m_2} \in \sn{\p R}$ then $\p{\elimtens(m_1, \abstr{xy} m_2)}$ $\in \sn{\p R}$.
\end{lemma}
\begin{proof}
  Again proof is by induction on $\ell(\p{m_1})$ and an application of Lemma~\ref{lem:forward}. If a reduction applies
  to $\p{m_1}$ then the resulting term is in $\sn{\p{P \otimes Q}}$ as a result of the induction hypothesis. If,
  $\p{m_1}$ is a value, and the resulting term is of the form $\p{(v_1/x,v_2/y)m_2}$. Otherwise $\p{m_1}$ is of the 
  form $\textstyle\sum_{i=1}^n \p{a_i} \sdot \p{v_n}^1 \p \otimes \p{v_n}^2$. In this case $\p{\elimtens(m_1, \abstr{xy} m_2)}$ reduces to 
  $\textstyle\sum_{i=1}^n \p{a_i} \sdot \p{\elimtens(} \p{v_n}^1 \p \otimes \p{v_n}^2 \p{, \abstr{xy}m_2)}$. By induction hypothesis, Lemma~\ref{lem:sn_bullet} and
  Lemma~\ref{lem:sn_plus}, this term is in $\sn{\p R}$. Hence, all one-step reducts of
  $\p{\elimtens(m_1, \abstr{xy} m_2)}$ are in $\sn{\p R}$. Therefore, the claim follows by Lemma~\ref{lem:forward}.
  \qed
\end{proof}

\begin{lemma}[Adequacy of $\otimes_{e}^m$]
  \label{lem:sn_tenselim_m}
  If $m_1 \in \sn{A \otimes B}$ and for all $m \in \sn{A}, n \in \sn{B}$
  $(m/x,n/y)m_2 \in \sn{C}$ then $\elimtens(m_1, \abstr{xy} m_2) \in \sn{C}$.
\end{lemma}
\begin{proof}
  The proof for this lemma follows using the same argument as the one for Lemma~\ref{lem:sn_tenselim_p}.
  \qed
\end{proof}

\begin{lemma}[Adequacy of $\mathcal B_i^m$]
  \label{lem:sn_l}
  If $\p m \in \sn{\p P}$, then $\mathcal B(\p m) \in \sn{\mathcal B(\p P)}$.
\end{lemma}
\begin{proof}
  Note that any reduction that applies to $\mathcal B(\p m)$ is through $\p m$. Hence, $\mathcal B(\p m)$
  strongly terminates. Since, $\mathcal B(\p m) \hookrightarrow \mathcal B(\p m') \implies \p m \hookrightarrow \p m'$,
  we have $\mathcal B(\p m) \in \sn{\mathcal B(\p P)}$.
  \qed
\end{proof}

\begin{lemma}[Adequacy of $\mathcal B(\p\multimap)_e^m$]
  \label{lem:sn_arrow_l}
  If $m \in \sn{\mathcal B(\p{P \multimap Q})}$ and $n \in \mathcal B(\p P)$ then $m~n \in \sn{\mathcal B(\p Q)}$.
\end{lemma}
\begin{proof}
  Again, proof is by induction on $\ell(m) + \ell(n)$ and Lemma~\ref{lem:forward}. We prove all one-step reducts of $m~n$ are in
  $\sn{\mathcal B(\p Q)}$. If a reduction applies to either $m$
  or $n$, then the resulting term is in $\sn{\mathcal B(\p Q)}$ by induction hypothesis. Otherwise $m$ is of the form $\textstyle\sum_{i=1}^n p_i \sdot \mathcal B(\p{\lambda \abstr{x}m_i'})$
  and $n$ is of the form $\textstyle\sum_{j=1}^k q_j \sdot \mathcal B(\p{v_j})$. In this case, $m~n$ reduces to $\textstyle\sum_{i=1}^n\textstyle\sum_{j=1}^kp_iq_j \sdot \mathcal B(\p{\lambda \abstr{x}m'~n})$.
  Now the claim follows
  by Lemma~\ref{lem:sn_arrow_ep}, Lemma~\ref{lem:sn_bullet}, Lemma~\ref{lem:sn_plus} and the definition of $\sn{\mathcal B(\p P)}$ for any proposition $\p P$.
  \qed
\end{proof}


\begin{lemma}[Adequacy of $\mathcal B(\otimes)^m$]
  \label{lem:sn_tau}
  If $m \in \sn{\mathcal B(\p P) \otimes \mathcal B(\p Q)}$, then $\tau(m) \in \sn{\mathcal B(\p{P \otimes Q})}$.
\end{lemma}
\begin{proof}
  Proof is by  induction on $\ell(\p m)$ and Lemma~\ref{lem:forward}. If a reduction applies to $m$ then the resulting term is in 
  $\sn{\mathcal B(\p{P \otimes Q})}$ by induction hypothesis. If $m$ is a value of the form $\mathcal B(\p{v_1}) \otimes \mathcal B(\p{v_2})$
  then the term reduces to $\mathcal B(\p{v_1 \otimes v_2})$ which is in $\sn{\mathcal B(\p{P \otimes Q})}$, from Lemma~\ref{lem:sn_tens_p}
  and $m \in \sn{\mathcal B(\p P) \otimes \mathcal B(\p Q)}$. Otherwise $m$ is of the form $\textstyle\sum_{i=1}^n p_i \sdot v_i$, in which case one of the
  following rules may apply:
  \begin{align*}
    \tau(m) &\hookrightarrow \textstyle\sum_{i=1}^n p_i \sdot \tau(v_i)\\
    \tau(m) &\hookrightarrow \tau(p_i \sdot v_i)
  \end{align*}
  The resulting term in both the cases is in $\sn{\mathcal B(\p{P \otimes Q})}$ by induction hypothesis,
  Lemma~\ref{lem:sn_bullet} and Lemma~\ref{lem:sn_plus}. Hence, all one step reducts of $\tau(m)$ are in $ \sn{\mathcal B(\p{P \otimes Q})}$.
  Now the result follows by Lemma~\ref{lem:forward}.
  \qed
\end{proof}

\begin{lemma}[Adequacy]
\label{lem:subst-strong-norm}
For the judgement $\Gamma \vdash M : T$, if $\theta \vDash \Gamma$ then $\theta(M) \in \sn T$.
\end{lemma}
\begin{proof}
  Proof is by induction on the derivation of $\Gamma\vdash M:T$.
  \begin{itemize}
    \item If the last rule is $ax$, $M=x$: Since $\theta\vDash\Gamma$, we have $\theta(x)\in\sn T$.
    \item If the last rule is sum, $M=M' \Plus N'$: Since $\theta(M' \Plus N') = \theta M' \Plus \theta N'$, from the induction
      hypothesis and Lemma~\ref{lem:sn_plus} it follows that $\theta M \in \sn T$.
    \item If the last rule is prod$(\alpha)$: $M$ is $\alpha \sdot N$: Since $\theta (\alpha \sdot N) = \alpha \sdot (\theta N)$, from the induction
      hypothesis and Lemma~\ref{lem:sn_bullet} it follows that $\theta M \in \textbf{SN}(T)$.
    \item If the last rule is $\topintro_i^p$, $M$ is $\p\topintro$: Since $M$ is closed and irreducible we have $\theta M = M$, and $M \in \sn{\p\top}$.
    \item If the last rule is $0_e^m$, $M$ is $\elimzero(m)$: Note that $\theta M = \elimzero(\theta m)$. Now the claim follows from the induction hypothesis 
      applied to $\theta  m $ and Lemma~\ref{lem:sn_elimzero}.
    \item If the last rule is $1_i$, $M$ is $\ast$: Then $M$ is closed irreducible proof term of $1$. Hence, $\theta M = M$, and we have $\theta M \in \sn{T}$.
    \item If the last rule is $1_e$, $M$ is $\elimone(m,n)$: Note that $\theta {\elimone(m,n)} = {\elimone(}\theta {m, } \theta {n)}$.
      Now the claim follows from the induction hypothesis and Lemmas~\ref{lem:sn_elimone_p} and \ref{lem:sn_elimone_m}.
    \item If the last rule is $\multimap_i$, $M$ is $\lambda \abstr{x}N$: 
      Note that $\theta ({\lambda \abstr{x}N}) = {\lambda \abstr{x}(}\theta {N)}$. 
      We need to show that $\theta({(V/x)N}) \in \sn{ T}$ for any $ V \in \sn{ S}$. However, note that $\theta({(V/x)N}) = \theta'( N)$ for a new substitution function,
      $\theta' = \theta \cup \{x \mapsto  V \}$. Since $ V \in \sn{ S}$, we have $\theta' \vDash {\Gamma, x : S}$.
      Hence, by the induction hypothesis, it follows that $\theta'( M)  \in \sn{ T}$. Hence, the claim follows from
      Lemmas~\ref{lem:sn_arrow_p} and~\ref{lem:sn_arrow_m}.
    \item If the last rule is $\multimap_e$, $M$ is $M'~N'$: Note that $\theta M = (\theta M')~(\theta N')$. Now the claim follows using the induction hypothesis on the terms
      $\theta M', \theta N'$ and applying Lemma~\ref{lem:sn_arrow_ep}, Lemma~\ref{lem:sn_arrow_em}.
    \item If the last rule is $\p\with_i^p$, $M$ is $\p{\pair{m_1}{m_2}}$: Note that $\theta M = \p{\langle} \theta \p{m_1 ,} \theta \p{m_2 \rangle}$. Now the claim follows from the
          induction hypothesis and Lemma~\ref{lem:sn_with}.
	\item If the last rule is $\p\with_{ei}^p$, $M$ is $\p{\elimwith^i(m_1, \abstr{x} m_2)}$: Thus, $\theta M = \p{\elimwith^i(}\theta \p{m_1, \abstr{x}}\theta \p{m_2)}$. Now 
	  the claim follows from the induction hypothesis and Lemma~\ref{lem:sn_with_e1}, Lemma~\ref{lem:sn_with_e2}.
    \item If the last rule is $\oplus_{i1}^m$, $M$ is $\inl(m)$: In this case $\theta M = \inl(\theta m)$. Now the claim follows from the induction hypothesis and Lemma~\ref{lem:sn_oplus_l}.
    \item If the last rule is $\oplus_{i2}^m$, $M$ is $ \inr(m)$: In this case $\theta M = \inr(\theta m)$. Now the claim follows from the induction hypothesis and Lemma~\ref{lem:sn_oplus_r}.
    \item If the last rule is $\oplus_e^m$, $M$ is $\elimplus(m, \abstr{x} n, \abstr{y} o)$: Thus, $\theta M = \elimplus(\theta m, \abstr{x} \theta n, \abstr{y} \theta o)$. Now the 
	  claim follows from the induction hypothesis and Lemma~\ref{lem:sn_oplus_elim}.
    \item If the last rule is $\otimes_i$, $M$ is  $\p{m \otimes n}$ or $m \otimes n$: We prove one case, the other follows analogously. 
          Note that $\theta M = \theta \p{m} \p \otimes \theta \p{n}$. Hence from the induction hypothesis
	  it follows that $\theta \p{m} \in \sn{\p P}$ and $\theta \p{n} \in \sn{\p Q}$. Now the claim follows from Lemmas~\ref{lem:sn_tens_p} and~\ref{lem:sn_tens_m}. 
    \item If the last rule is $\otimes_e$, $M$ is $\p{\elimtens(m , \abstr{xy}n)}$ or $\elimtens(m , \abstr{xy}n)$: Again we prove one case, the other follows analogously.
      In this case $\theta M = \p{\elimtens(}\theta \p{m, \abstr{xy}}\theta \p{n)}$. Hence the claim follows from the induction hypothesis and
      Lemmas~\ref{lem:sn_tenselim_p} and~\ref{lem:sn_tenselim_m}. 
    \item If the last rule is $\mathcal B_i^m$, $M$ is $\mathcal B(\p m)$: Since $\p m$ is a closed term $\theta \p{m} = \p m$, hence from the induction hypothesis and Lemma~\ref{lem:sn_l},
      $\theta M = \mathcal B(\p m) \in \sn{\p P}$.
    \item If the last rule is $\mathcal{B}(\p\multimap)^m_e$, $M$ is $m~n$: Note that $\theta M = (\theta m)~(\theta n)$. Now the claim follows using the induction hypothesis on the terms
	  $\theta m, \theta n$ and applying Lemma~\ref{lem:sn_arrow_l}.
    \item If the last rule is $\mathcal{B}(\p\otimes)^m$, $M$ is $\tau(m)$: Claim follows by the observation that $\theta \tau(m) = \tau(\theta m)$, an application of 
	  induction hypothesis and Lemma~\ref{lem:sn_tau}.
    \item If the last rule is $ex$, then the claim directly follows from the induction hypothesis.
  \end{itemize}
  \qed
\end{proof}

\strongnorm*
\begin{proof}
  The result follows from Lemma~\ref{lem:subst-strong-norm}, by using the identity function as the substitution function.
  \qed
\end{proof}

\section{Omitted Proofs in Section~\ref{sec:denotational}}\label{app:denotational}
\begin{lemma}[Substitution]
\label{lem:subst_d}
Let $\Gamma, x : S \vdash M : T$, $\Delta \vdash N : S$, and
$\Gamma , \Delta \vdash (N/x)M : T$ be valid judgements.  
Then:
\[
  \lrb{\Gamma , \Delta \vdash (N/x)M : T}
  = \lrb{\Gamma, x : S \vdash M : T}
  \circ (id_{\lrb{\Gamma}} \otimes \lrb{\Delta \vdash N : S}).
\]
\end{lemma}
\begin{proof}
  By induction on the derivation of $\Gamma,x:S\vdash M:T$.
  We consider the last rule in the derivation.
  \begin{description}
    \item[({\normalfont ax})] $x : S \vdash x : S$: In this case $(N/x)M=N$, $T=S$, and $\Gamma = \emptyset$.
    \item[({\normalfont sum})] $\Gamma , x : S \vdash M_1 \Plus M_2 : T$: This case follows directly from the induction hypothesis and the observation that $(N/x)(M_1 \Plus M_2) = (N/x)M_1 \Plus (N/x)M_2$.
    \item[({\normalfont prod}$(\alpha)$)] $\Gamma , x : S \vdash \alpha \sdot M : S$: This case also follows directly from the induction hypothesis and the observation that 
      $(N/x)\alpha \sdot M = \alpha \sdot (N/x)M$.
    \item[($\top_i^p$)] $\p{\Gamma \vdash \topintro : \top}$: This case follows from $!_{\lrb{\Gamma}\otimes\lrb{\Delta}} = {!}_{\lrb{\Gamma}\otimes\lrb{S}}\circ(id\otimes\lrb{\Delta \vdash N : \top})$.
    \item[($0_e^m$)] $\Gamma , \Delta \vdash \elimzero(m) : A$: In this case, first observe that $(n/x)\elimzero(m) = \elimzero((n/x)m)$. Now the claim follows from induction hypothesis applied to $m$
      and the following computation:
      \begin{align*}
	&\lrb{\Gamma, \Delta \vdash \elimzero((n/x)m) : A}\\
	&= !_{\zero\otimes\lrb{\Gamma}, A} \circ (\lrb{(n/x)m} \otimes id)\\
	&= !_{\zero\otimes\lrb{\Gamma}, A} \circ (\lrb{m} \otimes id) \circ (\lrb{n} \otimes id)
      \end{align*}
    \item[($1_i$)] $\vdash \ast : \one$: This case is impossible, since $\Gamma,x:S\neq\emptyset$.
    \item[($1_e$)] $\Gamma , x : S \vdash \elimone(M_1,M_2) : T$: In this case we have $(N/x)\elimone(M_1,M_2)=$ $\elimone((N/x)M_1, (N/x)M_2)$.
      We consider the case when $x$ appears in $M_1$, the other case follows using a similar   
      argument. Let $\Gamma = \Gamma_1, \Gamma_2$ so that $\Gamma_1 , x : S \vdash M_1 : \one$ and
      $\Gamma_2 \vdash M_2 : T$. Then we have,
      $\lrb{\Gamma, \Delta \vdash \elimone((N/x)M_1 , M_2) : T}$ $= \lambda_T \circ (\lrb{(N/x)M_1} \otimes \lrb{M_2})$.
      Applying the induction hypothesis, we have that $\lrb{\Gamma_1, \Delta \vdash (N/x)M_1 : \one}$
      $= \lrb{\Gamma_1, x : S \vdash M_1 : \one} \circ (id_{\lrb{\Gamma_1}} \otimes \lrb{\Delta \vdash N : \one})$.
      Hence we have,
      \begin{align*}
	&\lrb{\Gamma, \Delta \vdash \elimone((N/x)M_1, M_2) : T} \\
	&=\lambda_T \circ ((\lrb{\Gamma_1, x : S \vdash M_1 : \one}
	\circ (id_{\lrb{\Gamma_1}} \otimes \lrb{\Delta \vdash N : S})) \otimes \lrb{M_2}) \\
	&=\lambda_T \circ ((\lrb{\Gamma_1, x : S \vdash M_1 : \one} \otimes \lrb{M_2})
	\circ (id_{\lrb{\Gamma_1}} \otimes \lrb{\Delta \vdash N : S} \otimes id_{\lrb{\Gamma_2}})) \\
	&=\lrb{\Gamma, x : S \vdash \elimone(M_1,M_2) : T} \circ (id_{\lrb{\Gamma}} \otimes \lrb{\Delta \vdash N : S})
      \end{align*}
    \item[($\multimap_i$)] $\Gamma , x : S \vdash \lambda \abstr{y}M : {T \multimap R}$: We have $(N/x)\lambda \abstr{y}M = \lambda \abstr{y}(N/x)M$. We use the induction hypothesis
      on $(N/x)M$ to obtain the following:
      \begin{align*}
	&\lrb{\Gamma , \Delta \vdash \lambda \abstr{y}(N/x)M : {T \multimap R}} \\      
	&=\Phi (\lrb{\Gamma , \Delta , y : T \vdash (N/x)M : R}) \\
	&=\Phi (\lrb{\Gamma , y : T , x : S \vdash M : R}
	\circ (id_{\lrb{\Gamma, y : T}} \otimes \lrb{\p{\Delta \vdash N : S}})) \\
	&=\lrb{\Gamma, x : S \vdash \lambda \abstr{y}m : {T \multimap R}} \circ (id_{\lrb{\Gamma}} \otimes \lrb{\Delta \vdash n : S})
      \end{align*}
    \item[($\multimap_e$)] $\Gamma , x : S \vdash M_1~M_2 : T$:  We have $(N/x)(M_1~M_2) = (N/x)M_1~(N/x)M_2$. We consider the case when $x$ appears in $M_1$, the other
      case follows using a similar argument. Again we let $\Gamma = \Gamma_1 , \Gamma_2$ so that $\Gamma_1 , x : S \vdash M_1 : {R \multimap T}$, and
      $\Gamma_2 \vdash M_2 : R$. Let $f,g$ denote $\lrb{\Gamma_1 , x : S \vdash M_1 : {R \multimap T}},$ and $\lrb{\Gamma_2 \vdash M_2 : R}$ respectively.
      \begin{align*}
	&\lrb{\Gamma, \Delta \vdash (N/x)M_1~M_2 : T} \\
	&=\textit{eval}_{T, R}
	\circ (\lrb{\Gamma_1, \Delta \vdash (N/x)M_1 : {R \multimap T}} \otimes \lrb{\Gamma_2 \vdash M_2 : R}) \\
	&=\textit{eval}_{T, R} \circ ((f \circ (id_{\lrb{\Gamma_1}} \otimes \lrb{\Delta \vdash N : S})) \otimes g) \\
	&=\textit{eval}_{T, R} \circ (f \otimes g) \circ (id_{\lrb{\Gamma_1},\Gamma_2} \otimes \lrb{\Delta \vdash N : S})\\
	&=\lrb{\Gamma , x : S \vdash M_1~M_2 : T} \circ (id_{\Gamma} \otimes \lrb{\Delta \vdash N : S})
      \end{align*}
    \item[($\pwith_i^p$)] $\p{\Gamma , x : R \vdash \pair{m_1}{m_2} : P \with Q}$: Note that we have $\p{(n/x)\pair{m_1}{m_2}}=$ $\p{\pair{(n/x)m_1}{(n/x)m_2}}$.
      We use the induction hypothesis for both the terms $\p{(n/x)m_1} , \p{(n/x)m_2}$. We have:
      \begin{align*}
	&\lrb{\p{\Gamma \vdash (n/x)\pair{m_1}{m_2} : P \with Q}}\\
	&=\langle \lrb{\p{\Gamma \vdash (n/x)m_1 : P}} , \lrb{\p{\Gamma \vdash (n/x)m_2 : Q}}\rangle\\
	&= \langle \lrb{\p{\Gamma, x : R \vdash m_1 : P}}\circ (id_{\p \Gamma} \otimes \lrb{\p{\Delta \vdash n : R}}),\\
	&\hspace{2cm}\lrb{\p{\Gamma, x : R \vdash m_2 : Q}}\circ (id_{\p\Gamma} \otimes \lrb{\p{\Delta \vdash n : R}})\rangle\\
	&= \langle \lrb{\p{\Gamma, x : R \vdash m_1 : P}} , \lrb{\p{\Gamma, x : R \vdash m_2 : Q}} \rangle
	\circ (id_{\p \Gamma} \otimes \lrb{\p{\Delta \vdash n : R}})\\
	&= \lrb{\p{\Gamma , x : R \vdash \pair{m_1}{m_2} : P \with Q}} \circ (id_{\p\Gamma} \otimes \lrb{\p{\Delta \vdash n : R}})
      \end{align*}
    \item[($\pwith_{ei}^p$)] $\p{\Gamma , x : P' \vdash \elimwith^i(m', \abstr{y}n') : P}$: We present the case where $\p x$ appears in $\p m'$ first. Let $\p \Gamma = \p{\Gamma_1}, \p{\Gamma_2}$,
      so that $\p{\Gamma_1 , x : P' \vdash m' : Q \with R}$ and $\p{\Gamma_2 , y : Q \vdash n' : P}$ are valid. We have:
      \begin{align*}
	&\p{\lrb{\Gamma ,\Delta \vdash \elimwith^i((n/x)m', \abstr{y}n') : P}}\\
	&= \lrb{\p n'} \circ (\pi_i \otimes id_{\p \Gamma_2}) \circ (\lrb{\p{(n/x)m'}} \otimes id_{\p \Gamma_2})
	\circ  (id_{\lrb{\p \Gamma_1}} \otimes \sigma_{\lrb{\p \Gamma_2}, \lrb{\p \Delta}})\\
	&= \lrb{\p n'} \circ (\pi_i \otimes id_{\p \Gamma_2}) \circ (\lrb{\p m'} \otimes id_{\p \Gamma_2})
	\begin{aligned}[t]
	  &\circ (id_{\p \Gamma_1} \otimes \lrb{\p n} \otimes id_{\p \Gamma_2})\\
	  &\circ (id_{\lrb{\p \Gamma_1}} \otimes \sigma_{\lrb{\p \Gamma_2}, \lrb{\p \Delta}})
	\end{aligned}\\
	&= \lrb{\p n'} \circ (\pi_i \otimes id_{\p \Gamma_2}) \circ (\lrb{\p m'} \otimes id_{\p \Gamma_2}) \circ(id_{\p \Gamma} \otimes \lrb{\p n})\\
	&= \lrb{\p{\Gamma, x : P' \vdash \elimwith^i(m', \abstr{y}n') : P}} \circ (id_{\p \Gamma} \otimes \lrb{\p n})
      \end{align*}
      For the case when $\p x$ appears in $\p n'$, again let $\p \Gamma = \p \Gamma_1 , \p \Gamma_2$ so that
      $\p{\Gamma_1 \vdash m' : Q \with R}$, $\p{\Gamma_2 , \Delta \vdash (n/x)n' : P}$ are valid.
      We have $\p{\Delta \vdash n : P'}$. It suffices to show that $((\pi_1 \circ \lrb{\p n}) \otimes id_{\lrb{\p{\Gamma_2, P'}}}) \circ (id_{\lrb{\p \Gamma}} \otimes \lrb{\p n}) =$
      $(id_{\lrb{\p {Q, \Gamma_2}}} \otimes \lrb{\p n}) \circ ((\pi_1 \circ \lrb{\p m'}) \otimes id_{\lrb{\p{\Gamma_2}, \p \Delta}})$. But this holds,
      because $\p m',\p n$ are independent of each other, and act on disjoint contexts.
    \item[($\oplus_{i1}^m$)] $\Gamma , x : C \vdash \inl(m') : A \oplus B$: We have $(n/x)\inl(m') = \inl((n/x)m')$. We apply the induction hypothesis on $(n/x)m'$. Hence,
      \begin{align*}
	&\lrb{\Gamma , \Delta \vdash (n/x)\inl(m') : A \oplus B}\\
	&= i_1 \circ (\lrb{\Gamma, \Delta  \vdash (n/x)m' : A})\\
	&= i_1 \circ \lrb{\Gamma, x: C \vdash m' : A} \circ (id_{\Gamma} \otimes \lrb{\Delta \vdash n : C})\\
	&= \lrb{\Gamma, x: C \vdash \inl(m') : A \oplus B} \circ (id_{\Gamma} \otimes \lrb{\Delta \vdash n : C})
      \end{align*}
    \item[($\oplus_{i2}^m$)] $\Gamma , x : C \vdash \inr(m') : A \oplus B$: This case follows using the same argument as that for the above case.
    \item[($\oplus_{e}^m$)] $\Gamma , x : A' \vdash \elimplus(m' , \abstr{y}n', \abstr{z}o') : C$: Suppose $x$ appears in $m'$. In this case $(n/x)\elimplus(m' , \abstr{y}n', \abstr{z}o') =$
      $\elimplus((n/x)m', \abstr{y}n' , \abstr{z}o')$. Let $\Gamma = \Gamma_1, \Gamma_2$ so that
      $\Gamma_1 , x : A' \vdash m' : A \oplus B$, $\Gamma_2, y: A  \vdash n' : C$ and $\Gamma_2, z : B \vdash o' : C$ are valid. Let $f,g,h$ denote $\lrb{\Gamma_2 ,y : A \vdash n' : C},$
      $\lrb{\Gamma_2, z : B \vdash o' : C},$ $\lrb{\Gamma_1, x : A' \vdash m' : A\oplus B}$ respectively. We have:
      \begin{align*}
	&\lrb{\Gamma \vdash \elimplus((n/x)m', \abstr{y}n' , \abstr{z}o' : C)}\\
	&= [f,g] \circ d \circ \sigma \circ ((h \circ (id \otimes \lrb{n}))\otimes id)\\
	&= [f,g] \circ d \circ \sigma \circ (h \otimes id) \circ (id \otimes \lrb{n} \otimes id)\\
	&= [f,g] \circ d \circ \sigma \circ (h \otimes id) \circ (id \otimes \lrb{n})
      \end{align*}
      Suppose $x$ appears in $n',o'$. Then the term $(n/x)\elimplus(m', \abstr{y} n', \abstr{z} o')$ is equal to $\elimplus(m', \abstr{y}(n/x)n', \abstr{z}(n/x)o')$.
      Again let $\Gamma = \Gamma_1 , \Gamma_2$ so that $\Gamma_1 \vdash m : A \oplus B$, $\Gamma_2 , x : A' , y : A \vdash n : C$ and
      $\Gamma_2, x : A', z : B \vdash o :C$ are valid. Let $f,g,h$ denote $\lrb{\Gamma_2, y : A, x : A' \vdash n' : C}$, $\lrb{\Gamma_2 , z : B, x : A' \vdash o' : C}$,
      $\Gamma_1 \vdash m' : A \oplus B$ respectively. We use the induction hypothesis on $(n/x)n', (n/x)o'$. We have:
      \begin{align*}
	&\lrb{\Gamma_1,\Gamma_2,\Delta \vdash \elimplus(m',\abstr{y}(n/x)n', \abstr{z}(n/x)o') :C}\\
	&= [ f\circ (id \otimes \lrb{n}), g \circ(id \otimes \lrb{n}) ]
	\circ d \circ \sigma \circ (h \otimes id)\\
	&= [f,g] \circ (id \otimes \lrb{n})
	\circ d \circ \sigma \circ (h \otimes id)\\
	&= [f,g] \circ d \circ \sigma \circ (h \otimes id)
	\circ id \otimes \lrb{n}
      \end{align*}
      Note that the last equality holds because $m',n$ are independent terms and acting on disjoint contexts, therefore the corresponding morphisms commute.

    \item[($\otimes_i$)] $\Gamma , x : S \vdash M_1 \otimes M_2 : {T_1 \otimes T_2}$: Without loss of generality assume $x$ appears in $M$. The case when $x$ appears in $N$ follows using
      a similar argument. In this case we have, $(N/x)(M_1 \otimes M_2) = (N/x)M_1 \otimes M_2$. Let $\Gamma = \Gamma_1, \Gamma_2$ so that $\Gamma_1, x : S \vdash M_1 : {T_1}$
      and $\Gamma_2 \vdash M_2 : {T_2}$ are valid. We use the induction hypothesis for $(N/x)M_1$. Let $f,f',g$ denote $\lrb{\Gamma_1, \Delta \vdash (N/x)M_1 : {T_1}}$,
      $\lrb{\Gamma_1, x : S \vdash M_1 : {T_1}}$, $\lrb{\Gamma_2 \vdash M_2 : {T_2}}$ respectively.
      \begin{align*}
	&\lrb{\Gamma_1, \Gamma_2, \Delta \vdash (N/x)M_1 \otimes M_2 : {T_1\otimes T_2}}\\
	&=(f \otimes g) \circ (id_{\Gamma_1} \otimes \sigma_{\lrb{\Gamma_2}, \lrb{\Delta}})\\
	&= ((f' \circ (id_{\Gamma_1} \otimes \lrb{N})) \otimes g) \circ (id_{\Gamma_1} \otimes \sigma_{\lrb{\Gamma_2}, \lrb{\Delta}})\\
	&= (f' \otimes g) \circ (id_{\Gamma_1} \otimes \lrb{N}\otimes id_{\Gamma_2}) \circ (id_{\Gamma_1} \otimes \sigma_{\lrb{\Gamma_2}, \lrb{\Delta}})\\
	&= (f' \otimes g) \circ (id_{\Gamma} \otimes \lrb{N})
      \end{align*}
    \item[($\otimes_e$)] $\Gamma , x : S \vdash \elimtens(M' , \abstr{y z}N') : T$:
      Again there are two cases here. First we consider the case when $x$
	    appears in $M'$. Applying the induction hypothesis on $M'$, we have the following:
	    \begin{align*}
		    &\lrb{\Gamma , \Delta \vdash \elimtens((N/x)M', \abstr{y z}N') : T}\\
		    &= \lrb{N'} \circ (id \otimes \lrb{(N/x)M'})\\
		    &=\lrb{N'} \circ (id \otimes(\lrb{M'} \circ (id \otimes \lrb{N})))\\
		    &=\lrb{N'} \circ (id \otimes \lrb{M'}) \circ (id \otimes \lrb{N})\\
		    &=\lrb{\elimtens(M', \abstr{y z}N')} \circ (id \otimes \lrb{N})
	    \end{align*}
	    Now we consider the case when $x$ appears in $N'$. Applying the induction hypothesis on $N'$, we have the following:
	    \begin{align*}
		    &\lrb{\Gamma , \Delta \vdash \elimtens((N/x)M', \abstr{y z}N') : T}\\
		    &= \lrb{(N/x)N'} \circ (id \otimes \lrb{M'})\\
		    &= \lrb{N'} \circ (id \otimes \lrb{N}) \circ (id \otimes \lrb{M'})\\
		    &= \lrb{N'} \circ (id \otimes \lrb{M'}) \circ (id \otimes \lrb{N})
	    \end{align*}
	    Note that the last equality holds because $M',N$ are independent terms and acting on disjoint contexts, therefore the corresponding morphisms commute.
    \item[($\mathcal B_i^m$)] $\vdash\mathcal B(\p m) : \mathcal B(\p P)$: This case is impossible, since $\Gamma,x:S\neq\emptyset$.
    \item[($\mathcal B(\multimap)^m$)] $\Gamma , x : A \vdash m'~n' :\mathcal B(\p Q)$: Again we consider two cases, one when $x$ appears in $m'$ and the other when it appears in $n'$.
	  First we consider the case when it appears in $m'$. Applying the induction hypothesis to $m'$, we have the following:
	  \begin{align*}
	     &\lrb{\Gamma, \Delta \vdash (n/x)m'~n' :\mathcal B(\p Q)}\\
	     &= \mathcal B(eval) \circ \tau \circ (\lrb{(n/x)m'} \otimes \lrb{n'})\\
	     &= \mathcal B(eval) \circ \tau \circ ((\lrb{m'}\circ(id \otimes \lrb{n})) \otimes \lrb{n'})\\
	     &= \mathcal B(eval) \circ \tau \circ (\lrb{m'} \otimes \lrb{n'}) \circ (id \otimes \lrb{n})
	  \end{align*}
	  Similarly, for the case when $x$ appears in $n'$, we have the following:
	  \begin{align*}
                  &\lrb{\Gamma, \Delta \vdash (n/x)m'~n' :\mathcal B(\p Q)}\\
		  &= \mathcal B(eval) \circ \tau \circ (\lrb{m'} \otimes \lrb{(n/x)n'})\\
		  &= \mathcal B(eval) \circ \tau \circ (\lrb{m'} \otimes (\lrb{n'}\circ (id \otimes \lrb{n})))\\
                  &= \mathcal B(eval) \circ \tau \circ (\lrb{m'} \otimes \lrb{n'}) \circ (id \otimes \lrb{n})
	  \end{align*}
    \item[($\mathcal B(\otimes)^m$)] $\Gamma , x : A\vdash \tau(m') : B$: This case follows easily from the observation that $(n/x)\tau(m') = \tau((n/x)m')$ and the application of the induction hypothesis
      on $m'$.
    \item[({\normalfont ex})] $\Gamma,x:S_2,y:S_1\vdash M:T$. Direct from the induction hypothesis.
      \qed
  \end{description}
\end{proof}

\begin{restatable}{lemma}{psubsteq}
  \label{lem:subst_eq_p}
  \label{lem:subst_eq_m}
  The following equations hold for valid judgements:
  \begin{enumerate}
    \item$\lrb{\Gamma \vdash \elimone( \alpha\sdot \ast , M) : T} = \lrb{\Gamma \vdash \alpha \sdot M : T}$
    \item$\lrb{\Gamma \vdash (\lambda \abstr{x}M)~N : T} = \lrb{\Gamma \vdash (N/x)M : T}$
    \item$\lrb{\p{\Gamma \vdash \elimwith^i(\pair{m_1}{m_2} , \abstr{x}n) : P}} = \lrb{\p{\Gamma \vdash (m_i/x)n : P}}$
    \item $\lrb{\Gamma \vdash \elimplus(\inl(m), x.n, y.o) : A} = \lrb{\Gamma \vdash (m/x)n : A}$
    \item $\lrb{\Gamma \vdash \elimplus(\inr(m), x.n, y.o) : A} = \lrb{\Gamma \vdash (m/y)o : A}$
    \item$\lrb{\Gamma \vdash \elimtens(M_1 \otimes M_2, \abstr{xy}N) : T} = \lrb{\Gamma \vdash (M_1/x, M_2/y)N : T}$
  \end{enumerate}
\end{restatable}
\begin{proof}
  Most cases follow from Lemma~\ref{lem:subst_d}:
  \begin{enumerate}
    \item 
      $\begin{aligned}[t]
	\lrb{\Gamma \vdash \elimone(\alpha\sdot \ast, M) : T}
	&=\lambda_{T} \circ (\alpha \sdot id_I \otimes \lrb{\Gamma \vdash M : T})\\
	&=\lambda_{T} \circ (id_I \otimes \alpha \sdot \lrb{\Gamma \vdash M : T})\\
	&=\alpha \sdot \lrb{\Gamma \vdash M : T}\\
	&=\lrb{\Gamma \vdash \alpha \sdot M : T}
      \end{aligned}$
    \item Let $ \Gamma = {\Gamma_1} , {\Gamma_2}$ with ${\Gamma_1 \vdash \lambda \abstr{x}M : S \multimap T}$ and
      ${\Gamma_2 \vdash N : S}$. Let $f,g$ denote the morphisms $\lrb{{\Gamma_1, x : S \vdash M : T}}$, $\lrb{{\Gamma_2 \vdash N : S}}$ respectively.
      \begin{align*}
	\lrb{{\Gamma \vdash (\lambda \abstr{x}M)~N : T}} 
	&=\textit{eval}_{ T,  S} \circ (\Phi(f) \otimes g) \\
	&=\varepsilon_{\lrb{ S}} \circ (\Phi(f) \otimes id_{\lrb{ S}}) \circ (id_{\lrb{ \Gamma_1}} \otimes g) \\
	&=\varepsilon_{\lrb{ S}} \circ \_ \otimes \lrb{ S}(\Phi (f)) \circ (id_{\lrb{{\Gamma_1}}} \otimes g) \\
	&=f \circ (id_{\lrb{{\Gamma_1}}} \otimes g) \\
	&=\lrb{{\Gamma \vdash (N/x)M : T}}
      \end{align*}
    \item Let $\p \Gamma = \p{\Gamma_1}, \p{\Gamma_2}$ with $\p{\Gamma_1 \vdash \pair{m_1}{m_2} : Q \with R}$ and $\p{\Gamma_2 , x : Q \vdash n : P}$.
      \begin{align*}
	&\lrb{\p{\Gamma \vdash \elimwith^i(\pair{m_i}{m_2}, \abstr{x}o) : P}}\\
	&=\lrb{\p{\Gamma_2, x : Q \vdash n : P}} \circ (\pi_i \otimes id)
	\circ (\lrb{\p{\Gamma_1 \vdash \pair{m_1}{m_2} : Q \with R}} \otimes id)\\
	&=\lrb{\p{\Gamma_2 , x : Q \vdash n : P}} \circ (\lrb{\p{\Gamma_1 \vdash m_i : Q}} \otimes id) \circ
	\sigma_{\lrb{\p{\Gamma_1}}, \lrb{\p{\Gamma_2}}}\\
	&=\lrb{\p{\Gamma \vdash (m_i/x)o : P}}
      \end{align*}
    \item Let $\Gamma = \Gamma_1, \Gamma_2$, with $\Gamma_1 \vdash \inl(m) : B \oplus C$,
      $\Gamma_2 , x : B \vdash n : A$ and $\Gamma_2, y : C \vdash o : A$. Let $f,g$ denote the morphisms
      $\lrb{\Gamma_2 , x : B \vdash n : A}$, $\lrb{\Gamma_2, y : C \vdash o : A}$ respectively.
      \begin{align*}
	\lrb{\Gamma_1, \Gamma_2 \vdash \elimplus(\inl(m), \abstr{x}n , \abstr{y}o) : C}
	&= [f,g] \circ d \circ \sigma \circ (\lrb{\inl(m)}\otimes id)\\
	&= [f,g] \circ d \circ \sigma \circ (i_1 \otimes id) \circ (\lrb{m} \otimes id)\\
	&= [f,g] \circ d \circ (id \otimes i_1) \circ \sigma \circ (\lrb{m} \otimes id)\\
	&= f \circ \sigma \circ (\lrb{m} \otimes id)\\
	&= \lrb{\Gamma_1, \Gamma_2 \vdash (m/x) n : A}
      \end{align*}
    \item This case is analogous to the previous one.
    \item Let $\Gamma = \Gamma_1, \Delta_1, \Delta_2$ with
      $\Gamma_1 , x : S_1, x : S_2 \vdash N : T$, $\Delta_1 \vdash M_1 : S_1$ and $\Delta_2 \vdash M_2 : S_2$.
      \begin{align*}
	      &\lrb{\Gamma_1, \Delta_1, \Delta_2 \vdash \elimtens(M_1 \otimes M_2, \abstr{xy}N) : T}\\
	      &=\lrb{\Gamma_1 , x : S_1, x : S_2 \vdash N : T} \circ (id \otimes \lrb{M_1} \otimes \lrb{M_2})\\
	      & = \lrb{\Gamma \vdash (M_1/x, M_2/y)N : T}
	      \tag*{\qed}
      \end{align*}
  \end{enumerate}
\end{proof}

\soundnesscor*
\begin{proof}
  By induction on the reduction relation.
  First, notice that if $M \leftrightarrows N$, then $\lrb{M} = \lrb{N}$, by Lemma~\ref{lem:pm_eq}.
  Thus, we only need to show the theorem for the case $M\rightarrow N$ (see Figure~\ref{fig:red_rightarrow}).
  \begin{itemize}
    \item Rules~\eqref{rule:one}
      to~\eqref{rule:tensor}, are covered by
      Lemma~\ref{lem:subst_eq_p}
    \item Rules~\eqref{rule:commtop} to~\eqref{rule:comminr}
      are direct consequence of Lemma~\ref{lem:pm_eq}
\item Rule \eqref{rule:casting}:
	We have $\lrb{\cdot \vdash \tau(\mathcal B(\p{v \otimes w}))} = \tau \circ \lrb{\cdot \vdash \mathcal B(\p{v \otimes w})} =
		  \lrb{\cdot \vdash \mathcal B(\p v)} \otimes \lrb{\cdot \vdash \mathcal B(w)}
		  =\lrb{\cdot\vdash\mathcal B(\p v)\otimes\mathcal B(w)}$.
	  \item Rule \eqref{rule:commtau}:
		We have $\lrb{\Gamma \vdash \tau (\textstyle\sum_{i=1}^n p_i \sdot v_{bi})} = \tau \circ \textstyle\sum_{i=1}^n p_i \sdot \lrb{v_{bi}} = \textstyle\sum_{i=1}^n p_i \tau \circ \lrb{v_{bi}}
		=\lrb{\textstyle\sum_{i=1}^n p_i\sdot \tau (v_{bi})}$,
		because $\tau$ is a completely positive isomorphism.
    \item Rule~\eqref{rule:commB}:
      $\begin{aligned}[t]
	\lrb{\vdash \mathcal B(\p{a}\sdot \p{v_b}) : \mathcal B(\p P)}
	&= \mathcal B(\p a \sdot \lrb{\p{v_b}})\\
	&= \p a \sdot \lrb{\p{v_b}} \circ \_ \circ (\p a \sdot \lrb{\p{v_b}})^*\\
	&= \p a \sdot \lrb{\p{v_b}} \circ \_ \circ \p{a^*} \sdot \lrb{\p{v_b}}^*\\
	&= \p{aa^*} \sdot \lrb{\p{v_b}} \circ \_ \circ \lrb{\p{v_b}}^*\\
	&= |\p a|^2 \sdot \mathcal B(\p{v_b})\\
	&=\lrb{\vdash |\p a|^2 \sdot \mathcal B(\p{v_b}) : \mathcal B(\p P)}
      \end{aligned}$

    \item Rule~\eqref{rule:commBapp}:
      Since the rule $\mathcal B_i^m$ applies only to closed terms, the terms
      in this rule are necessarily closed.  Moreover, by
      Theorem~\ref{thm:prog}, the first values
      must be lambda terms.  To simplify the proof, we first consider the case
      $n = k = 1$ and $p_1 = q_1 = 1$, and then generalise the result.
      \begin{itemize}
	\item 
	  Let $f = \lrb{\p{\vdash \lambda \abstr{x}m : P \multimap Q}}$, and $g = \lrb{\p{\vdash v : P}}$.
	  We have,
	  \begin{align*}
	    \lrb{\vdash \mathcal B(\p{\lambda \abstr{x}m})~\mathcal B(\p v) : \mathcal B(\p Q)}
	    &= \mathcal B (eval_{\lrb{\p P}, \lrb{\p Q}}) \circ \tau\circ (\mathcal B(f) \otimes\mathcal B(g))\\
	    &= \mathcal B (eval_{\lrb{\p P}, \lrb{\p Q}} \circ (f \otimes g))\\
	    &= \mathcal B (\lrb{\p{\vdash (\lambda \abstr{x}m)~v : Q)}}
	  \end{align*}
	\item In the general case, we have $M=(\textstyle\sum_{i=1}^n p_i \sdot
	  \mathcal B(\p{m_i}))~(\textstyle\sum_{j=1}^k q_j \sdot \mathcal
	  B(\p{m'_j}))$ and $N= \textstyle\sum_{i,j} \mathcal B(\p{m_i~m'_j})$.
	  The equality of the denotations of these two terms follows from the
	  case above and Lemma~\ref{lem:pm_eq}.
      \end{itemize}
    \item The contextual rules are straightforward and we omit them.
      \qed
  \end{itemize}
\end{proof}

\adequacy*
\begin{proof} 
  Let $[.] \vdash E : T$, with $T \in \{\one, 1, \mathcal B(\one)\}$. Case analysis.
  \begin{itemize}
    \item Let $T = \one$ or $1$:
      By Theorem~\ref{thm:prog}, we have $E[M] \hookrightarrow^* \alpha\sdot \ast$ and $E[N] \hookrightarrow^* \beta\sdot \ast$. 
      Then, by Theorem~\ref{thm:soundnesshook}
      and Lemma~\ref{lem:subst_d},
      \[
	\lrb{\vdash\alpha\sdot\ast:1}
	= \lrb{\vdash E[M]:1}
	= \lrb{\vdash E[N]:1}
	= \lrb{\vdash\beta\sdot\ast:1}
      \]
      Thus, $\alpha = \beta$.

    \item  Let $T = \mathcal B(\one)$:
      By Theorem~\ref{thm:prog}, we have $E[M] \hookrightarrow^* p\sdot\mathcal B(\p\ast)$ and $E[N] \hookrightarrow^* q\sdot \mathcal B(\p\ast)$. 
      Then, by Theorem~\ref{thm:soundnesshook} and Lemma~\ref{lem:subst_d},
      \begin{align*}
	\lrb{\vdash p\sdot\mathcal B(\p\ast):\mathcal B(\one)}
	&= \lrb{\vdash E[M]:\mathcal B(\one)}\\
	&= \lrb{\vdash E[N]:\mathcal B(\one)}\\
	&= \lrb{\vdash q\sdot\mathcal B(\p\ast):\mathcal B(\one)}
      \end{align*}
      Thus, $p = q$.
  \end{itemize}
  Therefore, $M\sim N$.
  \qed
\end{proof}
