\subsection{Proof of lemma \ref{lem:Soundness pre}}\label{Proof of lem:Soundness pre}

\begin{proof}
Note that by rule $MV_\vee$, the maximums in the statement of the lemma exist and are unique when the algorithm terminates. The proof is by induction on the complexity of concept $C$. The base case (when $C$ is a primitive concept) is immediate by  construction of the model. For the induction step, we have four cases.

\noindent 1.~Suppose $C=C_1 \wedge C_2$. 

\noindent 1.1.~For the first claim, it is required to prove that
\begin{equation*}
\max \{ \alpha \mid \alpha\leq I(b, x_{C_1 \wedge C_2})\in\overline{\mathcal{A}}\}=\val{C_1 \wedge C_2}(b).
\end{equation*}
\iffalse
By the induction hypothesis, there is 
\begin{equation*}
    \val{C_1 \wedge C_2}(b)=\val{C_1}(b)\wedge\val{ C_2}(b)=\max\{ \alpha \mid \alpha \leq  I (b, x_{C_1}) \}\in  \overline{\mathcal{A}}\}\wedge\max\{ \beta \mid \beta \leq  I (b, x_{C_2})\}\in\overline{\mathcal{A}}.
\end{equation*}
\fi
\iffalse
{{\centering
 $ \val{C_1 \wedge C_2} (b) =  \max \{ \alpha \mid \alpha \leq  I (b, x_{C_1}) \}\in  \overline{\mathcal{A}}\}  \wedge  \max \{ \beta \mid \beta \leq  I (b, x_{C_2})\}\in  \overline{\mathcal{A}}\} 
 $.
 \par }}
 \fi

For direction $(\leq)$, suppose $\alpha_0 \leq b I x_{C_1 \wedge C_2} \in \overline{\mathcal{A}}$ for some $\alpha_0$. Then by using appending and $\wedge_A$ rules, we have $\alpha_0\leq I(b,x_{C_1})\in\overline{\mathcal{A}}$ and $\alpha_0 \leq I(b, x_{C_2})\in \overline{\mathcal{A}}$. Therefore, $\alpha_0\leq\max \{ \alpha \mid \alpha \leq  I (b, x_{C_1}) \}\in  \overline{\mathcal{A}}\}$, and $\alpha_0\leq\max \{ \alpha \mid \alpha \leq  I (b, x_{C_2}) \}\in  \overline{\mathcal{A}}\}$. Hence, by introduction hypothesis, we have $\alpha_0\leq\val{C_1}(b)$ and $\alpha_0\leq\val{C_2}(b)$, which implies $\alpha_0\leq\val{C_1}(b)\wedge\val{C_2}(b)=\val{C_1 \wedge C_2}(b)$. Therefore, we have $\max\{\alpha\mid\alpha\leq I(b, x_{C_1 \wedge C_2})\in\overline{\mathcal{A}}\}\leq\val{C_1 \wedge C_2}(b)$.
%Hence, $\max \{ \alpha \mid \alpha \leq  I (b, x_{C_1 \wedge C_2})\in  \overline{\mathcal{A}}\} \leq \val{C_1 \wedge C_2} (b)$. 

For direction $(\geq)$, suppose $\alpha_0 \leq \val{C_1 \wedge C_2}(b)=\val{C_1}(b)\wedge\val{C_2}(b)$. Therefore, we have $\alpha_0 \leq \val{C_1} (b)$, and $\alpha_0 \leq \val{C_2} (b)$. Hence, by induction hypothesis, there are $\alpha_1, \alpha_2 \in \mathbf{H}$, such that $\alpha_0\leq\alpha_1$, $\alpha_0 \leq \alpha_2$, $\alpha_1 \leq I(b, x_{C_1})$, and $\alpha_2 \leq I(b, x_{C_2}) \in \overline{\mathcal{A}}$. As $C_1 \wedge C_2$ occurs in $\overline{\mathcal{A}}$, by appending and $\wedge_A^{-1}$ rules, we get  $\alpha_1 \wedge \alpha_2 \leq b :C_1 \wedge C_2\in\overline{\mathcal{A}}$. By creation and the basic rules, this implies $\alpha_1 \wedge \alpha_2  \leq b I x_{C_1 \wedge C_2} \in \overline{\mathcal{A}}$. Therefore, we have $\alpha_0 \leq \max \{ \alpha \mid \alpha \leq I (b, x_{C_1 \wedge C_2})\in  \overline{\mathcal{A}}\}$. Hence,  by completeness of $\mathbf{H}$, we have $ \val{C_1 \wedge C_2} (b) \leq \max \{ \alpha \mid \alpha \leq I (b, x_{C_1 \wedge C_2})\in\overline{\mathcal{A}}\}$.



\noindent 1.2.~For the second claim, it is required to prove that
\begin{equation*}
    \descr{C_1 \wedge C_2}(y)=\max \{ \beta \mid \beta \leq  I (a_{C_1 \wedge C_2}, y)\in  \overline{\mathcal{A}}\}.
\end{equation*}

For direction $(\leq)$, notice that $\descr{C_1 \wedge C_2}(y)=\wedge_{b \in A} (\val{C_1\wedge C_2}(b)\rightarrow I(b,y))$. By the proof of the first claim above and the construction of the model, we have $ \descr{C_1 \wedge C_2}(y) =  \wedge_{b \in A} (  \max \{ \alpha \mid \alpha \leq  I (b, x_{C_1 \wedge C_2})\in  \overline{\mathcal{A}}\} \rightarrow \max \{ \beta \mid \beta \leq  I (b, y)\in  \overline{\mathcal{A}}\})$. Suppose $\alpha_0 \leq \descr{C_1 \wedge C_2}(y)$. Therefore, we have $\alpha_0 \leq \max \{ \alpha \mid \alpha \leq  I (b, x_{C_1 \wedge C_2})\in  \overline{\mathcal{A}}\} \rightarrow \max \{ \beta \mid \beta \leq I(b,y)\in\overline{\mathcal{A}}\}$ for every $b\in A$. By the creation rule, we have $1 \leq I(a_{C_1 \wedge C_2}, x_{C_1 \wedge C_2}) \in  \overline{\mathcal{A}}$, which means that $\max\{ \alpha \mid \alpha \leq  I (b, x_{C_1\wedge C_2})\in\overline{\mathcal{A}}\}=1$. Therefore, we get $\alpha_0 \leq  \max \{ \beta \mid \beta \leq  I (a_{C_1 \wedge C_2}, y) \in  \overline{\mathcal{A}}\}$. Hence,
by completeness of  $\mathbf{H}$,
we have $\descr{C_1 \wedge C_2}(y) \leq \max \{ \beta \mid \beta \leq I(a_{C_1 \wedge C_2}, y)\in  \overline{\mathcal{A}}\}$. 

For direction $(\geq)$, suppose $\alpha_0 \leq I (a_{C_1 \wedge C_2}, y)$. By construction of the model, there exists $\alpha_1 \in \mathbf{H}$, such that $\alpha_0 \leq \alpha_1$ and $\alpha_1 \leq I (a_{C_1 \wedge C_2}, y) \in  \overline{\mathcal{A}}$. Suppose $\alpha_2 \leq  I (b, x_{C_1 \wedge C_2}) \in \overline{\mathcal{A}}$ for some $b \in A$, and $\alpha_2 \in \mathbf{H}$, by appending and basic rules, we get $\alpha_1 \wedge \alpha_2 \leq I(b,y) \in  \overline{\mathcal{A}}$. Hence, we have $\alpha_1 \wedge\alpha_2\leq\max\{ \alpha \mid \alpha \leq  I (b, y )\in\overline{\mathcal{A}}\}$ for any $\alpha_2 \leq  I (b, x_{C_1 \wedge C_2})\in\overline{\mathcal{A}}$. Therefore, by properties of $\mathbf{H}$, we have $\alpha_0 \leq \alpha_1 \leq \alpha_2 \rightarrow \alpha_1 \wedge \alpha_2 \leq \max \{ \alpha \mid \alpha \leq  I (b, x_{C_1 \wedge C_2})\in  \overline{\mathcal{A}}\} \rightarrow \max \{ \beta \mid \beta \leq  I (b, y)\in  \overline{\mathcal{A}}\}$. Hence, by completeness of $\mathbf{H}$, we have $ I (a_{C_1 \wedge C_2}, y) \leq \max \{ \alpha \mid \alpha \leq  I (b, x_{C_1 \wedge C_2})\in  \overline{\mathcal{A}}\} \rightarrow \max \{ \beta \mid \beta \leq  I (b, y)\in\overline{\mathcal{A}}\}$ for any $b\in A$. Therefore, we have $\max\{\beta \mid\beta\leq I (a_{C_1 \wedge C_2}, y)\}\leq\wedge_{b \in A} (\val{C_1\wedge C_2}(b)\rightarrow I(b,y))=\descr{C_1 \wedge C_2}(y)$.
%By properties of $\mathbf{H}$, we have $\alpha_0 \leq \alpha_1 \leq \alpha_2  \rightarrow \alpha_1 \wedge \alpha_2 $.  Therefore, for any  $\alpha_2 \leq  I (b, x_{C_1 \wedge C_2}) \in \overline{\mathcal{A}}\in  \overline{\mathcal{A}}$,  we have $\alpha_1 \wedge \alpha_2 \leq I(b,y) \in  \overline{\mathcal{A}}$ which ensures Therefore, we have for any $b \in A$, $\alpha_2  \rightarrow \alpha_1 \wedge \alpha_2 \leq\rightarrow \max \{ \beta \mid \beta \leq  I (b, y)\})$. Therefore, we get $\alpha_0 \leq \descr{C_1 \wedge C_2}(y)$. Hence, $\max \{ \beta \mid \beta \leq  I (a_{C_1 \wedge C_2}, y)\} \leq \descr{C_1 \wedge C_2}(y) $. 

\noindent 2.~The proof for  $C=C_1 \vee C_2$  is similar to the previous one.

\noindent 3.~Suppose $C=[R_\Box] C_1$.

\noindent 3.1.~For the first claim, it is required to prove that 
\begin{equation*}
\val{[R_\Box] C_1}(b)=\max\{ \beta  \mid \beta  \leq I (b, x_{\Box C_1})\in \overline{\mathcal{A}} \}.
\end{equation*}


For direction $(\leq)$, notice that $\val{[R_\Box] C_1}(b)= \bigwedge_{y \in X} (\descr{C_1}(y) \rightarrow R_\Box (b,y))$. By induction and construction of the model, this is equivalent to $\val{[R_\Box] C_1}(b)= \bigwedge_{y \in X} (\max \{ \alpha \mid \alpha \leq  I (a_{C_1},y) \}  \rightarrow \max \{ \beta  \mid \beta  \leq R_\Box (b, y) \in \overline{\mathcal{A}} \})$. Suppose $\alpha_0 \leq \val{[R_\Box] C_1}(b)$. By creation and basic rules, we have $1 \leq I (a_{C_1},x_{C_1}) \in \overline{\mathcal{A}}$. By induction hypothesis claim above, we get $\alpha_0 \leq \max \{ \beta  \mid \beta  \leq  R_\Box (b, x_{C_1}) \in \overline{\mathcal{A}} \}$. By  rule $R_\Box$, this implies $\alpha_0 \leq \max \{ \beta  \mid \beta  \leq  I (b, \Box x_{C_1})=I(b, x_{\Box C_1})\in \overline{\mathcal{A}} \}$.  Therefore, $\val{[R_\Box] C_1}(b) \leq \max \{ \beta\mid \beta\leq I(b, x_{\Box C_1})\in\overline{\mathcal{A}}\}$.  

For direction $(\geq)$, suppose $\alpha_0  \leq I(b, x_{\Box C_1})$. By construction of the model, we have $\alpha_1\leq I(b, x_{\Box C_1})\in\overline{\mathcal{A}}$ for some $\alpha_0\leq\alpha_1\in \mathbf{H}$. Suppose $\alpha_2 \leq  I (a_{C_1},y) \in \overline{\mathcal{A}}$ for some $y$. Then by appending and $\Box$ rules, we get $\alpha_1 \wedge \alpha_2  \leq R_\Box (b, y)$. By properties of $\mathbf{H}$, we have $\alpha_0  \leq   \alpha_1 \leq \alpha_2 \rightarrow \alpha_1 \wedge \alpha_2$. Hence we get $\alpha_0 \leq \max \{ \alpha \mid \alpha \leq  I (a_{C_1},y) \}  \rightarrow \max \{ \beta  \mid \beta  \leq  R_\Box (b, y) \in \overline{\mathcal{A}} \}$ for any $y$. Therefore, $\max \{ \beta  \mid \beta  \leq   I (b, x_{\Box C_1})\in \overline{\mathcal{A}} \} \leq \val{[R_\Box] C_1}(b)$.

\noindent 3.2.~For the second claim, it is required to prove that 
\begin{equation*}
\descr{[R_\Box C_1]}(y)=\max\{ \beta \mid \beta \leq  I (a_{\Box C_1}, y)\in\overline{\mathcal{A}}\}.
\end{equation*}

For direction $(\leq)$, notice that $\descr{[R_\Box] C_1 }(y)=\wedge_{b \in A}(\val{[R_\Box] C_1}(b)\rightarrow I(b,y))$. By the proof of the first claim and construction of the model, we have 
$ \descr{[R_\Box C_1]}(y) =  \wedge_{b \in A} (  \max \{ \alpha \mid \alpha \leq  I (b, x_{\Box C_1})\} \rightarrow \max \{ \beta \mid \beta \leq  I (b, y)\})$. Suppose $\alpha_0 \leq \descr{[R_\Box] C_1}(y)$. Then for every $b$, $\alpha_0 \leq \max \{ \alpha \mid \alpha \leq  I (b, x_{\Box C_1})\} \rightarrow \max \{ \beta \mid \beta \leq  I (b, y)\}$. By applying this to $1 \leq I(a_{\Box C_1}, x_{\Box C_1}) \in  \overline{\mathcal{A}}$ added by creation rule, we get $\alpha_0 \leq  \max \{ \beta \mid \beta \leq  I (a_{\Box C_1}, y)\}$. Therefore, $ \descr{[R_\Box C_1]}(y) \leq \max \{ \beta \mid \beta \leq  I (a_{\Box C_1}, y)\in\overline{\mathcal{A}}\}$. 


For direction $(\geq)$, suppose $\alpha_0 \leq I (a_{\Box C_1 }, y)$. By construction of the model, there exists $\alpha_1 \in \mathbf{H}$ such that $\alpha_0 \leq \alpha_1$ and $\alpha_1 \leq I (a_{\Box C_1}, y) \in  \overline{\mathcal{A}}$.  Suppose $\alpha_2 \leq  I (b, x_{\Box C_1}) \in \overline{\mathcal{A}}$ for some $b \in A$, $\alpha_2 \in \mathbf{H}$. Then, by appending and basic rule, we get $\alpha_1 \wedge \alpha_2 \leq I(b,y) \in  \overline{\mathcal{A}}$. Therefore, for   for any $\alpha_2 \leq  I (b, x_{\Box C_1 }) \in \overline{\mathcal{A}}$, we have 
$\alpha_1 \wedge \alpha_2 \leq  \max \{ \alpha \mid \alpha \leq  I (b, y )\} \in  \overline{\mathcal{A}} $.  Hence, we have $\alpha_0 \leq \alpha_1 \leq \alpha_2 \rightarrow \alpha_1 \wedge \alpha_2 \leq \max \{ \alpha \mid \alpha \leq  I (b, x_{\Box C_1})\in  \overline{\mathcal{A}}\} \rightarrow \max \{ \beta \mid \beta \leq  I (b, y)\in  \overline{\mathcal{A}}\}$. Therefore, by the completeness of $\mathbf{H}$, we have $ I (a_{\Box C_1}, y) \leq \max \{\alpha \mid \alpha \leq  I (b, x_{\Box C_1})\in\overline{\mathcal{A}}\} \rightarrow \max \{ \beta \mid \beta \leq  I (b, y)\in  \overline{\mathcal{A}}\}$. Therefore, we have $\max\{ \beta \mid \beta \leq  I (a_{\Box C_1}, y)\in\overline{\mathcal{A}}\}\leq\descr{[R_\Box C_1]}(y)$.


\noindent 4. The proof for  $C=\langle R_\Diamond \rangle C_1$  is similar to the previous one. 

This concludes the proof.
\end{proof}




