\tilde{\mathbf{Y}}_i &= \mathbf{W}_r^T * \mathbf{Z}_i + \mathbf{W}_i^T * \mathbf{Z}_r + \mathbf{b}_i,
\end{aligned}
\label{eq:complex_transconv}
\end{equation}
which is then normalized by complex batch normalization (BN) and activated by a complex ReLU:
\begin{equation}
\tilde{\mathbf{Z}} = \text{Complex ReLU}\Big( \text{Complex BN}\big(\tilde{\mathbf{Y}}_r + j\,\tilde{\mathbf{Y}}_i\big) \Big)
\label{eq:decoder_activation}
\end{equation}

