\subsection{Complex conformer in the bottleneck layer}
\label{subsec:conformer_symbolic}
\vspace{-0.3em}


We use complex-valued conformers in the bottleneck layer of our CTFT-Net to capture both local and global dependencies \textit{among consecutive spectrograms}. Our complex conformer comprises complex multi-head self-attention, complex feed-forward, and complex convolutional modules, inspired by \cite{gulati2020conformer}. The complex conformer optimally balances global context with fine-grained local information for BWE. %The output of the last (eighth) encoder block is fed as input to the conformer block to effectively model the long-term dependencies of the complex compact bottleneck layer's representation. 

\begin{comment}
The input to the conformer block is
\begin{align}
\mathbf{X} \in \mathbb{R}^{B \times C \times F \times T},
\end{align}
where \(B\) denotes the batch size, \(C\) the number of channels, \(F\) the spectral dimension, and \(T\) the temporal dimension. First, we rearrange \(\mathbf{X}\) so that the conformer processes each channel independently. After multiplying the batch size and temporal dimension, we define
\begin{align}
S = B \cdot T,
\end{align}
and perform the following permutation and reshaping:
\begin{align}
\mathbf{x} = \operatorname{reshape}\Bigl(\operatorname{permute}(\mathbf{X}, [\,2,\,1,\,4,\,3\,])\Bigr) \in \mathbb{R}^{C \times S \times F}.
\end{align}
Thus, for each channel \(c \in \{1,\dots,C\}\), the conformer operates on
\begin{align}
\mathbf{x}_c \in \mathbb{R}^{S \times F}.
\end{align}

For a given channel, the Conformer encoder layer consists of Feed-Forward (FF), Multi-Head Self-Attention (MHA), and a Convolution Module.

\subsubsection{First Feed-Forward Network (FFN) Module:} The feed-forward network is defined as
\begin{align}
F_{\mathrm{FFN}}(\mathbf{x}) = W_2\, \operatorname{ReLU}(W_1 \mathbf{x}),
\end{align}
with learnable weights \(W_1 \in \mathbb{R}^{F \times d_{\mathrm{ff}}}\) and \(W_2 \in \mathbb{R}^{d_{\mathrm{ff}} \times F}\). A residual connection with layer normalization (denoted by \(\operatorname{LN}\)) is applied:
\begin{align}
\mathbf{z}_1 = \operatorname{LN}\Bigl(\mathbf{x} + F_{\mathrm{FFN}}(\mathbf{x})\Bigr) \in \mathbb{R}^{S \times F}.
\end{align}

\subsubsection{Multi-Head Self-Attention (MHA) Module:} The output \(\mathbf{z}_1\) is provided as input to the MHA module. The Query, Key, and Value projections are calculated as
\begin{align}
\mathbf{Q} = \mathbf{z}_1 W^Q,\quad \mathbf{K} = \mathbf{z}_1 W^K,\quad \mathbf{V} = \mathbf{z}_1 W^V,
\end{align}
with projection matrices \(W^Q, W^K, W^V \in \mathbb{R}^{F \times d_k}\). The self-attention is computed by
\begin{align}
\operatorname{Attention}(\mathbf{Q},\mathbf{K},\mathbf{V}) = \operatorname{softmax}\Bigl(\frac{\mathbf{Q}\mathbf{K}^\top}{\sqrt{d_k}}\Bigr)\mathbf{V}.
\end{align}
Then, applying dropout and a residual connection with layer normalization:
\begin{align}
\mathbf{z}_2 = \operatorname{LN}\Bigl(\mathbf{z}_1 + \operatorname{Dropout}\bigl(\operatorname{Attention}(\mathbf{Q},\mathbf{K},\mathbf{V})\bigr)\Bigr) \in \mathbb{R}^{S \times F}.
\end{align}

\subsubsection{Convolution Module:} To capture local context in the complex bottleneck feature, we process \(\mathbf{z}_2\) with two sequential convolutional layers. First, we reshape \(\mathbf{z}_2\) to align the feature and sequence dimensions:
\begin{align}
\tilde{\mathbf{z}}_2 = \operatorname{permute}(\mathbf{z}_2) \in \mathbb{R}^{F \times S}.
\end{align}
Then we apply the first convolution \(C_1\) with a ReLU activation:
\begin{align}
\mathbf{y}_1 = \operatorname{ReLU}\Bigl(C_1(\tilde{\mathbf{z}}_2)\Bigr) \in \mathbb{R}^{F \times S}.
\end{align}
Next, we apply a second convolution \(C_2\) with ReLU:
\begin{align}
\mathbf{y}_2 = \operatorname{ReLU}\Bigl(C_2(\mathbf{y}_1)\Bigr) \in \mathbb{R}^{F \times S},
\end{align}
and then invert the permutation:
\begin{align}
\mathbf{y}_2' = \operatorname{permute}^{-1}(\mathbf{y}_2) \in \mathbb{R}^{S \times F}.
\end{align}
Finally, a residual connection with layer normalization is applied:
\begin{align}
\mathbf{z}_3 = \operatorname{LN}\Bigl(\mathbf{z}_2 + \mathbf{y}_2'\Bigr) \in \mathbb{R}^{S \times F}.
\end{align}

\subsubsection{Second Feed-Forward Network (FFN) Module:} Finally, we apply a second FFN block:
\begin{align}
\mathbf{z}_4 = \operatorname{LN}\Bigl(\mathbf{z}_3 + \operatorname{Dropout}\bigl(F_{\mathrm{FFN}}(\mathbf{z}_3)\bigr)\Bigr) \in \mathbb{R}^{S \times F}.
\end{align}

\subsubsection{Reshaping to the Original Dimensions:} For each channel, the output of the conformer is \(\mathbf{z}_4 \in \mathbb{R}^{S \times F}\). Reassembling across all channels and inverting the initial permutation yields the final output
\begin{align}
\mathbf{X}' \in \mathbb{R}^{B \times C \times F \times T},
\end{align}
with \(S = B \cdot T\).

\subsubsection{Overall Transformation.} 


For each channel, the conformer encoder layer performs:

\begin{align}
\mathbf{B}_1 &= \operatorname{LN}\Bigl(\mathbf{x} + F_{\mathrm{FFN}}(\mathbf{Z}_8)\Bigr),\\[1mm]
\mathbf{B}_2 &= \operatorname{LN}\Bigl(\mathbf{B}_1 + \operatorname{Dropout}\bigl(\operatorname{Attention}(\mathbf{Q},\mathbf{K},\mathbf{V})\bigr)\Bigr),\\[1mm]
\mathbf{B}_3 &= \operatorname{LN}\Bigl(\mathbf{B}_2 + \operatorname{ReLU}\Bigl(C_{1D}\Bigl(\operatorname{ReLU}\bigl(C_{1D}(\mathbf{B}_2)\bigr)\Bigr)\Bigr)\Bigr),\\[1mm]
\mathbf{B}_4 &= \operatorname{LN}\Bigl(\mathbf{B}_3 + \operatorname{Dropout}\bigl(F_{\mathrm{FFN}}(\mathbf{B}_3)\bigr)\Bigr).
\end{align}


\end{comment}


\begin{comment}
After processing all channels, the data is reassembled to reconstruct the tensor in \(\mathbb{R}^{B \times C \times F \times T}\).

For the real and imaginary parts of the complex bottleneck feature, we apply the conformer independently. Then the real and imaginary features are combined using the following formulas:

\begin{align}
\text{real}_{\mathrm{out}} &= \mathrm{Conformer}\bigl(x_{\mathrm{real}}\bigr) - \mathrm{Conformer}\bigl(x_{\mathrm{imag}}\bigr),\\[1mm]
\text{imag}_{\mathrm{out}} &= \mathrm{Conformer}\bigl(x_{\mathrm{imag}}\bigr) + \mathrm{Conformer}\bigl(x_{\mathrm{real}}\bigr).
\end{align}

After reassembling, the final complex output is given by
\begin{align}
\mathbf{X}'_{\text{complex}} = \operatorname{ComplexTensor}\Bigl(\text{real}_{\mathrm{out}},\, \text{imag}_{\mathrm{out}}\Bigr).
\end{align}

