\subsection{Comprehensive evaluation metrics}
\label{subsec:Evaluation_Metrics}
\vspace{-0.3em}

To comprehensively evaluate the reconstructed audio, we use four evaluation metrics: log spectral distance (LSD) \cite{liu2022neural} for spectral distortion, short-time objective intelligibility (STOI) \cite{taal2011algorithm} for intelligibility, perceptual evaluation of speech quality (PESQ) \cite{rix2001perceptual} for perceived quality, and scale-invariant signal-to-distortion ratio (SI-SDR) \cite{le2019sdr} for overall signal distortion.

%\begin{align}
%\footnotesize
%\mathrm{LSD} = \frac{1}{N}\sqrt{\frac{1}{2\pi} \sum_{k=1}^{K} \Bigl( %\log_{10}\Bigl|X(k)\Bigr|^2 - \log_{10}\Bigl|Y(k)\Bigr|^2 \Bigr)^2},
%\end{align}



\begin{comment}
\textbf{Log Spectral Distance (LSD)} measures the difference between the log-magnitude spectra of the target and generated enhanced speech signals. It is defined as
\begin{align}
\mathrm{LSD} = \frac{1}{N}\sqrt{\frac{1}{2\pi} \sum_{k=1}^{K} \Bigl( \log_{10}\Bigl|X(k)\Bigr|^2 - \log_{10}\Bigl|Y(k)\Bigr|^2 \Bigr)^2},
\end{align}
where \(X(k)\) and \(Y(k)\) denote the spectral magnitudes of the target and generated signals, respectively, and \(K\) is the number of frequency bins.

\textbf{Short-Time Objective Intelligibility (STOI)} quantitatively measures the intelligibility of generated speech by comparing short-time temporal envelopes between the target and generated signals. A simplified representation is given by
\begin{align}
\mathrm{STOI} = \frac{1}{M} \sum_{m=1}^{M} \frac{\sum_{n=1}^{N} \Bigl( x_{n,m} - \bar{x}_m \Bigr) \Bigl( y_{n,m} - \bar{y}_m \Bigr)}{\sqrt{\sum_{n=1}^{N} \Bigl( x_{n,m} - \bar{x}_m \Bigr)^2}\,\sqrt{\sum_{n=1}^{N} \Bigl( y_{n,m} - \bar{y}_m \Bigr)^2}},
\end{align}
where \(x_{n,m}\) and \(y_{n,m}\) represent the short-time segments of the target and generated signals for the \(m\)-th segment (of length \(N\)), and \(\bar{x}_m\) and \(\bar{y}_m\) are their respective means. The final STOI score ranges from 0 (poor intelligibility) to 1 (perfect intelligibility).

\textbf{Perceptual Evaluation of Speech Quality (PESQ)} predicts the perceived quality of speech as judged by human listeners. Although the full PESQ algorithm (defined in ITU-T P.862) is complex, a high-level formulation is
\begin{align}
\mathrm{PESQ} = f\Bigl( D_{\text{raw}} \Bigr),
\end{align}
where \(D_{\text{raw}}\) is a raw distortion measure computed from a perceptually motivated model and \(f(\cdot)\) maps this measure to a Mean Opinion Score (MOS) scale, typically ranging from 1 (poor quality) to 4.5 (excellent quality).

\textbf{Scale-Invariant Signal-to-Distortion Ratio (SI-SDR)} evaluates the quality of the estimated signal relative to a reference while being invariant to scaling. The SI-SDR is given by
\begin{align}
\mathrm{SI\text{-}SDR}(s,\hat{s}) = 10 \log_{10} \frac{\left\lVert\beta s\right\rVert^2}{\left\lVert\hat{s} - \beta s\right\rVert^2},
\end{align}
where \(s,\hat{s} \in \mathbb{R}^T\) (with \(T\) samples),
\begin{align}
\langle \hat{s}, s \rangle = \hat{s}^\top s,\quad \text{and} \quad \lVert s \rVert^2 = \langle s, s \rangle.
\end{align}
We then compute
\begin{align}
\beta = \frac{\langle \hat{s}, s \rangle}{\lVert s \rVert^2}.
\end{align}
Here, \(\mathbf{s}\) is the target signal, \(\hat{\mathbf{s}}\) is the generated signal, and \(\langle \cdot, \cdot \rangle\) denotes the inner product.
\end{comment}


