\smallskip  
\noindent\textbf{Lemma Definition:}  

\texttt{lemma ParseDigitsAndDot(s1: string, s2: string)}  

\texttt{\quad \textbf{requires} $\forall$ i | 0 $\leq$ i $<$ |s1| :: '0' $\leq$ s1[i] $\leq$ '9'}  

\texttt{\quad \textbf{ensures} ParseDecStr(s1+"."+s2).value.1 == "."+s2}  

\texttt{\quad \{}  

\texttt{\quad \quad if |s1| == 1 \{}  

\texttt{\quad \quad \quad \textbf{assert} ParseDecStr("."+s2).None?;}  

\texttt{\quad \quad \} else \{}  

\texttt{\quad \quad \quad ParseDigitsAndDot(s1[1..],s2);}  

\texttt{\quad \quad \quad \textbf{assert} s1 + "." + s2 == [s1[0]] + (s1[1..] + "." + s2);}  

\texttt{\quad \quad \}}  

