\section{Solving the $p$-Riccati equation}\label{section_resolution}
    The goal of this section is to present an algorithm to solve the
    $p$-Riccati equation relative to an irreducible polynomial $N\in C[Y]$
    over $K_N$. We discuss its complexity and its applications to the
    factorisation of differential operators in $K\langle\partial\rangle$.
    This algorithm makes use of algebraic
    geometry tools such as Riemann-Roch spaces and the Picard group of $K_N$.\\
    We recall that van der Put and Singer presented,
    in~\cite[§13.2.1]{PuSi03}, a method to compute
    solutions of $p$-Riccati equations over $\Fbb_q(x)$. Their method will serve as a guideline
    for the techniques we develop in the general case.\\
    We keep the notations of the previous section. In addition, we suppose
    that $N\in C[Y]$ is a fixed irreducible polynomial and use the
    notations introduced in Notation~\ref{notation_K_N}. In particular,
    we recall that $S_N$ denotes the set of solutions of the $p$-Riccati
    equation $f^{(p-1)}+f^p=y_N$.
  \begin{Proposition}\label{borne_val}
    Let $\Pfrak$ be a place of $K_N$, $t_{\Pfrak}$ be a prime element of
    $\Pfrak$. Then, for all $f\in S_N$, we have
    $\nu_\Pfrak(f)\geq\min(p^{-1}\nu_{\Pfrak}(y_N),\nu_\Pfrak(t'_\Pfrak)-1)$.
  \end{Proposition}
  \begin{proof}
    We have
    \begin{align*}
      \nu_{\Pfrak}(y_N)&=\nu_{\Pfrak}(f^{(p-1)}+f^p)\\
      &\geq\min(\nu_{\Pfrak}(f^{(p-1)},p\nu_{\Pfrak}(f)).
    \end{align*}
    Furthermore equality holds if
    $\nu_{\Pfrak}(f^{(p-1)})\neq p\nu_{\Pfrak}(f)$.
    Since $\nu_\Pfrak(f^{(p-1)})\geq
    \nu_\Pfrak(f)+(p-1)(\nu_\Pfrak(t_\Pfrak')-1)$ if
    $\nu_{\Pfrak}(f)<\nu_{\Pfrak}(t_\Pfrak')-1$, we find in particular that
    $p\nu_{\Pfrak}(f)<\nu_{\Pfrak}(f)+(p-1)(\nu_{\Pfrak}(t_\Pfrak')-1)\leq
    \nu_{\Pfrak}(f^{(p-1)})$ so $\nu_{\Pfrak}(y_N)=p\nu_{\Pfrak}(f)$.
  \end{proof}
  In fact we can show that if solutions exists, some of them verify a
  slightly better bound.
  \begin{Definition-Proposition}\label{residue_manip}
    Let $f\in S_N$ and $\Pfrak$ be a
    place of $K_N$ verifying
    $\nu_{\Pfrak}(y_N)\geq p\nu_\Pfrak(t_\Pfrak')$. Then
    there exists $k\in\Fbb_p$ such that for all $g\in K_N$, if
    $\nu_{\Pfrak}(g)\equiv k\pmod p$ then $f-\frac{g'}{g}\in S_N$ and
    $\nu_{\Pfrak}\left(f-\frac{g'}{g}\right)\geq \nu_\Pfrak(t_\Pfrak')$.
    We call $k$ the ramified residue of $f$ in $\Pfrak$ and write 
    \[\mathfrak{Re}_{\Pfrak}(f):=k.\]
  \end{Definition-Proposition}
  \begin{proof}
   % Set $e:=e(\Pfrak'|\Pfrak)$.
   % We first consider the easy case when $\Pfrak=\Pfrak_\infty$. Then for any
   % $g\in K_N$, $f-\frac{g'}{g}\in S_N$, thus
   % $\nu_{\Pfrak'}\left(f-\frac{g'}{g}\right)\geq 1-e$.\\

   % We now suppose that $\Pfrak\neq\Pfrak_\infty$.\\
    If $\nu_{\Pfrak}(f)\geq \nu_\Pfrak(t_\Pfrak')$ then we can take $k=0$. Indeed in this case,
    if $\nu_{\Pfrak}(g)\equiv 0\pmod p$ then there exists $l\in\Nbb$ such
    that $g=t_{\Pfrak}^{pl}u$ with $\nu_{\Pfrak}(u)=0$. Then 
    $\frac{g'}{g}=\frac{u'}{u}+pl\frac{t'_{\Pfrak}}{t_{\Pfrak}}=\frac{u'}{u}$.
    Since $\nu_\Pfrak(u)=0$, we can write
    $u=\sum_{n=0}^{\infty}u_nt_\Pfrak^n$ and
    $u'=t_\Pfrak'\sum_{k=0}^{\infty}(n+1)u_{n+1}t_\Pfrak^n$. Thus
    $\nu_\Pfrak(u')\geq \nu_\Pfrak(t_\Pfrak')$ and
    $\nu_{\Pfrak}\left(\frac{g'}{g}\right)\geq \nu_\Pfrak(t_\Pfrak')$ which yields the
    result.\\
    Suppose now that $\nu_{\Pfrak}(f)=\nu_\Pfrak(t_\Pfrak')-1$. We set
    $e=1-\nu_\Pfrak(t_\Pfrak')$, $a:=(t_\Pfrak^{e-1}t_\Pfrak')(\Pfrak)$ and 
    $c:=(t_\Pfrak^ef)(\Pfrak)$. Let us show
    that $c\in\Fbb_p^\times a$. The characteristic $p$ does not divide $e$,
    and we know that $\nu_\Pfrak(f^{(p-1)})=-pe$. Furthermore we know 
    (Lemma~\ref{p-1_power_derivation}) that
    $f^{(p-1)}:=\frac{\ud^{p-1}}{\ud t_\Pfrak^{p-1}}(t_\Pfrak^{p-1}f)$.
    It follows that
    $(t_\Pfrak^{pe}f^{(p-1)})(\Pfrak)=-a^{p-1}c$ 
    and 
    $(t_\Pfrak^{pe}f^p)(\Pfrak)=c^p$.
    But 
    $t_\Pfrak^{pe}(f^{(p-1)}+f^p)(\Pfrak)=(t_{\Pfrak}^{pe}y_N)(\Pfrak)=0$
    since $\nu_\Pfrak(y_N)>-pe$.
    It follows that
    $t_\Pfrak^{pe}(f^{(p-1)}+f^p)(\Pfrak)=c^p-a^{p-1}k=0$. Thus $c^{p-1}=a^{p-1}$ and $c\in\Fbb_p^{\times}a$. We set $k:=c\cdot
    a^{-1}$.

    Let $g\in K_N$ be such that $\nu_\Pfrak(g)\equiv k\pmod p$.
    There exists $l\in\Zbb$ and $u\in K_N$ such that $\nu_\Pfrak(u)=0$ and
    $g=t_\Pfrak^{pl+k}u$. Then
    $\frac{g'}{g}=k\frac{t_\Pfrak}{t_\Pfrak}+\frac{u'}{u}$.
    Since $\nu_\Pfrak(u)=0$, $\nu_\Pfrak(u')> -e$ and
    $\nu_\Pfrak\left(\frac{g'}{g}\right)=-e$. Then
    $\left(t_\Pfrak^{e}\frac{g'}{g}\right)(\Pfrak)=k(t_\Pfrak^{e-1}t_\Pfrak)(\Pfrak)=ka=c$.
    Thus
    $\left(t_\Pfrak^e\left(f-\frac{g'}{g}\right)\right)(\Pfrak)=0$,
    which is to say that
    $\nu_\Pfrak\left(f-\frac{g'}{g}\right)\geq 1-e=\nu_\Pfrak(t_\Pfrak')$.
  \end{proof}
   In particular if $\Pfrak$ is neither ramified nor a
  pole of $y_N$ then $S_N$ contains an element with no pole in $\Pfrak$.
  This local improvement on the bound provided in
  Proposition~\ref{borne_val} is accomplished by adding an element of the form
  $\frac{g'}{g}$. Unfortunately adding such an element makes new poles
  appear in general so this local approach is not enough.
  We globalize it in the following theorem.
  \begin{Theoreme}\label{theo_local_sol}
    Let $f\in S_N$ and $S:=\{\Pfrak\in \Pbb_{K_N}|\nu_{\Pfrak}(y_N)<
    p\nu_\Pfrak(t_\Pfrak')\}$. Set
    \[\mathfrak{Re}(f):=\sum_{\substack{\Pfrak\in\Pbb_{K_N}\\\Pfrak\notin
    S}}\mathfrak{Re}_{\Pfrak}(f)\cdot\Pfrak.\]
    If there exist $D',D_p\in\mathrm{Div}(F)$ such that 
    $\mathfrak{Re}(f)\sim D'+pD_P$
    then $S_N$ contains an element $\varphi$ verifying for all places $\Pfrak$ outside $S\cup
    \mathrm{supp}(D')$ that 
    $\nu_{\Pfrak}(\varphi)\geq \nu_\Pfrak(t_\Pfrak')$.
  \end{Theoreme}
  \begin{proof}
    Since $\mathfrak{Re}(f)\sim D'+pD_p$, there exists $g\in K_N$ such that $\mathfrak{Re}(f)-D'-pD_p=(g)$.
    From Lemma~\ref{affine_S_N}, we deduce that $f-\frac{g'}{g}\in S_N$.
    Let $\Pfrak\in\Pbb_{K_N}\backslash(S\cup \mathrm{supp}(D'))$.
    Then we find
        \begin{align*}
          \nu_{\Pfrak}(g)&=\nu_{\Pfrak}(\mathfrak{Re}(f))-\nu_{\Pfrak}(D')-p\nu_{\Pfrak}(D_p)\\
          &=\nu_{\Pfrak}(\mathfrak{Re}(f))-0-p\nu_{\Pfrak}(D_p)\\
          &\equiv \nu_\Pfrak(\mathfrak{Re}(f))\pmod p\\
          &\equiv \mathfrak{Re}_{\Pfrak}(f)\pmod p
        \end{align*}
        By definition of $\mathfrak{Re}_{\Pfrak}(f)$, $f-\frac{g'}{g}$ is an
        element of $S_N$ verifying for any place $\Pfrak$ outside
        $S\cup\mathrm{Supp}(D')$ that
        \[\nu_\Pfrak(f-\frac{g'}{g})\geq \nu_\Pfrak(t_\Pfrak').\]
  \end{proof}
  \begin{Definition}
    We consider
    $\Gfrak^p_N=\text{\large$\nicefrac{\mathrm{Cl}(K_N)}{p\mathrm{Cl}(K_N)}$}$.
    Since $K_N$ is an algebraic function field of characteristic $p$, $\Gfrak^p_N$ is a 
    finite commutative group of the form $\Gfrak^p_N\simeq
    \left(\text{\Large$\nicefrac{\Zbb}{p\Zbb}$}\right)^n$
    for some $n\in\Nbb^*$.
  \end{Definition}
  \begin{Corollaire}\label{local_sol}
    For each place $\Pfrak\in\Pbb_{K_N}$ we denote by $t_\Pfrak$ a prime
    element of $\Pfrak$.\\
    Let $(D_1,\ldots,D_n)\in\mathrm{Div}(K_N)^n$ be a lifting of a generating
    family of
    $\Gfrak^p_N$ viewed as a $\Fbb_p$-vector space.\\
    Let $S=\bigcup_{i=1}^n\Supp D_N$ and set
    \[A:=\max\left(\sum_{\Pfrak\in
    S}\Pfrak+\mathrm{Diff}(K_N)-2(x)_\infty,\frac{(y_N)_-}{p}\right).\]
    If $S_N$ is not empty then it contains an element of $\Lcal(A)$.
  \end{Corollaire}
  \begin{proof}
    Let $f\in S_N$ and let $\mathfrak{Re}(f)$ be defined similarly as in
    Theorem~\ref{theo_local_sol}. Since $D_1,\ldots,D_n$ is a basis of
    $\Gfrak^p_N$, there exists a linear combination $D'=a_1D_1+\ldots+a_nD_n$ such
    that $\mathfrak{Re}(f)\equiv D'\pmod{\Gfrak_N^p}$. Thus there exists
    $D_p\in\mathrm{Div}(K_N)$ such that
    \[\mathfrak{Re}(f)\sim D'+pD_p.\]
    %According to theorem~\ref{theo_local_sol}, $S_N$ contains an element
    %$f_*$
    %with no poles outside of $\mathrm{supp}(D')\cup S$ (since $S$
    %contains a place of degree $1$).
    Besides $\mathrm{supp}(D')\subset\bigcup_{i=1}^n\mathrm{supp}(D_i)\subset S$.
    According to Theorem~\ref{theo_local_sol}, $S_N$ contains an element
    $f^*$ verifying for all places outside of $S$ that $\nu_{\Pfrak}(f^*)\geq
    \nu_\Pfrak(t_\Pfrak')$.
    The corollary now follows from Proposition~\ref{borne_val} and the fact that
    the valuation in $\Pfrak$ of the divisor $\Diff(K_N)-2(x)_\infty$ is
    precisely $-\nu_\Pfrak(t_\Pfrak')$.
  \end{proof}
  \begin{Definition}\label{construct_divisor}
    For any effective divisor $D$ over $K_N$, we define
    \[A(D):=\max\left(\sum_{\Pfrak\in\Supp D}\Pfrak
    +\mathrm{Diff}(K_N)-2(x)_-,\frac{(y_N)_-}{p}\right).\]
    We say that $D$ is a generating divisor of $\Gfrak^p_N$ if and only if
    $(\Pfrak)_{\Pfrak\in\Supp D}$ is a generating family of $\Gfrak^p_N$.
    In this case 
    \[S_{N}=\varnothing\Leftrightarrow S_N\cap\Lcal(A(D))=\varnothing.\]

    For a family of effective divisors $(D_1,\ldots,D_n)$ we define
    \[A(D_1,\ldots,D_n)=A(D_1+\ldots+ D_n).\]
  \end{Definition}
