  To our knowledge there exists no algorithm able to compute the cokernel
  of the multiplication by $p$ in the divisor class group of a curve
  $\Ccal$ of genus $g$ in polynomial time in $g$ and the characteristic
  $p$. We instead opt to choose enough uniformly random elements of
  $\Gfrak^p_N$ to generate the whole group. Since we know that $\Gfrak^p_N$
  is of the form $\Fbb_p^n$ with $n$ being an integer smaller than $g+1$,
  we know that we only need to select $O(g)$ elements on average. We use  
  Algorithm~\ref{algo_irreducibility} beforehand to ensure the existence of
  a solution. We refer to~\cite[Section~3.5]{Bruin10} in which the author
  present an algorithm to select uniformly random elements in
  $\mathrm{Cl}^0(K_N)$. If $K_N$ is seen as the regular function field of a
  curve $\Ccal$, \cite[Algorithm~3.7]{Bruin10} presupposes the choice of a
  line bundle $\Lcal$ over $\Ccal$ of degree at least $2g+1$. Since we are
  working over finite fields, line bundles of arbitrary degrees exists and
  we can choose a line bundle of degree exactly $2g+1$. Then we can use 
  \cite[Algorithm~3.7]{Bruin10} to pick uniformly random elements in
  $\mathrm{Cl}^0(K_N)$ represented by uniformly random effective divisors of degree 
  $2g+1$ in polynomial time in $g$ and $\log(q)$. 
  However, \cite[Algorithm~3.7]{Bruin10} also suppose that the zeta
  function of $\Ccal$ is known in order to ensure the uniform distribution of the divisors.
  The computation of the zeta function can be done in time polynomial in
  $g$ and linear in $b$ and $p$ (precisely $\tilde{O}(pbd_x^6d_y^4)$ bit
  operations~\cite{tuitman17}). 
  \begin{Remarque}
    In~\cite[section~13.2]{BCEJM10} the authors also state that
    $\mathrm{Cl}^0(K_N)$ is generated by the places of degree less than
    $1+2\log_q(4g-2)$. This in turns guarantees the existence of $D$ a
    generating divisor of $\Gfrak_{N_*}^p$ of degree $\tilde{O}(d_xd_y)$. 
    However the probability of generating
    $\Gfrak^p_N$ with $O(g)$ uniformly chosen effective divisors of degree
    less than $1+\log_q(4g-2)$ could be very low which is why we do not use
    it for our algorithm.
  \end{Remarque}
  From now on we will assume that we are able to pick uniformly random
  elements in $\mathrm{Cl}^0(K_N)$. If $\Gfrak^{p}_N$ is of dimension $r$ over
  $\Fbb_p$ then we only need on average to select $O(r)$ elements to generate $\Gfrak^{p}_N$.\\

  We now discuss in more details the computation of the linear system
  representing the $p$-Riccati equation over some
  $\Lcal(A(D))$. The main issue lies in the computation of the $(p-1)$-th
  derivative of the elements of a basis of $\Lcal(A(D))$. Instead of
  computing their exact value in $K_N$, we compute their Taylor expansion
  up to a high enough precision.

  \begin{Proposition}\label{Proposition_section_stability}
    Let $\Phi_N:K_N\rightarrow C_N$ denote the Frobenius endomorphism over
    $K_N$ and $D\in\mathrm{Div}(K_N)$. Let $f\in\Lcal(A(D))$. Then
    $\Phi_N^{-1}(f^{(p-1)}+f^p)\in\Lcal(A(D))$.
  \end{Proposition}
  \begin{proof}
    Let $\Pfrak\in\Pbb_{K_N}$. If $\Pfrak\notin\Supp(A(D))$ then by definition
    of $A(D)$, $f$ is not a ramified place and $f$ has no poles in $\Pfrak$.
    Thus neither $f^{(p-1)}$ nor $f^p$ has a pole in $\Pfrak$. Thus
    $\Phi_N^{-1}(f^{(p-1)}+f^p)$ has no pole in $\Pfrak$.
    For $\Pfrak\in\Supp(A(D))$, we let $t_\Pfrak$ be a prime element of
    $\Pfrak$. We know that 
    \[
      \nu_\Pfrak(\Phi_N^{-1}(f^{(p-1)}+f^p))\geq \min (p^{-1}\cdot
      (\nu_\Pfrak(f)+(p-1)(\nu_\Pfrak(t_\Pfrak')-1)),\nu_\Pfrak(f))
    \]
    Besides we know that if $\nu_\Pfrak(f)\leq\nu_\Pfrak(t_\Pfrak')-1$ then
    $p^{-1}\cdot(\nu_\Pfrak(f)+(p-1)(\nu_\Pfrak(t_\Pfrak')-1))\geq\nu_\Pfrak(f)$
    so in that case we get that 
    $\nu_\Pfrak(\Phi_N^{-1}(f^{(p-1)}+f^p))\geq \nu_\Pfrak(f)$ which
    implies the desired result since $f\in\Lcal(A(D))$.
    If now we have $\nu_\Pfrak(f)>\nu_\Pfrak(t_\Pfrak')-1$ then 
    $p^{-1}\cdot(\nu_\Pfrak(f)+(p-1)(\nu_\Pfrak(t_\Pfrak')-1))>\nu_\Pfrak(t'_\Pfrak)-1$.
    Since valuations have to be integers we deduce that
    $\nu_\Pfrak(\Phi_N^{-1}(f^{(p-1)}+f^p))\geq \nu_\Pfrak(t'_\Pfrak)\geq
    -\nu_\Pfrak(A(D))$. Thus $\Phi_N^{-1}(f^{(p-1)}+f^p)\in\Lcal(A(D))$.
  \end{proof}
  \begin{Notation}
    From this point forward we assume that $K=\Fbb_{p^b}(x)$, for
    $b\in\Nbb^*$. We suppose that
    $N\in \Fbb_{p^b}[x^p,y]$ is a fixed separable irreducible polynomial and set
    $N_*(x,y)\in \Fbb_{p^b}[x,y]$ such that $N_*^p(Y)=N(Y^p)$. Let $a$ be the $p$-th
    root of $y_N\in K_N$. Then $N_*(a)=0$ and $K_N=K[a]$. We set
    $d_x=\deg_x N_*$ and $d_y=\deg_Y N_*$.
  \end{Notation}
  \begin{Definition}
    Let $f\in K_N$. There exist unique $f_0,\ldots, f_{p-1}\in K_N$ such
    that
    \[f=\sum_{i=0}^{p-1}f_i^{p}x^i.\]
    For all $i\in\ldbrack 0;p-1\rdbrack$ We denote by $S_i(f):= f_i$ the
    $i$-th section of $f$.
  \end{Definition}
  Although we define sections for all $i\in\ldbrack0;p-1\rdbrack$, we will
  really only be interested in $S_{p-1}$ as shown in the following lemma:
  \begin{Lemme}\label{section_derivation}
    For any $f\in K_N$, \[\Phi_N^{-1}(f^{(p-1)})=-S_{p-1}(f).\]
  \end{Lemme}
  \begin{proof}
    Let $f:=\sum_{i=0}^{p-1}f_i^p x^i$. It suffices to show that
    $f^{(p-1)}=-f_{p-1}^p$. But this is obvious since
    $f^{(p-1)}=(p-1)!f_{p-1}^p$ and $(p-1)!=-1\mod p$.
  \end{proof}
  Thus another way of writing $p$-Riccati equation is
  \[b-S_{p-1}(b)=a.\]
  We now use the fact that Lemma~\ref{section_derivation} also holds over $K_{N,\Pfrak}$ 
  for any $\Pfrak\in\Pbb_{K_N}$. Let $\Pfrak$
  be a place over $K_N$ that does not belong in $\Supp(A(D))$. Then the
  injective homomorphism from $K_N$ to its $\Pfrak$-completion induces an injective 
  homomorphism of $\Fbb_q$-vector spaces
  $\Lcal(A(D))\hookrightarrow \Gcal_\Pfrak[[t_\Pfrak]]$.
  It follows that there exists a constant $N\in\Nbb$ such that for all
  $f\in\Lcal(A(D))$, $f=0$ if and only if $\nu_\Pfrak(f)\geq N$.
  \begin{Lemme}
    Let $\Pfrak\in\mathrm{Div}(K_N)$, let $D$ be an effective divisor of $K_N$ and
    set $d:=\deg(A(D))$. For any $f\in\Lcal(A(D))$,
    \[f=0\Leftrightarrow \nu_\Pfrak(f)>\frac{d}{\deg(\Pfrak)}.\]
  \end{Lemme}
  \begin{proof}
    Since $f\in\Lcal(A(D))$, if $f\neq 0$ then we know that $\deg
    (f)_\infty\leq d$. But since $\deg
    (f)_\infty=\deg (f)_0$ we know that $\nu_\Pfrak(f)\leq
    \frac{\deg(f)_\infty}{\deg(\Pfrak)}\leq \frac{d}{\deg(\Pfrak)}$.
  \end{proof}
  Thus it suffices for a function $f\in\Bcal$ (where $\Bcal$ is a basis of
  $\Lcal(A(D))$) to compute the image of $f-S_{p-1}(f)$ modulo
  $t_\Pfrak^{\left\lfloor \frac{\deg(A(D))}{\deg \Pfrak}\right\rfloor+1}$ in
  $\Gcal_{\Pfrak}[[t_\Pfrak]]$. If one writes $f=\sum_{k=0}^{\infty} f_i
  t_\Pfrak^i$ then $S_{p-1}(f)\mod t_\Pfrak^{\left\lfloor
  \frac{\deg(A(D))}{\deg \Pfrak}\right\rfloor+1}$ can be deduced from the knowledge of the
  coefficients $f_{pk+p-1}$ for $k\leq \frac{deg(A(D))}{\deg\Pfrak}$.
  To that end we can compute the first $p\left\lfloor \frac{\deg(A(D))}
  {\deg\Pfrak}\right\rfloor+p-1$ coefficients of the Taylor expansion of
  $f$. In practice, we compute the Taylor expansion of $a$ of which we know the minimal
  polynomial, in
  $t_\Pfrak$ up to the desired precision by Newton iteration (note that by
  definition of $A(D)$, $a\in\Lcal(A(D))$). This can be done in $\tilde{O}(p\deg(A(D))d_y)$
  operations in $\Fbb_q$. Then, knowing that elements of $\Lcal(A(D))$ are given by
  polynomials $F(x,a)$ we get their Taylor expansions by composition for an
  additional cost of $\tilde{O}(p\deg(A(D))d_y)$ operations in $\Fbb_q$.
\begin{Proposition}\label{coefficient_trace_formula}
  Let $Q_i$ be the quotient of the Euclidean division of $N_*(x,y)$ by $y^{i+1}$ for
  any $i\in\Nbb$. Then for any $f:=\sum_{k=0}^{d_y-1} f_ka^k\in K_{N}$
  and any $i\in\ldbrack 0;d_y-1\rdbrack$,
  $f_i=\Tr_{K_{N}/\Fbb_q(x)}\left(\frac{Q_i(x,a) f}{\partial_y
  N_*(x,a)}\right)$.
\end{Proposition}
\begin{proof}
  Let us fix $N_*(x,y)=\sum_{k=0}^{d_y} \eta_k(x) y^k$. From \cite[Lemma~2 section~III.
  6]{Serre04} we know that $\Tr_{K_{N}/\Fbb_{p^b}(x)}\left(\frac{a^{i}}{\partial_y
  N_*(x,a)}\right)=\frac{1}{\eta_{d_y}}\delta_{i,d_y-1}$,  for all
  $i\leq d-1$. Thus the result holds for $i=d_y-1$, since $Q_{d_y-1}=\eta_{d_y}$. Then for all
  $i$ we have $Q_i=Q_{i+1} y+\eta_{i+1}$. We assume the proposition to be
  true for $i+1$. Then 
  \[
    \Tr_{K_{N}/\Fbb_{p^b}(x)}\left(\frac{Q_i(x,a) f}{\partial_y
    N_*(x,a)}\right)=\Tr_{K_{N}/\Fbb_{p^b}(x)}\left(\frac{Q_{i+1}(x,a)a f}{\partial_y
    N_*(x,a)}\right)+\eta_{i+1}\Tr_{K_{N}/\Fbb_{p^b}(x)}\left(\frac{f}{\partial_y
    N_*(x,a)}\right)\]
  and by hypothesis $\Tr_{K_{N}/\Fbb_{p^b}(x)}\left(\frac{Q_{i+1}(x,a)a f}{\partial_y
    N_*(x,a)}\right)$ is the coefficient of $a^{i+1}$ in $af$, which is
    given by $f_i-\frac{f_{d_y-1}\eta_{i+1}}{\eta_{d_y}}$, while $Tr_{K_{N}
    /\Fbb_{p^b}(x)}\left(\frac{f}{\partial_y N_*(x,a)}\right)$ is the
    coefficient of $a^{d_y-1}$ of $\frac{f}{\eta_{d_y}}$.\\

    \[\Tr_{K_{N}/\Fbb_{p^b}(x)}\left(\frac{Q_i(x,a) f}{\partial_y
    N_*(x,a)}\right)=f_i-\frac{f_{d_y-1}\eta_{i+1}}{\eta_{d_y}}+\eta_{i+1}\frac{f_{d_y-
    1}}{\eta_{d_y}}=f_i.\]
\end{proof}
\begin{Corollaire}\label{coeff_poles_trace}  
  Let $D$ be an effective divisor over $K_N$ and $P$ be an irreducible
  polynomial in $\Fbb_{p^b}[x]$ coprime with
  $\mathrm{Disc}(N_*)$ and the leading coefficient of $N_*$. If none of the
  places in $\Supp(D)$ divides $P$ then for any
  $f\in\Lcal(A(D))$, none of the coefficients of $f$ in the basis
  $(1,a,\ldots,a^{d_y-1})$ have a pole in $P$.
\end{Corollaire}
\begin{proof}
  Let $l_c$ be the leading coefficient of $N_*$. The function $l_c a$ is integral and
  its minimal polynomial is $N_1=l_c^{d_y-1} N_*(x,Y/l_c)$. We have
  $\Disc(N_1)=l_c^{d_y-1}\Disc(N_*)$ and $(\partial_Y N_*(x,a))_+\leq
  (\partial_Y N_1(x,l_c a))_0
  \leq (d_y-1)(l_c)_0+(\mathrm{Disc}(N_*))_0$. This shows that for all $i$
  (with the notations of the previous proposition),
  $\frac{Q_i(x,a)}{\partial_yN_*(x,a)}$ has no poles that divides $P$ since
  the poles of $a$ are among those of $l_c$.\\
  Let us now show that $\Supp(A(D))$
  does not contain any place that divides $P$. 
  Let $\mathrm{Diff}(K_{N_*})_0$ be the different divisor of $K_{N_*}$ outside of
  the places at infinity. Since $l_c a$ is integral we know that
  $\mathrm{Diff}(K_{N_*})_0\leq (\partial_Y N_1(x,l_c a))_0\leq
  (d_y-1)(l_c)_0+(\mathrm{Disc}(N_*))_0$. Thus $\Supp(A(D))\cap\Supp(P)\subset
  (\Supp(\Diff(K_N))\cap\Supp (P))\cup
  (\Supp(a)_\infty\cap\Supp(P)\subset\Supp(l_c)\cap\Supp(P)=\varnothing$.
  Thus if we set $\Ocal_P$ the valuation ring associated to $P$ in
  $\Fbb_{p^b}(x)$ and
  $\Ocal_P'$ its integral closure in $K_{N}$, then for all $i$ and all
  $f\in \Lcal(A(D))$,  $\frac{Q_i(x,a)f}{\partial_yN_*(x,a)}\in \Ocal_P'$.
  It follows that if $f_i$ denotes the $i$-th coefficient of $f$ then
  $f_i=\Tr_{K_N/\Fbb_{p^b}(x)}\left(\frac{Q_i(x,a)f}{\partial_yN_*(x,a)}\right)\in
  O_P$ and $f_i$ has no pole in $P$.
\end{proof} 
When knowing the Taylor expansion of $a$ up to the desired precision, computing
the Taylor expansion of an element $f$ of $\Lcal(A(D))$ by composition requires to
compute the Taylor expansion of its coefficients. This can be done in
$\tilde{O}(p\max(\eta,\deg A(D)) d_y)$ operations in $\Fbb_{p^b}$ where $\eta$ is
the degree of the coefficients of $f$. As we show now, by
construction of $A(D)$, $\eta$ and $\deg(A(D))$ have the same order of magnitude.
  \begin{Lemme}
    Let $f\in K_N$ and $\Pfrak\in\Pbb_{\Fbb_{p^b}(x)}$. 
  \[\nu_{\Pfrak}(\Tr_{K_N/\Fbb_{p^b}(x)}(f))
    \geq \min_{\Pfrak'|\Pfrak}\left
    \lfloor\frac{\nu_{\Pfrak'}(f)}{e(\Pfrak'|\Pfrak)}\right\rfloor.\]
  \end{Lemme}
\begin{proof}
  Let $\Ocal_\Pfrak$ be the valuation ring associated to the place
  $\Pfrak$ and $\Ocal_\Pfrak'$ be its integral closure in $K_N$.
  For any $f\in K_N$, if $f\in \Ocal_\Pfrak'$ then $\Tr_{K_N/\Fbb_{p^b}(x)}(f)\in\Ocal_{\Pfrak}$
  \cite[Corollary~3.3.2]{StHe08}.\\
  It follows that if $\Pfrak$ is a pole of $\Tr_{K_N/\Fbb_{p^b}(x)}(f)$, then at least
  one of the places lying under $\Pfrak$ is a pole of $f$. Let
  $\Pfrak^*$ above $\Pfrak$ be such that
  \[\left\lfloor
  \frac{\nu_{\Pfrak^*}(f)}{e(\Pfrak^*|\Pfrak)}\right\rfloor=\min_{\Pfrak'|\Pfrak}\left                  \lfloor\frac{\nu_{\Pfrak'}(f)}{e(\Pfrak'|\Pfrak)}\right\rfloor.\]
  %Set  $-\nu:=\nu_{\Pfrak^*}(f)$, $e:=e(\Pfrak^*|\Pfrak)$
  Set $k=\left\lceil
  \frac{-\nu_{\Pfrak^*}(f)}{e(\Pfrak^*|\Pfrak)}\right\rceil$ and  $P\in K_N$
  a prime element of $\Pfrak$. Then for any $\Pfrak'$ above $\Pfrak$ we have

  \[
    \nu_{\Pfrak'}(P^k f)=ke(\Pfrak'|\Pfrak)+\nu_{\Pfrak'}(f).\]
  By definition $k\geq -\frac{\nu_{\Pfrak'}(f)}{e(\Pfrak'|\Pfrak)}$ thus
  $\nu_{\Pfrak'}(P^kf)\geq 0$. It follows that
  \begin{align*}
    \nu_{\Pfrak}(\Tr_{K_N/\Fbb_{p^b}(x)}(P^k f))&=
    \nu_{\Pfrak}(P^k\Tr_{K_N/\Fbb_{p^b}(x)}(f))\\
    &=k+\nu_{\Pfrak}(\Tr_{K_N/\Fbb_{p^b}(x)}(f))\\
    &\geq 0\\
    \nu_{\Pfrak}(\Tr_{K_N/\Fbb_{p^b}(x)}(f))&\geq -k
  \end{align*}
  which is the desired result.
\end{proof}
\begin{Proposition}\label{divisor<->coeff}
  Let $D$ be an effective divisor over $K_N$ and $f=\frac{1}{f_{-1}}\sum_{i=0}^{d_y-1}f_i
  a^i\in\Lcal(A(D))$ where $f_{-1},f_0,\ldots,f_{d_y-1}\in\Fbb_q[x]$ are
  globally coprime polynomials.\\
  Then for any $i\in\ldbrack-1;d_y-1\rdbrack$, both $\deg(f_i)$ and
  $\deg(A(D))$ are in $O(\deg(D)+d_xd_y)$.\\
\end{Proposition}
\begin{proof}

  Let $P\in\Fbb_q[x]$ be an irreducible polynomial and let $Q_i$ denote the
  quotient of the Euclidean division of $N_*$ by $Y^{i+1}$ applied to $x$
  and $a$. If $P$ is a pole of $\Tr_{K_{N_*}/\Fbb_q(x)}(Q_if)$:

  \begin{align*}
    \nu_P(\Tr_{K_{N_*}/\Fbb_q(x)}(Q_if))\deg(P)
    &\geq \min_{\Pfrak|P}\left\lfloor\frac{\nu_{\Pfrak}(Q_i)+
    \nu_\Pfrak(f)}{e(\Pfrak|P)}\right\rfloor\deg(P)\\
    &\geq \sum_{\Pfrak|P}(\nu_\Pfrak(Q_i)+\nu_\Pfrak(f))\deg(\Pfrak)\\
    &\geq \sum_{\Pfrak|P}(\nu_\Pfrak(Q_i)-\nu_\Pfrak(A(D)))\deg(\Pfrak)\\
  \end{align*}
  It follows that
  \[\deg (\Tr_{K_{N_*}/\Fbb_q(x)}(Q_if))_\infty \leq \deg (Q_i)_\infty+\deg(A(D)).\]
  But $A(D)\leq D+\mathrm{Diff}(K_N)-2(x)_\infty+(a)_\infty$.
  Thus, since $\deg(\Diff(K_N)-2(x)_\infty)=2g-2$, where $g$ denotes the
  genus of $K_N$, $\deg A(D)\leq \deg(D)+d_x+2g-2$.
  Since $g\leq (d_x-1)(d_y-1)$ (see~\cite[Corollary~2.6]{Beelen09}), it
  follows that $\deg(A(D))=O(\deg(D)+d_xd_y)$ and 
  $\deg (\Tr_{K_{N_*}/\Fbb_q(x)}(Q_if))_\infty=O(d_xd_y+\deg(D))$.
  Thus, according to Corollary~\ref{coefficient_trace_formula},
  $\partial_yN_*(x,a)f$ has coefficients of degree $O(d_xd_y+\deg(D))$.
  Since $(\partial_yN_*(x,a)f)^{-1}$ has coefficients of size $O(d_xd_y)$, the
  result follows.
\end{proof}
\begin{Notation}\label{notation_T_P(B)}
  Let $\Bcal$ be a basis of $\Lcal(A(D))$ with $D\in\mathrm{Div}(K_{N})$, and $P\in\Fbb_q[x]$ 
  an irreducible polynomial verifying the hypothesis of
  Corollary~\ref{coeff_poles_trace}. Let $\Pfrak\in\Pbb(K_N)$ be lying over
  $P$ and $t_\Pfrak$ be a prime element of $\Pfrak$ and $B_0$ be an
  $\Fbb_p$-basis of $\Gcal_\Pfrak$.
  We denote by $\Tcal_\Pfrak(\Bcal)$ the matrix with coefficient in $\Fbb_p$
  whose columns are the Taylor expansion of the image of elements of
  $\Bcal$ by the map $f\mapsto f-S_{p-1}(f)$, at
  precision $\left\lfloor\frac{\deg A(D)}{\deg \Pfrak}\right\rfloor+1$ written in
  the basis $\Bcal_0\times(t_\pfrak^i)_{i\deg(\Pfrak)\leq\deg(A(D))}$.
\end{Notation}
We can now write the final version of our algorithm the solve the
$p$-Riccati equation in Algorithm~\ref{algo_p-riccati_irred}.\\
  \begin{algorithm}
  \begin{flushleft}
    \emph{Input:} $N_*\in \Fbb_{p^b}[x,y]$ an irreducible separable polynomial.\\
    \emph{Output:} $f\in K[a]$, where $a$ is a root of $N_*$ such that
    $f^{(p-1)}+f^{p}=a^p$, if such an $f$ exists. 

  \end{flushleft}
    \begin{enumerate}
      \item Test if $N_*^p(\partial)$ is irreducible using
        Algorithm~\ref{algo_irreducibility}.
      \item \textbf{If} $N_*^p(\partial)$ is irreducible \textbf{return}.
      \item Set $d_y:=\deg_Y N_*$ and
        $K_{N_*}:=K[a]=\nicefrac{\Fbb_{p^b}(x)[y]}{(N_*)}$.
      \item Compute $(a)_\infty$.
      \item Compute $A:=\mathrm{Diff}(K_{N_*})-2(x)_\infty$.
      \item Set $D:=0$, $n:=0$ and $l=0$.
      \item\label{step_random_div} Select
        $(D_1,\ldots,D_{n})\in\mathrm{Div}(K_{N})^{n}$ a family of
        $n$ randomly chosen divisors\\ of degrees $2g+1$
      \item $D\leftarrow D+D_1+\ldots D_n$, $l\leftarrow l+n$, $n\leftarrow
        n+\max(1,l)$ and $A(D):=A$.
      \item \textbf{For} $\Pfrak\Supp D$ \textbf{do:}
    \begin{itemize}
      \item $A(D)\leftarrow A(D)+\Pfrak$ 
    \end{itemize}
  \item $A(D)\leftarrow \max((a)_-,A(D_1,\ldots,D_{g+1}))$.
  \item Compute a basis $\Bcal$ of $\Lcal(A(D))$
  \item Select $P\in\Fbb_q[x]$ an irreducible polynomial verifying the
    hypothesis of\\ Corollary~\ref{coeff_poles_trace} with respect to $D$ and $\Pfrak|P$.
  \item Compute the Taylor expansion  $V$ of $a$ in $t_\Pfrak$ at precision
    $\left\lfloor \frac{\deg A(D_1,\ldots,D_{g+1})}{\deg \Pfrak}\right\rfloor+1$
  \item Compute $\Tcal_{\Pfrak}(\Bcal)$ (see Notation~\ref{notation_T_P(B)}).
  \item Solve $\Tcal_{\Pfrak}(\Bcal)X=V$.
    \item \textbf{If} a solution $X$ exists reconstruct a solution to the
      $p$-Riccati equation from it\\
        and \textbf{return} it.
  \item \textbf{Else} redo from step~\ref{step_random_div}
  \end{enumerate}
    \caption{p-Riccati\_with\_irreducibility}
    \label{algo_p-riccati_irred}
  \end{algorithm}

\begin{Theoreme}\label{complexity_size_p-riccati}
  Let $r$ be the dimension of $\Gfrak^p_N$ over $\Fbb_p$, where
  $N(y^p)=N_*^p(y)$. We have $r\leq d_xd_y$ and Algorithm~\ref{algo_p-riccati_irred} returns 
  if it exists a solution of the $p$-Riccati equation relative to $N$ whose coefficients are of
  degree $O(rd_xd_y)$ at the cost of 
  \begin{itemize}
    \item testing the irreducibility of
      $N_*^p(\partial)$ using Algorithm~\ref{algo_irreducibility}
    \item factoring the divisors $(a)_\infty$ and $(x)_\infty$
    \item computing the different divisor of $K_{N}$
    \item selecting $O(r)$ uniformly random elements of $\mathrm{Div}(K_{N_*})$ of degree
      $2g+1$
    \item computing  $O(\log_2(r))$ basis of Riemann-Roch spaces of
      dimension $O(rd_xd_y)$.
    \item $\tilde{O}(bpr^2d_x^2d_y^3+(brd_xd_y)^{\omega})$ bit operations.
  \end{itemize}
  The total complexity of the computation is polynomial in $b$, $d_x$
  and $d_y$ and linear in $p$.
\end{Theoreme}
\begin{proof}
  The cost of steps $(1)$ to $(5)$ in Algorithm~\ref{algo_p-riccati_irred}
  is the cost of using Algorithm~\ref{algo_irreducibility}. The
  cost of step (4) is the cost of computing $(a)_\infty$, $(x)_\infty$ and 
  $\mathrm{Diff}(K_{N_*})$.\\
  The degree of $D$ roughly doubles at each repetition of steps $(7)$ to $(15)$ and are
  repeated on average $O(\log_2(r))$ times after which we have selected
  $O(r)$ uniformly random elements of $\Gfrak^p_N$ which form a generating
  family of it.
  The cost of steps
  (7) to (10) is essentially the cost of selecting uniformly random
  divisors of degree $2g+1$. By definition of $A(D)$, it
  is of degree $O(d_xd_y+rg)$. Since $g=O(d_xd_y)$ we find that
  $A(D)$ is of degree $O(rd_xd_y)$.\\
  Since we know that the solution of the $p$-Riccati equation constructed by
  Algorithm~\ref{algo_p-riccati_irred} is an element of
  $\Lcal(A(D))$, Proposition~\ref{divisor<->coeff} states
  that this solution has coefficients of degree $O(rd_xd_y)$.\\
  The cost of step (11) is thus the cost of computing a basis of
  $\Lcal(A(D))$ which is of dimension
  $O(\deg(A(D)) \subset O(rd_xd_y)$.\\
  Step (11) requires the computation of $\mathrm{Disc}(N_*)$ whose cost is
  negligible in regard of the final result.\\
  The cost of steps (13) and (14) is the cost of computing the Taylor
  expansions of $O(rd_xd_y)$ functions in $\Lcal(A(D))$ using Newton
  iterations. The cost for one such function is $\tilde{O}(bprd_xd_y^2)$ bit
  operations so the total cost is $\tilde{O}(bpr^2d_x^2d_y^3)$. Using this
  we can compute the Taylor expansions of $h-S_{p-1}(h)$ for $h\in\Bcal$
  at precision $O(\frac{rd_xd_y}{\deg(\Pfrak)})$. We recall that $\Bcal$ is
  an $\Fbb_{p^b}$-basis of $\Lcal(A(D))$. Since we want the result on an
  $\Fbb_p$-basis, we still need to multiply the result by an $\Fbb_p$-basis
  of $\Fbb_{p^b}$ which can be done in $\tilde{O}((brd_xd_y)^2\log(p))$ bit
  operations. Thus steps
  (13) and (14) can be done in $\tilde{O}(bpr^2d_x^2d_y^3+(brd_xd_y)^2)$ binary
  operations.\\
  Finally, step (14) is a matter of solving a $\Fbb_p$-linear system of
  size $O(brd_xd_y)\times O(brd_xd_y)$ which can be done in
  $\tilde{O}((b rd_xd_y)^{\omega})$ operations in $\Fbb_p$.\\
  Reconstructing the solution to the $p$-Riccati equation is a matter of
  summing $O(rd_xd_y^2)$ polynomial coefficients in $\Fbb_{p^b}[x]$ of degree
  $O(rd_xd_y)$ which can be done in $\tilde{O}(br^2d_x^2d_y^3\log(p))$ bit
  operations.

  The sum of those cost yield the final result.
\end{proof}

  \begin{Remarque}\label{iterative_improvement}
    In our experiments we often found that $r=O(1)$ hence the expression of
    the complexity in terms of this additional parameter and not purely in
    terms of $d_x$ and $d_y$.
  \end{Remarque}

\section{Application to factorisation of differential operators}

Now that we have a working algorithm to solve $p$-Riccati equations and
degree bounds for the solutions, we discuss how it fits in the broader
context of differential operators factorisation. We begin by discussing how
to go from a solution of the $p$-Riccati equation relative to $N$, to the
corresponding irreducible divisor of $N(\partial^p)$.

\begin{Proposition}\label{Proposition_kernel_irred_div}
  Let $N\in C[Y]$ be a separable irreducible polynomial and $f\in K_N$ be a solution
  to the $p$-Riccati equation relative to $N$. If $L$ is a generator of the
  ideal of operators in $K\langle\partial\rangle$ which are left multiple
  of $\partial-f$ then $L$ is an irreducible divisor of $N(\partial^p)$.
\end{Proposition}
\begin{proof}
  We consider $K\langle\partial\rangle_{\leq\deg(N)}=\{L\in
  K\langle\partial\rangle|\mathrm{ord}(L)\leq\deg(N)\}$ and the $K$-linear
  map $\psi_N:K\langle\partial\rangle_{\leq\deg(N)}\rightarrow
  \nicefrac{K_N\langle\partial\rangle}{K_N\langle\partial\rangle(\partial-f)}$
  which maps an operator to its image modulo $\partial-f$. \\Since $\dim_K 
  K\langle\partial\rangle_{\leq\deg(N)}=\deg(N)+1$ and $\dim_K
  \nicefrac{K_N\langle\partial\rangle}{K_N\langle\partial\rangle(\partial-f)}=\deg(N)$,
  $\psi_N$ has a nontrivial kernel. In particular $\mathrm{ord}(L)\leq
  \deg(N)$. Let us show that $L$ is a divisor of $N(\partial^p)$. We claim
  that $\gcrd(L,N(\partial^p))$ is a multiple of $\partial-f$. Indeed,
  $\partial-f$ is a divisor of $\partial^p-y_N$ which is a divisor of
  $N(\partial^p)$ and is also a divisor of $L$. By definition of $L$,
  $\gcrd(L, N(\partial^p))=L$ and $L$ is a divisor of $N(\partial^p)$.
  Since $\mathrm{ord}(L)\leq\deg(N)$, it has to be irreducible according to
  Proposition~\ref{properties_sec_1}.(v).
\end{proof}
The proof of this result also points to an algorithmic way of deducing an
irreducible divisor of $N(\partial^p)$ from a solution to the $p$-Riccati
equation relative to $N$.
\begin{Corollaire}\label{better_way}
  Let $N\in C[Y]$ be an irreducible polynomial and $f\in K_N$ be a solution
  to the $p$-Riccati equation relative to $N$. Set $d_y=\deg(N)$.\\
  Let $a_0=1$ and for all $i\in\ldbrack0;d_y-1\rdbrack$,
  $a_{i+1}=a_if+a_i'$. Consider the matrix $M(f)$ in $M_{d_y,d_y+1}(K)$ whose columns
  are the coefficients of the $a_i$ (in some fixed $K$ basis of $K_N$).
  Then for any nonzero $v=(v_0,\ldots,v_{d_y})\in\ker(M)$,
  $\sum_{i=0}^{d_y}v_i\partial^i$ is an irreducible divisor of
  $N(\partial^p)$.
\end{Corollaire}
\begin{proof}
  We consider $K\langle\partial\rangle_{\leq\deg(N)}=\{L\in
  K\langle\partial\rangle|\mathrm{ord}(L)\leq\deg(N)\}$ and the $K$-linear
  map $\psi_N:K\langle\partial\rangle_{\leq\deg(N)}\rightarrow
  \nicefrac{K_N\langle\partial\rangle}{K_N\langle\partial\rangle(\partial-f)}$
  which maps an operator to its image modulo $\partial-f$. For dimensional
  reasons, we know that
  $\psi_N$ has a nontrivial kernel. Besides, any nonzero
  element of the kernel is a multiple of $\partial-f$ in
  $K\langle\partial\rangle$ of order less than $\deg(N)$. From
  Proposition~\ref{Proposition_kernel_irred_div} and
  Proposition~\ref{properties_sec_1}.(v) this means that it is a
  irreducible divisor of $N(\partial^p)$.
  We claim that the matrix $M(f)$ is the matrix of this restriction from the
  basis $(1,\partial,\ldots,\partial^d)$ to the $K$-basis of $K_N\simeq
  \text{\large$\nicefrac{K_N\langle\partial\rangle}{K_N\langle\partial\rangle(\partial-f)}$}$
  we have fixed.\\
  Indeed let $L'=\partial^k l_k+\partial^{k-1}l_{k-1}+\cdots+l_0$ be any
  differential operator in $K_N\langle\partial\rangle$. Then
  there exists an operator $B=\partial^{k-1}b_{k-1}+\cdots+\partial b_1+b_0\in
  K_N\langle\partial\rangle$ and $b_{-1}\in K_N$ such that
  \[L'=B(\partial-f)+b_{-1}.\]
  Then 
  \begin{align*}
    L'&=\sum_{i=0}^{k-1}\partial^{i+1}b_i-\sum_{i=0}^{k-1}\partial^i
    (b_i'+fbi)+b_{-1}\\
    &=\partial^kb_{k-1}+\sum_{i=0}^{k-1}\partial^i(b_{i-1}-b_i'-fb_i) 
  \end{align*}
    and we find that $l_i=b_{i-1}-b_{i}'-fb_{i}$, or equivalently 
  $b_{i-1}=l_i+b_{i}'+fb_{i}$ and $b_{k-1}=l_k$. We apply this result to
  $L'=\partial^k$. It immediately follows that the corresponding $b_{-1}$
  is the $k$-th term of the recursive sequence defined by $a_0=1$,
  $a_{i+1}=a_if+a_i'$, which concludes the proof.
\end{proof}
It is now easy to see that the coefficients of
$\gcrd(N(\partial^p),\varphi_N^{-1}(\partial-f))$ are of size independent
from $p$ as long as it is also the case for the coefficients of $f$, which we
know to hold true from Theorem~\ref{complexity_size_p-riccati}.

\begin{Lemme}
  We keep the notation of Corollary~\ref{better_way} with the additional
  hypothesis that $f\in\Lcal(A(D))$ where $D\in\mathrm{Div}(K_N)$ is a
  generating divisor of $\Gfrak^p_N$. Then for all $i\in\ldbrack
  1;d_y\rdbrack$,
  \[a_i\in\Lcal\big(iA(D)+(i-1)\max(\mathrm{Diff}(K_N)-2(x)_\infty,\,0)\big).\]
\end{Lemme}
\begin{proof}
  We know that $a_1=f\in\Lcal(A(D))$ so the proposition is verified here.
  We now suppose that the conclusion of the lemma holds for the index $i$.
  Let $\Pfrak\in\Pbb_{K_N}$ be a place and $t_\Pfrak$ be a prime element of
  it. Then 
  \[\nu_\Pfrak(a_i')\geq \nu_\Pfrak(a_i)+\nu_\Pfrak(t_\Pfrak')-1.\]
  In all generality, $1-\nu_\Pfrak(t_\Pfrak')$ is precisely one more than
  the valuation of $\mathrm{Diff}(K_N)-2(x)_\infty$ in $\Pfrak$. In particular
  if $\Pfrak$ is ramified then it is smaller than twice the valuation of
  $\mathrm{Diff}(K_N)-2(x)_\infty$ which is smaller than the valuation of $A(D)+\mathrm{Diff}(K_N)-
  2(x)_\infty$. If it is not ramified then either $a_i$ does not have a pole in
  $\Pfrak$, in which case neither does $a_i'$ or it has one and we have
  both $\nu_\Pfrak(a_i')\geq \nu_\Pfrak(a_i)-1$ and $\nu_\Pfrak(A(D))\geq 1$.
  Thus $\nu_\Pfrak(a_i)-\nu_\Pfrak(a_i')$ is once again smaller than the
  valuation of $A(D)+\mathrm{Diff}(K_N)-2(x)_\infty$.
  Therefore 
  $$a_i'\in\Lcal\big((i+1)A(D)+i\max(\mathrm{Diff}(K_N)-2(x)_\infty,0)\big.$$
  Furthermore
  since $f\in A(D)$, so too does $f a_i$ and the result follows.
\end{proof}
  \begin{algorithm}[H]
  \begin{flushleft}
    \emph{Input:} $N_*\in \Fbb_q(x)[Y]$ an irreducible separable polynomial, $f$ a
    solution of the $p$-Riccati equation relative to $N_*$.\\
    \emph{Output:} $L\in K\langle\partial\rangle$ the smallest monic multiple of
    $\partial-f$ with coefficients in $K$.
  \end{flushleft}
    \begin{enumerate}
      \item Set $K_{N_*}=\Fbb_q(x)[a]$ with $a$ a root of $N_*$.
      \item Set $d_y:=\deg N_*$.
      \item Set $a_0:=1$.
      \item \textbf{For} $i$ going from $1$ to $d_y$ \textbf{do}:
        \begin{itemize}
          \item Set $a_{i}:=a_{i-1}'+fa_{i-1}$
        \end{itemize}
      \item Set $M\in M_{d,d+1}(\Fbb_q(x))$ the matrix whose columns are
        the $a_i$\\written in the $\Fbb_q(x)$-basis $(1,a,\ldots,a^{d_y-1})$
        of $K_{N_*}$.
      \item Solve $MX=0$.
      \item Reconstruct $L$ from a solution and return it.
  \end{enumerate}
    \caption{Irreducible\_factors}
    \label{algo_p-riccati<->factor}
  \end{algorithm}
\begin{Theoreme}\label{size_p-riccati<->factor}
  Let $N_*\in\Fbb_{p^b}[x,y]$ be a separable irreducible polynomial. Keeping
  the notations of the previous sections, we suppose that
  $\dim_{\Fbb_p}\Gfrak^{p}_{N_*}=r$. Using
  Algorithm~\ref{algo_p-riccati_irred} we can compute a solution $f$ of the
  $p$-Riccati equation relative to $N$ whose coefficients are of degrees $O(rd_xd_y)$.
  Then Algorithm~\ref{algo_p-riccati<->factor} computes an irreducible
  divisor of $N_*^p(\partial)$ whose coefficients are of degree
  $O(rd_xd_y^3)$ in $\tilde{O}(rd_xd_y^{\omega+2})$ operations in
  $\Fbb_{p^b}$.
\end{Theoreme}
\begin{proof}
  The coefficients of the irreducible divisor returned by
  Algorithm~\ref{algo_p-riccati<->factor} can be expressed using the minors of the
  matrix $M$ whose columns are the $a_i$ written in the basis
  $(1,a,\ldots,a^{d_y-1})$. Since we know that $f$ has coefficients of
  degree $O(rd_xd_y)$, by immediate recurrence we get that $a_i$ has
  coefficients of degree $O(rd_xd_y^2)$. Thus the minors of $M$ are of
  degree $O(d_y^2rd_xd_y)$ since $M$ is a matrix of size $d\times(d+1)$.
  Furthermore, the coefficients $a_i$ can all be computed in
  $\tilde{O}(rd_xd_y^3)$ operations in $\Fbb_q$. It finally remains
  to solve a linear system of size $d\times (d+1)$ with coefficients in $\Fbb_q(x)$ of degree
  $O(rd_xd_y^2)$. This can be done in in $\tilde{O}(rd_xd_y^{\omega+2})$ operations in
  $\Fbb_{p^b}$~\cite{Storjohann03}.
\end{proof}
\begin{Remarque}
  In practice we have observed that the growth of the size of the
  coefficients, from those of the solution to the $p$-Riccati equation, to
  those of the corresponding irreducible divisor of $N(\partial^p)$, is
  only linear in $d_y$ (and not quadratic as shown in
  Theorem~\ref{size_p-riccati<->factor}). We infer that the situation is
  similar to seeking the minimal polynomial of an algebraic function in
  some $K[a]$.
\end{Remarque}
