\textbf{Model} & \textbf{B-U} & \textbf{M-R} & \textbf{R-L} & \textbf{B-S} \\
\hline
MU-LLaMA & 0.190 & 0.207 & 0.219 & 0.863 \\
\hline
\textbf{MusiScene} & \textbf{0.421} & \textbf{0.403} & \textbf{0.404} & \textbf{0.901} \\
